// Riot's de_de Legends of Runeterra card text (Data Dragon via InFinity54 LoR_DDragon mirrors, sets 1–9), saved 2026-10-21.
// Also ATLAS_I18N_LOR_G = {sets: English set name → name, regions: nameRef → name, rarities: RARITY → name} from globals-de_de.json.
// code → [name, card text, level-up text, flavor, type, subtypes, regions, rarity]; missing codes fall back to English.
window.ATLAS_I18N_LOR={"01IO012":["Zwillingsdisziplinen","Gib einem Verbündeten in dieser Runde +3|+0 oder +0|+3.","","„Fürchte dich niemals vor Veränderung. Sie wird dich hinterfragen, deine Grenzen testen. Sie ist unsere größte Lehrerin.“\n– Karma","Zauber",[],["Ionia"],"GEWÖHNLICH"],"01IO015":["Yasuo","Wenn du einen Gegner betäubst oder zurückrufst, verursache ich 2 Schaden an ihm.","Du hast 5+ Einheiten betäubt oder zurückgerufen.","„Der Tod ist wie der Wind …“","Einheit",[],["Ionia"],"Champion"],"01IO020":["Hüterin der Masken","Wenn ich beschworen werde, gib anderen Verbündeten in dieser Runde +1|+0.","","„An diesem Tag wird das Gesicht der Disziplin, des Trainings, der Demut und des Gleichgewichts das deine werden. Heute wirst du ein Kinkou.“","Einheit",[],["Ionia"],"GEWÖHNLICH"],"01IO045":["Bote des Frühlings","Unterstützung: Ich gebe meinem unterstützten Verbündeten in dieser Runde Lebensraub.","","„Im Winter hörten wir die Fußstapfen\nauf dem verschneiten Grund.\nSie hinterließen neue Ranken und Blätter,\nVorboten der kommenden Jahreszeit.“\n– Gedicht der Shon-Xan","Einheit",[],["Ionia"],"GEWÖHNLICH"],"01IO008":["Fee Klingenwirbler","Wenn du eine Einheit betäubst oder zurückrufst, gewähre mir +2|+0.","","„Oh, du findest mich also ,niedlich‘? ,Flauschig‘?! Mal sehen, wie ,allerliebst‘ du DAS findest!“","Einheit",["YORDLE"],["Ionia"],"SELTEN"],"01IO040":["Lebensklinge der Kinkou","","","„Einst standen hier unsere Schulen, Tempel, Behausungen. Jetzt wandern wir durch schattenverseuchte Ruinen. Zeds Orden hat das Erbe dieser heiligen Stätte geschändet. Dafür werden sie bezahlen.“","Einheit",[],["Ionia"],"GEWÖHNLICH"],"01IO041":["Karma","Rundenende: Erschaffe einen zufälligen Zauber aus deinen Regionen auf der Hand.","Du bist erleuchtet.","„Durch Besinnung können wir den Geist schärfen und einen Weg um jedes Hindernis finden.“","Einheit",[],["Ionia"],"Champion"],"01IO011":["Zurückrufen","Rufe einen Verbündeten zurück.","","Der kluge Kämpfer weiß, wann sein Kampf verloren ist. Ein erfolgreicher Rückzug bedeutet, an einem anderen Tag besser kämpfen zu können. ","Zauber",[],["Ionia"],"GEWÖHNLICH"],"01IO009":["Zed","Angriff: Beschwöre 1 angreifenden Lebender Schatten mit meinen Werten.","Ich habe gesehen, wie verbündete Lebende Schatten oder ich den gegnerischen Nexus zweimal geschlagen haben.","„Nur Narren nennen das Gleichgewicht ihren Meister. Die Schatten haben mir wahre Macht gezeigt.“","Einheit",[],["Ionia"],"Champion"],"01IO014":["Ältester der Grünlichtung","Wenn ich beschworen werde, gewähre Verbündeten auf der Hand +1|+1.","","Ionias Wissen wurde in Schriften festgehalten, doch es sind die Geschichten und Lehren der ehrwürdigen Ältesten, die den uralten Texten neues Leben schenken.","Einheit",[],["Ionia"],"GEWÖHNLICH"],"01IO005":["Flinker Poro","","","„Das klingt vielleicht verrückt, aber das Letzte, an das ich mich erinnere, ist ein … flauschiges Gefühl …?“\n– Brigant der Navori","Einheit",["PORO"],["Ionia"],"GEWÖHNLICH"],"01IO044":["Verschwörer der Navori","Rufe einen Verbündeten zurück, um mich auszuspielen.","","„Hopp hopp, wir müssen hier raus! Mein Name? Ich erklär dir alles unterwegs, versprochen …“","Einheit",[],["Ionia"],"GEWÖHNLICH"],"01IO023":["Juwelenverzierter Wachlöwe","Ausspielen: Ich gewähre einem Verbündeten auf der Hand +3|+3.","","„In Zeiten des Konflikts suchten Dorfbewohner die Wächterin des Herbsttals auf. Ihr Segen soll dabei helfen, das Blatt in der Schlacht noch wenden zu können.“\n– Sage der Ersten Lande","Einheit",[],["Ionia"],"SELTEN"],"01IO029":["Gesäte Saat","Gewähre Verbündeten auf der Hand +1|+0.","","„Nicht nur Samen, Sprösslinge. Das Erbe des Landes selbst, die Versprechen unserer blühenden Zukunft.“\n– Karma","Zauber",[],["Ionia"],"SELTEN"],"01IO003":["Zeichen des Todes","Entferne Vergänglich von einem Verbündeten und gewähre es einem Gegner.","","„Ich bin die Klinge in der Dunkelheit.“\n– Zed","Zauber",[],["Ionia"],"SELTEN"],"01IO047":["Schattenflamme","Gewähre ALLEN kämpfenden Begleitern Vergänglich.","","Wenn die Magieströme aus ihrem Gleichgewicht gebracht werden, fließen sie von der Geisterwelt in die der Sterblichen und bewirken dabei oft Verblüffendes.","Zauber",[],["Ionia"],"EPISCH"],"01IO026":["Inspirierender Mentor","Ausspielen: Ich gewähre einem Verbündeten auf der Hand +1|+0.","","„Hat mich Jahre gekostet, diese körperliche Verfassung zu erreichen! Ich habe Vögel aufgespürt, Wolken beobachtet und ein Blech Brötchen nach dem anderen geholt! Diese totale Hingabe ist für die meisten unerreichbar.“","Einheit",[],["Ionia"],"GEWÖHNLICH"],"01IO024":["Auf- und Untergang","Beschwöre 2 exakte Kopien eines Verbündeten. Sie sind vergänglich.","","„Shen ist zwischen den Gefahren zweier Welten hin- und hergerissen und er wird keine von beiden retten können. Ich widme mich voll und ganz Ionia.“\n– Zed","Zauber",[],["Ionia"],"SELTEN"],"01IO028":["Geschuppter Schnapper","Ausspielen: Gewähre mir +3|+0 oder +0|+3.","","Einer der ältesten Bewohner der Grünlichtung, der dank seiner ständigen Anpassung an die Umgebung die Zeit überdauert hat.","Einheit",["REPTIL"],["Ionia"],"GEWÖHNLICH"],"01IO057":["Schattenassassine","Wenn ich beschworen werde, ziehe 1.","","Grazil schreitet sie\nLeise Schritte im Schatten\nUnd kaum eine Spur.","Einheit",[],["Ionia"],"GEWÖHNLICH"],"01IO032":["Shen","Unterstützung: Ich gebe meinem unterstützten Verbündeten in dieser Runde Barriere.","Ich habe gesehen, wie Verbündete 5 Mal Barriere erhalten haben.","„Das Reich der Lebenden und das der Geister sind wie zwei verschränkte Hände miteinander verschlungen …“ ","Einheit",[],["Ionia"],"Champion"],"01IO013":["Schattenteufel","","","„Was würdest du für Macht opfern? Die Verwandlung beginnt mit einem Schwur, besiegelt auf der Haut …“\n– Zed","Einheit",[],["Ionia"],"GEWÖHNLICH"],"01IO018":["Schnelle","Gib einem Verbündeten in dieser Runde +1|+0 und Direktangriff.","","Im Kampf geht es nur darum, wer wem zuerst das Leben nehmen kann.","Zauber",[],["Ionia"],"GEWÖHNLICH"],"01IO056":["Yone, Windjäger","Ausspielen: Betäube 2 Gegner.","","„Als ich ein Kind war, fragte ich meinen Bruder: ‚Flieht der Wind oder folgt er?‘ Damals hat er bei mir Rat gesucht. Jetzt suche ich ihn, um Gerechtigkeit einzufordern.“\n","Einheit",[],["Ionia"],"SELTEN"],"01IO016":["Zephyr-Weiser","Ausspielen: Erschaffe eine exakte Kopie einer Karte auf der Hand außer Zephyr-Weiser.","","„Der Krieger betrauerte seinen Verlust, als der Älteste ihn tröstete: ,Suche nach dem Weisen der Himmel. Er bringt zurück, was in dieser Welt verloren, aber noch nicht vergessen ist.‘“\n– Sage der Ersten Lande","Einheit",["VOGEL"],["Ionia"],"SELTEN"],"01IO036":["Wachposten der Grünlichtung","Schlag: Senke die Kosten der teuersten Einheit auf der Hand um 1.","","„Patrouille, da kommt eine ... nein ... ZWEI riesige Pelzkreaturen auf uns zu! Erbitte Unterst… Oh. Moment. Hatte das Fernrohr schon wieder verkehrt rum …“","Einheit",["YORDLE"],["Ionia"],"GEWÖHNLICH"],"01IO033":["Minah Flinkfuß","Ausspielen: Rufe 3 Gegner zurück.","","„Wir sprinteten direkt über die Weide, als plötzlich dieses KIND wie aus dem Nichts angesprungen kam, und uns ZACK, BUMM, PENG über den Haufen schlug!“\n– Brigant der Navori","Einheit",[],["Ionia"],"EPISCH"],"01IO001":["Ritual der Erneuerung","Heile einen Verbündeten oder deinen Nexus um 4. Ziehe 1.","","„Nur, wenn der Geist erhaben ist, kann der Körper geheilt werden.“\n– Karma","Zauber",[],["Ionia"],"SELTEN"],"01IO010":["Geeinter Halt","Tausche 2 Verbündete miteinander. Gib ihnen in dieser Runde Barriere.","","„Jeder Schritt befindet sich im Gleichgewicht.“\n– Shen\n","Zauber",[],["Ionia"],"SELTEN"],"01IO022":["Geist","Gib einem Verbündeten in dieser Runde Ungreifbar.","","„Jetzt versteck dich … und komm nicht wieder, bis alles erledigt ist.“\n– Zed","Zauber",[],["Ionia"],"GEWÖHNLICH"],"01IO021":["Windflügel-Schlüpfling","Wenn ich beschworen werde, gib anderen Verbündeten in dieser Runde +2|+2.","","„Die ersten Frühlingsblüten sprießen an Ionias Klippen, wo die Flügelschläge der Schlüpflinge das Land in die sanften Winde der Jahreszeit hüllen.“\n– Sage der Ersten Lande","Einheit",[],["Ionia"],"EPISCH"],"01IO054":["Einsicht der Zeitalter","Erschaffe einen zufälligen anderen Zauber aus deinen Regionen auf der Hand.\nErleuchtet: Erschaffe 2.","","„Wenn du zweifelst, wisse, dass du niemals allein bist. Die Vergangenheit ist immer an unserer Seite. Sie kennt unzählige Versionen der Zukunft und all die Hoffnung, die sie mit sich bringen.“\n– Karma","Zauber",[],["Ionia"],"SELTEN"],"01IO027":["Stille Schattenseherin","Nexusschlag: Erschaffe eine Kopie von mir auf der Hand.","","„Einem sterblichen Körper kann man nicht trauen. Er ist zerbrechlich. Fein wie die Grenze zwischen Licht und Schatten.“","Einheit",[],["Ionia"],"EPISCH"],"01IO031":["Wolkenschwimmer","Deine Sofort- und Fokuszauber kosten 1 weniger.","","Seinen Gesang konnte man selbst in den Dörfern hören: Lange, tiefe Tonwellen, die aus den Himmeln über die Hügel flossen, jede von ihnen so formlos und fremd wie die Wolken eines Nachmittags.","Einheit",[],["Ionia"],"SELTEN"],"01IO002":["Ionias Wille","Rufe eine Einheit zurück.","","Als Eindringlinge zum ersten Mal Fuß auf ionischen Boden setzten, wurde ihnen klar, dass es nicht reichen würde, nur die Einwohner dieses Landes zu erobern.","Zauber",[],["Ionia"],"GEWÖHNLICH"],"01IO017":["Klingenspäher der Navori","Wenn ich beschworen werde, gib mir in dieser Runde Ungreifbar.","","„Ich werd ihn überraschen. Kinderspiel. Hilf mir bei der Flucht und ich teil die Beute mit dir, du wirst es garantiert nicht bereuen!“","Einheit",["YORDLE"],["Ionia"],"GEWÖHNLICH"],"01IO042":["Energischer Schüler","Wenn du einen anderen Verbündeten beschwörst, gib mir in dieser Runde +1|+1.","","„Wozu sollte ich kämpfen, wenn niemand zusieht und meine Technik bewundert?“","Einheit",[],["Ionia"],"GEWÖHNLICH"],"01IO006":["Duo der Grünlichtung","Wenn du einen anderen Verbündeten beschwörst, gib mir in dieser Runde +1|+0.","","„He, pass auf die Äste auf! Links, LINKS!“\n„Wenn ich auf DEINER Schulter sitze, kannst du die Richtung vorgeben. Ansonsten hab ich das Sagen!“","Einheit",[],["Ionia"],"SELTEN"],"01IO050":["Wegfinderin der Kinkou","Loyalität: Beschwöre einen Verbündeten mit 1 Kosten aus deinem Deck.","","Wo sie auch hingeht, sie sorgt dafür, dass andere ihr folgen können.","Einheit",[],["Ionia"],"SELTEN"],"01IO048":["Yusari","","","„Euer Orden hat uns aus unserer Heimat vertrieben. Ihr habt Eure Macht bewiesen, Meister Zed. Nun lasst mich beweisen, dass auch ich Eurer Lehren würdig bin.“","Einheit",[],["Ionia"],"SELTEN"],"01IO007":["Ren Schattenklinge","Schlag: Erschaffe 1 Schattenteufel auf der Hand.","","„Fliehe. Kämpfe. Erschaudere. Ganz egal, die Schatten werden dich holen.“","Einheit",[],["Ionia"],"EPISCH"],"01IO053":["Smaragdgrüner Erwecker","Erleuchtet: Ich habe +4|+4.","","„Der Krieg nährt sich von unseren Urinstinkten. Aber Instinkte haben keine Macht über unsere wichtigsten Tugenden: Vertrauen, Geduld und Besinnung.“","Einheit",[],["Ionia"],"GEWÖHNLICH"],"01IO004":["Heiltrank","Heile einen Verbündeten oder deinen Nexus um 3.","","Jede Generation, Region und Familie hat ihr eigenes Hausmittelchen – aber manche sind zweifellos effektiver als andere.","Zauber",[],["Ionia"],"GEWÖHNLICH"],"01IO049":["Verwehren","Halte einen Schnellzauber, einen langsamen Zauber oder eine Fertigkeit auf.","","Nein.","Zauber",[],["Ionia"],"SELTEN"],"01IO052":["Wegelagerer der Navori","Wenn ich beschworen werde, beschwöre 1 Brigant der Navori mit meinen Werten.","","„Ich war ein Wandermusiker, bekannt von hier bis zum Plazidium, bis die Noxianer kamen. Jetzt halte ich mich mit Diebstählen über Wasser. Meine Mutter hatte recht. Wäre ich nur Heiler geworden …“","Einheit",[],["Ionia"],"GEWÖHNLICH"],"01IO030":["Das Empyreum","","","„Der Himmel selbst ächzte, als Wolkenwirbel und mächtige Böen unsere Brigade niederwehten. Wir wollten ihm folgen, aber wer kann dem Wind hinterherjagen?“\n– General der Legion","Einheit",["DRACHE"],["Ionia"],"EPISCH"],"01IO019":["Hüterin der Grünlichtung","Wenn ein Verbündeter Barriere erhält, gewähre mir +2|+0.","","„Die Lichtung beschützt ihre Bewohner. Und du … du kommst nicht von hier …“","Einheit",[],["Ionia"],"GEWÖHNLICH"],"01IO046":["Stahlsturm","Betäube einen angreifenden Gegner.","","„Hasagi!“\n– Yasuo","Zauber",["ELEMENTAR"],["Ionia"],"SELTEN"],"01IO037":["Spirituelle Zuflucht","Gib einem Verbündeten in dieser Runde Barriere und Lebensraub.","","„Die Klinge gehörte einst meinem Vater. Möge sie dir die Stärke verleihen, die mir damals gefehlt hat.“\n– Shen","Zauber",[],["Ionia"],"GEWÖHNLICH"],"01IO043":["Flussformer","Schlag: Ziehe einen Zauber.","","„Wir sind die stolzen Kinder der Ersten Lande, und die Wellen ihrer Magie fließen sowohl in unserem vastayanischen Blut als auch durch unser Reich.“","Einheit",[],["Ionia"],"SELTEN"],"01IO038":["Einsame Geistliche","Ausspielen: Rufe alle anderen Verbündeten zurück.","","„Meine Reflexe und mein Instinkt sind die einzigen Begleiter, die ich mir wünsche.“","Einheit",[],["Ionia"],"SELTEN"],"01IO039":["Schattenwechsel","Rufe einen Verbündeten zurück, um 1 Lebender Schatten an seiner Stelle zu beschwören.","","Stehst du dem Gegner gegenüber, den du zu sehen glaubst? Oder ist es eine Täuschung der Schatten?","Zauber",[],["Ionia"],"GEWÖHNLICH"],"01IO055":["Schützer des Qi","Gewähre einem Verbündeten auf der Hand Barriere. Ziehe 1.","","„Diejenigen, die das Gleichgewicht wahren, erfahren den Schutz der Kinkou.“\n– Shen\n","Zauber",[],["Ionia"],"GEWÖHNLICH"],"01NX020":["Draven","Wenn ich beschworen werde oder zuschlage: Erschaffe 1 Wirbelnde Axt auf der Hand.","Ich habe mit insgesamt 2+ Wirbelnde Äxte zugeschlagen.","„Du willst ein Autogramm? Stell dich hinten an, Kumpel.“","Einheit",[],["Noxus"],"Champion"],"01NX006":["Vladimir","Ausspielen: Verursache 1 Schaden an beliebig vielen Verbündeten, um die gleiche Menge Schaden an einem Gegner zu verursachen.","5+ Verbündete haben Schaden überlebt.","Gnadenlos. Kaltblütig. Grausam. Faszinierend. Scharfsinnig. Bezaubernd. Unwiderstehlich …","Einheit",[],["Noxus"],"Champion"],"01NX004":["Unerbittlicher Schlag","Töte eine Einheit mit 3 oder weniger Stärke.","","Jeder stirbt irgendwann. Die Schwachen sterben nur schneller.","Zauber",[],["Noxus"],"SELTEN"],"01NX048":["Scharlachroter Kurator","Wenn ich Schaden überlebe, erschaffe eine zufällige scharlachrote Einheit auf der Hand.","","„Die Damen und Herren!“ „–Einladung, ja. Der Ball der Nachtschwärmer! Was denkt ihr?“ „Oh, dann gehen wir!“ „Endlich trefft ihr meine Familie.“ „Entweder das, oder gar nichts! Kye? Kommst du mit?“","Einheit",[],["Noxus"],"GEWÖHNLICH"],"01NX038":["Darius","","Ich sehe, dass der gegnerische Nexus die Hälfte seines anfänglichen Lebens oder weniger hat.","„Ein eiserner Wille und die Stärke eines Titanen. Kein General könnte die trifarianische Legion besser anführen.“\n– Swain","Einheit",[],["Noxus"],"Champion"],"01NX023":["Arachnoider Wirt","Wenn ich beschworen werde, gewähre anderen verbündeten Spinnen +2|+0.","","Ein Blick genügt, und du gehörst ihr. Ein einziger Biss, und du gehörst ihnen.","Einheit",["SPINNE"],["Noxus"],"SELTEN"],"01NX013":["Entscheidendes Manöver","Betäube einen Gegner. Gib allen Verbündeten in dieser Runde +2|+0.","","„Jeder Narr kann seinen Gegner mit einer überwältigenden Militärgewalt konfrontieren. Es benötigt Weitsicht, diese Macht bis zum entscheidenden Moment zu verbergen.“\n– Swain","Zauber",[],["Noxus"],"SELTEN"],"01NX046":["Arachnoide Wache","Ausspielen: Betäube einen Gegner.","","„Oh, wie sie mich fesselt! Ihre endlos langen Beine, ihre betörend süße Stimme und ihre Augen, so rot wie Rosen. Dass sie heute ausgerechnet mit mir speisen möchte …!“\n– Glückloser Aristokrat","Einheit",["SPINNE"],["Noxus"],"GEWÖHNLICH"],"01NX047":["Transfusion","Verursache 1 Schaden an einem Verbündeten und gib einem anderen in dieser Runde +2|+2.","","„Es ist ein Geben und Nehmen, meine Lieben. Ihr gebt, und ich nehme.“\n– Vladimir","Zauber",[],["Noxus"],"GEWÖHNLICH"],"01NX040":["Saboteurin der Legion","Angriff: Verursache 1 Schaden am gegnerischen Nexus.","","„Unsere Schildbrecher können einen Mann zweiteilen. Aber die Legion verfügt über andere Möglichkeiten, wenn ein etwas … feineres Händchen nötig ist.“\n– Swain","Einheit",[],["Noxus"],"GEWÖHNLICH"],"01NX025":["Brüderliche Bande","Gewähre 2 Verbündeten +2|+0.","","„Bande, die im Krieg geschmiedet werden, sind so stark wie die einer Familie. Ja, in beiden Fällen teilt man Blut.“\n– Veteran der Legion","Zauber",[],["Noxus"],"GEWÖHNLICH"],"01NX055":["Hausspinne","Wenn ich beschworen werde, beschwöre 1 Jungspinne.","","„Meine Spinnen lieben Gesellschaft. Schade, dass die Gesellschaft sich nie auch so fühlt.“\n– Elise","Einheit",["SPINNE"],["Noxus"],"GEWÖHNLICH"],"01NX030":["Scharlachrote Adeptin","Wenn ich Schaden überlebe, verursache 1 Schaden am gegnerischen Nexus.","","„Ich habe gerade an dich gedacht, mein lieber Edvin! Hast du sie auch bekommen?“ „Sehr gut.“ „An meinem Arm? Ich würde dir mein Geleit anbieten.“ „Traumhaft. Was meinst du, Edvin?“","Einheit",[],["Noxus"],"SELTEN"],"01NX007":["Arena-Kampfkommentator","Angriff: Ich gebe anderen angreifenden Verbündeten in dieser Runde +1|+0.","","Er schrie vor Entzückung. In diesem Augenblick schlug das Herz der Arena im Gleichklang mit seinem und die Aufregung des Publikums lag fest in seiner triumphierenden Hand.","Einheit",[],["Noxus"],"SELTEN"],"01NX021":["Marodeur der Legion","Angriff: Ich gewähre verbündeten Marodeuren der Legion überall +1|+1.","","Auf den Fersen der trifarianischen Legion folgen stets opportunistische Briganten, die es auf die zurückgelassenen Schwachen und Verletzten abgesehen haben.","Einheit",[],["Noxus"],"GEWÖHNLICH"],"01NX009":["Publikumsliebling","Wenn ich beschworen werde, gewähre mir +1|+1 pro Verbündeten, den du hast.","","Einige Vergelter heben sich durch Charisma ab, andere durch ihre Technik. Vessid kann mit nichts davon dienen, aber kein anderer verwandelt seine Gegner effizienter in eine Blutlache.","Einheit",[],["Noxus"],"SELTEN"],"01NX011":["Wirbelnder Tod","Ein kämpfender Verbündeter schlägt einen kämpfenden Gegner.","","„Ich habe den besten Job.“\n– Draven","Zauber",[],["Noxus"],"GEWÖHNLICH"],"01NX053":["Vergeltung","Wenn du einen Verbündeten mit 5+ Stärke hast, töte ALLE Einheiten mit 4 oder weniger Stärke.","","„DIE MENGE TOBT! JETZT WIRD ABGERECHNET!“\n– Arena-Kampfkommentator","Zauber",[],["Noxus"],"EPISCH"],"01NX054":["Einschüchterndes Gebrüll","Betäube alle Gegner mit 4 oder weniger Stärke.","","„Er atmet tief ein – vielleicht sehen wir einen – ja, da ist er, Leute! Das ist Thunders berühmter Kriegsruf! Wir zittern hier wie Espenlaub, Thuuuuuunder!“\n– Arena-Kampfkommentator","Zauber",[],["Noxus"],"SELTEN"],"01NX029":["Veteran der Legion","Wenn ein anderer Verbündeter Schaden überlebt, gewähre ihm +1|+0.","","Er lag im Sterben, als er aus dem Krieg zurückkehrte. Nur die Fürsorge seines Ehemanns und die Salben des Apothekers konnten ihn heilen. Noxus scheute keine Kosten, um seinen Expertenrat zu sichern.","Einheit",[],["Noxus"],"EPISCH"],"01NX014":["Shiraza die Klinge","Ich verursache doppelten Schaden am Nexus.","","„Was hat er gesagt?! Dieser Mann hat nur Stroh im Kopf. Aber diese Schultern sind einfach einmalig …“","Einheit",[],["Noxus"],"EPISCH"],"01NX042":["Katarina","Wenn ich beschworen werde, erschaffe 1 flüchtiges Auf Messers Schneide auf der Hand.","Ich habe einmal zugeschlagen. Wenn ich eine Stufe aufsteige, rufe mich zurück.","„Es geht nichts über ein bisschen demacianische Zielübungen, um die Sinne zu schärfen …“","Einheit",[],["Noxus"],"Champion"],"01NX051":["Hauptmann Farron","Wenn ich beschworen werde, erschaffe 2 Exemplare von Dezimieren auf der Hand.","","Tief in der Grube von Zhaun galt der junge Benn Farron als Bedrohung. Unberechenbar. Unhaltbar. In den noxianischen Reihen wurde er willkommen geheißen. Anerkannt. Gefördert.","Einheit",[],["Noxus"],"EPISCH"],"01NX012":["Nachhut der Legion","","","In Noxus, wo Soldaten für ihre Kühnheit auf dem Schlachtfeld verehrt werden, kommt die Einteilung in die Nachhut einer Bestrafung gleich.","Einheit",[],["Noxus"],"GEWÖHNLICH"],"01NX043":["Auf Messers Schneide","Verursache 1 Schaden an einem beliebigen Ziel.","","„In den richtigen Händen kann eine Klinge alles durchtrennen … und ich meine wirklich alles.“\n– Katarina","Zauber",[],["Noxus"],"GEWÖHNLICH"],"01NX037":["Grenadier der Legion","Letzter Wunsch: Verursache 1 Schaden am gegnerischen Nexus.","","Jedem Noxianer wird eingebläut, dass ein Leben im Dienst des Imperiums ein erfüllendes Leben ist, aber nur wenige verbringen ihre Tage so spektakulär wie die Grenadiere der Legion.","Einheit",[],["Noxus"],"GEWÖHNLICH"],"01NX010":["General der Legion","Wenn ich beschworen werde, gewähre mir +1|+1 pro Einheit, die du in diesem Spiel betäubt oder zurückgerufen hast.","","Alle Noxianer kennen die drei Prinzipien der Stärke, aber wenn sich ein Soldat erfolgreich hocharbeiten will, muss er lernen, sie alle zu meistern.","Einheit",[],["Noxus"],"GEWÖHNLICH"],"01NX017":["Trommlerin der Legion","Unterstützung: Ich gebe meinem unterstützten Verbündeten in dieser Runde Direktangriff.","","Die Legion verkündete die Ausdehnung des Imperiums mit jedem Trommelschlag. Nichts konnte sie aufhalten. Nichts hielt sie auf.","Einheit",[],["Noxus"],"GEWÖHNLICH"],"01NX003":["Arena-Buchmacher","Rundenbeginn: Wirf deine günstigste Karte ab und ziehe 1.","","„… du hast auf Shiraza als EINZIGE ÜBERLEBENDE gesetzt, und dieser ionische Junge, dem fehlt zwar ein Arm, aber er ist nicht tot. Also hat er überlebt. Du kannst natürlich den Einsatz verdoppeln …“","Einheit",["YORDLE"],["Noxus"],"SELTEN"],"01NX039":["Weitsicht","Gewähre beim Ausspielen oder Abwerfen allen Verbündeten +1|+0.","","„Diejenigen, die die Zukunft nicht sehen können, haben keinen Platz in ihr.“\n– Jericho Swain","Zauber",[],["Noxus"],"SELTEN"],"01NX041":["Trifarianischer Schildbrecher","","","„Mir fehlt die nötige Geduld für eine Belagerung. Schickt die Schildbrecher.“\n– Darius","Einheit",[],["Noxus"],"GEWÖHNLICH"],"01NX036":["Minotaurus-Vergelter","Rundenbeginn: Betäube den schwächsten Gegner.","","„Mir ist egal, wer dir wie Unrecht getan hat. Wenn ich es da unten begleichen soll, will ich zuerst das Geld sehen. Es gibt keinen Rabatt für rührselige Geschichten.“","Einheit",[],["Noxus"],"SELTEN"],"01NX044":["Rammbock","Angriff: Gewähre mir +4|+0.","","„Sir, sie weigern sich, ihre Tore zu öffnen. Sie verlangen, mit Darius zu reden, aber er ist zwei Tagesritte entfernt. Sollen wir Reiter aussenden?“\n„Oh, das wird nicht nötig sein.“","Einheit",[],["Noxus"],"EPISCH"],"01NX005":["Scharlachrote Aristokratin","Ausspielen: Verursache 1 Schaden an einem Verbündeten und gewähre ihm +1|+0 und Überwältigen.","","„Riecht nach einer idealen Gelegenheit.“ „Wie soll ich meine nur ertragen?“ „Reizende Idee, aber mein Vater würde mich enterben. … Wir könnten allerdings unsere Outfits aufeinander abstimmen.“","Einheit",[],["Noxus"],"GEWÖHNLICH"],"01NX016":["Trifarianischer Hoffnungsträger","Wenn ich beschworen werde, gewähre mir +2|+0, wenn du einen anderen Verbündeten aus Noxus hast.","","„Du verdienst dir den Titel, wenn deine Axt vom Kampf stumpf ist und deine Stiefel mit Blut durchtränkt sind.“\n– Veteran der Legion","Einheit",[],["Noxus"],"GEWÖHNLICH"],"01NX019":["Macht","Gib einem Verbündeten in dieser Runde +3|+0 und Überwältigen.","","„Wenn ich sage, dass Raffinesse überbewertet wird, heißt das nicht, dass sie nutzlos ist. Sie ist einfach nur überbewertet.“\n– Darius","Zauber",[],["Noxus"],"GEWÖHNLICH"],"01NX015":["Geliebtes Haustier","","","Sie liebt sie alle. Sie liebt diese eine einfach nur etwas mehr.","Einheit",["SPINNE"],["Noxus"],"GEWÖHNLICH"],"01NX050":["Todeslotus","Verursache 1 Schaden an ALLEN kämpfenden Einheiten.","","„Tanze mit mir.“\n– Katarina","Zauber",[],["Noxus"],"SELTEN"],"01NX056":["Shunpo","Verursache 2 Schaden an einem Gegner, dann mobilisiere dich.","","Wenn du die Klinge bemerkst, ist es schon zu spät.","Zauber",[],["Noxus"],"GEWÖHNLICH"],"01NX033":["Trifarianische Beurteilerin","Wenn ich beschworen werde, ziehe 1 pro Verbündeten mit 5+ Stärke, den du hast.","","„Nur ein gnadenlos kritisches Auge kann erkennen, wer für die trifarianische Legion geeignet ist. Und sie kann Wölfe bereits von weitem von Schafen unterscheiden.“\n– General der Legion","Einheit",[],["Noxus"],"SELTEN"],"01NX052":["Blut für Blut","Verursache 1 Schaden an einem verbündeten Begleiter. Wenn er überlebt, erschaffe eine Kopie von ihm auf der Hand.","","Nichts richtet eine größere Sauerei an als die erste Lektion eines Hämomanten.","Zauber",[],["Noxus"],"GEWÖHNLICH"],"01NX045":["Brutaler Vergelter","","","„Nächster ist KLAUE! War letztens ein BLUTIGES Gemetzel gegen die Psycho Fünf … jetzt die Psycho Drei. Alles klaaar! Setzt jetzt auf das heutige Opfer. Vier zu eins!“\n– Karl, Arena-Buchmacher","Einheit",[],["Noxus"],"SELTEN"],"01NX031":["Ruhmsuchende Trifarianerin","","","Die meisten sind zufrieden, nachdem sie sich einen Platz in der trifarianischen Legion gesichert haben … aber nicht alle.","Einheit",[],["Noxus"],"SELTEN"],"01NX002":["Dezimieren","Verursache 4 Schaden am gegnerischen Nexus.","","„Manchmal braucht es ein taktisches Genie, um eine Festung zu stürmen. Und manchmal muss man einfach fester zuschlagen.“\n– Darius","Zauber",[],["Noxus"],"SELTEN"],"01NX008":["Basilisk-Reiter","Loyalität: Gewähre mir +1|+1 und Überwältigen.","","Diese spezielle Einheit verwendet auch Pferde, nur nicht zum Reiten. Die Bestien finden sie köstlich.","Einheit",[],["Noxus"],"SELTEN"],"01NX034":["Anhänglicher Poro","","","„Noxus hat keinen Platz für … für Schwä… Kann mal jemand dieses VERDAMMTE DING von mir nehmen?!“\n– Darius","Einheit",["PORO"],["Noxus"],"GEWÖHNLICH"],"01NX035":["Dravens größter Fan","Wenn ich beschworen werde, bewege Draven an die Spitze deines Decks, falls du ihn nicht auf der Hand oder dem Spielfeld hast.","","„Du willst ein Autogramm? Stell … Stell dich hinten an, Kumpel.“","Einheit",[],["Noxus"],"GEWÖHNLICH"],"01NX026":["Waghalsiger Trifarianer","","","„Waghalsigkeit ist eine Schwäche. In der Legion kann sie jedoch zu einem Werkzeug geformt werden.“\n– Swain","Einheit",[],["Noxus"],"GEWÖHNLICH"],"01NX027":["Elixier des Zorns","Gib einem Verbündeten in dieser Runde +3|+0.","","„Wenn die offene Hand abgelehnt wird, gibt es immer noch die Faust.“\n– Noxianische Redewendung","Zauber",[],["Noxus"],"GEWÖHNLICH"],"01NX022":["Noxianische Guillotine","Töte eine verletzte Einheit und erschaffe eine flüchtige Noxianische Guillotine auf der Hand.","","Darius versteht Gnade als einen gut gezielten Hieb.","Zauber",[],["Noxus"],"SELTEN"],"01NX032":["Scharlachroter Erwecker","Wenn ich beschworen werde, verursache 1 Schaden an allen anderen Verbündeten.","","„Tja … selbst wenn ich Nein sage, würdet ihr mich mitschleifen. Also was auch immer.“","Einheit",[],["Noxus"],"SELTEN"],"01NX024":["Kato der Arm","Unterstützung: Ich gebe meinem unterstützten Verbündeten in dieser Runde +3|+0 und Überwältigen.","","„Shiraza ist eine tolle Freundin. Rein platonisch, wir sind echt nicht zusammen. Aber wenn wir es wären, würde ich ihr einen wundervollen Jahrestag wünschen. Danke, keine weiteren Fragen bitte.“","Einheit",[],["Noxus"],"EPISCH"],"01NX049":["Intrige","Betäube einen Gegner.","","„Gewähre deinem Feind genügend Seil, mit dem er sich aufknüpfen kann, und man spart sich die Mühe, ihn zum Galgen schleifen zu müssen.“\n– LeBlanc","Zauber",[],["Noxus"],"GEWÖHNLICH"],"01DE031":["Redner der Dämmerung","Rundenende: Gewähre anderen Verbündeten +1|+1, falls in dieser Runde ein Verbündeter gestorben ist.","","„Die Stunde mag dem Bösen gehören, doch den Tag gewinnen sie nicht. Gedenkt unseren Gefallenen und tragt diese Erinnerungen wie eine Rüstung!“","Einheit",[],["Demacia"],"EPISCH"],"01DE022":["Lucian","","Ich habe gesehen, wie 4+ Verbündete oder eine verbündete Senna gestorben sind.","„Mir geht es gut, Senna, so lange ich dich habe.“","Einheit",[],["Demacia"],"Champion"],"01DE019":["Mobilisierung","Senke die Kosten von Verbündeten auf der Hand um 1.","","„Innerhalb von zwei Wochen vom Feld an die Front. Das erwarten wir von jedem körperlich gesunden Demacianer.“\n– Garen","Zauber",[],["Demacia"],"SELTEN"],"01DE042":["Lux","","Ich habe gesehen, dass du 6+ Mana für Zauber eingesetzt hast. Wenn ich eine Stufe aufsteige, erschaffe ein Finales Funkeln auf der Hand.","„Ich wusste immer, dass an mir etwas anders ist … ein Licht im Inneren. Ich weiß nicht, was es ist, aber ich muss es verstehen lernen!“ ","Einheit",[],["Demacia"],"Champion"],"01DE010":["Flinkschwingen-Lanzenreiter","Letzter Wunsch: Erschaffe eine zufällige Elite auf der Hand.","","„Es braucht ein tapferes Herz, um sein Leben einer Silberschwinge anzuvertrauen und weit über festem Boden zu kämpfen. Tapfer und unerschütterlich.“\n– Garen","Einheit",["ELITE","VOGEL"],["Demacia"],"SELTEN"],"01DE020":["Verteidiger der Vorhut","","","„Wir wussten nicht, wer oder was diese Kreaturen waren. Wir kannten jedoch die Gesichter der Soldaten an unserer Seite, und mehr brauchten wir nicht.“","Einheit",["ELITE"],["Demacia"],"GEWÖHNLICH"],"01DE034":["Kampfschmied","Wenn du eine Elite beschwörst, gewähre ihr +1|+1.","","Kriege werden in der Schmiede gewonnen.","Einheit",[],["Demacia"],"SELTEN"],"01DE002":["Tianna Kronwacht","Wenn ich beschworen werde, mobilisiere dich.","","„Unser Haus hat für dieses Reich geblutet. Du wirst die Ehre dieser Familie nicht für ein paar Lichtspielereien wegwerfen.“","Einheit",[],["Demacia"],"EPISCH"],"01DE012":["Garen","Wenn ich beschworen werde, gib anderen Verbündeten in dieser Runde +1|+1.","Ich habe zwei Mal zugeschlagen.","Training und Ausdauer sind das Zeichen des Soldaten. Selbst im Angesicht großer Gefahr geben wir nicht auf.","Einheit",["ELITE"],["Demacia"],"Champion"],"01DE017":["Unabhängig","Wenn du genau 1 Verbündeten hast, gewähre ihm +3|+3.","","Wenn andere scheitern, fällt es einem wahren Helden zu, den Weg zum Sieg zu finden.","Zauber",[],["Demacia"],"SELTEN"],"01DE045":["Fiora","","Ich habe 2 Gegner getötet.","„Von der Arena bis zum Turnier, vom Übungsgelände bis zum Schlachtfeld, ich sehne mich nach einem würdigen Gegner und werde nicht ruhen, bis ich zweifellos die Beste bin.“","Einheit",[],["Demacia"],"Champion"],"01DE052":["Blankstahl-Formation","Wenn ich beschworen werde oder angreife: Gib Verbündeten in dieser Runde Barriere.","","„Diese Formation ist eine taktische Grundlage. Sie erfordert, dass jeder Soldat in seinen Schild vertraut und den Schilden seiner Gefährten. Solange sie standhalten, wird unser Reich es auch.“\n– Garen\n","Einheit",[],["Demacia"],"EPISCH"],"01DE021":["Erbarmungslose Verfolgung","Mobilisiere dich.",""," „Jeder muss sich seinen Ängsten stellen. Du hast Glück, dass ich jetzt hier bin.“\n– Lucian\n","Zauber",[],["Demacia"],"GEWÖHNLICH"],"01DE025":["Festnehmen","Ein Verbündeter hält eine Einheit fest.","","„Füge dich uns. Wir sind das Gesetz und du unterliegst ihm. Das ist alles.“\n– Überzeuger der Magiesuchenden","Zauber",[],["Demacia"],"GEWÖHNLICH"],"01DE007":["Urteil","Ein kämpfender Verbündeter schlägt alle kämpfenden Gegner.","","Der Kreis der Gerechtigkeit schließt sich immer.","Zauber",[],["Demacia"],"EPISCH"],"01DE055":["Duellant der Laurent","Ausspielen: Gewähre einem Verbündeten auf der Hand Herausforderer.","","„Er war ein aufgeblasener Schnösel mit teurer Klinge, aber konnte wirklich mit ihr umgehen! Ich würde eine Revanche fordern, aber konnte mir seinen Namen nicht merken.“\n– Demacianischer Fähnrich","Einheit",[],["Demacia"],"GEWÖHNLICH"],"01DE048":["Anstifter der Magiesuchenden","Gewähre mir +2|+2, sobald du in diesem Spiel einen Zauber mit 6+ Kosten ausgespielt hast.","","„Einst zwang die wilde Magie der Runenkriege Runeterra in die Knie. So entstand unser Orden, um unser Königreich zu beschützen und es von Magie – egal ob von außen oder innen – zu befreien.“\n– Handbuch der Magiesuchenden","Einheit",[],["Demacia"],"SELTEN"],"01DE001":["Bannerträger der Vorhut","Loyalität: Ich gewähre anderen Verbündeten +1|+1.","","„Wisse um die Bedeutung unseres Banners. Es weht für unseren König, unsere Häuser, unsere Bürger. Es ist unser unerschütterlicher Glaube an Demacia selbst. Halte es hoch. Zeig ihnen unseren Stolz.“\n– Tianna Kronwacht ","Einheit",["ELITE"],["Demacia"],"SELTEN"],"01DE043":["Kriegsköche","Unterstützung: Ich gebe meinem unterstützten Verbündeten in dieser Runde +1|+1.","","In der demacianischen Armee ist mit niemandem zu spaßen.","Einheit",[],["Demacia"],"GEWÖHNLICH"],"01DE049":["Mutiger Poro","","","„Der neue Rekrut steht unseren besten Soldaten in Ausdauer und Tapferkeit nichts nach. Wird er es in die Vorhut schaffen? Er ist … kleiner als der Rest, aber wir werden sehen.“\n– Feldwebel der Vorhut","Einheit",["PORO"],["Demacia"],"GEWÖHNLICH"],"01DE053":["Chevalier der Laurent","Schlag: Erschaffe einen anderen zufälligen Begleiter mit Herausforderer aus deinen Regionen auf der Hand.","","„… Meine Güte.“\n– Fiora","Einheit",[],["Demacia"],"EPISCH"],"01DE033":["Gedenken","Ich koste 1 weniger für jeden Verbündeten, der in dieser Runde gestorben ist. Beschwöre einen zufälligen Begleiter aus Demacia mit 5 Kosten.","","„Heute erheben wir uns, um das Unrecht zu vergelten, das unsere Vorgänger ereilt hat. Die Opfer unserer Kameraden waren nicht umsonst.“\n– Brillante Wächterin","Zauber",[],["Demacia"],"SELTEN"],"01DE044":["Erneuerter Heldenmut","Heile einen Verbündeten vollständig, verdopple dann seine Stärke und sein Leben.","","In Demacia ist es nicht nur Angeberei, dass man es allein mit zwei Gegnern aufnehmen kann.","Zauber",[],["Demacia"],"SELTEN"],"01DE024":["Sichersteller der Magiesuchenden","Letzter Wunsch: Erschaffe einen zufälligen Zauber aus einer anderen Region als Demacia mit 6+ Kosten auf der Hand.","","„Arkane Gegenstände sind zweifelsohne faszinierend. Diese Objekte der Macht sollten jedoch unseren Experten überlassen werden, sicher vor der gut gemeinten Ignoranz der Bürger.“\n– Handbuch der Magiesuchenden","Einheit",[],["Demacia"],"GEWÖHNLICH"],"01DE004":["Silberschwingen-Vorhut","Ausspielen: Beschwöre eine exakte Kopie von mir.","","Sie fuhren wie silberne Blitze aus den Wolken herab, flink und sicher im Sturz auf ihre Ziele. Danach waren sie so schnell verschwunden, wie sie gekommen waren. ","Einheit",["ELITE","VOGEL"],["Demacia"],"GEWÖHNLICH"],"01DE011":["Meisterschüler der Laurent","","","„Er hat WAS getan? Ich habe ihm Pierre de Guillards unbezahlbaren Säbel anvertraut! Er hat gesagt, er braucht ihn nur zum Training!“\n– Klingenmeister der Laurent","Einheit",[],["Demacia"],"GEWÖHNLICH"],"01DE047":["Nachfolge","Beschwöre 1 Unerschrockene Vorhut.","","Die Trachten der unerschrockenen Vorhut werden von einem Soldaten an den nächsten übergeben, damit die neuen Rekruten die Bürde und den Stolz ihrer Verantwortungen spüren können.","Zauber",[],["Demacia"],"GEWÖHNLICH"],"01DE046":["Grenzposten der Vorhut","","","Nur weil es ruhig scheint, ist es noch lange nicht sicher.","Einheit",["ELITE"],["Demacia"],"GEWÖHNLICH"],"01DE050":["Läutern","Lasse einen Begleiter verstummen.","","„Dein Graumal aus Petrizit ist dein Hauptschutz gegen Magie, ein Symbol unserer Pflichten und eine Erinnerung für andere an unsere Autorität. Ehre es über allem.“\n– Handbuch der Magiesuchenden","Zauber",[],["Demacia"],"GEWÖHNLICH"],"01DE040":["Überzeuger der Magiesuchenden","Gewähre mir +1|+1 und Herausforderer, sobald du in diesem Spiel einen Zauber mit 6+ Kosten ausgespielt hast.","","„Bürger von Demacia, es ist mir eine Ehre, euch zu schützen. Doch dafür benötigen wir eure unbeirrte Unterstützung, denn selbst innerhalb unserer Mauern befinden sich Magier!“\n","Einheit",[],["Demacia"],"SELTEN"],"01DE036":["Novizin der Vorhut","Wenn du eine Elite beschwörst, senke meine Kosten um 1.","","„Jede Begegnung und jede Reise hat mir etwas Neues beigebracht. Aber je mehr ich lernte und je stärker ich wurde, desto mehr begriff ich, dass mir noch viel bevorstand …“\n– Cithria, Novizin der Vorhut\n","Einheit",["ELITE"],["Demacia"],"GEWÖHNLICH"],"01DE037":["Konter","Gib einem Verbündeten in dieser Runde +3|+0 und Barriere.","","„Wie passend! Du kämpfst wie ein Poro!“\n– Fiora","Zauber",[],["Demacia"],"SELTEN"],"01DE014":["Verstärkung","Beschwöre 2 Einheiten der Unerschrockenen Vorhut, gewähre dann Eliteverbündeten +1|+1.","","„Unsere Widersacher wissen, dass ein Angriff gegen einen von uns ein Angriff auf uns alle ist.“\n– Kodex der Vorhut","Zauber",[],["Demacia"],"SELTEN"],"01DE015":["Brillante Wächterin","Wenn ich beschworen werde, gewähre mir Lebensraub und Robust, falls in dieser Runde ein Verbündeter gestorben ist.","","„Wellen aus kalten, untoten Händen zogen ihre Gefährten nach unten. Nur sie blieb übrig, ein Leuchtfeuer der Gerechtigkeit, dessen Klinge die Namen der Gefallenen widerhallte.“\n– Demacianischer Fähnrich","Einheit",[],["Demacia"],"SELTEN"],"01DE003":["Klingenmeister der Laurent","Ausspielen: Ich gewähre einem Verbündeten +2|+2.","","„Ja, sie sind schön. Doch wie bei jedem eleganten Instrument entfaltet sich ihre wahre Schönheit erst in den Händen eines Meisters.“ ","Einheit",[],["Demacia"],"SELTEN"],"01DE026":["Einzelkampf","Ein Verbündeter und ein Gegner schlagen sich gegenseitig.","","„Spar dir die Worte, lassen wir unsere Schwerter sprechen.“\n– Fiora","Zauber",[],["Demacia"],"GEWÖHNLICH"],"01DE032":["Prismatische Barriere","Gib einem Verbündeten in dieser Runde Barriere.","","„Die Welt kann einem den Rücken zudrehen, wenn man anders ist. Die Leute sagen, anders zu sein sei eine Schwäche, aber es macht uns stark, mitfühlend. Ich beschütze dich selbst in den dunkelsten Zeiten!“\n– Lux","Zauber",[],["Demacia"],"GEWÖHNLICH"],"01DE027":["En garde","Gib Verbündeten in dieser Runde Herausforderer.","","„Es gibt keinen Demacianer, der eine Lektion in der Fechtkunst von einem Laurent ausschlagen würde. Oder eine überlebt hätte.“\n– Fiora","Zauber",[],["Demacia"],"SELTEN"],"01DE006":["Feldwebel der Vorhut","Wenn ich beschworen werde, erschaffe 1 Für Demacia! auf der Hand.","","„Er leitet unsere Exerzierübungen von Morgen bis Abend und kämpft an vorderster Front. Hart wie Stahl, fest wie ein Felsen – einen besseren Anführer gibt es nicht.“\n– Demacianischer Fähnrich","Einheit",["ELITE"],["Demacia"],"SELTEN"],"01DE038":["Senna, Wächterin des Lichts","Wenn zum ersten Mal ein verbündeter Lucian stirbt, gewähre mir +1|+1 und Doppelangriff.","","„Unsere Wächter sind die erste Verteidigungslinie zwischen der Flut der rastlosen Untoten und den Menschenreichen. Wir schlagen zuerst zu und weichen NIEMALS zurück, auch wenn wir unser Leben riskieren.“","Einheit",[],["Demacia"],"SELTEN"],"01DE041":["Rücken an Rücken","Gib 2 Verbündeten in dieser Runde +3|+3.","","„Gib mir Deckung, ich geh rein!“\n„Witzig, genau das wollte ich zu dir sagen.“\n– Lorn und Dax vom östlichen Bataillon","Zauber",[],["Demacia"],"SELTEN"],"01DE035":["Für Demacia!","Gib Verbündeten in dieser Runde +3|+3.","","„Es ist unsere Heimat, unsere Familien, unsere Waffenbrüder. Es ist unser Stolz, unsere Ehre, unsere Stärke. Und deshalb kämpfen wir heute für sein Fortbestehen. Ruft mit mir seinen Namen: DEMACIA!“\n– Feldwebel der Vorhut","Zauber",[],["Demacia"],"SELTEN"],"01DE018":["Brillanter Schlag","Gib einem Verbündeten in dieser Runde +1|+1.","","„Untote kämpfen, als gäbe es kein Morgen. Wir sorgen dafür, dass sie es nicht sehen werden.“\n– Lucian","Zauber",[],["Demacia"],"GEWÖHNLICH"],"01DE009":["Blankstahl-Beschützerin","Ausspielen: Ich gebe einem Verbündeten in dieser Runde Barriere.","","„Wir sind eine wohlhabende Nation, weil das Schicksal eines jeden Kriegers eine Münze ist, die wir nie leichtfertig aufs Spiel setzen.“\n– König Jarvan III.","Einheit",[],["Demacia"],"GEWÖHNLICH"],"01DE039":["Cithria von Wolkenfeld","","","„Meine Mutter erzählte mir vor dem Schlafengehen von den größten Helden Demacias, während sie ihr Schwert schliff. Meine Träume waren voller Abenteuer und heute beginnt meine ganz eigene Geschichte.“","Einheit",["ELITE"],["Demacia"],"GEWÖHNLICH"],"01DE056":["Erstklinge der Vorhut","Angriff: Gewähre mir +2|+2.","","Der Kampfschrei ertönt und ich stürme bereits entschlossen voran. Ich brauche nichts weiter als den Befehl meiner Herrin, um mein Schicksal zu kennen und ihr zu Willen zu sein.","Einheit",["ELITE"],["Demacia"],"GEWÖHNLICH"],"01DE029":["Flinkfeder-Aufspürer","Wenn du einen anderen Verbündeten beschwörst, gewähre mir Herausforderer.","","Diese Verwandten der Silberschwingen-Raubvögel verfügen über die gleichen räuberischen Instinkte und machen ihre vergleichsweise geringe Größe mit Beharrlichkeit wett.","Einheit",["VOGEL"],["Demacia"],"GEWÖHNLICH"],"01DE028":["Kavallerie der Vorhut","","","Die Vorhut benötigt keine Trommeln, keine Musik, die ihrem Vorstoß den Takt vorgibt. Das gleichmäßige Trampeln der Hufe auf der Erde ist genug.","Einheit",["ELITE"],["Demacia"],"GEWÖHNLICH"],"01DE013":["Kettenweste","Gewähre einem Verbündeten Robust.","","Demacianischer Stahl ist überall auf der Welt bekannt für seine überragende Stärke. Nur ein ebenso angesehener und starker Schmied ist in der Lage, mit ihm zu arbeiten.","Zauber",[],["Demacia"],"GEWÖHNLICH"],"01DE023":["Ermittlerin der Magiesuchenden","Erschaffe 1 Festnehmen auf der Hand, sobald du in diesem Spiel einen Zauber mit 6+ Kosten ausgespielt hast.","","„Entschuldigen Sie die Störung, aber wir bitten um Ihre uneingeschränkte Kooperation. Uns wurde von … ,ungewöhnlichen Vorfällen‘ berichtet …“","Einheit",[],["Demacia"],"GEWÖHNLICH"],"01DE051":["Cithria die Kühne","Angriff: Ich gebe anderen angreifenden Verbündeten in dieser Runde +1|+1 und Bedrohlich.","","„Legenden und Märchen waren für mich immer mehr als Fantasie. Sie waren Abenteuer, die mich riefen. Ich verließ Wolkenfeld, um mein Abenteuer zu finden und erlebte einige. Und sie sind nur der Anfang.“\n","Einheit",["ELITE"],["Demacia"],"EPISCH"],"01DE054":["Erlöserin der Vorhut","Wenn ich beschworen werde, ziehe eine Einheit, falls in dieser Runde ein Verbündeter gestorben ist.","","„Wir gedenken den Gefallenen in jedem Schlachtruf, in jedem Schwerthieb und in jedem Zusammenstoß unserer Schilde! Heute werden wir siegen!“","Einheit",["ELITE"],["Demacia"],"GEWÖHNLICH"],"01DE030":["Silberschwingen-Jägerin","","","Pfeile prasselten salvenweise von den Festungsmauern nieder, aber kein einziger konnte den silbernen Punkt erwischen, der durch die Luft flitzte. ","Einheit",["VOGEL"],["Demacia"],"GEWÖHNLICH"],"01PZ040":["Jinx","","Ich sehe, dass deine Hand leer ist.","„Is’ was, Gräte?“\n„Ich mach mir Sorgen um dich, Jinx! Jedes Mal, wenn du dich langweilst, willst du …“\n„… was in die Luft jagen! Klasse Idee, Gräte!“","Einheit",[],["Piltover & Zhaun"],"Champion"],"01PZ008":["Teemo","Nexusschlag: Verstecke 5 Giftige Poffpilze auf zufälligen Karten im gegnerischen Deck.","Du hast 15+ Giftige Poffpilze versteckt.","„Bandle-Späher-Regel 154: Fürchte niemals das Unbekannte! Regel 276: Die Waldbewohner sind unsere Freunde! Regel 354: Pelziges kann man vielleicht streicheln, aber nicht einfach essen! Regel 417 …“","Einheit",["YORDLE"],["Bandle","Piltover & Zhaun"],"Champion"],"01PZ056":["Heimerdinger","Wenn du einen Zauber ausspielst, erschaffe einen flüchtigen Turm in Höhe seiner Kosten auf der Hand. Er kostet 0.","Ich habe gesehen, wie du Technologie-Verbündete mit 12+ Stärke beschworen hast.","„Verrückter Wissenschaftler? Pah! Ich bin ja wohl eindeutig ein ‚geistig sehr stabiler, vielseitiger, wenn auch leicht chaotischer Wissenschaftler‘, ich muss doch sehr bitten!“","Einheit",["YORDLE"],["Bandle","Piltover & Zhaun"],"Champion"],"01PZ013":["Extremer Experimentator","Ausspielen: Wirf deine Hand ab. Ziehe 3. Verursache 3 Schaden an einem Gegner.","","Seine Träume haben ihn seine Hände gekostet, doch er ließ sich davon nicht beirren. Nichts würde ihm in die Quere kommen.","Einheit",[],["Piltover & Zhaun"],"EPISCH"],"01PZ007":["Elektroanlage der Parade","Unterstützung: Erschaffe 4 Kopien des unterstützten Verbündeten in deinem Deck.","","Das Donnern der Kanonen lockte die Massen zum Plaza, voller Vorfreude auf die Show. Es sollte Wochen dauern, bis ihre Haare endlich wieder frei von Konfettischnipseln waren.","Einheit",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"01PZ018":["Wunderkind der Akademie","","","Wie sie zielt? Eine hervorragende Frage.","Einheit",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"01PZ019":["Eifriger Lehrling","Wenn ich beschworen werde, fülle 2 Zaubermana wieder auf.","","Nicht jeder ist auf Anhieb dafür geschaffen, den Fortschritt in Piltover voranzubringen. Manche brauchen etwas Führung – wie diejenigen, die Erfindungen durch die falsche Linse betrachten.","Einheit",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"01PZ025":["Poffpilz-Händler","Wenn du einen Zauber ausspielst, verstecke 3 Giftige Poffpilze im gegnerischen Deck.","","„Taugen die was?“\n„Na klar! Die sind erste Sahne! Hab selbst mit ihnen geredet!“\n„Okay, her dam… Moment, was?“\n„Mhm! Der hier wird bald heiraten!“\n„Wie viele hast du gegessen?“\n„… und zwar eine Seepocke!“","Einheit",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"01PZ048":["Corina Veraza","Ausspielen: Vernichte die obersten 5 Karten deines Decks und verursache pro vernichtetem Zauber 1 Schaden an allen Gegnern und am gegnerischen Nexus.","","„Die engstirnigen Piltoveraner kennen nur Zahnräder und Metall. Sie wissen die feine Kunst in jedem Stamm, jeder Blüte und jeder Zelle meiner Atemsphäre nicht zu schätzen. Das wird ihr Untergang sein.“","Einheit",[],["Piltover & Zhaun"],"EPISCH"],"01PZ028":["Funk-Apparillo","Beschwöre beim Ausspielen oder Abwerfen 1 Schrottwühler.","","Mit einer Handvoll Schrott und nur wenig Zeit ließ sich die junge Erfinderin von etwas Ungewöhnlichem inspirieren: eine Kreatur, die sie einst am Fluss eines entfernten Dschungels entlangkrabbeln sah.","Zauber",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"01PZ050":["Ansteigende Zauberkraft","Gib einem Verbündeten in dieser Runde +4|+0 und Direktangriff.","","„Es kitzelt ein bisschen, wenn er anfängt zu glühen. Das ist normal … oder?“\n– Ezreal","Zauber",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"01PZ054":["Neuling der Bombencrew","Angriff: Verursache 2 Schaden am gegnerischen Nexus.","","„Bist du dir dabei sicher?“\n„Nö.“\n„Du hättest Ja sagen sollen.“\n„Du hättest nicht fragen sollen.“","Einheit",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"01PZ030":["Ominöse Gestalt","Ausspielen: Wähle einen Begleiter. Verwandle mich in eine exakte Kopie von ihm.","","„Hallo, Kollegen Chem-Barone!“","Einheit",["YORDLE"],["Piltover & Zhaun"],"SELTEN"],"01PZ017":["Vertreter für gebrauchte Fässer","Wenn ich beschworen werde, beschwöre 2 Kaustische Fässer.","","„Ziehl schickt dich? Wie gesagt, das ist sein Kram. Ich nehme nichts zurück, was ich noch nie gesehen hab. Aber zufälligerweise hab ich ’ne Lieferung Fässer reinbekommen, von der ich mich trennen würde …“","Einheit",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"01PZ038":["Grubenbuddler","Ausspielen: Wirf eine Karte ab, um 1 zu ziehen.","","In der Grube wird alles wiederverwertet.","Einheit",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"01PZ036":["Ezreal","Nexusschlag: Erschaffe 1 Mystischer Schuss mit Flüchtig auf der Hand.","Du hast Gegner 8+ Mal anvisiert.","„Schutzbrille? Jap. Schal? Dabei. Irrer Handschuh-mit-magischen-Eigenschaften-die-ich-total-kapiere? Jau, jawoll und jo!","Einheit",[],["Piltover & Zhaun"],"Champion"],"01PZ035":["Jae Medarda","Wenn ich anvisiert werde, ziehe 1.","","Jae, der Erstgeborene der angesehenen Medarda-Familie, zog die Jagd nach uralten Artefakten der Auseinandersetzung mit dem Familienbetrieb vor … sehr zum Verdruss seines Vaters.","Einheit",[],["Piltover & Zhaun"],"EPISCH"],"01PZ010":["Pilzwolke","Verstecke 5 Giftige Poffpilze im gegnerischen Deck.","","Erst ein sanftes Ploppen, wenn der Poffpilz aufplatzt. Dann brennende, unerträgliche Schmerzen. Als Letztes verklingt ein Kichern in der Ferne …","Zauber",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"01PZ045":["Zhaunitisches Straßenkind","Ausspielen: Wirf eine Karte ab, um 1 zu ziehen.","","„Ich hatte gedacht, dass die Grubenratten aufeinander aufpassen.“\n„Die sind zu beschäftigt damit, sich in Selbstmitleid zu suhlen, Bruder.“\n„Eine Schande. Oh … hast du meine Geldbörse gesehen?“","Einheit",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"01PZ002":["Hinterhof-Barkeeper","Wenn ich beschworen werde, erschaffe für jeden Hinterhof-Barkeeper, den du in diesem Spiel beschworen hast, eine zufällige Karte auf der Hand.","","„Klar Mann, es hat ’nen leichten Kick, so wie die Grube ’n wenig riecht. Der Eimer steht beim Klimperkasten.“","Einheit",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"01PZ004":["Energietrommelfeuer","Verursache 3 Schaden an einem Gegner oder dem gegnerischen Nexus, 2 an einem anderen, 1 an einem letzten.","","„Wenn man Talent hat, gibt es so was wie Glückstreffer nicht.“\n– Ezreal","Zauber",[],["Piltover & Zhaun"],"EPISCH"],"01PZ020":["Waghalsiger Poro","","","Ihr erster Flug war nur ein Versehen: Sie rutschte am Tag des Fortschritts in eine Kanone, während sie sich putzte. Jetzt zieht sie zu Ehren Piltovers über den Himmel und begeistert die Menge am Boden.","Einheit",["PORO"],["Piltover & Zhaun"],"GEWÖHNLICH"],"01PZ046":["Fälschungen","Wähle eine Karte auf der Hand. Erschaffe 4 exakte Kopien davon in deinem Deck.","","Nachahmung ist die höchste Form der Diebeskunst.","Zauber",[],["Piltover & Zhaun"],"SELTEN"],"01PZ052":["Mystischer Schuss","Verursache 2 Schaden an einem beliebigen Ziel.","","„Ich treffe immer. Ab und zu gebe ich vielleicht ein paar Warnschüsse ab.“\n– Ezreal","Zauber",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"01PZ033":["Die Miez-Maschine","Wenn du in diesem Spiel 20 neue Karten ausgespielt hast, beschwöre Katerstrophe.","","„Letztlich war jeder von uns getäuscht worden, der in Von Yipps Vision involviert war. Niemand wusste, was wir anrichteten, welche Mächte wir entfesseln würden.“\n– Projektingenieur aus Piltover","Zauber",[],["Piltover & Zhaun"],"EPISCH"],"01PZ005":["Hextech-Transmogulator","Verwandle einen Begleiter in eine exakte Kopie eines anderen Begleiters.","","„DU HAST DOCH STÄNDIG ERWÄHNT, DASS DU ABNEHMEN WILLST.“\n„ALSO HAST DU MICH IN EINEN YORDLE VERWANDELT?!“\n„ABER SO HAST DU ABGENOMMEN!“\n„… UND ICH BIN EIN YORDLE!“","Zauber",[],["Piltover & Zhaun"],"SELTEN"],"01PZ021":["Handlanger von Middenstokke","Nexusschlag: Beschwöre eine exakte Kopie von mir.","","„Herr Berz, wir haben Sie IM Tresor gefunden, unter goldenen Zahnrädern mit der kaputten Safetür.“\n„Das war ’n Doppelgänger.“\n„Sie haben noch immer die Tür in der Hand.“\n„Das glaubst DU.“","Einheit",[],["Piltover & Zhaun"],"SELTEN"],"01PZ031":["Statischer Schock","Verursache 1 Schaden an einem Gegner oder dem gegnerischen Nexus und 1 an einem anderen.\nZiehe 1.","","„Und so haben wir die Bogenentladung entdeckt! Natürlich hat mein Vorgänger ein solches Ereignis vermutet, aber er hat die Reichweite des Bogens unterschätzt. Der arme Kerl …“\n– Heimerdinger","Zauber",[],["Piltover & Zhaun"],"SELTEN"],"01PZ059":["Goldener Pressbot","","","TÖTEN. ZERMALMEN. ZERSTÖREN. NOCHMAL.","Einheit",["TECHNOLOGIE"],["Piltover & Zhaun"],"GEWÖHNLICH"],"01PZ001":["Durchstöbern","Wirf zum Ausspielen bis zu 2 Karten ab. Ziehe 1 für jede abgeworfene Karte.","","„Oooooh Junge, FÜNF VOLLSTRECKER UND EIN GOLEM? Sekündchen! Ich hab da doch was … Iiiirgendwo …“\n– Jinx","Zauber",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"01PZ057":["Provisorische Montage","Beschwöre 2 Schrottwühler.","","Zwei sanftmütige Kreaturen, die einst durch eine unüberwindliche Grenze aus Festland voneinander getrennt waren, haben endlich in den lauwarmen Gewässern der Grube zueinandergefunden.","Zauber",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"01PZ027":["Thermogener Strahl","Verbrauche zum Ausspielen dein gesamtes Mana.\nVerursache den entsprechenden Schaden an einer Einheit.","","„Uns sind sowohl Zeit als auch Geld ausgegangen. Der Strahl funktioniert zwar, aber es war uns nicht möglich, seinen Energieverbrauch zu regulieren.“\n– Zhaunitischer Experimentator","Zauber",[],["Piltover & Zhaun"],"SELTEN"],"01PZ055":["Scharfsinnige Gelehrte","Wenn du eine Karte ziehst, gib mir in dieser Runde +1|+0.","","Vorstellungskraft ist der Zündfunke großer Erfindungen. Die Forschung ist jedoch der Treibstoff, der den Funken zu einer Flamme auflodern lässt.","Einheit",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"01PZ014":["Unerlaubte Erfindung","Beschwöre 1 Illegale Apparatur.","","„Ihre Fehlversuche nehmen ständig andere Formen an: das Beben entfernter Explosionen, stinkende Dämpfe aus den Rissen. Irgendwann legen sie unsere Stadt in Schutt und Asche.“\n– Philanthrop aus Piltover","Zauber",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"01PZ034":["Grubenbastler","Loyalität: Erschaffe eine Karte der Grubenwerke auf der Hand. Sie kostet in dieser Runde 0.","","Die Kinder von Zhaun erkundeten bald schon die alten Minenschächte und die tieferen Ebenen der Gassen. Was für eine Welt sie dort entdeckten! Was für Freunde sie fanden.\n","Einheit",[],["Piltover & Zhaun"],"SELTEN"],"01PZ003":["Zusammenbau-Bot","Wenn du einen Zauber ausspielst, gewähre mir +1|+1.","","„Jeder Einfaltspinsel kann eine Maschine bauen, aber man muss außergewöhnlich scharfsinnig sein, um einem mechanisierten Geist WAHREN Fortschritt einzuhauchen! Diese verdammten Bürokraten werden bald angekrochen kommen …“\n– Klas Henwick","Einheit",[],["Piltover & Zhaun"],"SELTEN"],"01PZ044":["Chempunk-Shredder","Ausspielen: Verursache 1 Schaden an allen Gegnern.","","„… sein Solo fällt durch eine harmonische Molltonleiter, bevor es arpeggisiert – ja, das ist ein Fachbegriff. Vermutlich kannst du sein Werk nicht einmal verstehen.“\n– Max Bliff, Musikexperte","Einheit",[],["Piltover & Zhaun"],"SELTEN"],"01PZ029":["Angesehener Wohltäter","Ausspielen: Manifestiere eine epische Karte aus deinen Regionen.","","„Ich war jung und wütend, bin für Geld und Ruhm über Leichen gegangen. Jetzt setze ich mein Vermögen für selbstlose Zwecke ein, um meine Missetaten zu büßen.“","Einheit",[],["Piltover & Zhaun"],"SELTEN"],"01PZ051":["Wummenschmiedin","Alle deine Zauber und Fertigkeiten verursachen 1 Schaden zusätzlich.","","„Du willst mehr Wumms, ja? Na, dann biste hier genau richtig!“","Einheit",[],["Piltover & Zhaun"],"SELTEN"],"01PZ023":["Professor von Yipp","Wenn du einen Verbündeten mit 1 Kosten beschwörst, gewähre ihm +2|+2.","","„Heute präsentiere ich Ihnen, liebes Komitee, meine neueste Erfindung! Wie mein geschätzter Kollege demonstriert hat …“","Einheit",["KATZE"],["Piltover & Zhaun"],"SELTEN"],"01PZ024":["Instabiler Voltechniker","Gewähre mir +4|+0 und Direktangriff, sobald du in diesem Spiel einen Zauber mit 6+ Kosten ausgespielt hast.","","Name: Klas Henwick. Alter: 51. Art der Zulassung: Klasse 2 (eingeschränkt). Status: Widerrufen. Kommentar: Hat Warnungen nach Laborexplosion ignoriert (Fall 13X764NM). KEINEN ZUTRITT GEWÄHREN.","Einheit",[],["Piltover & Zhaun"],"SELTEN"],"01PZ049":["Tag des Fortschritts!","Ziehe 3, dann senke die Kosten dieser Karten um 1.","","TAG DES FORTSCHRITTS!\nFeier auf dem PLAZA DER SONNENTORE!\nDie neusten HEXTECH-WUNDERWERKE!\nAuftritt des WAGHALSIGEN POROS!\nDer MANN VON MORGEN spricht über die LAGE VON HEUTE!\nFREIER Eintritt!\nPiltoveraner Kinder willkommen!","Zauber",[],["Piltover & Zhaun"],"EPISCH"],"01PZ006":["Plaza-Wächter","Ich koste 1 weniger für jeden Zauber, den du in diesem Spiel ausgespielt hast.","","Du hast zwanzig Sekunden, um die Anweisungen zu befolgen.","Einheit",[],["Piltover & Zhaun"],"SELTEN"],"01PZ053":["Wuselrudel","Wenn ich beschworen werde, erschaffe 1 Pilzwolke auf der Hand.","","„Hmm, genau! Die schleichen in Rudeln rum! Sie WIRKEN verrückt, aber man weiß es nich’ so genau. Nich’ wie ich! Sie haben große Pläne. Groß. Poffpilze. Käse … Sorbet. Wo war ich?“\n– Poffpilz-Händler","Einheit",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"01PZ012":["Flammenfresser!","Wenn ich abgeworfen werde, beschwöre mich.","","„BEISST ORDENTLICH ZU!“\n– Jinx","Einheit",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"01PZ039":["Ich werd’ verrückt!","Wirf zum Ausspielen 1 Karte ab.\nVerursache 3 Schaden an einem beliebigen Ziel.","","„MIT SACK, PACK UND GRANATE!“\n– Jinx","Zauber",[],["Piltover & Zhaun"],"SELTEN"],"01PZ016":["Geniestreich","Erschaffe einen zufälligen Zauber mit 6+ Kosten aus deinen Regionen auf der Hand.\nFülle dein Zaubermana wieder auf.","","Ein Geistesblitz genügt, um ein Vermächtnis aufzubauen.","Zauber",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"01PZ058":["Wuselkumpel","Wenn ich beschworen werde, erschaffe 2 Pilzwolken auf der Hand.","","„Hab ’ne Große geseh’n! Schwer wie’n Pferd und schlau wie’n Krugg. Muss man im Auge behalten, echt. Die olle Tomate is’ nich’ umsonst die Wuselkönigin!“\n– Poffpilz-Händler","Einheit",["YORDLE"],["Piltover & Zhaun"],"SELTEN"],"01PZ009":["Ungeübter Aeronaut","","","„Persönliche Flugmaschinen? Nichts als Hirngespinste! Ich habe meinen Lehrling den letzten Prototypen gerade entsorgen lassen. Apropos, wo ist er hin?“\n– Ingenieur aus Piltover","Einheit",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"01PZ042":["Unerschrockene Seefahrerin","Unterstützung: Ich gebe meinem unterstützten Verbündeten in dieser Runde Ungreifbar.","","Viele Piltoveraner erforschen das große Unbekannte mithilfe von Wissenschaft und Erfindungen in ihren sicheren Laboren. Nur wenige brechen auf, um das größte Unbekannte zu entdecken: die Welt.","Einheit",[],["Piltover & Zhaun"],"SELTEN"],"01PZ026":["Karte der Grubenwerke","Gewähre einem Verbündeten Ungreifbar.","","„Pilties denken, sie wüssten alles, aber ihre Karten zeigen nur die Orte, von denen wir ihnen erzählt haben! Die Einheimischen können dir besser helfen … zu einem gewissen Preis.“\n– Ajuna Lem, Grubenbastler","Zauber",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"01PZ043":["Chempunk-Taschendieb","Nexusschlag: Erschaffe eine exakte Kopie eines zufälligen Zaubers aus dem Deck deines Gegners auf der Hand.","","Die Verstoßenen unterhalb der Stadt wurden ihrem Schicksal überlassen. Jedoch fanden sie zusammen, vereinten sich und erschufen ein neues Zuhause. Es war nicht viel, aber es gehörte ihnen. Zhaun.","Einheit",[],["Piltover & Zhaun"],"SELTEN"],"01PZ047":["Kaustisches Fass","Letzter Wunsch: Verursache 1 Schaden an BEIDEN Nexus.","","„Ich würd dir ja zu ’nem Anzug raten, aber da unten wird dir die Luft ausgehen. Nimm wenigstens Handschuhe! Lass den Schmodder auf nichts kommen, das du behalten willst.“\n– Ziehl, zhaunitischer Vorarbeiter","Einheit",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"01FR024":["Anivia","Angriff: Verursache 1 Schaden an allen Gegnern und dem gegnerischen Nexus.\nLetzter Wunsch: Belebe mich als Einivia wieder.","Du bist erleuchtet.","„Ich wurde in diesem ungezähmten Land geboren und ich werde es schützen. Weder Zeit, Kriege, noch der Tod werden meine Wacht beenden.“","Einheit",["VOGEL"],["Freljord"],"Champion"],"01FR039":["Tryndamere","","Anstatt zu sterben, steige ich eine Stufe auf.","„Stirb nicht für deine Sache. Lebe für sie …“","Einheit",[],["Freljord"],"Champion"],"01FR006":["Eisgeborenes Erbe","Gewähre einem Verbündeten und allen verbündeten Kopien überall +2|+2.","","„Die Magie von Freljord fließt seit Generationen im Blut der Eisgeborenen. Unsere Vorfahren haben ein uraltes Böses weggesperrt und wir sind auf seine Rückkehr vorbereitet.“\n– Gregor, der Wächter","Zauber",[],["Freljord"],"GEWÖHNLICH"],"01FR022":["Omenfalke","Wenn ich beschworen werde, gewähre den obersten 2 Verbündeten in deinem Deck +1|+1.","","„Dreimal erreichten unsere Plünderer die Tore der Avarosa und jedes Mal trafen sie auf gespannte Bogen. Welche List warnt sie vor unseren Angriffen?“\n– Narbenkrieger Steffen","Einheit",["VOGEL"],["Freljord"],"GEWÖHNLICH"],"01FR042":["Harsche Winde","Friere 2 Gegner ein.","","„Du willst mich in meinen eigenen Landen herausfordern? Darauf bist du nicht vorbereitet, Kleiner.“\n– Anivia","Zauber",["ELEMENTAR"],["Freljord"],"SELTEN"],"01FR009":["Braum","Wenn ich zum ersten Mal Schaden überlebe, beschwöre 1 Mächtiger Poro.","Ich habe insgesamt 10+ Schaden überlebt.","„Papa, erzähl die von Braum und seiner Tür!“\n„Oder die, als sein Sturz einen Berg gespalten hat!“\n„Oh! Was ist mit der, als er eine Taverne vor einem tobenden Yeti gerettet hat?!“","Einheit",[],["Freljord"],"Champion"],"01FR018":["Reifzahnwolf","Schlag: Wenn ich eine Einheit mit 0 Stärke getroffen habe, töte sie.","","Raubtiere aus den nördlichen Gefilden haben gelernt, dass jene, die vom eisigen Griff des Winters außer Gefecht gesetzt wurden, die leichteste Beute sind.","Einheit",["HUND"],["Freljord"],"SELTEN"],"01FR036":["Meisterschütze der Avarosa","Ausspielen: Verursache 1 Schaden an einem Gegner.","","In Freljord kannst du jagen oder du kannst verhungern.","Einheit",[],["Freljord"],"GEWÖHNLICH"],"01FR045":["Narbenkrieger Steffen","Wenn ich Schaden überlebe, gewähre mir +3|+0.","","„Ich habe meinen Eid für die Winterklaue besiegelt, als Sejuani mir meine erste Narbe geschenkt hat. Alle Narben danach habe ich mir in ihrem Dienste verdient.“","Einheit",[],["Freljord"],"GEWÖHNLICH"],"01FR008":["Einsamer Poro","Wenn ich beschworen werde, erschaffe einen anderen zufälligen Poro mit 1 Kosten auf der Hand.","","„Ich bin im Frost von Freljord aufgewachsen, aber der Anblick dieses traurigen Kerlchens treibt mir noch immer den kältesten Schauer über die Haut.“\n– Poro-Hirte","Einheit",["PORO"],["Freljord"],"GEWÖHNLICH"],"01FR055":["Zersplittern","Verursache 4 Schaden an einem Gegner, wenn dieser 0 Stärke hat. Friere ihn ansonsten ein.","","„Wenn Winter über das Land reitet, unterwirft sie die Starken und vernichtet die Schwachen.“\n– Narbenkrieger Steffen","Zauber",["ELEMENTAR"],["Freljord"],"GEWÖHNLICH"],"01FR038":["Ashe","Angriff: Ich friere den stärksten Gegner ein.","Du hast die Stärke von 5+ Gegnern auf 0 verringert. Wenn ich eine Stufe aufsteige, erschaffe 1 Kristallpfeil an der Spitze deines Decks.","„Wenn ich über meine Heimat blicke, sehe ich, was ist, aber auch was sein könnte. Wohlhabend und reichhaltig, nicht nur für mein Volk, sondern alle, die nach Frieden suchen. Freljord, vereint.“","Einheit",[],["Freljord"],"Champion"],"01FR029":["Hilferuf","Ziehe einen Champion.","","„Plünderer im Anmarsch! Schlagt Alarm und entzündet die Feuer, wir werden jede Hilfe brauchen.“\n– Patrouille der Avarosa","Zauber",[],["Freljord"],"SELTEN"],"01FR035":["Narbenlose Plünderin","Wenn ich Schaden überlebe, gewähre mir +3|+0.","","„Die Erziehung der Avarosa lässt ihre Kinder verweichlicht und unvorbereitet auf die Hitze des Kampfs heranwachsen. Unser Volk wird in den Feuern des Krieges geboren.“\n– Narbenmutter Vrynna","Einheit",[],["Freljord"],"GEWÖHNLICH"],"01FR020":["Lawine","Verursache 2 Schaden an ALLEN Einheiten.","","Die Seele einer jeden Lawine ist ein Steinchen, das ins Rollen gerät.","Zauber",["ELEMENTAR"],["Freljord"],"SELTEN"],"01FR014":["Yeti-Jährling","Letzter Wunsch: Erschaffe 2 Erzürnte Yetis in deinem Deck.","","„Er war so winzig und friedlich! Schwer zu glauben, dass er mal zu einem … na ja … Yeti heranwachsen würde.“\n– Fallensteller der Avarosa","Einheit",["YETI"],["Freljord"],"GEWÖHNLICH"],"01FR049":["Pirschender Wolf","Wenn ich beschworen werde, beschwört dein Gegner 1 Schneehase.","","„Man kann aus einem Hasen keinen Wolf machen.“\n– Sprichwort der Winterklaue","Einheit",["HUND"],["Freljord"],"GEWÖHNLICH"],"01FR037":["Vorreiter der Avarosa","Loyalität: Ich gewähre dem obersten Verbündeten in deinem Deck +3|+3 und Überwältigen.","","Als die Reihen der Verstärkung die Spitze des Kamms erreichten, verneigten sich die Vorreiter vor der Kriegsmutter. Denn sie – ihre leibhaftige Avarosa, ihre Königin Ashe – versprach den Frieden.","Einheit",[],["Freljord"],"SELTEN"],"01FR026":["Alpha-Wildklaue","","","Die Stärke eines Kriegsrosses, die rücksichtslose Grausamkeit einer Katze.","Einheit",["KATZE"],["Freljord"],"GEWÖHNLICH"],"01FR030":["Spröder Stahl","Friere einen Gegner mit 3 oder weniger Leben ein.","","„Kühl? Ha! Hoffen wir, dass euer Kampfgeist standhafter ist als euer Sommerlandstahl!“\n– Braum","Zauber",["ELEMENTAR"],["Freljord"],"GEWÖHNLICH"],"01FR013":["Narbenmutter Vrynna","Wenn ich Schaden überlebe, gewähre mir +3|+0.","","„Eher sterbe ich zitternd in der Kälte, bevor ich mir eine Feuerstelle mit Ashes Schwächlingen teile. Aber wenn sie sich nach Wärme sehnen, werde ich sie ihnen bringen.“","Einheit",[],["Freljord"],"EPISCH"],"01FR019":["Hauch des Winters","Töte alle Gegner mit 0 Stärke und friere alle Gegner ein.","","Kriegsmutter Winter ist der erste und letzte Gegner für jeden, der Freljord überfällt. Ihre Blutgeschworenen sind der gnadenlose Wind und die schneidende Kälte.","Zauber",["ELEMENTAR"],["Freljord"],"EPISCH"],"01FR041":["Dorfwache der Avarosa ","Wenn ich beschworen werde, gewähre Verbündeten in deinem Deck +1|+1.","","„Viele Stämme unter einem Banner! Vielleicht wird Freljord eines Tages geeinigt Seite an Seite kämpfen.“","Einheit",[],["Freljord"],"EPISCH"],"01FR025":["Poro-Hirte","Wenn ich beschworen werde, ziehe 1 Poro, falls du einen sichtbaren Poro-Verbündeten hast.","","Eine Herde braucht nur zwei Dinge: Liebe und Gesellschaft. Alles andere ist unbedeutend.\n","Einheit",[],["Freljord"],"SELTEN"],"01FR054":["Plünderin der Narbenschwestern","","","„Die Schwachen ernten, doch die Starken nehmen. Die kleinen Avarosa werden noch begreifen, wo ihr Platz ist!“","Einheit",[],["Freljord"],"SELTEN"],"01FR021":["Tarkaz der Stammeslose","Angriff: Verursache 1 Schaden an ALLEN kämpfenden Einheiten.","","„Tarkaz kämpfte erbitterter und besser als die meisten. Er akzeptierte seine Niederlage mit Würde. Na ja, größtenteils …“\n– Tryndamere","Einheit",[],["Freljord"],"EPISCH"],"01FR043":["Herz der Meute","Ausspielen: Kombiniere deine Poro-Begleiter zu einer Poro-Meute und gewähre ihr ihre Werte und positiven Schlüsselwörter.","","„Eine Geschichte noch, aber sei still, sonst kommt Mutter!“\n„Vor langer Zeit griffen Räuber das Dorf der Avarosa an. Ihre wenigen Kämpfer waren entkräftet, doch dann tauchte ein Poro auf und bot ihnen seine Hilfe an …“","Einheit",["PORO"],["Freljord"],"SELTEN"],"01FR033":["Wyrding-Steine","Rundenbeginn: Erhalte in dieser Runde einen zusätzlichen Manastein.","","„Diese uralten Steinhügel erinnern uns daran, dass wir nur der jüngste einer langen Linie von Stämmen sind, die diesen ungezähmten Landen trotzen.“\n– Ashe","Einheit",[],["Freljord"],"GEWÖHNLICH"],"01FR011":["Eistal-Bogenschütze","Ausspielen: Friere einen Gegner ein.","","Die Avarosa sind stolz auf ihre harschen Jahreszeiten und eisigen Lande. Ihre scharfsichtigen Verteidiger gehen sogar noch einen Schritt weiter. ","Einheit",[],["Freljord"],"GEWÖHNLICH"],"01FR050":["Freundlicher Gastwirt","Ausspielen: Heile einen Verbündeten oder deinen Nexus um 3.","","„Diese gute, alte Kneipe ist die ,Beschwipste Eule‘! Wir haben jede Menge Eintöpfe und Gebräue, um die Kälte zu vertreiben. Komm einfach rein!“","Einheit",[],["Freljord"],"GEWÖHNLICH"],"01FR052":["Jene, die umherzieht","Ausspielen: Vernichte ALLE Einheiten mit 4 oder weniger Stärke im Spiel oder auf der Hand.","","„Ich kämpfte mich aus dem Schutt und sah, wie eine klaffende Wunde das Land durchzog. Um mich herum lag schwelende Asche und in der Ferne verschwand eine gewaltige Gestalt …“\n– Björg der Wanderer","Einheit",[],["Freljord"],"EPISCH"],"01FR016":["Poro-Snack","Gewähre Poro-Verbündeten überall +1|+1.","","„Sie verschlingen die Dinger und gucken dich dann an mit heraushängenden Zungen, fröhlich wie’n Elnuk bei Tauwetter, und wollen mehr! Wie soll man da Nein sagen.“\n– Bäcker der Avarosa","Zauber",[],["Freljord"],"GEWÖHNLICH"],"01FR005":["Kampfrausch","Gewähre einem Verbündeten +8|+4.","","„Mir wurde gesagt, ich wäre … aufbrausend.“\n– Tryndamere","Zauber",[],["Freljord"],"SELTEN"],"01FR023":["Ruf der Kriegsmutter","Beschwöre den obersten Verbündeten aus deinem Deck sofort und zu JEDEM Rundenbeginn.","","Es wird der Tag kommen, an dem ein unmissverständlicher Ruf durch Freljord hallt. An diesem Tag werden wir ihm alle folgen, da er die Rückkehr unserer uralten Feinde verkündet.","Zauber",[],["Freljord"],"EPISCH"],"01FR047":["Animalischer Mystiker","Erleuchtet: Ich habe +4|+4.","","„Wer sich das Brüllen der Biester zu eigen macht, wird bald seine Muttersprache vergessen.“\n– Anivia","Einheit",[],["Freljord"],"GEWÖHNLICH"],"01FR056":["Eisiger Yeti","Wenn ich beschworen werde, friere Gegner mit 3 oder weniger Leben ein.","","„AaaaaAAAaaaaAaaaaah!“\n– Björg der Wanderer","Einheit",["YETI"],["Freljord"],"SELTEN"],"01FR027":["Elnukbulle","","","Die Volksmärchen der Avarosa erzählen vom „Alten Onkel Elnuk“, einem sturen, alten Griesgram, der nichts anderes wollte als ein warmes Fleckchen Gras und einen Streit, in den er sich festbeißen konnte. ","Einheit",["ELNUK"],["Freljord"],"GEWÖHNLICH"],"01FR057":["Rudelverhalten","Gib Verbündeten in dieser Runde +2|+2 und Überwältigen.","","Ein einsames Heulen hallte durch die Nacht, gefolgt von einem weiteren, und dann noch einem. Innerhalb kürzester Zeit jaulte das Rudel mit einer Stimme – ein Chor aufgepeitschter Stimmen, die nach Blut schrien.","Zauber",[],["Freljord"],"SELTEN"],"01FR004":["Elixier des Metalls","Gib einem Verbündeten in dieser Runde +0|+2.","","„Hart hier draußen, was? Aber keine Sorge, hier in der Eule servieren wir etwas ganz Besonderes, das zieht dir die Kälte direkt aus den Knochen und lässt sogar Säuglingen Haare auf der Brust wachsen!“\n– Freundlicher Gastwirt","Zauber",[],["Freljord"],"GEWÖHNLICH"],"01FR048":["Fallensteller der Avarosa","Wenn ich beschworen werde, erschaffe 1 Erzürnter Yeti in den obersten 3 Karten deines Decks.","","„Hab die ganze Woche nichts gefangen! Entweder sind mir diese Biester auf der Spur oder irgendwas verscheucht sie …“","Einheit",[],["Freljord"],"GEWÖHNLICH"],"01FR017":["Elnukherde","Ausspielen: Beschwöre jeden Elnuk aus den obersten 6 Karten in deinem Deck und lege den Rest zurück in dein Deck.","","„Die Avarosa sind wie Elnuks – träge Grasfresser, die leichte Opfer für die Narbenlosen sind. Nur durch die schiere Größe ihres Stammes sind sie noch am Leben.“\n– Narbenmutter Vrynna","Einheit",["ELNUK"],["Freljord"],"GEWÖHNLICH"],"01FR046":["Fasse Mut","Gewähre einem verletzten Verbündeten +3|+3.","","„… Seine Wunden waren zwar tief, doch Braum warf den Kopf zurück und lachte. Er wusste, dass Helden in Zeiten der Not geboren werden!“\n– Die Geschichte von Braum","Zauber",[],["Freljord"],"SELTEN"],"01FR012":["Katalysator der Äonen","Erhalte einen leeren Manastein. Dein Nexus wird um 3 geheilt.","","Weder Rubin noch Saphir können den Glanz des Äonensteins übertreffen – ein brillantes Juwel mit einer legendären Heilwirkung.","Zauber",[],["Freljord"],"GEWÖHNLICH"],"01FR040":["Schamanin der Reifhauer","Rundenbeginn: Ich friere den stärksten Gegner ein.","","„Um eins mit der Wildnis zu werden, darf man sich nicht vor der Kälte verstecken, sondern muss sich ihrer Grausamkeit hingeben.“","Einheit",[],["Freljord"],"SELTEN"],"01FR031":["Uralter Yeti","Rundenende: Senke meine Kosten um 1.","","„Was war das? Klang wie ein Niesen. Können Gletscher … niesen?“\n– Björg der Wanderer\n","Einheit",["YETI"],["Freljord"],"SELTEN"],"01FR053":["Mächtiger Poro","","","„Der alte Langhorn hat ’n Auge verloren, als er den Poro-König vor einer streitlustigen Wildklaue verteidigt hat! Nicht die Größe des Hammers ist wichtig, sondern die des Herzens.“\n– Poro-Hirte\n","Einheit",["PORO"],["Freljord"],"GEWÖHNLICH"],"01FR010":["Blutgeschworeneneid","Gewähre 2 Verbündeten +0|+3.","","„Ich werde ein Feuer in deinem Herzen sein, ein Schild an deiner Seite. Lass mich die Stärke finden, unser Volk zu beschützen. Mögen unsere Leben wie das Blut des Eids zusammenfließen.“\n– Tryndamere","Zauber",[],["Freljord"],"SELTEN"],"01FR001":["Blitzfrost","Friere einen Gegner ein.","","Die Kälte schlägt ohne Vorwarnung zu und lässt selbst den stärksten Krieger hilflos zurück.","Zauber",["ELEMENTAR"],["Freljord"],"SELTEN"],"01FR032":["Sternenklarer Seher","Wenn du einen Zauber ausspielst, gewähre dem obersten Verbündeten in deinem Deck +1|+1.","","„Verleihe ihnen hellhörige Ohren, um den herannahenden Wind zu vernehmen, leichte Füße, um den Schnee zu überqueren, und scharfe Augen, um hinter den Schleier des Winters zu blicken.“","Einheit",[],["Freljord"],"SELTEN"],"01FR051":["Lügengeschichten","Wenn du einen Yeti hast, beschwöre 1 Erzürnter Yeti. Wenn nicht, erschaffe 1 an der Spitze deines Decks.","","„… und der hat ein Maul voller spitzer Zähne und riesige Fäuste und wü-ti-gende Augen und ein OHRENBETÄUBENDES GEBRÜLL! Hat Onkel Björg mir gesagt!“\n– Ingvar die Jüngere","Zauber",[],["Freljord"],"GEWÖHNLICH"],"01FR034":["Jene, die überdauern","Wenn ich beschworen werde, gewähre mir +1|+1 pro gestorbenen Verbündeten.","","„Ah, der alte Björg hat viel durchgemacht. Hat seine Leute im Norden verloren. Kam Monate danach blass und babbelnd zurück. Redet nur noch von ,Bestien‘ hier und ,Klauen‘ dort. Armer Kerl …“\n– Freundlicher Gastwirt","Einheit",[],["Freljord"],"SELTEN"],"01FR007":["Babbelnder Björg","Wenn ich beschworen werde, ziehe eine Einheit mit 5+ Stärke.","","„I-Ihr müsst mir glauben! Er war riesig, wirklich! RIIIESIG!“","Einheit",[],["Freljord"],"GEWÖHNLICH"],"01FR003":["Patrouille der Avarosa","Letzter Wunsch: Ziehe 1.","","„Einst suchte ich meinen Platz auf entfernten Schlachtfeldern. Jetzt habe ich ihn bei meinen Brüdern gefunden, in meiner Heimstatt. Meine Augen sind die ihren, ihre Sicherheit liegt in meinen Händen.“","Einheit",[],["Freljord"],"GEWÖHNLICH"],"01SI038":["Phantomtäuscherin","Wenn ein anderer Verbündeter stirbt, verursache 1 Schaden am gegnerischen Nexus.","","Ihr grausamster Trick war nicht, gutgläubige Soldaten durch ihr Wimmern in den Tod zu führen, sondern Zweifel bei den Überlebenden zu säen, die nach ihrer Rückkehr das Flehen ihrer Töchter ignorierten.","Einheit",[],["Schatteninseln"],"SELTEN"],"01SI049":["Blick ins Jenseits","Töte einen Verbündeten, um 2 zu ziehen.","","„Ich lag falsch. Wir sind nicht dazu bestimmt, hinter den fahlen Vorhang zu spähen. Welche Erkenntnis dahinter auch verborgen sein mag, der Preis ist zu hoch.“\n– Arie Wrence, unerschrockene Verteidigerin","Zauber",[],["Schatteninseln"],"GEWÖHNLICH"],"01SI053":["Elise","Angriff: Beschwöre 1 angreifende Jungspinne.","Rundenbeginn: Du hast 3+ andere Spinnen.","Elise herrschte einst über ein mächtiges Haus von Noxus. Ihre Verbindung zu den Schatteninseln gewährt ihr für ein paar geopferte Seelen eine unnatürliche Jugend und Schönheit. Eine leichte Entscheidung.","Einheit",["SPINNE"],["Schatteninseln"],"Champion"],"01SI057":["Urzeitlicher Krokolith","Töte 2 Verbündete, um mich auszuspielen.","","„Steck sie in ’nen Käfig, dum-di-dum …\nPflück jede Seele, Stück für Stück\nLass sie niemals geh’n, mein Herr\nSonst fallen Geister über dich her …“","Einheit",["REPTIL"],["Schatteninseln"],"SELTEN"],"01SI023":["Seelenhirtin","Wenn du einen vergänglichen Verbündeten beschwörst, gewähre ihm +1|+1.","","Nur die Gefallenen wussten, dass sie nicht allein unterwegs war. Nur sie konnten die zahllosen Gefährten sehen, die sie auf ihrem Weg in die Länder jenseits der Grenzen begleitete.","Einheit",[],["Schatteninseln"],"GEWÖHNLICH"],"01SI010":["Ansturm der Schatten","Beschwöre 2 Phantomreiter.","","Sie leben jetzt so, wie sie damals gestorben sind: Loyal bis zum bitteren Ende.","Zauber",[],["Schatteninseln"],"GEWÖHNLICH"],"01SI042":["Hecarim","Angriff: Beschwöre 2 angreifende Phantomreiter.","Du hast mit 7+ vergänglichen Verbündeten angegriffen.","Das ist kein Donner. Der Schatten des Kriegs zieht am Horizont herauf.","Einheit",[],["Schatteninseln"],"Champion"],"01SI027":["Frische Opfergaben","Wenn 3+ Verbündete in dieser Runde gestorben sind, beschwöre Ekelschlund.","","„Knie vor deinem unersättlichen Gott. Oder noch besser, stirb für ihn.“\n– Elise","Zauber",[],["Schatteninseln"],"SELTEN"],"01SI048":["Verfluchter Aufseher","Letzter Wunsch: Beschwöre 1 Entkommene Kreatur.","","Wahnsinn und Zeit. Nie gab es ein schrecklicheres Gespann.","Einheit",[],["Schatteninseln"],"GEWÖHNLICH"],"01SI018":["Schreiber der Sorgen","Wenn ich beschworen werde, erschaffe eine exakte Kopie eines Verbündeten, der in diesem Spiel gestorben ist.","","„Wenn unser Autor doch nur gewusst hätte, dass bald die Zerstö- die Zer- nein, nein, nein, die Tinte ist wieder ausgelaufen! Wenn unser Autor- nein, nein, nein!“","Einheit",[],["Schatteninseln"],"GEWÖHNLICH"],"01SI030":["Kalista","","Ich habe gesehen, wie 3+ Verbündete gestorben sind.","Zu Lebzeiten war sie ein General, eine Beschützerin, eine Heldin. Doch nachdem ihr Körper verfiel, blieben nichts als die lodernden Flammen der Vergeltung übrig – ein unsterblicher Rachegeist.","Einheit",[],["Schatteninseln"],"Champion"],"01SI035":["Rhasa der Entzweier","Ausspielen: Wenn ein Verbündeter in dieser Runde gestorben ist, töte die beiden schwächsten Gegner.","","„Man sagte uns … sie nannten es die Reise einer Legende. Wir würden … für Demacias Zukunft. Wir segelten voller Hoffnung. Doch all … all diese Leben … wofür?“\n– Arie Wrence, demacianische Soldatin","Einheit",[],["Schatteninseln"],"EPISCH"],"01SI005":["Geistkrabbler","Ich koste 1 weniger für jeden Verbündeten, der in diesem Spiel gestorben ist.","","Einst war dieses Monster ein Lasttier in einem längst vergessenen Königreich. Nun sucht es die verlassenen Schlachtfelder ab, während die Überreste des Kampfes seine Schale bilden und die Seelen der Toten seinen Kern.","Einheit",[],["Schatteninseln"],"SELTEN"],"01SI037":["Finsterer Poro","","","Ich meine, es gibt schlimmere Arten zu sterben.","Einheit",["PORO"],["Schatteninseln"],"GEWÖHNLICH"],"01SI052":["Thresh","","Ich habe gesehen, wie 6+ Einheiten gestorben sind.","„Klirr, klapper, machen die Ketten, jemand will dich finden,\nKlirr, klapper, der Wächter hat Ketten, um dich zu binden …“","Einheit",[],["Schatteninseln"],"Champion"],"01SI033":["Kommandant Ledros","Ausspielen: Verursache Schaden (wird aufgerundet) am gegnerischen Nexus in Höhe der Hälfte seines Lebens.\nLetzter Wunsch: Ich kehre auf deine Hand zurück.","","Die meisten Geister verloren sich selbst, als ihre Erinnerungen im Laufe der Jahre verblassten. Sein Leid hielt Ledros jedoch in seiner Vergangenheit fest. Manchmal heilt die Zeit doch nicht alle Wunden.","Einheit",[],["Schatteninseln"],"EPISCH"],"01SI003":["Das Grauen","Belebe die 6 stärksten Verbündeten wieder, die in diesem Spiel gestorben sind, und gewähre ihnen Vergänglich.","","In gewissen Nächten fluten hungrige Seelen den schwarzen Nebel. Er trägt sie übers Meer, um die Lebenden heimzusuchen und die anwachsende Finsternis mit grauenvollem Unleben zu füllen.","Zauber",[],["Schatteninseln"],"EPISCH"],"01SI041":["Der Unsterbliche","Letzter Wunsch: Belebe mich beim nächsten Rundenbeginn wieder und gewähre mir +1|+1 pro Tod von mir.","","Der alte Märtyrer erinnerte sich daran, wie er seine Kameraden geschlossen ins Verderben geschickt hatte. Den Grund dafür hat er jedoch bereits vor Jahren vergessen …","Einheit",[],["Schatteninseln"],"EPISCH"],"01SI045":["Seele absorbieren","Entziehe einem Verbündeten 4.","","„Was dich umbringt, macht mich nur stärker.“\n– Thresh","Zauber",[],["Schatteninseln"],"GEWÖHNLICH"],"01SI036":["Schauriges Gefühl","Wenn ein Verbündeter in dieser Runde gestorben ist, beschwöre 2 Jungspinnen.","","Dieses unheimliche Gefühl auf deiner Haut ist nicht annähernd so beunruhigend wie das darunter.","Zauber",[],["Schatteninseln"],"GEWÖHNLICH"],"01SI051":["Gequältes Wunderkind","Wenn ein anderer Verbündeter stirbt oder Letzter Wunsch: Fülle dein Zaubermana wieder auf.","","Er arbeitete ununterbrochen, um seine Komposition zu perfektionieren. Dann durchfuhr ihn für einen Augenblick eine dunkle Stille. Andere schrien und rannten um ihr Leben. Er bemerkte nichts.","Einheit",[],["Schatteninseln"],"SELTEN"],"01SI012":["Ahnungsloser Inselbewohner","Ausspielen: Ich gewähre einem Verbündeten auf der Hand Vergänglich und senke seine Kosten um 1.","","Oh, der arme Kerl …","Einheit",[],["Schatteninseln"],"GEWÖHNLICH"],"01SI031":["Eiserner Vorbote","Angriff: Gewähre mir +1|+0 pro vergänglichen Verbündeten, den du hast.","","Im Tod wie im Leben verkündet er lauthals das finstere Gebot. Und im Tod wie im Leben antworten Hecarims treue Ritter auf den Ruf und stürmen ins Gemetzel.","Einheit",[],["Schatteninseln"],"SELTEN"],"01SI034":["Schwarzer Speer","Wenn ein Verbündeter in dieser Runde gestorben ist, verursache 4 Schaden an einer Einheit.","","„Unser Speer singt für die Gefallenen.“\n– Kalista","Zauber",[],["Schatteninseln"],"GEWÖHNLICH"],"01SI043":["Glückloser Aristokrat","Letzter Wunsch: Beschwöre 1 Jungspinne.","","„L-Lady Elise? Wo … wo seid Ihr hin?“","Einheit",[],["Schatteninseln"],"GEWÖHNLICH"],"01SI009":["Beschwipste Geister","Unterstützung: Ich gewähre meinem unterstützten Verbündeten +2|+0 und Vergänglich.","","Manche werfen einen Blick auf die Zerstörung und sehen nichts als Ruinen und Elend. Andere sehen ein halb volles Glas.","Einheit",[],["Schatteninseln"],"GEWÖHNLICH"],"01SI007":["Spukrelikt","Beschwöre 3 Entfesselte Geister.","","Diese uralten Artefakte werden von den Lebenden, die sie für sich beanspruchen wollen, und den Toten, die sie unbedingt behalten wollen, gleichermaßen geschätzt.","Zauber",[],["Schatteninseln"],"GEWÖHNLICH"],"01SI056":["Huschender Kanker","Wenn ich beschworen werde, gib anderen Spinnenverbündeten in dieser Runde +1|+0 und Gegnern -1|-0.","","„Sie können ein Netz von der Größe eines Mannes in weniger als einer Minute spinnen ... Möchtest du mal sehen?“\n– Elise","Einheit",["SPINNE"],["Schatteninseln"],"SELTEN"],"01SI001":["Racheakt","Töte eine Einheit.","","Die Betrogenen rufen mit ihrem letzten Atemzug Kalista an und hoffen, dass ihr Speer Rache üben wird.","Zauber",[],["Schatteninseln"],"GEWÖHNLICH"],"01SI019":["Die Kiste","Verursache 3 Schaden an jedem Gegner, der in dieser Runde beschworen wurde.","","„Niemand entkommt.“\n– Thresh","Zauber",[],["Schatteninseln"],"SELTEN"],"01SI011":["Gefräßiger Schlächter","Töte einen Verbündeten, um mich auszuspielen.","","Du bist, was du isst.","Einheit",[],["Schatteninseln"],"GEWÖHNLICH"],"01SI014":["Nebelgeist","Wenn ich beschworen werde, gewähre anderen verbündeten Nebelgeister überall +1|+0.","","Diese Schreckgespenster der Inseln haben ihre Persönlichkeit schon vor langer Zeit abgelegt, um zu einer Fusion aus reinem, unstillbaren Hunger zu werden.","Einheit",[],["Schatteninseln"],"GEWÖHNLICH"],"01SI022":["Zeichen der Inseln","Gewähre einem Verbündeten +2|+2 und Vergänglich.","","Stärke, aber zu welchem Preis?","Zauber",[],["Schatteninseln"],"GEWÖHNLICH"],"01SI006":["Besessenheit","Klaue einen gegnerischen Begleiter für diese Runde. (Nicht spielbar, wenn du bereits 6 Verbündete oder Wahrzeichen hast.)","","Er öffnete seine Augen und bemerkte sofort, wie seine Hände rot glänzten und das Lager ungewöhnlich still war. ","Zauber",[],["Schatteninseln"],"SELTEN"],"01SI028":["Seelensplitter","Beschwöre eine exakte Kopie eines Verbündeten. Sie ist vergänglich und hat 1|1.","","„Ich zog den Körper aus dem Wasser, um die arme Seele zu identifizieren. Als ich ihre Schulter berührte, drehte sie sich um und zeigte ihr Gesicht. Sie war … ich?“\n– Arie Wrence, demacianische Soldatin","Zauber",[],["Schatteninseln"],"SELTEN"],"01SI025":["Gräueltat","Töte einen Verbündeten, um Schaden in Höhe seiner Stärke an einem beliebigen Ziel zu verursachen.","","Töten bedeutet denjenigen nichts, die den Tod nicht verstehen können.","Zauber",[],["Schatteninseln"],"SELTEN"],"01SI046":["Ruf des Nebels","Belebe einen zufälligen Verbündeten wieder, der in dieser Runde gestorben ist.","","„Der Nebel trennt den Geist vom Körper und hinterlässt nur eine Karikatur des Lebens. Ich reise zu diesen verfluchten Inseln, um ihm ein Ende zu bereiten.“\n– Arie Wrence, Unerschrockene Verteidigerin","Zauber",[],["Schatteninseln"],"GEWÖHNLICH"],"01SI050":["Erwachen der Brut","Beschwöre 3 Jungspinnen, gewähre dann Spinnenverbündeten +1|+0.","","Nach dem Schlüpfen sind sie am hungrigsten.","Zauber",[],["Schatteninseln"],"SELTEN"],"01SI016":["Geistruferin","Loyalität: Beschwöre 1 Nebelgeist.","","Sie erscheint auf leisen Sohlen. Das Entsetzen, das ihr folgt, ist weit weniger verstohlen.","Einheit",[],["Schatteninseln"],"SELTEN"],"01SI021":["Hai-Streitwagen","Letzter Wunsch: Das nächste Mal, wenn ein vergänglicher Verbündeter angreift, belebe mich angreifend wieder.","","„Sie hat WAS gesehen? Ich verstehe. Wahnsinn ist eine grausame Geliebte, Apotheker. Die anderen sind wenigstens noch größtenteils bei Verstand.“\n– Demacianischer Chirurg","Einheit",[],["Schatteninseln"],"SELTEN"],"01SI032":["Chronistin des Untergangs","Ausspielen: Töte einen Verbündeten und belebe ihn dann wieder.","","Es gab eine Zeit, da saß sie bei ihrem Vater, dem obersten Bewahrer, während er die staubigen Folianten studierte. Er hatte gehofft, dass sie eines Tages die Rolle übernehmen würde. Aber nicht so.","Einheit",[],["Schatteninseln"],"GEWÖHNLICH"],"01SI058":["Ätherischer Seelensammler","Ausspielen: Töte einen Verbündeten, um einen zufälligen Begleiter zu beschwören, der 2 mehr kostet.","","Geister, leiht mir eure Stimmen! Gemeinsam beschwören wir eine unendliche Dunkelheit herauf!","Einheit",[],["Schatteninseln"],"SELTEN"],"01SI054":["Umklammerung der Untoten","Entziehe einer Einheit 3.","","Die Toten wünschen sich nichts mehr als das unablässige, pulsierende Klopfen der Lebenden verstummen zu lassen.","Zauber",[],["Schatteninseln"],"GEWÖHNLICH"],"01SI044":["Geisterhafte Matrone","Ausspielen: Wähle einen Verbündeten auf der Hand. Beschwöre eine exakte, vergängliche Kopie von ihm.","","Die Zerstörung stürzte alle auf ihrem Weg ins Verderben. Die Gütigen wurden grausam. Die Tapferen wurden bösartig. Die Vernunft wich der Feindseligkeit.","Einheit",[],["Schatteninseln"],"EPISCH"],"01SI039":["Arachnoides Grauen","","","Einige bösartige Geister lassen sich von der örtlichen Fauna inspirieren und verwandeln vertraute Dinge in alptraumartige Zerrbilder.","Einheit",["SPINNE"],["Schatteninseln"],"GEWÖHNLICH"],"01SI020":["Der Wiederentfacher","Wenn ich beschworen werde, belebe den stärksten toten verbündeten Champion wieder.","","Welche Bedeutung hat eine erlöschende Kerze, außer ihren Nachfolger zu entzünden?","Einheit",[],["Schatteninseln"],"SELTEN"],"01SI029":["Vernichtendes Wehklagen","Verursache 1 Schaden an allen Gegnern. Heile deinen Nexus um 3.","","Was uns tötet, macht sie nur stärker.","Zauber",[],["Schatteninseln"],"GEWÖHNLICH"],"01SI004":["Geißel der Tiefsee","","","Einige tauchten auf ihrer Flucht vor der Zerstörung weit unter die Wellen, im Glauben, dass die Verderbnis nicht bis in die Tiefe sickern würde. Sie irrten sich.","Einheit",[],["Schatteninseln"],"GEWÖHNLICH"],"01SI026":["Beute des Wächters","Letzter Wunsch: Erschaffe einen zufälligen anderen Begleiter mit Letzter Wunsch auf der Hand, der 3 oder weniger kostet.","","Er hielt seinen Atem so gut er konnte an und betete, dass der Wächter weiterging. Er ahnte nicht, dass diese Verfolgung erst der Anfang von Threshs vorzüglichen Quälereien war.","Einheit",[],["Schatteninseln"],"GEWÖHNLICH"],"01SI040":["Abscheuliches Festmahl","Entziehe einer Einheit 1 und beschwöre eine Jungspinne.","","„My … Mylady! Ich wusste nicht, dass Ihr eine solche Spinnenliebhaberin seid! Könntet Ihr sie vielleicht wegrufen? L-Lady Elise? Bitte?“\n– Lord Sassen, glückloser Aristokrat","Zauber",[],["Schatteninseln"],"GEWÖHNLICH"],"01SI015":["Die Zerstörung","Töte ALLE Einheiten.","","Es ist schwer zu glauben, dass etwas so Reines wie Liebe etwas derartig Grausames und Unentrinnbares verursachen kann. ","Zauber",[],["Schatteninseln"],"EPISCH"],"01SI055":["Seelenfresser","","","„Als unsere Schiffe sich der verfluchten Küste nähern, frage ich mich: Stammen diese albtraumhaften Schöpfungen aus diesen Ländern? Haben sie je wirklich gelebt?“\n– Arie Wrence, demacianische Soldatin","Einheit",[],["Schatteninseln"],"SELTEN"],"01SI047":["Verblassende Erinnerungen","Wähle einen Begleiter. Erschaffe eine vergängliche Kopie von ihm auf der Hand.","","Einen Moment lang erinnerte sie sich. Tanzendes Sonnenlicht auf ihrer Haut, der Geschmack von saftigen Brombeeren und die sanfte Melodie der Wiesen im Wind. Dann … war es verschwunden.","Zauber",[],["Schatteninseln"],"SELTEN"],"02PZ001":["Submiautikum","Wenn ich beschworen werde, ziehe 1.\nSolltest du in diesem Spiel mindestens 10 andere neue Karten ausgespielt haben, dann gewähre mir +4|+0.","","Nichts konnte seine Flucht vor diesen nutzlosen Menschen verhindern. Nicht mal ein bisschen Wasser …","Einheit",["KATZE"],["Piltover & Zhaun"],"EPISCH"],"02PZ010":["Erfahrener Ermittler","Wenn ich beschworen werde, ziehen ALLE Spieler 1 Karte.","","Einige Ermittler verlassen sich auf ihre Instinkte, um einen Fall zu knacken, andere auf ihre Kontakte. Doch Ermittler J. S. Harknors Stärke sind Gründlichkeit und Bürokratie. Und zwar eine Menge Bürokratie.","Einheit",["YORDLE"],["Piltover & Zhaun"],"GEWÖHNLICH"],"02PZ006":["Hab dich!","Wenn ich gezogen werde, koste ich in dieser Runde 2 weniger.\nVerursache 3 Schaden an einer Einheit.","","„Würden Sie bitte diese Handschellen anprobieren, Herr Berz?“\n„Was springt für mich dabei raus?“\n„Sie können sie behalten.“\n„… In Ordnung.“\n„Sie sind verhaftet. Abführen!“","Zauber",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"02PZ004":["Mauerbrecher","Gib einem Verbündeten in dieser Runde +2|+0.\nErschaffe einen flüchtigen Mauerbrecher auf der Hand.","","„Ich lass meine Fäuste sprechen.“\n– Vi","Zauber",[],["Piltover & Zhaun"],"SELTEN"],"02PZ007":["Aufmerksame Ermittlerin","Wenn du eine Karte mit 2 Kosten ausspielst, ziehe 1 Karte und gewähre ihr Flüchtig.","","„Alle Kommissare reagieren, aber ein guter Kommissar handelt vorausschauend und ein beispielhafter Kommissar verhindert.“\n– Handbuch der Wachtmeister","Einheit",[],["Piltover & Zhaun"],"SELTEN"],"02PZ002":["Chefmechanikerin Zevi","Wenn du eine Karte ziehst, gewähre ihr Flüchtig und erschaffe eine exakte Kopie von ihr auf der Hand.","","Mit fünf Jahren hat sie das weltweit erste Multifrequenz-Schallmesser entwickelt. Obwohl es nicht sehr praktikabel war (sie verwendete es vor allem zum Schneiden von Brot), ebnete es für sie den Weg zur Rüstungsabteilung der Wachtmeisterelite.","Einheit",[],["Piltover & Zhaun"],"EPISCH"],"02PZ008":["Vi","Während ich auf dem Spielfeld oder der Hand bin, gewähre mir +1|+0, wenn du eine andere Karte ausspielst (max. +8|+0).","Ich habe auf einen Schlag mit 10+ Schaden zugeschlagen.","„Vollstreckerin Vi, bitte! Denkt an das Volk! Den Kollateralschaden! Den PAPIERKRAM FÜR VERLETZUNGSANSPRÜCHE!“\n– Aufmerksame Ermittlerin","Einheit",[],["Piltover & Zhaun"],"Champion"],"02PZ009":["Beweisspur","Erschaffe eine zufällige Karte mit 2 Kosten aus deinen Regionen auf der Hand. Sie kostet in dieser Runde 2 weniger.","","„Also“, verkündete Ermittler Harknor, „führt uns die Spur zu …“","Zauber",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"02PZ003":["Fertigmachen!","Wenn ich gezogen werde, koste ich in dieser Runde 2 weniger.\nErhöhe einen Verbündeten auf 4|4.","","„Probleme am Pier! Nimm das hier und grüße sie von mir.“\n– Chefmechanikerin Zevi","Zauber",[],["Piltover & Zhaun"],"SELTEN"],"02PZ005":["Wachtmeisterstreife","Wenn ich gezogen werde, koste ich in dieser Runde 1 weniger.","","Die Sprinttechnik von Wachtmeisterin Mir war ein Running Gag unter den anderen Vollstreckern. Wachtmeister Kepple verstand ihn nicht.","Einheit",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"02BW040":["Bombardier-Schildkröte ","","","„MEINE KROESDE SCHTÄRGE IS WOL DAS ICH DAS VOLK FERSCHTEH UND AUSERTEM ANSCHEINENT MEINE RECHDSCHRAIPUNK“\n– Nachricht, die in den Sand gekritzelt wurde","Einheit",[],["Bilgewasser"],"GEWÖHNLICH"],"02BW057":["Flutwellenreiter","","","„Ich hab schon die seltsamsten Dinge über den Riffen gesehen, ehrlich, Käpt’n. Was tut dieser Tölpel in die Orangen? Das würde ich gerne mal wissen …“\n– Bootsmann","Einheit",[],["Bilgewasser"],"GEWÖHNLICH"],"02BW041":["Monster der Tiefsee","","","„Das verdammte Biest fürchte nicht,\nDenn seinen Zorn überlebt man,\nDoch was ist mit dem, der den Bogen bricht,\nUnd die armen Seelen mit sich nahm?“\n– Gedicht, das in den Balken einer Taverne in Bilgewasser geritzt wurde","Einheit",["SEEUNGEHEUER"],["Bilgewasser"],"GEWÖHNLICH"],"02BW013":["Lautlose Meuchlerin","","","„… und der Schwachkopf hat gesagt, meine ,Augen würden wie das Meer im Mondlicht funkeln‘. Ich hab nur gesagt, er soll sich die Schmeicheleien sonst wo hinstecken, wenn er seine Zunge behalten will.“","Einheit",[],["Bilgewasser"],"GEWÖHNLICH"],"02BW034":["Affenidol","Rundenbeginn: Verursache 2 Schaden an mir und beschwöre 1 Pulveräffchen.","","„Das ist ein … Souvenir. Die Crew hat es einem verrückten alten Rivalen abgenommen. Sieht aus, als wäre sein närrisches Gemurmel über ‚uralte, rätselhafte Kräfte‘ gar nicht so weit hergeholt gewesen …“\n– Miss Fortune","Einheit",[],["Bilgewasser"],"SELTEN"],"02BW056":["Verschlinger der Tiefen","Ausspielen: Vernichte einen Gegner mit weniger Leben als ich.","","„Ich war draußen auf dem Meer\nHinter Bilgewassers Bucht, so leer\nDa kam sie aus den Tiefen her\nDie Gesunkene Dame mit den Flügelohren …“\n– „Ballade der Gesunkenen Dame mit den Flügelohren“","Einheit",["SEEUNGEHEUER"],["Bilgewasser"],"EPISCH"],"02BW060":["Scharfäugige Korsarin","Wenn Verbündete angreifen, verursache 1 Schaden am gegnerischen Nexus.","","„Wer klein ist, hat überraschenderweise einen Vorteil im Kampf. Anscheinend schaut nie jemand nach unten.“","Einheit",["YORDLE"],["Bilgewasser"],"GEWÖHNLICH"],"02BW011":["Yordleganove","Loyalität: Klaue 1 und erschaffe 1 Warnschuss auf der Hand.","","„Du weißt doch, Freunde helfen Freunden liebend gern aus. Und mir gefällt das Leuchten in deinen Augen und das Funkeln deines Entermessers! Das ist ein wirklich, wirklich hübsches Entermesser.“","Einheit",["YORDLE"],["Bilgewasser"],"SELTEN"],"02BW030":["Wärter der Schiffsfriedhöfe","Wenn ich beschworen werde, entsorge 2 und erschaffe 2 Schätze in deinem Deck.","","„Heutzutage gibt’s unter den Wellen mehr Schätze als drüber, würd ich wetten. Man könnt sie sich auch kinderleicht schnappen, wenn sie nich’ wär.“\n– Kaltblütiger Kaperer","Einheit",["SEEUNGEHEUER"],["Bilgewasser"],"EPISCH"],"02BW019":["Blubberbär","","","Lebhafte Ströme der Magie winden sich durch die Riffe der Schlangeninseln und spenden den außergewöhnlichen Meeresbewohnern Nahrung.","Einheit",[],["Bilgewasser"],"GEWÖHNLICH"],"02BW007":["Gerissene Glücksspielerin","Wirf 2 Karten ab, um mich auszuspielen.\nAngriff: Ziehe 2 und gewähre ihnen Flüchtig.","","„Das ist meistens ’n Klacks. An den Tischen sitzen lauter Trottel, die so damit beschäftigt sind, sich die Kehlen heiser zu singen, dass sie sich nich’ aufs Spiel konzentrieren. Nich’, dass mich das stört. Münzen sind Münzen und bei mir sind sie besser aufgehoben als bei denen.“","Einheit",[],["Bilgewasser"],"SELTEN"],"02BW014":["Korallenkreaturen","Wenn ich beschworen werde, erschaffe einen zufälligen Zauber mit 1 Kosten aus deinen Regionen auf der Hand.","","In den meisten flachen Gewässern wimmelt es von Meerestieren, doch nichts kann den Riffen des Azurkorridors das Wasser reichen. Dieser Korridor ist ein magischer Ort voller Wunder, der wirkt, als stamme er nicht von dieser Welt.","Einheit",[],["Bilgewasser"],"SELTEN"],"02BW055":["Kaltblütige Quartiermeisterin","Plündern: Ich gewähre Verbündeten mit 1 Kosten überall +1|+0.","","Sobald sie abgefeuert wurde, müssen die Hakenmänner schnell sein. Blut im Wasser zieht Gesellschaft an … und keine sehr angenehme.","Einheit",[],["Bilgewasser"],"EPISCH"],"02BW017":["Zitruskurier","Plündern: Heile deine Verbündeten und deinen Nexus um 3, dann mobilisiere dich.","","„Alle Seemänner halten sich für harte Kerle! Grr hier, arrr da. Ja, ja, schön und gut, aber Orangen braucht man trotzdem! Sind gut für Haut und Zähne und machen mich glücklich. Entweder du isst oder du schwimmst. Ganz einfach.“","Einheit",[],["Bilgewasser"],"SELTEN"],"02BW038":["Torpedorochen","Wenn ich beschworen werde, ziehe einen Zauber aus deinem Deck, der 3 oder weniger kostet.","","Torps hat die Rennstrecke des Azurkorridors einmal sogar in unter drei Minuten geschafft. Gegen Ende des Parkours musste sie sogar dem zertrümmerten Rumpf der Jilldaw ausweichen! Die Strömungen waren richtig GENIAL!","Einheit",[],["Bilgewasser"],"EPISCH"],"02BW021":["Jäger der Klingenschuppen","Ausspielen: Belege einen Gegner mit Verletzlich.","","„Ich hab gehört, dass er meilenweit schwimmt, um sein Ziel zu finden. Und wenn er’s findet, denn schießt er nie daneben. Ich weiß nich’ mal, ob er ’n Mann oder ’n Fisch ist, aber er kennt diese Gewässer viel besser als wir.“\n– Kaltblütiger Kaperer","Einheit",[],["Bilgewasser"],"SELTEN"],"02BW035":["Sheriff Lariette Rose","Wenn ich beschworen werde, belege alle Gegner mit Verletzlich.","","Es gibt in Bilgewasser zwar kein offizielles Gesetz, doch eine Handvoll tapferer Seelen sorgt innerhalb der Stadtmauern nach eigenem Ermessen für Gerechtigkeit.","Einheit",[],["Bilgewasser"],"EPISCH"],"02BW058":["Kaltblütiger Kaperer","Plündern: Gewähre mir +1|+1.","","Die Aufnahme bei den Kaltblütigen Korsaren ist eine blutige Angelegenheit. Die Seeleute müssen beweisen, dass sie sich auf einem Schiff, in einem Kampf und an der Schlachtbank zu helfen wissen. Die unangenehmsten Kandidaten brauchen dafür nur eine einzige Prügelei.","Einheit",[],["Bilgewasser"],"GEWÖHNLICH"],"02BW028":["Rex’ schwere Geschütze","Plündern: Spiele Kanonensperrfeuer 7-mal auf zufällig anvisierte Gegner aus.","","„Segel vorbei an den Seemännern, segel vorbei an dem Wrack,\nDer Kampf ist schon vorbei.\nKein Rauch mehr über dem Wasser, ihr Kapitän hat Rex getroffen,\nUnd ihr Schiff ist nichts als Zunder.“\n– „Zurück nach Haus, Sally“","Einheit",[],["Bilgewasser"],"EPISCH"],"02BW037":["Auge des Abgrunds","Nexusschlag: Ziehe 1.","","„Aye, riefen sie, machten sich auf den Weg\nUnd stifteten Unruhe in Nashramae.\nDoch die Natur erhob sich und viele starben,\nDer Rest versorgt beim allsehenden Auge seine Narben!“\n– „Das allsehende Auge“","Einheit",["SEEUNGEHEUER"],["Bilgewasser"],"SELTEN"],"02BW008":["Bootsmann","Ausspielen: Beschwöre 1 Pulverfass oder einen zufälligen Begleiter mit 1 Kosten.","","Er lernte, dass es nur wenige Dinge gibt, die einen faulenzenden Seemann so schnell motivieren können wie eine brennende Lunte.","Einheit",["YORDLE"],["Bilgewasser"],"SELTEN"],"02BW047":["Bodensatzbuddler","Wenn ich beschworen werde, entsorge 3.","","Es braucht schon ein besonderes Talent, robuste, seetaugliche Ausrüstung zu verschrotten. Aber wenn sie eine Sache können, dann das. Und auch nur das.","Einheit",[],["Bilgewasser"],"GEWÖHNLICH"],"02BW004":["Deckshelferin","Wenn ich beschworen werde, beschwöre 1 Pulverfass.","","„Aye, wir könnten bei Dämmerung gegen sie kämpfen, wenn ihre Besatzung wach ist und die Kanonen ausgerichtet. Oder wir hinterlassen ihnen heut Nacht ein Geschenk, ganz still und heimlich …“","Einheit",[],["Bilgewasser"],"GEWÖHNLICH"],"02BW002":["Die Schrecken der Meere","Wenn ich beschworen werde, ziehe Gangplank.\nVerdopple allen Schaden, den deine Zauber, Fertigkeiten und Verbündeten verursachen.","","„Ohhh, verabschiede dich vom Leben und raff die Segel,\nDenn die Schrecken der Meere kommt.\nAuf’m Weg in die Tiefe, wo’s Gräber gibt zuhauf,\nDenn der Schrecken der Meere kommt!“\n– „Die Schrecken der Meere kommt“","Einheit",[],["Bilgewasser"],"EPISCH"],"02BW016":["Zweiarmiger Bandit","Wenn ich beschworen werde oder bei Rundenbeginn: Gewähre mir +0|+1 für jede Karte, die du in der letzten Runde gezogen hast, dann mische meine Werte.","","Einer der Prototypen warf drei Bomben aus und explodierte dann. Bei den späteren Modellen wurde diese „Funktion“ entfernt.","Einheit",[],["Bilgewasser"],"SELTEN"],"02BW027":["Jagdflotte","Wenn ich beschworen werde, beschwört dein Gegner 1 Goldener Narwal.","","Das Gold, das unter den Wellen funkelt, ist weder Münze noch Barren, sondern das glänzende Horn des durchtriebenen Widersachers vom Kapitän der Schlachterflotte.","Einheit",[],["Bilgewasser"],"GEWÖHNLICH"],"02BW050":["Souveräne Solistin","Plündern: Senke die Kosten von Verbündeten auf der Hand und im Deck um 2.","","„Begleitet uns auf eine musikalische Reise! Erfreut euch an Weisen aus ganz Runeterra! Denkt immer daran – bare Münze für den Eintritt und Trinkgelder wissen wir sehr zu schätzen …“\n– Jahrmarktschreier","Einheit",[],["Bilgewasser"],"SELTEN"],"02BW015":["Die Sirene","Wenn ich beschworen werde, ziehe Miss Fortune.\nWährend ich angreife, verursachen alle deine Zauber und Fertigkeiten 1 Schaden zusätzlich.","","Die Sirene ist ganz und gar unverkennbar. Ihre breiten, makellosen Segel und das polierte Holz ihres Rumpfs macht sie so ansehnlich und schmuckvoll wie die Kapitänin am Steuer.","Einheit",[],["Bilgewasser"],"EPISCH"],"02BW010":["Plündernder Poro","Plündern: Gewähre mir 2 zufällige Schlüsselwörter.","","„Sein Bild hängt schon länger an der Anschlagtafel als das der meisten anderen, denn er ist ein gieriger, unbarmherziger Teufel, der sich von nichts und niemandem seine Pläne durchkreuzen lässt. Aber das Schlimmste ist, dass er … dass er niedlich ist, verdammte Axt!“\n– Gangplank","Einheit",["PORO"],["Bilgewasser"],"GEWÖHNLICH"],"02BW009":["Billardbetrüger","Wenn ich beschworen werde, ziehe beim nächsten Rundenbeginn 1 Karte und gewähre ihr Flüchtig.","","„Macht für mich keinen Sinn. Es lief alles glatt, aber am Ende … hat’s einfach nicht geklappt. Ist nicht mein Tag, schätz ich …“\n– Gerissene Glücksspielerin","Einheit",[],["Bilgewasser"],"GEWÖHNLICH"],"02BW005":["Söldnerin","Wenn ich beschworen werde, belege den stärksten Gegner mit Verletzlich.","","„Bist du das auf dem Bild? Uff, du siehst in echt ja noch grausiger aus als gedacht. Hoffen wir, dass dein Kopf meine Zeit wert ist.“","Einheit",[],["Bilgewasser"],"GEWÖHNLICH"],"02BW039":["Jaull-Jäger","Wenn ich beschworen werde, erschaffe ein zufälliges Seeungeheuer auf der Hand.","","Die Aussicht auf Reichtümer lockt unzählige Crews in tiefe Gewässer. Diese armen Seelen merken schnell, wie furchterregend das Meer sein kann und warum so wenige zurückkehren.","Einheit",[],["Bilgewasser"],"SELTEN"],"02BW006":["Mysteriöser Magier","Ausspielen: Verwandle einen Verbündeten in einen zufälligen Begleiter mit 5 Kosten.","","„Marvolio? Wo … Wo sind meine Hände?“\n„Jetzt werrrrde ich sie zurrrrückholen! Tadaa! *räusper* Ta…daa…!“\n„… WO SIND MEINE HÄNDE?!“\n„ICH– ICH MUSS LOS! VIELEN DANK FÜRRRR DIE AUFMERKSAMKEIT!“","Einheit",[],["Bilgewasser"],"SELTEN"],"02BW036":["Goldener Narwal","","","Der Legende nach bestahl ein bleicher, gehörnter Wal die Bärtige Dame. Zur Strafe bedeckte die Dame die gierige Kreatur mit glitzerndem Gold, auf dass sie auf ewig die Habsucht der Leute auf sich ziehe.","Einheit",[],["Bilgewasser"],"GEWÖHNLICH"],"02BW033":["Schwarzmarkthändler","Wenn du eine gegnerische Karte ziehst, senke ihre Kosten um 1.\nPlündern: Klaue 1.","","„Wenn du es willst, hab ich es! Ich hab sogar ‚besondere Ware‘ … Aber vergiss nicht, die hast du nicht von mir!“","Einheit",[],["Bilgewasser"],"SELTEN"],"02BW032":["Gangplank","Wenn ich beschworen werde, beschwöre 1 Pulverfass.","Du hast in 5+ Runden Schaden am gegnerischen Nexus verursacht.","„Starr ihn nicht zu lange an, sonst erwischt er dich noch. Und rede nicht schlecht von ihm, denn er hört jedes Flüstern in Bilgewasser. Da kommt er. Kinn runter. Augen noch tiefer.“\n– Deckshelferin auf der Schrecken der Meere","Einheit",[],["Bilgewasser"],"Champion"],"02BW022":["Miss Fortune","Wenn Verbündete angreifen, verursache 1 Schaden an allen kämpfenden Gegnern und dem gegnerischen Nexus.","Ich habe gesehen, wie du 4 Mal angegriffen hast.","„ ‚Miss‘ Fortune? Hier draußen nennst du mich Kapitän.“","Einheit",[],["Bilgewasser"],"Champion"],"02BW046":["Fizz","Wenn du einen Zauber ausspielst, halte alle gegnerischen Zauber und Fertigkeiten auf, die mich anvisieren, und gib mir in dieser Runde Ungreifbar.","Du hast 6+ Zauber ausgespielt.","Von all den legendären Gestalten in Bilgewasser ist Fizz wohl der launenhafteste. Einige Seeleute verfluchen ihn, weil unzählige Wracks die Küste zieren …","Einheit",["YORDLE"],["Bandle","Bilgewasser"],"Champion"],"02BW026":["Twisted Fate","Ausspielen: Spiele eine Schicksalskarte aus.","Ich habe gesehen, wie du 9 Karten gezogen hast.","„Jetzt schau auf die Hände, zähl die Karten und versuch, mitzukommen. Und denk dran …“","Einheit",[],["Bilgewasser"],"Champion"],"02BW053":["Nautilus","","Wenn du in der Tiefe bist. Wenn ich eine Stufe aufsteige, kopiere entsorgte Verbündete mit 4+ Kosten in dein Deck.","„Ein Anker brach die Groll. Hat Finn mitgerissen, einfach so. Jetzt sind nur noch ein paar von uns übrig, und die Nacht kommt … und die Kälte. Es tut mir leid, Mama. Du hattest recht. Der Titan lebt.“\n– Gefundene Notiz","Einheit",[],["Bilgewasser"],"Champion"],"02BW061":["Asse im Ärmel","Wenn ich gezogen werde, koste ich in dieser Runde 1 weniger.\nGewähre einem Verbündeten +2|+1.","","„Nichts geht über eine Glückssträhne, wenn die Pokerchips nicht ausgehen sollen.“\n– Twisted Fate","Zauber",[],["Bilgewasser"],"GEWÖHNLICH"],"02BW024":["Doppelter Ärger","Beschwöre 2 zufällige Begleiter mit 1 Kosten.","","„He, Gav, is’ das nich’ der Kerl, hinter dem wir her sind? Sieht aus, als hätte er ’nen Freund gefunden.“\n„Ist das … Ist das ein Haimensch, Baz?“\n„Und ’n ganzer Batzen Gold, Kumpel. Komm schon …“\n– Baz und Gav, aufstrebende Kopfgeldjäger","Zauber",[],["Bilgewasser"],"SELTEN"],"02BW003":["Brachiale Methoden","Plündern: Rufe IRGENDEINEN Begleiter auf deine Hand zurück.","","„Du arbeitest jetzt für uns!“\n– Bootsmann","Zauber",[],["Bilgewasser"],"SELTEN"],"02BW025":["Köder auswerfen","Belege einen Gegner mit Verletzlich und beschwöre Langzahn.","","„Hai!“\n– Fizz","Zauber",[],["Bilgewasser"],"GEWÖHNLICH"],"02BW012":["Mehr Pulver!","Beschwöre 2 Pulverfässer.","","„Pulverfass!“\n– Gangplank","Zauber",[],["Bilgewasser"],"GEWÖHNLICH"],"02BW018":["Parrrlay","Verursache 1 Schaden an einem beliebigen Ziel.\nWird es dadurch getötet, verursache 1 Schaden am gegnerischen Nexus.","","Wenn Gangplank vermittelt, verläuft das oft kurz und immer blutig.","Zauber",[],["Bilgewasser"],"GEWÖHNLICH"],"02BW048":["Gefängnisausbruch","Beschwöre einen zufälligen Begleiter mit 1 Kosten.","","„Was meinst du, Baz? Kein wirklich zäher Brocken.“\n„Biste sicher, Gav? Er ist aus dem Knast ausgebrochen …“\n„Dann ist er gewieft, aber kein zäher Brocken. Na los!“\n– Baz und Gav, aufstrebende Kopfgeldjäger","Zauber",[],["Bilgewasser"],"GEWÖHNLICH"],"02BW043":["Zieh eine Karte","Lege zum Ausspielen eine Karte von der Hand zurück in dein Deck.\nZiehe beim nächsten Rundenbeginn 2 Karten und gewähre ihnen Flüchtig.","","„Ich schmiede mein Glück selbst.“\n– Twisted Fate","Zauber",[],["Bilgewasser"],"SELTEN"],"02BW051":["Verspielter Täuscher","Entferne einen angreifenden Verbündeten aus dem Kampf, um dich zu mobilisieren.","","„Immer einen Sprung voraus!“\n– Fizz","Zauber",[],["Bilgewasser"],"SELTEN"],"02BW054":["Reißende Flut","Betäube einen Gegner.\nLege diesen Gegner zurück ins gegnerische Deck, wenn du einen Nautilus hast.","","„Hinab mit ihnen …“\n– Nautilus","Zauber",[],["Bilgewasser"],"SELTEN"],"02BW042":["Verschmelzung","Erhöhe in dieser Runde Stärke und Leben von Verbündeten auf die Anzahl an anderen Zaubern, die du in diesem Spiel ausgespielt hast.","","Die Strömungen und Gezeiten um Bilgewasser herum werden zurecht wegen ihrer Stärke und Unberechenbarkeit gefürchtet. Doch kein Seemann kennt die wahren Kräfte dieser Gewässer.","Zauber",[],["Bilgewasser"],"EPISCH"],"02BW059":["Streuschuss","Entsorge 3.\nVerursache 7 Schaden an einer Einheit.","","„Wenn es sie versenkt, war es das wert.“\n– Sprichwort aus Bilgewasser","Zauber",[],["Bilgewasser"],"SELTEN"],"02BW023":["Verlockung der Tiefen","Senke die Kosten von verbündeten Seeungeheuern überall um 1.\nZiehe ein Seeungeheuer.","","Seemänner sprechen mit gedämpften Stimmen von dunklen Tagen, die am Horizont heraufziehen. Die Meere werden brodeln und schäumen und entsetzliche Schrecken werden aus den Wellen emporsteigen.","Zauber",[],["Bilgewasser"],"SELTEN"],"02BW031":["Doppelte Ladung","Verursache 2 Schaden an einem Gegner.\nWird er dadurch getötet, verursache 4 Schaden am gegnerischen Nexus.","","„Ich schieße immer zuerst.“\n– Miss Fortune","Zauber",[],["Bilgewasser"],"SELTEN"],"02BW029":["Bergungsgut","Entsorge 2.\nZiehe 2.","","Treibgut bleibt nicht lange an der Wasseroberfläche. Jeder Seefahrer, der etwas taugt, muss wertvolle Fracht schnell von alltäglichem Schrott unterscheiden können …","Zauber",[],["Bilgewasser"],"GEWÖHNLICH"],"02BW049":["Stibitzte Beute","Klaue 1.\nPlündern: Klaue 1 weitere.","","Was mir gehört, gehört mir, und was dir gehört … gehört auch mir.","Zauber",[],["Bilgewasser"],"GEWÖHNLICH"],"02BW001":["Letzte Warnung","Mache einen Gegner in dieser Runde verletzlich. Wenn er in dieser Runde stirbt, ziehe 1.","","„Kopf hoch und fleißig sein, Bursche! Wenn der Käpt’n dich durchhängen sieht, schneidet er dich auf, hisst dich als Flagge und verfüttert dich an die Möwen. Und jetzt beweg deinen Hintern!“\n– Deckshelferin","Zauber",[],["Bilgewasser"],"GEWÖHNLICH"],"02BW063":["Kartentrick","Plündern: Ziehe eine zufällige Karte aus der gegnerischen Hand, die kein Champion ist.","","„Beim Kartenspiel geht es nicht ums Glück, sondern um Menschenkenntnis. Wenn du den Gegner auf der anderen Tischseite zum Zweifeln bringst, kannst du ihm auch gleich alles abnehmen.“\n– Twisted Fate","Zauber",[],["Bilgewasser"],"SELTEN"],"02BW045":["Kugelhagel","Verursache 1 Schaden an drei unterschiedlichen, zufällig anvisierten Gegnern oder dem gegnerischen Nexus.","","„Hab was im Visier!“\n– Miss Fortune","Zauber",[],["Bilgewasser"],"GEWÖHNLICH"],"02BW020":["Warnschuss","Verursache 1 Schaden am gegnerischen Nexus.","","„Du sollst zusammen mit uns schießen, Bursche! Sonst is’ es ja keine Salve!“\n– Bootsmann","Zauber",[],["Bilgewasser"],"GEWÖHNLICH"],"02BW044":["Überbordwerfen","Entsorge 4.","","„Was sein Gewicht nicht wert ist, geht über Bord. Dasselbe gilt auch für euch. Und jetzt zurück an die Arbeit!“\n– Bootsmann","Zauber",[],["Bilgewasser"],"SELTEN"],"02BW062":["Inselnavigatorin","Wenn ich beschworen werde, beschwöre einen zufälligen Begleiter mit 1 Kosten und gewähre ihm Späher.","","„Lass das Licht von der Schlangenmutter\nVon den Wellen zu den Wolken steigen.\nDer Himmel blickt herab auf unsere Kutter,\nAls würde er seine grauen Augen neigen.\nSie lächelt friedlich …“\n– Gebet an Nagakabouros","Einheit",[],["Bilgewasser"],"SELTEN"],"02FR009":["Wolfsreiterin","Plündern: Erhalte einen leeren Manastein.","","Die jungen Reiter der Winterklaue werden mit einem Wolfswelpen betraut, sobald sie eine Waffe halten können. Ihre Erziehung ist einzig auf den Kampf ausgerichtet: Der Wolf soll anfallen und verwunden, der Reiter plündern und stehlen.","Einheit",[],["Freljord"],"GEWÖHNLICH"],"02FR004":["Der Kälte ausgesetzt","Friere einen Gegner in dieser Runde ein und mache ihn verletzlich.","","„Diese Warmblüter würden nicht einen Tag in Freljord überstehen!“\n– Sejuani","Zauber",["ELEMENTAR"],["Freljord"],"SELTEN"],"02FR002":["Sejuani","Ausspielen: Friere einen Gegner in dieser Runde ein und mache ihn verletzlich.","Du hast in 5+ Runden Schaden am gegnerischen Nexus verursacht.","Während ihr Flegel aus wahrem Eis bereits respekteinflößend ist, so ist Sejuani selbst eine Waffe, die in der unerbittlichen Kälte Freljords geschmiedet und gegen eiskalte Gefilde erprobt ist.","Einheit",[],["Freljord"],"Champion"],"02FR001":["Schwester der Glut","Rundenbeginn: Verursache 1 Schaden an ALLEM.","","„Sie werden ihre fruchtbaren Felder bestellen,\nSchwach werden sie ihre Samen säen.\nWir werden fast alles in Brand setzen, \nDie Winterklaue holt sich, was ihr beliebt!“\n– Kinderspruch der Winterklaue","Einheit",[],["Freljord"],"SELTEN"],"02FR005":["Geistwanderer der Ursaren","Plündern: Ich werde zum Ursar der Sturmklauen.","","Die Ursaren sind zu Beginn Menschen, doch sie geben das vertraute Erscheinungsbild ihrer Sterblichkeit für die wilde, ungezähmte Stärke auf, die ihnen der große Geist von Volibear verleiht.","Einheit",[],["Freljord"],"GEWÖHNLICH"],"02FR010":["Geteilte Beute","Gewähre den obersten 3 Einheiten in deinem Deck +1|+1.\nPlündern: Ziehe eine davon.","","„Lasst uns geschwisterlich teilen.“\n– Gnadenlose Kriegerin","Zauber",[],["Freljord"],"SELTEN"],"02FR008":["Langschiff der Plünderer","Wenn ich beschworen werde, ziehe Sejuani.\nPlündern: Verdopple die Stärke und das Leben von Verbündeten in deinem Deck.","","„Wenn uns der Frühling mildes Wetter für die Aussaat beschert, kommen auch die Langschiffe … und das einst üppige Korn wächst nur noch spärlich.“\n– Dorfwache der Avarosa","Einheit",[],["Freljord"],"EPISCH"],"02FR007":["Zorn des Nordens","Gib einem Verbündeten in dieser Runde +3|+4.","","„Akzeptiere die Bestie in deinem Inneren!“\n– Sejuani","Zauber",[],["Freljord"],"GEWÖHNLICH"],"02FR006":["Gnadenlose Kriegerin","","","Die Winterklaue sucht in Freljord ihresgleichen. Alle wissen um die Wildheit dieser gnadenlosen Räuber. Hat sie der Blutdurst erst einmal überkommen, kann man nur noch für einen schnellen Tod beten.","Einheit",[],["Freljord"],"GEWÖHNLICH"],"02FR003":["Aurora Porealis","Erschaffe 2 zufällige Poros und 2 Poro-Snacks auf der Hand.","","„Erbittest du des Poros Gnade,\nUnd schaust des Nachts gen Himmel,\nErblickst du Snacks unter den Sternen,\nFunkelnd leuchten sie herab.“\n– Ingvar die Jüngere","Zauber",[],["Freljord"],"EPISCH"],"02NX001":["Die Leviathan","Wenn ich beschworen werde, ziehe Swain.\nRundenbeginn: Verursache zweimal 1 Schaden am gegnerischen Nexus.","","Als die Ionier es am Horizont erblickten, hielten sie es für ein Monster. Ganz falsch lagen sie damit nicht – das stählerne Kriegsschiff ist furchteinflößend und stellt das bis dahin größte Meisterstück der noxianischen Flottentechnik dar.","Einheit",[],["Noxus"],"EPISCH"],"02NX007":["Swain","Nexusschlag: Verursache 3 Schaden am gegnerischen Nexus.","Du hast 14+ Schaden außerhalb des Kampfes verursacht.","„Eine Macht, welche den sterblichen Verstand übersteigt, offenbarte mir das Vermögen zu sehen, was anderen verborgen bleibt. Ich spähe durch die Dunkelheit, die andere fürchten.“","Einheit",[],["Noxus"],"Champion"],"02NX006":["Stadteinebner","Rundenbeginn: Verursache 1 Schaden am gegnerischen Nexus.","","Die Stimme des Ältesten war überraschend ruhig. „Wozu, so sage mir,“ fragte er, „sammeln wir Steine für höhere Mauern, wenn die Noxianer sie jedes Mal wieder einreißen?“","Einheit",[],["Noxus"],"SELTEN"],"02NX002":["Aurok Goldhorn ","Angriff: Betäube alle verletzten Gegner.","","„Seit Generationen wurden wir unterjocht. Erst als Noxus sich unser Land nahm, verstanden wir, was wahre Freiheit bedeutet. Darum kämpfe ich für das Imperium.“","Einheit",[],["Noxus"],"EPISCH"],"02NX009":["Ausgehungerte Schar","Verursache 4 Schaden an einer Einheit, wenn sie verletzt oder betäubt ist.","","Lauscht. Könnt ihr sie hören? Das Donnern von eintausend flatternden Flügeln.","Zauber",[],["Noxus"],"SELTEN"],"02NX004":["Imperiale Sprengstoffexpertin","Ausspielen: Verursache 1 Schaden an einem Verbündeten, um 2 Schaden am gegnerischen Nexus zu verursachen.","","„Schnell und leise, bis zur Explosion.“","Einheit",[],["Noxus"],"GEWÖHNLICH"],"02NX003":["Noxianische Inbrunst","Verursache 3 Schaden an einem Verbündeten, um an einem beliebigen Ziel 3 Schaden zu verursachen.","","„Es müssen Opfer erbracht werden.“\n– Jericho Swain","Zauber",[],["Noxus"],"GEWÖHNLICH"],"02NX010":["Elfenbein-Kriegsbestie","Gegner mit 4 oder weniger Stärke verursachen keinen Schaden an mir.","","„Ist eine Kriegsbestie erst einmal in Bewegung, kann sie nichts mehr aufhalten – am besten geht man ihr aus dem Weg.“\n– Basilisk-Reiter","Einheit",[],["Noxus"],"SELTEN"],"02NX008":["Griff des Todes","Verursache 2 Schaden an einem Gegner und 1 am gegnerischen Nexus.","","„Versuche, mit Würde zu sterben.“\n– Swain","Zauber",[],["Noxus"],"GEWÖHNLICH"],"02NX005":["Eisenballiste","","","„Eine Belagerung ist einfach – Vorausgesetzt, man verfügt über die richtigen Werkzeuge. Die Einebner treiben sie heraus und die Katapulte legen sie um.“\n– Belagerungsingenieur","Einheit",[],["Noxus"],"GEWÖHNLICH"],"02DE003":["Treuer Dachsbär","","","Es stimmt, was man sagt: Wie der Besitzer, so das Haustier.","Einheit",[],["Demacia"],"GEWÖHNLICH"],"02DE008":["Großhornhirsch","","","Ein Waldhüterrekrut verbringt zusammen mit seinen Gefährten Monate im Wald, um zu erlernen, wie er jede Bewegung seines Hirschs vorhersagen können. Er muss sich in Geduld üben, aber sobald sich die beiden angenähert haben, kann sich nichts mehr zwischen sie stellen.","Einheit",[],["Demacia"],"GEWÖHNLICH"],"02DE004":["Wildhüter der Grünzahnberge","","","„Ich habe einen Eid geschworen, diesen Wald und alle, die hier Zuflucht suchen, zu beschützen.“","Einheit",["ELITE"],["Demacia"],"GEWÖHNLICH"],"02DE006":["Quinn","Wenn ich beschworen werde, beschwöre Valor.","Ich habe gesehen, wie du 4 Mal angegriffen hast.","„Unsere Quinn war schon immer eine furchtlose Elite-Waldhüterin. Egal, ob Valor an ihrer Seite ist oder am Himmel, die beiden sind nicht aufzuhalten.“\n– Genevieve Ulmenherz, Elite-Waldhüterin","Einheit",[],["Demacia"],"Champion"],"02DE009":["Vielgeprüfter Waldhüter","Letzter Wunsch: Beschwöre 1 Treuer Dachsbär.","","Bertrand begann seine Karriere bei den Bandle-Spähern. Er hat alle Abzeichen außer das Abzeichen für „Fröhliche Einstellung“ erlangt.","Einheit",["YORDLE"],["Demacia"],"SELTEN"],"02DE005":["Unnachgiebigkeit","Gewähre einem Verbündeten „Ich kann keinen Schaden erleiden oder sterben“.","","Die Waldhüterin ignorierte den Schmerz in ihrem verwundeten Bein, stemmte sich wieder hoch und reckte ihr Schwert in die Höhe. Nicht nur ihre eigene Entschlossenheit hielt sie auf den Beinen, sondern die Entschlossenheit von ganz Demacia.","Zauber",[],["Demacia"],"EPISCH"],"02DE002":["Blendender Ansturm","Beschwöre Valor.","","„Er ist in meinen Haaren! ER IST IN MEINEN HAAREN!“\n– Marodeur der Legion","Zauber",[],["Demacia"],"SELTEN"],"02DE010":["Genevieve Ulmenherz","Wenn ich beschworen werde, gib anderen Verbündeten in dieser Runde +1|+1.","","Den Waldhütern von Demacia beim Kämpfen zuzusehen, ist inspirierend. Sie kämpfen als Einheit – Mensch und Tier, Seite an Seite, wild entschlossen und absolut untrennbar.","Einheit",[],["Demacia"],"EPISCH"],"02DE007":["Entschlossenheit der Waldhüterin","Gib Verbündeten in dieser Runde Robust.","","„Wenn der Gegner immer näher rückt, lasst keine Furcht in eure Herzen dringen, denn die Bäume werden uns beschützen.“\n– Wildhüter der Grünzahnberge","Zauber",[],["Demacia"],"SELTEN"],"02DE001":["Gezielter Schlag","Wähle einen Gegner. 2 Verbündete führen nacheinander einen Schlag gegen ihn aus.","","„Mir nach, alle zusammen!“\n– Wildhüter der Grünzahnberge","Zauber",[],["Demacia"],"GEWÖHNLICH"],"02SI005":["Harzmagie","Entsorge 3.\nHeile Verbündete um 3.","","„Diese Inseln werden geläutert.“\n– Maokai","Zauber",[],["Schatteninseln"],"SELTEN"],"02SI010":["Wanderin der Faulblüten","Wenn ich beschworen werde, entsorge 3.","","„Der Baumriese hat noch weiter … Kreaturen gezeigt. Diese eine … um mit jedem Schritt Lebenskraft zu verteilen … bemerkenswert solch … hier. Das sind wahrhaftig Gesegnete Inseln!“\n– Hinterlassenes Tagebuch","Einheit",[],["Schatteninseln"],"GEWÖHNLICH"],"02SI008":["Maokai","Wenn du in einer Runde zum ersten Mal einen anderen Verbündeten beschwörst, entsorge 2 und beschwöre einen Sprössling.","Deine Einheiten und Karten sind insgesamt 25+ Mal gestorben oder wurden entsorgt.","Diese verfluchten Lande würden Maokai nicht brechen. Der Baumriese war fest entschlossen und sein Zorn brannte zu hell, als dass ihn irgendetwas aufhalten konnte.","Einheit",[],["Schatteninseln"],"Champion"],"02SI007":["Dornenkröte","Letzter Wunsch: Entsorge 2 und heile deinen Nexus um 2.","","„… bemerkenswerte Spezies … selbe Kreatur, die ich als Kind gefunden habe … nicht einen Tag gealtert! Ich frage mich … nächstes Städtchen. Vielleicht leben diese wundervollen Kerlchen ewig!“\n– Hinterlassenes Tagebuch","Einheit",[],["Schatteninseln"],"GEWÖHNLICH"],"02SI003":["Terror der Fluten","Verbündete Seeungeheuer haben Bedrohlich.\nAngriff: Gib Gegnern in dieser Runde -2|-0.","","Sie erkannten die Gefahr zu spät. Das titangroße Wesen riss seinen riesigen Schlund auf und stürzte sich auf sie. Die Jäger konnten nur auf den Tod warten, während sich die endlosen Zähne langsam durch ihr Schiff bohrten.","Einheit",["SEEUNGEHEUER"],["Schatteninseln"],"EPISCH"],"02SI001":["Sammler des Niedermoors","Wenn ein anderer Verbündeter stirbt, entziehe dem gegnerischen Nexus 1.","","„Ich habe Niven heute getroffen … der neue Fährmann! Er hat uns gerudert … um … Er hat eine sehr schöne Gesangsstimme! Bevor … muss ihn bald zum Abendessen einladen.“\n– Hinterlassenes Tagebuch","Einheit",[],["Schatteninseln"],"SELTEN"],"02SI002":["Wuchernde Wildranke","Wenn du einen Begleiter ausspielst, töte ihn, um eine Wuchernde Wildranke zu beschwören.","","„Heute … noch ein bemerkenswertes … aufgetaucht bei … die Kinder hatten große Angst. Aber … keine Bedrohung. Verhätschelt … ein sehr zutrauliches Wesen. Muss noch mehr Beeren für sie suchen!“\n– Hinterlassenes Tagebuch","Einheit",[],["Schatteninseln"],"EPISCH"],"02SI004":["Befallene Hüterin","Ausspielen: Töte einen Verbündeten, um 2 Sprösslinge zu beschwören.","","„Jedes Herz ist ein Garten, in dem Wurzeln wachsen können!“","Einheit",[],["Schatteninseln"],"SELTEN"],"02SI006":["Borkenbiest","Wenn zum ersten Mal ein Verbündeter stirbt, gewähre mir +2|+2.","","Die Wesen der Schatteninseln haben jede Sentimentalität vor langer Zeit hinter sich gelassen. Sie brauchen alle Nahrung.","Einheit",[],["Schatteninseln"],"GEWÖHNLICH"],"02SI009":["Sprösslingwurf","Beschwöre beim nächsten Rundenbeginn 1 Sprössling.","","„Wuuuuuuhu!“\n– Sprössling","Zauber",[],["Schatteninseln"],"GEWÖHNLICH"],"02IO008":["Schallwelle","Gib einem Verbündeten in dieser Runde Herausforderer.\nErschaffe einen flüchtigen Resonanzschlag auf der Hand.","","„Meistere dich selbst …“\n– Lee Sin","Zauber",[],["Ionia"],"GEWÖHNLICH"],"02IO002":["Schuppen des Drachen","Wenn ich beschworen werde, erschaffe 1 Drachenschutz auf der Hand.","","„Ein Schüler muss mit Mitgefühl handeln, denn der Drache hat die Ersten Lande gehegt und sie mit Wärme und Leben gesegnet.“\n– Lehren des Drachen","Einheit",[],["Ionia"],"GEWÖHNLICH"],"02IO006":["Lee Sin","Wenn du einen Zauber ausspielst, gib mir in dieser Runde Herausforderer.\nSpielst du einen weiteren aus, gib mir in dieser Runde Barriere.","Du hast 8+ Zauber ausgespielt.","„Der Drache hilft denen, die würdig sind. Den Erschöpften gibt er Kraft. Den Kranken gibt er Trost. Den Verlorenen gibt er Hoffnung. Den Erschütterten gibt er Halt …“","Einheit",[],["Ionia"],"Champion"],"02IO004":["Hörner des Drachen","","","„Ein Schüler muss sich mit all seiner Kraft bemühen, denn der Drache hat die Erde aus den Wellen emporgehoben und uns ein Zuhause gegeben.“\n– Lehren des Drachen","Einheit",[],["Ionia"],"GEWÖHNLICH"],"02IO003":["Auge des Drachen","Rundenbeginn: Fluss: Beschwöre 1 Drachling.","","„Ein Schüler muss mit Klarheit denken, denn der Drache zieht die Sonne über unseren Himmel und enthüllt die Welt, die uns umgibt.“\n– Lehren des Drachen","Einheit",[],["Ionia"],"EPISCH"],"02IO001":["Klauen des Drachen","Während ich auf der Hand bin, beschwöre mich, wenn du 2 Zauber in einer Runde ausspielst.","","„Ein Schüler muss konzentriert zuhören, denn der Drache hat den ersten Klang ertönen lassen und unseren jungen Geist mit dem Geschenk der Magie betraut.“\n– Lehren des Drachen","Einheit",[],["Ionia"],"GEWÖHNLICH"],"02IO005":["Erschütternder Schlag","Betäube einen Gegner, um 1 Schwanz des Drachen zu beschwören.","","„Du hast mich nicht verschwinden sehen, und wirst mich auch nicht zurückkehren sehen.“\n– Schwanz des Drachen","Zauber",[],["Ionia"],"SELTEN"],"02IO010":["Rückzug","Rufe einen Verbündeten zurück, um eine flüchtige Rückkehr auf der Hand zu erschaffen.","","Die ersten Noxianer, die jemals einen Fuß auf die Strände von Ionia gesetzt haben, fanden einen schwachen und unvorbereiteten Gegner vor. Unzählige wurden abgeschlachtet, aber einer Handvoll gelang es, sich in Sicherheit zu bringen …","Zauber",[],["Ionia"],"SELTEN"],"02IO007":["Zorn des Drachen","Ein Verbündeter schleudert einen Gegner in den gegnerischen Nexus, wodurch zuerst der Gegner und dann der gegnerische Nexus geschlagen werden.\nWenn der Gegner überlebt, rufe ihn zurück.","","„Der Drache muss freigelassen werden, sonst verschlingt er mich von innen heraus.“\n– Lee Sin","Zauber",[],["Ionia"],"EPISCH"],"02IO009":["Tiefenmeditation","Fluss: Ich koste 2 weniger.\nZiehe 2 andere Zauber.","","Meditation ist eine Reise ohne Ziel – ein Weg, dem nur gefolgt werden kann, wenn man unterwegs von ihm abkommt.","Zauber",[],["Ionia"],"SELTEN"],"03NX019":["Jage die Schwachen","Dein Gegner wirft den schwächsten Begleiter auf seiner Hand ab.","","„Die Schwachen haben keinen Platz in dieser Welt. Jeder Tag bringt ihnen neue Schrecken, neue Schmerzen. Ich bringe ihnen nicht den Tod, ich erweise ihnen Gnade.“\n– Arrel die Fährtenleserin","Zauber",[],["Noxus"],"SELTEN"],"03NX022":["Wilde Pranken","Ein Verbündeter schlägt einen Gegner. Wenn er Überwältigen hat, wird überschüssiger Schaden direkt am gegnerischen Nexus verursacht.","","„Oooh, der Wilde sieht heute aber BESONDERS blutrünstig aus! Haltet euch von den Klauen fern, Leute!“\n– Arena-Kampfkommentator","Zauber",[],["Noxus"],"EPISCH"],"03NX007":["Riven","Wenn ich beschworen werde und du die Angriffsmarke hast oder wenn du sie erhältst, schmiede neu.","Du hast die Klinge des Exils erschaffen.","„Ich werde nicht davor fliehen, was ich war. Ich habe ein Versprechen gegeben, das zu reparieren, was ich zerbrochen habe …“","Einheit",[],["Noxus"],"Champion"],"03NX006":["Schwertgriff","Gib einem Verbündeten in dieser Runde +2|+0. Schmiede neu.","","„Du kennst deinen Gegner erst dann wirklich, wenn du seine Waffe kennst. So erfährst du, wie er sich bewegt, wie er denkt, wann er zuschlägt. Sie ist die wahre Essenz ihres Trägers.“\n– Arrel die Fährtenleserin","Zauber",[],["Noxus"],"GEWÖHNLICH"],"03NX002":["Arrel die Fährtenleserin","Rundenende: Wenn du in dieser Runde einen Zauber auf mich ausgespielt hast, schlage ich den schwächsten Gegner.","","„Versteck dich, wir finden dich. \nAtme, wir hören dich.\nLauf, wir töten dich.“","Einheit",[],["Noxus"],"EPISCH"],"03NX018":["Ergreifen","Betäube einen Gegner.\nWenn du einen Darius hast, mobilisiere dich.","","„Das erledige ich selbst.“\n– Darius","Zauber",[],["Noxus"],"SELTEN"],"03NX009":["Erbitterte Kriegerin","","","„Nichts ist vergleichbar mit der Jagd nach einem anderen Soldaten. Um ihn zu verfolgen, musst du denken und fühlen wie er. Um ihn zu fangen, musst du ihn so fürchten wie er dich. Es ist ein Band, das wenige je kennenlernen, aber eines, das ich mehr genieße als jedes andere.“","Einheit",[],["Noxus"],"GEWÖHNLICH"],"03NX017":["Basilisk-Bluthund","Ausspielen: Verursache 4 Mal 1 Schaden an einem Verbündeten und einem Gegner.","","Die Basiliskenzähmer füttern ihre Schützlinge in den Tagen vor einer Schlacht nicht mehr mit lebendigem Futter. Wenn die Tiere dann freigelassen werden, machen sie keinen Unterschied mehr zwischen Freund und Feind und sind vollkommen unbezwingbar.","Einheit",["REPTIL"],["Noxus"],"EPISCH"],"03NX015":["Überlebenskünste","Das Leben von Verbündeten kann in dieser Runde nicht unter 1 fallen.\nBeim Abwerfen kann in dieser Runde das Leben des stärksten Verbündeten nicht unter 1 fallen.","","„Die Drachenhunde haben die Spur aufgenommen. Sie werden sie finden und wir werden das zu Ende bringen. Es gibt keine andere Möglichkeit.“\n– Arrel die Fährtenleserin","Zauber",[],["Noxus"],"SELTEN"],"03NX014":["Eiserne Entschlossenheit","Gib einem Verbündeten in dieser Runde +3|+2.","","„Klar, ich repariere eure Waffen und kümmere mich um die Reittiere und koche euer verdammtes Essen. Wofür bin ich sonst gut, was?“\n– Erath, Klingenknappe","Zauber",[],["Noxus"],"GEWÖHNLICH"],"03NX003":["Klingenknappe","Letzter Wunsch: Schmiede neu.","","„Wie die Jägerinnen gesagt haben – einhundert Tage und Nächte. Einhundert Blasen an den Füßen, einhundert Krabbelviecher in meinem Frühstück, einhundert Mal ‚Klinge‘ hier und ‚Rache‘ da. Und auf jeden Fall mehr als einhundert Einschüchterungen von den dreien, sage ich dir …“ ","Einheit",[],["Noxus"],"GEWÖHNLICH"],"03NX001":["Runenmagierin","Wenn ich beschworen werde, schmiede neu.","","„Die meisten Waffen sind primitive Werkzeuge, genauso unfähig wie die Hand, die sie führt. Doch eine Waffe mit Runenmagie ist so viel mehr als bloßer Stahl.“","Einheit",[],["Noxus"],"GEWÖHNLICH"],"03NX005":["Brutale Jägerin","Wenn ich beschworen werde, gib mir in dieser Runde Direktangriff.","","„Da bist du ja. Wir WUSSTEN, dass du dich nicht kampflos ergibst! Oder haben wir zumindest gehofft.“","Einheit",[],["Noxus"],"SELTEN"],"03BW006":["Jack, der Gewinner","Rundenbeginn: Erschaffe 1 Bei den Fischen schlafen auf der Hand.","","Jahre im Boxring haben Jack wichtige Lektionen gelehrt. Er erkannte, dass ein Gegner, der bluten kann, auch Angst kennt. Er erkannte die Macht eines stummen Starrens. Er erkannte die Macht unkontrollierter Gewalt.","Einheit",[],["Bilgewasser"],"EPISCH"],"03BW010":["Bayou-Bankett","Ein Verbündeter hält einen anderen Verbündeten fest und erhält dessen Werte.","","„Tritt ein, Freund, und alles, was du begehrst, soll auf ewig dein sein.“\n– Tahm Kench","Zauber",[],["Bilgewasser"],"GEWÖHNLICH"],"03BW005":["Versunkene Kosten","Lege eine Einheit oder ein Wahrzeichen zurück ins Deck.","","„Ich habe dir genau das gegeben, was du begehrt hast, mein Freund. Ich habe nie gesagt, dass es für immer sein würde.“\n– Tahm Kench","Zauber",[],["Bilgewasser"],"SELTEN"],"03BW004":["Tahm Kench","Wenn ich beschworen werde oder bei Rundenbeginn: Erschaffe 1 Erlesener Geschmack auf der Hand.","Ich habe 3+ Einheiten festgehalten. Wenn ich eine Stufe aufsteige, vernichte meine festgehaltenen Gegner und lasse meine Verbündeten frei.","„Diesen Gesichtsausdruck kenne ich, mein Freund. Du denkst, dass die Karten auf deiner Hand nicht die sind, die du verdienst. Du hast ein Verlangen nach feineren Dingen, nicht wahr? Vielleicht erlaubst du mir, deinen Hunger zu stillen und dich alles zu kosten zu lassen, was du dir je gewünscht hast. Du musst nur deinen Namen auf mein Papier schreiben … und dann, mein Freund, musst du dein Leben lang um nichts mehr bitten.“","Einheit",[],["Bilgewasser"],"Champion"],"03BW002":["Lässiger Lurch","Rundenbeginn: Verursache 2 Schaden an mir.","","„Ah, die Menschen sind dumm! Gib ihnen kaltes Getränk und warmen Stuhl und sie erzählen jedem mit freundlichem Gesicht alle Geheimnisse. Und wer hat ein freundlicheres Gesicht als der junge Leonard, hmm?“\n– Wahrsagende Unke","Einheit",[],["Bilgewasser"],"GEWÖHNLICH"],"03BW014":["Affentheater","Beschwöre 1 Pulveräffchen.\nPlündern: Beschwöre beim nächsten Rundenbeginn 1 weiteres Pulveräffchen.","","„Ooch … du glaubst, die sind süß? SIND SIE NICHT. Die schaffen’s überall rein, machen mehr Dreck als ein seekranker Kurier und SIE HALTEN NICHT IHRE DÄMLICHE KLAPPE. KEINE AFFEN AUF DEM SCHIFF. BASTA.“\n– Bootsmann","Zauber",[],["Bilgewasser"],"GEWÖHNLICH"],"03BW007":["Boxtopus","Ausspielen: Verursache 3 Schaden an mir.","","„Sicher, Pablo liegt vielleicht etwas ‚auf dem Trockenen‘ – heh – und klar, er hat ordentlich einstecken müssen. Aber weißt du was? Ansonsten kriegt hier niemand Oktokills, Kumpel.“\n– Großspuriger Kleinganove","Einheit",[],["Bilgewasser"],"GEWÖHNLICH"],"03BW016":["Pulverboot","Verursache 1 Schaden an einer Einheit.\nBeschwöre Pulverfässer in Höhe des verursachten Schadens.","","„Der junge Gerent hat direkt vor der ersten Explosion Alarm geschlagen. Unser Schiff schwankte, unser Fock ging in Flammen auf, doch die Jilldaw hielt stand. Ich dachte, das wäre unser Untergang, doch als ich Gerents Blick über das Meer folgte, sah ich mehrere Ruderboote, die sich uns näherten, alle randvoll mit Pulver.“\n– Überlebender der Jilldaw","Zauber",[],["Bilgewasser"],"SELTEN"],"03BW001":["Der Schlachterhafen","Rundenbeginn: Entsorge 1. Wenn du in der Tiefe bist, zerstöre mich, um ein zufälliges Seeungeheuer zu beschwören.","","Jeden Tag wandern Einheimische über den Schlachterhafen, um die Schrecken zu sehen, die die Jäger von Bilgewasser aus den Tiefen gezogen haben. Meistens sind die Ungeheuer tot. Meistens.","Wahrzeichen",[],["Bilgewasser"],"EPISCH"],"03BW015":["Raubeiniger Haudrauf","Ausspielen: Verursache 2 Schaden an mir.","","„JETZT SCHLAG DEN GONG SCHON! ICH ZEIG DEM ALTEN KNACKER, WOHER MEINE SPITZNAMEN KOMMEN, AYE. ‚ACHT-FAUST-PABLO‘, ‚DER KRACHENDE KRAKEN‘, ‚DER TENTAKEL-TERROR‘! DU WIRST NACH DEINER MAMI SCHREIEN, WENN ICH MIT DIR FERTIG BIN!“\n– Boxtopus","Einheit",[],["Bilgewasser"],"GEWÖHNLICH"],"03BW003":["Großspuriger Kleinganove","Ausspielen: Verursache 1 Schaden an allen anderen Verbündeten und gewähre mir für jeden +1|+0.","","Der Aufstieg zur Macht ist oft gewalttätig … aber normalerweise nicht so unglaublich schlampig.","Einheit",[],["Bilgewasser"],"SELTEN"],"03BW017":["Wirbelnder Quallenfisch","Ich koste 1 weniger für jeden Zauber, den du in diesem Spiel ausgespielt hast.\nWenn ich beschworen werde, erschaffe einen zufälligen Zauber mit 1 Kosten aus deinen Regionen auf der Hand.","","„Ftillgeftanden, Grünfnabel! Deine Miffion ift ef, den Gegner tfu infiltrieren, fo viele Blafen wie möglich tfu legen und unf allef tfu fagen, waf du fiehst! ALLEF, HAFT DU VERFTANDEN?“\n– Admiral Shelly, Bombardier-Schildkröte","Einheit",[],["Bilgewasser"],"EPISCH"],"03BW008":["Wahrsagende Unke","Ausspielen: Verursache 1 Schaden an mir und einem Verbündeten, um 1 zu ziehen.","","„Der alten Babs sind ein paar Malheure passiert. Hat in ihrer Zeit ein paar Einheimische getötet, aber das macht sie wohl authentischer.“\n– Lässiger Lurch","Einheit",[],["Bilgewasser"],"GEWÖHNLICH"],"03BW020":["Pulverpandämonium","Beschwöre pro aktiviertes Plündern in diesem Spiel 1 Pulveräffchen.","","„Och, diese kleinen Rußnäschen sind gar nicht so übel. Kleiner Tipp – sie lieben Feuerwerke. Du musst also nur das feindliche Schwarzpulverlager ausschalten und die Äffchen machen den Rest.“\n– Miss Fortune","Zauber",[],["Bilgewasser"],"EPISCH"],"03BW009":["Erpressung","Verursache 2 Schaden an einem Verbündeten, um 2 Gegner mit Verletzlich zu belegen.","","„Willste mir sagen, wo du die ‚zusätzlichen Fässer‘ her hast, Witzbold? Hm? Ansonsten spielen wir Tauziehen mit deiner Zunge und Jimbos Arm. Und weißte … ich werd nich’ auf dich setzen.“\n– Großspuriger Kleinganove","Zauber",[],["Bilgewasser"],"SELTEN"],"03DE010":["Der große Platz","Wenn ein Verbündeter beschworen wird, gib ihm in dieser Runde +1|+1 und Herausforderer.","","Tianna blickte über die Versammlung und sah sich die Reihen der versammelten Soldaten an. Das einzige Geräusch auf dem Platz kam von ihrem im Wind flatternden Banner. Sie nickte kurz anerkennend und hob dann das Banner mit einem Ausruf: „Wer von euch ist bereit, für Demacia zu kämpfen?“. Der donnernde Antwortschrei der Menge ließ sogar die Berge erzittern. ","Wahrzeichen",[],["Demacia"],"EPISCH"],"03FR009":["Die Heulende Schlucht","Rundenbeginn: Erschaffe einen zufälligen Stufe-2-Champion auf der Hand, der nicht auf deiner Hand, in deinem Deck oder auf dem Spielfeld ist.","","Helden kommen auf die Brücke, angezogen von etwas Unbekanntem. Sie trotzen der bitteren Kälte und der baufälligen Konstruktion, um zu sehen, was sie erwartet – Sieg oder Tod.","Wahrzeichen",[],["Freljord"],"EPISCH"],"03MT005":["Abweichende Pfade","Ziehe oder zerstöre ein Wahrzeichen.","","Targon ist ein unberechenbarer Ort, wo das Unzerstörbare gebrochen wird und das Zerstörte wiederhergestellt wird.","Zauber",[],["Targon"],"GEWÖHNLICH"],"03SI009":["Schatzkammern von Helia","Rundenbeginn: Töte wenn möglich deinen teuersten Verbündeten, um einen Verbündeten aus deinem Deck zu beschwören, der 1 mehr kostet.","","Was könnte eine Seele eher zu diesem elenden Ort locken als das Versprechen von ewigem Leben und unendlichem Reichtum?","Wahrzeichen",[],["Schatteninseln"],"EPISCH"],"03IO006":["Kloster von Hirana","Rundenbeginn: Erschaffe 1 Zuflucht auf der Hand.","","In den ionischen Bergen verbirgt sich eine Handvoll Heiligtümer für diejenigen, die ihre Mitte finden und meditieren wollen.","Wahrzeichen",[],["Ionia"],"EPISCH"],"03NX013":["Verbrannte Erde","Töte eine verletzte Einheit oder zerstöre ein Wahrzeichen.","","„Die Drachenhunde haben die Spur aufgenommen. Sie werden sie finden und wir werden das zu Ende bringen. Es gibt keine andere Möglichkeit.“\n– Arrel, Fährtenleserin","Zauber",[],["Noxus"],"GEWÖHNLICH"],"03NX004":["Noxkraya-Arena","Rundenende: Dein stärkster Verbündeter und der schwächste Gegner schlagen sich gegenseitig.","","„Haaaallo, Vergelterfans, seid ihr bereit für einen Abend voller brennend heißer Kämpfe im FEUERRING?! Oh, oh, es scheint, als hätte Willi Winzling den Kürzeren gezogen. Er tritt gegen den mächtigen, kampferprobten GRANAAAAK den Großen an! Ruft die Ärzte zum Ring, das dauert nicht lange!“\n– Arena-Kampfkommentator","Wahrzeichen",[],["Noxus"],"EPISCH"],"03DE004":["Hauptmann Arrika","Ausspielen: Halte eine Einheit oder ein Wahrzeichen fest.","","Als in Arrikas Kindheit Noxus in ihre Heimat einfiel, sah sie mit eigenen Augen, wie gewaltig dessen Zerstörung sein konnte. Bei ihrem Eintritt in den Militärdienst schwor sie sich, dass die noxianische Flagge niemals über Demacia gehisst werden würde und keine Waisen mehr zurückgelassen werden würden.","Einheit",["ELITE"],["Demacia"],"SELTEN"],"03IO005":["Heimkehr","Rufe eine verbündete Einheit oder Wahrzeichen zurück, um eine gegnerische Einheit oder Wahrzeichen zurückzurufen.","","„Heeeerbeeeert, komm zurüüüüück …“\n– Herberts Haus","Zauber",[],["Ionia"],"GEWÖHNLICH"],"03MT052":["Sternenquelle","Rundenende: Heile verletzte Verbündete um 1. Wenn ich gesehen habe, wie du bei Verbündeten 22+ Leben geheilt hast, gewinnst du das Spiel.","","„Bis hoch zum fallenden heiligen Fluss,\nTief in die Teiche, die heilenden Quellen\nScheint das Licht, erstrahlt das Wasser,\nLausche dem Flussgesang,\nHoch auf dem Kristallberg.“\n– Ottrani-Vers","Wahrzeichen",[],["Targon"],"EPISCH"],"03MT064":["Targons Gipfel","Rundenbeginn: Senke die Kosten einer zufälligen Karte auf der Hand ALLER Spieler in dieser Runde auf 0.","","Targons kristalliner Beschützer bewacht das Tor zum himmlischen Reich. In seiner Gegenwart schwindet alles – Hoffnung, Zweifel und Angst. Seine Prüfungen machen alle sterblichen Belange unwichtig und entblößen die Essenz der Seele des Reisenden. Danach wird er gerichtet, denn der Wächter ist der große Beurteiler. ","Wahrzeichen",[],["Targon"],"EPISCH"],"03SI008":["Zerfallen","Töte einen Verbündeten, um eine Einheit zu töten oder ein Wahrzeichen zu zerstören.","","Auf diesen heimgesuchten Inseln ist nichts von Dauer. Alles endet.","Zauber",[],["Schatteninseln"],"SELTEN"],"03PZ001":["Die Universität von Piltover","Rundenbeginn: Wirf deine Hand ab. Erschaffe 3 zufällige Karten auf der Hand und gewähre ihnen Flüchtig.","","Die Erfindungen von Professor Cecil B. Heimerdinger haben ihn berühmt gemacht, doch es waren seine lebhaften Vorlesungen und die berüchtigten unvorhersehbaren Demonstrationen, die ihm den dauerhaften Ruf als Piltovers genialsten Kopf beschert haben.","Wahrzeichen",[],["Piltover & Zhaun"],"EPISCH"],"03FR003":["Eines, das starrt","Ausspielen: Vernichte ALLE Wahrzeichen oder verursache 3 Schaden an ALLEN anderen Einheiten.","","„Wir hatten keine Zeit, unsere Habseligkeiten zu packen oder die anderen zu warnen. Wir konnten nur in den Wald rennen und dabei zusehen, wie unsere Heimat dem Erdboden gleichgemacht wurde.“\n– Dorfwache der Avarosa","Einheit",[],["Freljord"],"SELTEN"],"03MT026":["Rahvun, Speer des Tageslichts","Tagesanbruch: Erschaffe eine zufällige Tagesanbruch-Karte auf der Hand.\nFür uns ist immer Tag.","","„Haltet an eurem Glauben fest, Ra-Horak, dann wird euer Licht nie schwächer werden!“","Einheit",[],["Targon"],"SELTEN"],"03MT067":["Kristallsteinbock","Ausspielen: Gewähre einem Verbündeten Überwältigen.","","Diejenigen, die den Targon bezwingen wollen, sollten sich mit der örtlichen Fauna anfreunden. Keine Kreatur kennt die Gefahren des Targon besser und niemand kann schneller durch sein eisiges Terrain reisen.","Einheit",[],["Targon"],"GEWÖHNLICH"],"03MT084":["Formung der Sterne","Ersuche eine himmlische Karte mit 7+ Kosten. Heile dann einen Verbündeten oder deinen Nexus um 5.","","„Sieh hinauf zu den Sternen. Wenn du Glück hast, sehe ich zurück zu dir.“\n– Aurelion Sol","Zauber",[],["Targon"],"GEWÖHNLICH"],"03MT221":["Die Reißzähne","Ausspielen: Ersuche eine himmlische Karte, die 3 oder weniger kostet.","","„Mutter Mond, zeige mir den Weg,\nÖffne mir den Himmel,\nLass mich hinter den Schleier blicken.“\n– Gebet der Lunari","Einheit",[],["Targon"],"EPISCH"],"03MT093":["Wanderstern","Verursache 5 Schaden an einem Gegner, der in dieser Runde angegriffen hat oder betäubt ist.","","„Kawummsi!“\n– Zoe","Zauber",[],["Targon"],"GEWÖHNLICH"],"03MT073":["Dämmerungsbringerin der Lunari","Wenn ich beschworen werde, erschaffe 1 Abendblütenstaub auf der Hand.","","„Abendblüten erblühen in der Nacht, und auch dann nur unter dem Licht eines Vollmondes. Sie sind ein stolzes Symbol der Lunari und wir nutzen ihren Staub seit Jahrhunderten, da nur wir wissen, wie man ihn sicher erntet.“","Einheit",[],["Targon"],"GEWÖHNLICH"],"03MT002":["Einsturz des Himmels","Ich koste 2 weniger für jeden verbündeten Drachen oder Himmlischen, den du hast. Verursache 15 Schaden an allen Gegnern.","","„Wenn die Zeit reif ist, werde ich an Runeterra vermutlich ein Exempel statuieren. Womöglich werde ich die qualmenden Überreste des Planeten bis in alle Ewigkeit hinter mir herziehen. Wie ein kaputtes, wertloses Spielzeug. Ich weiß es noch nicht. Ich habe nicht viel darüber nachgedacht.“\n– Aurelion Sol","Zauber",[],["Targon"],"EPISCH"],"03MT217":["Aphelios","Nachteinbruch: Wähle eine Mondwaffe, die auf der Hand erschaffen wird.\nWenn du in einer Runde das erste Mal 2 andere Karten ausspielst, erschaffe die Mondwaffe der nächsten Phase auf der Hand, wenn du noch keine hast.","Du hast 4+ Mondwaffen ausgespielt.","„Mit jeder Auseinandersetzung zeigen wir den Solari, dass wir ihren Respekt verdienen. Wir haben sie gelehrt, dass das Licht des Mondes dem Licht ihrer Sonne ebenbürtig ist. Wir haben sie gelehrt, nicht jenes zu missachten, was sie nicht kennen. Und was die Lektionen angeht, die sie erst noch lernen müssen …“\n– Halbmondsprecher der Lunari","Einheit",[],["Targon"],"Champion"],"03MT044":["Sonnenwächter","Tagesanbruch oder wenn du einen anderen Tagesanbruch aktivierst: Gewähre mir +1|+1.","","„Strahlender Beschützer, dein Zorn brennt wie die Mittagssonne. Komm herbei und bestrafe jene, die in diesen geweihten Ort eindringen.“\n– Inschrift des Sonnenwächters","Einheit",[],["Targon"],"EPISCH"],"03MT056":["Diana","Nachteinbruch oder wenn du einen anderen Nachteinbruch aktivierst: Gib mir in dieser Runde Herausforderer.","Du hast Nachteinbruch 4+ Mal aktiviert.","In Silber und Blau gekleidet stand sie inmitten der Lunari und bereitete sich auf die Schlacht vor, ihre Augen wie Sterne, und strahlte pures Licht aus. Der Mond ging auf und badete sie in seinem Schein, während die versammelten Lunari ihre Augen schlossen, vertieft in Dankbarkeit und im Gebet für ihre Sicherheit.","Einheit",[],["Targon"],"Champion"],"03MT020":["Strahlendes Lumihorn","Ausspielen: Heile einen Verbündeten und deinen Nexus um 3.","","„Siehst du diesen Stern, der sich über den Nachthimmel bewegt? Das ist ein ausgewachsenes Lumihorn. Die kleinen leihen uns ihre Heilungsmagie, bis sie wieder an den Himmel zurückkehren, aber die großen beherrschen diese Macht selbst. Es soll Glück bringen, wenn man eines sieht und als solches erkennt. Noch mehr Glück bringt es, eines zu pflegen.“\n– Lidari, Hüterin der Sterne","Einheit",[],["Targon"],"GEWÖHNLICH"],"03MT091":["Supercoole Sternenkarte","Ersuche eine himmlische Karte, die 3 oder weniger kostet.","","„Und diese drei EXTRA funkelnden Sterne nenne ich … ‚Das himmlische Springseil‘! Oder ist es eher ein umgedrehtes Grinsegesicht?“\n– Zoe","Zauber",[],["Targon"],"SELTEN"],"03MT047":["Cygnus der Mondjäger","Nachteinbruch: Gib einem Verbündeten in dieser Runde Ungreifbar.","","Die Lunari erwarteten die Abenddämmerung und die Sicherheit, die sie versprach. Der Pfad vor ihnen schien verlassen, aber Cygnus wusste, dass vor ihnen ein Solari-Lager wartete. Auf eine Geste hin formierten sich die anderen hinter ihm.","Einheit",[],["Targon"],"EPISCH"],"03MT094":["Schattenspionin der Lunari","Nachteinbruch: Gewähre mir Ungreifbar.","","„Richten wir unsere Augen zum Himmel, zur Sonne, zum Licht unserer He– Augenblick … was …? Was ist das …?“\n– Priesterin der Solari","Einheit",[],["Targon"],"GEWÖHNLICH"],"03MT036":["Segen des Targon","Gewähre einem Verbündeten +3|+3.","","„Eine kleine Aufmerksamkeit vom Targon.“\n– Taric","Zauber",[],["Targon"],"SELTEN"],"03MT092":["Bergziege","Schlag: Erschaffe 1 Juwel auf der Hand.","","Die Ziegen des Targon sind noch gefährlicher als ihre gewöhnlichen Verwandten, denn die Edelsteine, aus denen ihre Hörner sind, hinterlassen bei einem Treffer schmerzhafte Splitter in ihrem Gegner. ","Einheit",[],["Targon"],"SELTEN"],"03MT060":["Breitschultriger Beschützer","Rundenbeginn: Heile deinen Nexus um 3. Ich nehme Schaden in Höhe der Heilung.","","„Niemand kennt die Pfade des Targon so gut wie ich, also muss ich mich um die, äh, eigenwilligeren Lumihörner kümmern. Gut, dass sie mich haben!“ ","Einheit",[],["Targon"],"EPISCH"],"03MT001":["Freche Wolkenfrettchen","Ausspielen: Betäube Gegner mit 2 oder weniger Stärke.","","In der kristallinen Stille der Berge konnten sie das helle Klirren von fallendem Eis hören und weit über ihnen etwas, das nach … Gelächter klang.","Einheit",[],["Targon"],"GEWÖHNLICH"],"03MT055":["Soraka","Unterstützung: Heile mich und meinen unterstützten Verbündeten um 4.","Du hast verletzte Verbündete 4+ Mal geheilt.","„Heilen ist ein selbstloser Akt, das liegt in seiner Natur. Du musst ihnen die Stärke nicht nehmen, sie wird willentlich gegeben. Zeig ihnen Mitgefühl und du wirst sie leuchten sehen.“","Einheit",[],["Targon"],"Champion"],"03MT048":["Segenspenderin","Wenn ich beschworen werde, erschaffe 1 Juwel auf der Hand.","","„Es heißt, der Beschützer habe diese Edelsteine gesegnet. Trage sie, dann ist er im Geiste bei dir.“","Einheit",[],["Targon"],"GEWÖHNLICH"],"03MT082":["Morgenlicht","Gib Verbündeten in dieser Runde +1|+1.\nAktiviere den Tagesanbruch-Effekt eines Verbündeten.","","„Wir erheben uns mit der Dämmerung! Marschiert ins Licht!“\n– Leona","Zauber",[],["Targon"],"SELTEN"],"03MT058":["Taric","Unterstützung: Ich gebe meinem unterstützten Verbündeten und mir in dieser Runde Robust. Kopiere deinen letzten nur auf mich ausgespielten Zauber in dieser Runde auf diesen Verbündeten (wird nicht erneut kopiert).","Ich habe gesehen, wie du Verbündete 7+ Mal unterstützt oder anvisiert hast.","„Tarics Freundlichkeit inspiriert alle, die ihm begegnen und ermutigt sie, in sich selbst die Wärme zu finden, um selbst die kälteste Nacht zu überstehen.“\n– Weissager des Berges","Einheit",[],["Targon"],"Champion"],"03MT062":["Gutgelaunte Glitzerologin","Ausspielen: Wenn du eine sichtbare himmlische Karte hast, gewähre einem Verbündeten +1|+1 und Zauberschild.","","„… und dann ist ein Glitzerfalter wie Sternenstaub, und fällt auf den Boden, aber dann fliegt er wieder hinauf und ist ganz großartig und letzte Nacht habe ich einen gesehen, der war sooo schön, aber jetzt habe ich Hunger, und der flog hoch bis zu den STERNEN und dann …“","Einheit",[],["Targon"],"SELTEN"],"03MT040":["Glitzerfalter","","","„Hoffnung ist zerbrechlich, sie fliegt immer höher und sollte nie gefangen werden.“\n– Priesterin der Lunari","Einheit",[],["Targon"],"GEWÖHNLICH"],"03MT086":["Zerstreute Zeichnerin","Ausspielen: Wirf 1 Karte ab, um eine himmlische Karte zu ersuchen, die 3 oder weniger kostet.","","„Das mag ich besonders! Ich nenne es ‚Metaphysische Identität der bewussten Psyche‘. Aber wenn du den Kopf so neigst … sieht es irgendwie aus wie zwei Löffel.“","Einheit",[],["Targon"],"SELTEN"],"03MT016":["Ängstlicher Dickhäuter","","","„Ooch, will der große Dickhäuter nicht durch das kleine Portalchen? Das ist okay, wir können– HAHAHAHA, war nur Spaß. RAUSMITDIR!“\n– Zoe","Einheit",[],["Targon"],"GEWÖHNLICH"],"03MT054":["Leona","Tagesanbruch: Betäube den stärksten Gegner.","Du hast Tagesanbruch 5+ Mal aktiviert.","Sie stand zwischen den anderen und bereitete sich auf die Schlacht vor. Mit Augen wie Glut strahlte sie in Scharlachrot und Gold gekleidet ihr Licht aus. Als die Sonne aufging und sie mit ihrem Licht krönte, senkte jeder anwesende Solari seine Augen – jedoch nicht aus Scham, sondern um ihrer leuchtenden Anführerin Ehre zu erweisen.","Einheit",[],["Targon"],"Champion"],"03MT220":["Der Widdersprung","Nachteinbruch: Betäube einen Gegner. Ist er ein Begleiter, betäube ihn beim nächsten Rundenbeginn erneut.","","„Mutter Mond, die Nacht wartet schon,\nMögen wir unsere Peiniger aufhalten,\nerteilen wir ihnen eine Lektion.“\n– Gebet der Lunari","Einheit",[],["Targon"],"SELTEN"],"03MT021":["Ewige Spalter des Verstands","Ausspielen: Wähle 2 Gegner.\nRundenbeginn: Betäube sie.","","Reisende, die dieser Kreatur in die Augen sehen, sollen von einem so tiefgründigen Wissen, einer so großartigen Einsicht überwältigt werden, dass ihr Verstand unter ihrem Blick zusammenbricht.","Einheit",["DRACHE"],["Targon"],"EPISCH"],"03MT006":["Inviolus Vox","Wenn ein Verbündeter mit Zorn zum ersten Mal in einer Runde einen Gegner tötet, erschaffe einen zufälligen Drachenbegleiter auf der Hand.","","„Schaut zum Himmel und sehet, was ich sehe! Erst die Signale, denn in der Nacht glänzen sie. Dann kommt der Zorn, denn bei Tag steht alles lichterloh in Flammen. Ihr werdet sehen! Wir alle werden sehen!“\n– Verkünderin der Drachen","Einheit",["DRACHE"],["Targon"],"EPISCH"],"03MT015":["Erblickt das Unendliche","Ersuche.","","Die Himmel erstrecken sich über dir, ein schwarzer Vorhang erleuchtet von funkelnden Sternen. Du bist in dieser Weite klein und dein Leuchten schwach. Wohin schweift dein Blick zuerst?","Zauber",[],["Targon"],"GEWÖHNLICH"],"03MT013":["Verhängnis des Mondlichts","Lasse 2 gegnerische Einheiten in dieser Runde verstummen.\nNachteinbruch: Sie können in dieser Runde nicht abwehren.","","„Wer das Mondlicht nicht gewöhnt ist, muss lernen darin zu sehen, sonst wird er nie etwas erkennen.“\n– Diana","Zauber",[],["Targon"],"GEWÖHNLICH"],"03MT009":["Zoe","Nexusschlag: Erschaffe 1 Supercoole Sternenkarte auf der Hand oder senke ihre Kosten um 1, wenn du schon eine hast.","Ich habe gesehen, wie du 10 Karten mit verschiedenen Namen ausgespielt hast.","„Hey, halloooo! Was machst du da? Ist das ein KARTENSPIEL? Kann ich auch spielen? Was?! ICH bin in DEINEM Spiel? Ha! Das ist ’ne verrückte Dimension …“","Einheit",[],["Targon"],"Champion"],"03MT087":["Aurelion Sol","Ausspielen: Ersuche eine himmlische Karte mit 7+ Kosten.\nRundenbeginn: Erschaffe eine zufällige himmlische Karte auf der Hand.","Rundenende: Verbündete haben 20+ Gesamtstärke.","„Es ist mir egal, was du über mich schreibst, mittelprächtige Kreatur! Aber sorge dafür, dass man mich als gutaussehend bezeichnet. Und als grandios. Und als sehr, sehr intelligent. Weißt du, wie man das schreibt?“","Einheit",["DRACHE"],["Targon"],"Champion"],"03MT019":["Bastion","Gewähre einem Verbündeten +1|+1 und Zauberschild.","","„Ehre dem Berg.“\n– Taric","Zauber",[],["Targon"],"GEWÖHNLICH"],"03MT214":["Der Flug","Nexusschlag: Ziehe 1 und lege mich in die obersten 3 Karten deines Decks.","","„Mutter Mond, schenke mir Zuversicht,\nErfülle mich mit der Überzeugung des Flugs,\nZeige mir meinen Pfad.“\n– Gebet der Lunari","Einheit",["VOGEL"],["Targon"],"SELTEN"],"03MT071":["Tyari der Reisende","Unterstützung: Ich gewähre meinem unterstützten Verbündeten +0|+2.","","Auf einer Reise muss man sich der Erfahrung öffnen, die einen unausweichlich verändert. Durch die Reise nimmt man etwas Neues mit sich … und lässt etwas von seinem alten Wesen zurück. ","Einheit",[],["Targon"],"GEWÖHNLICH"],"03MT008":["Wunsch","Heile verletzte Verbündete vollständig.","","„Für das Leben!“\n– Soraka","Zauber",[],["Targon"],"SELTEN"],"03MT023":["Sonnenexplosion","Verursache 6 Schaden an einer Einheit.\nTagesanbruch: Lasse sie stattdessen in dieser Runde verstummen und verursache 6 Schaden an ihr.","","Wenige Dinge überstehen einen Blick, der so unerbittlich ist wie der der Sonne.","Zauber",[],["Targon"],"SELTEN"],"03MT045":["Astraler Schutz","Heile einen Verbündeten um 4 und gewähre ihm +0|+4.","","„Hast du gedacht, du hättest uns besiegt? Ha! Das war nur der Anfang.“\n– Breitschultriger Beschützer","Zauber",[],["Targon"],"GEWÖHNLICH"],"03MT080":["Bewahrer der Quellen","Wenn ich beschworen werde, erschaffe 1 Segen der Quellen auf der Hand.","","„Ich kümmere mich hauptsächlich um die Quellen, doch ein Hirte muss sich meistens um seine Herde kümmern. Manchmal geraten die Prioritäten aneinander.“","Einheit",[],["Targon"],"GEWÖHNLICH"],"03MT042":["Zauberklau","Manifestiere einen gegnerischen Zauber, der in diesem Spiel ausgespielt wurde.","","„Oh, das war so TOLL! Aber wie viel cooler wäre es, wenn ich das stattdessen selbst mache! OKsupidanke!“\n– Zoe","Zauber",[],["Targon"],"SELTEN"],"03MT057":["Sonnenschmied der Solari","Tagesanbruch: Gib mir in dieser Runde Lebensraub.","","Der Sonnenschmied hielt den Fokuskristall hoch, während Licht den Raum flutete. Das Solari-Artefakt bündelte die hellen Sonnenstrahlen zu einer mächtigen Verzauberung für seine Waffe.","Einheit",[],["Targon"],"GEWÖHNLICH"],"03MT041":["Mentor der Steine","Unterstützung: Ich gewähre meinem unterstützten Verbündeten +2|+2.\nLetzter Wunsch: Erschaffe 3 Juwelen auf der Hand.","","„Hast du irgendwas von dem verstanden, was er da drin gesagt hat?“\n„Kein Wort. Klang aber nett.“\n– Emir und Haley, Besucher des Berges","Einheit",["YORDLE"],["Targon"],"EPISCH"],"03MT027":["Zenitklinge","Gewähre einem Verbündeten +1|+2. Gib ihm in dieser Runde Überwältigen.\nTagesanbruch: Ziehe 1 Zenitklinge.","","„Lass die Sonne dich mit ihrer Kraft erfüllen!“\n– Priesterin der Solari","Zauber",[],["Targon"],"GEWÖHNLICH"],"03MT096":["Priesterin der Solari","Tagesanbruch: Ersuche eine himmlische Karte, die 4, 5 oder 6 kostet.","","Die Solari richten wie alle Targonier auf der Suche nach Führung ihren Blick zu den Sternen, denn der in ihrem Glaube wichtigste Stern ist die Sonne.","Einheit",[],["Targon"],"SELTEN"],"03MT028":["Schildträgerin der Solari","Tagesanbruch: Gib mir in dieser Runde +0|+4.","","„Es war dumm, nicht im Schutz der Nacht zu kommen.“ Die Schildträgerin richtete sich auf. „Leg deine Waffen nieder und komm friedlich mit.“\nDie Lunari kniete still nieder und zückte ihre gekrümmten Klingen erneut.\nSo sei es.\nDie Solari machte sich bereit und erhob ihren Schild, um die Strahlen der aufgehenden Sonne zu spiegeln. ","Einheit",[],["Targon"],"GEWÖHNLICH"],"03MT089":["Wächter der Mondsichel","Nachteinbruch: Gewähre mir +2|+0.","","„Stoischer Beschützer, die sanfte Berührung des Vollmondes erneuert deine Kraft. Erwache und beschütze uns vor denen, die in diesen heiligen Ort eindringen wollen.“\n– Inschrift des Wächters der Mondsichel","Einheit",[],["Targon"],"SELTEN"],"03MT051":["Leitende Berührung","Heile einen Verbündeten oder deinen Nexus um 2. Ziehe 1.","","Lumihörner leuchten am hellsten, wenn sie glücklich sind.","Zauber",[],["Targon"],"GEWÖHNLICH"],"03MT003":["Drachennest","Ziehe 2 verschiedene Drachen oder gewähre verbündeten Drachen +1|+1 und Überwältigen.","","„Ihre Rufe hören sich an wie eine heisere Katze. Wenn du sie hörst, dann nimm die Beine in die Hand und lauf zur nächsten Wachpatrouille. Ist das klar? Denn wo Dracheneier sind, da sind auch Drachen.“\n– Targonischer Wildbeuter","Zauber",[],["Targon"],"SELTEN"],"03MT098":["Gesegnete Kraft der Sonne","Gewähre einem Verbündeten +0|+2.","","„Unser Schild ist unsere Überzeugung, unsere Entschlossenheit, unser Vertrauen in das Licht!“\n– Schildträgerin der Solari","Zauber",[],["Targon"],"GEWÖHNLICH"],"03MT215":["Durch den Schleier","Wähle eine Mondwaffe, die auf der Hand erschaffen wird.","","„Öffne dich, Aphelios …“\n– Alune","Zauber",[],["Targon"],"GEWÖHNLICH"],"03MT063":["Mondträumerin","Ausspielen: Ersuche.\nNachteinbruch: Senke die Kosten dieser Karte um 1.","","„Sieh nur, all unsere Freunde am Himmel! Siehst du den total hellen Stern? Das ist das Auge des Boten, der auf uns herabblickt! Der trübe Sternhaufen da drüben? Dort verbirgt sich der Trickster hinter den Wolken! Und dort drüben– KULUN, SCHH! Du kannst die nicht herunterziehen …!“","Einheit",[],["Targon"],"GEWÖHNLICH"],"03MT100":["Drache der Eklipse","Tagesanbruch: Der nächste Drache oder die nächste himmlische Einheit, die du ausspielst, kostet 2 weniger.\nNachteinbruch: Erschaffe einen zufälligen Drachen und himmlischen Begleiter auf der Hand.","","Drachenschuppe (Drache der Eklipse, Draco Obscuratus)\nNotizen: Schuppe hat unglaubliche optische Eigenschaften. Im direkten Sonnenlicht extrem reflektierend.\nGekritzelt: NACHTS LEUCHTET SIE!\n– Notizen von Anden Mayne, eierköpfiger Forscher","Einheit",["DRACHE"],["Targon"],"SELTEN"],"03MT076":["Weissager des Berges","Deine himmlischen Karten kosten 1 weniger.\nLoyalität: Ersuche.","","„Man kann viel von den Sternen und ihrer Anleitung lernen. Für uns sind sie eine Konstante, ein Weg, unseren Pfad zu verfolgen.“","Einheit",[],["Targon"],"SELTEN"],"03MT029":["Sternenhirtin","Wenn du einen verletzten Verbündeten heilst, gewähre mir +2|+0.","","„Seit ich das erste Mal eines über den Nachthimmel fliegen gesehen habe, liebe ich Lumihörner. Wenn ich nur gewusst hätte, dass ich mal so viele treffen würde!“","Einheit",[],["Targon"],"SELTEN"],"03MT219":["Der verschleierte Tempel","Wenn du in einer Runde das erste Mal 2 andere Karten ausspielst, fülle 2 Mana wieder auf und gewähre deinem stärksten Verbündeten +1|+0.","","Hier, im Reich der Geister, tritt Alune mit ihrem Bruder Aphelios in Kontakt. Sie flüstert dem stillen Assassinen Worte des Trosts zu und reicht ihm seine Waffen der Vergeltung durch den Schleier.","Wahrzeichen",[],["Targon"],"SELTEN"],"03MT079":["Sternenstrolch","Ich koste 2 weniger, wenn du eine sichtbare himmlische Karte hast.","","„Erwachsene sind LANGWEILIG. Die einzig coolen hier sind Zoe und ihre Freunde. Von denen kann ich viel lernen. Nicht wie diese ätzende Strahle-Priesterin. Oh MANN.“","Einheit",[],["Targon"],"GEWÖHNLICH"],"03MT007":["Flügges Lumihorn","","","„Wie jedes flügge Tier muss ein junges Lumihorn irgendwann zu seinem ersten zaghaften Flug aufbrechen. Darin ähneln sie all den anderen Sternen am Nachthimmel, denn sie fallen ebenso leicht. Zum Glück sind wir da, um sie aufzufangen und sie zurückzubringen, wenn sie bereit sind.“\n– Lidari, Hüterin der Sterne","Einheit",[],["Targon"],"GEWÖHNLICH"],"03MT038":["Weißflammen-Beschützer","","","Es waren die Kinder des Targon, die sich zuerst mit den jüngeren, friedlicheren Drachen anfreundeten. Vielleicht spürten die jugendlichen Kreaturen die unschuldige Neugier der Kinder und entschieden sich, diese zu beschützen. ","Einheit",["DRACHE"],["Targon"],"GEWÖHNLICH"],"03MT014":["Verkünderin der Drachen","Verbündete Drachen kosten 1 weniger.","","Die Wolken schmiegten sich um ihre gewaltigen Silhouetten und der Himmel selbst schien durch ihre klagenden Rufe zu erbeben. Sie wusste, was bevorstand, und doch empfand sie keine Furcht, sondern die warme Umarmung des Schicksals.","Einheit",[],["Targon"],"SELTEN"],"03MT110":["Aus dem Weg","Für den Rest des Spiels sind verbündete Buffs für diese Runde (außer Barriere) permanent. Ziehe 1.","","„You know I mean everything that I say\nWhen you see me coming get out of the way\nI came to slay I came to slay\nBack and I’m better and ready to stay.“\n– Kai’Sa, „THE BADDEST“","Zauber",[],["Targon"],"EPISCH"],"03MT017":["Siegel des Boten","Erschaffe 5 Exemplare von Der Bote in deinem Deck.","","„Zeit verstreicht, die Himmel ordnen sich neu. Die Schlange tritt zur Seite und der Bote nimmt ihren Platz ein. Eine Zeit des Überflusses steht bevor …“\n– Priesterin der Lunari","Zauber",[],["Targon"],"SELTEN"],"03MT025":["Splitter des Berges","Fülle deine Hand mit Juwelen.","","„Wenn man einen Edelstein bewegt, tanzt das Licht darin. Wie bei einem Lebewesen wohnt ihm ein Feuer inne.“\n– Taric","Zauber",[],["Targon"],"EPISCH"],"03MT216":["Die Himmelsschatten","Wenn ich beschworen werde, fülle 2 Zaubermana wieder auf, wenn du eine sichtbare Karte mit Nachteinbruch hast.","","„Mutter Mond, lass mich nicht vergessen,\nDass trotz meiner Einsamkeit\nDeine Kinder über mir tanzen\nUnd ich nicht allein bin.“\n– Gebet der Lunari","Einheit",[],["Targon"],"GEWÖHNLICH"],"03MT012":["Beurteiler des Gipfels","Ich koste 1 weniger für jedes Mal, wenn du in diesem Spiel Verbündete anvisiert oder unterstützt hast.","","Der Beurteiler ist die letzte Prüfung des Berges, denn nur der Wächter sieht hinter die Taten des Kletterers und in seinen Geist.","Einheit",[],["Targon"],"EPISCH"],"03MT085":["Stille","Lasse eine Einheit in dieser Runde verstummen.","","„Sie werden zur Ruhe kommen.“\n– Soraka","Zauber",[],["Targon"],"SELTEN"],"03MT081":["Besucher des Berges","Unterstützung: Ich gewähre meinem unterstützten Verbündeten +2|+2. Hat dieser Verbündete Unterstützung, gewähre dem von ihm unterstützten Verbündeten +2|+2 und setze dies weiter fort.","","Jedes Wesen, das sich dem Targon stellt, hat einen Grund für den Aufstieg. Manche wollen sich vor ihren Freunden beweisen. Andere wollen sich selbst etwas beweisen.","Einheit",[],["Targon"],"EPISCH"],"03MT030":["Sterndeuterin","Wenn du einen verletzten Verbündeten heilst, gib ihm in dieser Runde Ungreifbar.","","„Die Sterne sind nur eine begrenzte Zeit mit uns. Sobald ich mich um sie gekümmert habe, schicke ich sie zurück in den Himmel, mit einem Blitz aus Sternenlicht … und zappelnden Hufen.“","Einheit",[],["Targon"],"SELTEN"],"03MT088":["Soldat der Solari","Tagesanbruch: Gib mir in dieser Runde +1|+1.","","Die Sonne wärmte ihn, als er vor dem Gefängnis der Ketzerin wachte und die leisen Bitten ignorierte, die bald bitterer Stille wichen.","Einheit",[],["Targon"],"GEWÖHNLICH"],"03MT033":["Großvater Rumul","Ausspielen: Gewähre 2 Verbündeten +0|+4.","","„Ohren auf, Osu. Hörst du das? Glocken! Großvater ist zurück!“\n– Illi, Sternenhirtin","Einheit",[],["Targon"],"SELTEN"],"03MT035":["Fahle Kaskade","Gib einem Verbündeten in dieser Runde +1|+1.\nNachteinbruch: Ziehe 1.","","„Im Schutze der Dunkelheit, bewacht von einem fahlen Mond.“\n– Diana","Zauber",[],["Targon"],"GEWÖHNLICH"],"03MT075":["Priesterin der Lunari","Nachteinbruch: Ersuche.","","„Oh Sterne über uns, die Pilgern gleich durch die Weite der Nacht ziehen – bleibt doch bei uns und erzählt, was ihr gesehen habt.“\n– Lobgesang des Abends","Einheit",[],["Targon"],"SELTEN"],"03MT218":["Sternenknochen","Wenn du einen sichtbaren Himmlischen hast, erschaffe Der Bote in deinem Deck und gewähre himmlischen Verbündeten überall +1|+1.","","„Möge der Bote spielen,\nUnd sein Überschwang\nDie Sterne entfachen.“\n– Gebet der Lunari","Zauber",[],["Targon"],"EPISCH"],"03MT074":["Schlafblasen-Alarm","Betäube einen Gegner. Erschaffe 1 flüchtigen Wanderstern auf der Hand.","","„Schlafenszeit für dich! Ein Glitzerfalter, zweeeei Glitzerfalter, drei– Hey, wasistdasdennda?“\n– Zoe","Zauber",[],["Targon"],"SELTEN"],"03MT072":["Versengter Feuerspeier","","","Unzählige Herausforderungen erwarten jene, die den Targon erklimmen. Manche, wie der endlose Aufstieg, zehren langsam an ihrer Kraft. Manche zeigen sich sofort.","Einheit",["DRACHE"],["Targon"],"GEWÖHNLICH"],"03MT039":["Flatternder Poro","","","Im Weltraum hört dich niemand quieken.","Einheit",["PORO"],["Targon"],"GEWÖHNLICH"],"03PZ019":["Geflickter Porobot","Während ich auf der Hand bin, habe ich ein zufälliges Schlüsselwort, das sich jede Runde ändert. Wenn ich beschworen werde, gewähre mir dieses Schlüsselwort.","","Nicht ganz so flauschig wie ein echter, aber er ist genauso niedlich.","Einheit",["PORO"],["Piltover & Zhaun"],"SELTEN"],"03PZ005":["Ballistik-Bot","Rundenbeginn: Erschaffe 1 Zündung auf der Hand.","","Proband gab an, nur seinen Geist intakt halten zu wollen, genauer Wortlaut: „Dort bewahre ich all meine Rachepläne auf.“\n– Augmentor-Log, Eintrag 1011","Einheit",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"03PZ004":["Todesstrahl – Mk 1","Verursache 1 Schaden an einer Einheit. Erschaffe 1 Todesstrahl – Mk 2 in den obersten 3 Karten deines Decks.","","„Heute habe ich erfolgreich demonstriert, dass Strahlungsenergie zu einem einzigen mächtigen Strahl gebündelt werden kann! Mit den richtigen Verbesserungen kann dieser Strahl zu einem Werkzeug unerreichter Präzision werden, aber es gibt noch viel zu tun.“\n– Viktors Entwurfsnotizen","Zauber",[],["Piltover & Zhaun"],"SELTEN"],"03PZ003":["Viktor","Wenn ich beschworen werde oder Rundenbeginn: Erschaffe 1 Hexkern-Aufrüstung auf der Hand.","Du hast 7+ erschaffene Karten ausgespielt.","„Zhaun, du hast mehr als genug Tragödien gesehen und die Zeit für Veränderung ist gekommen. Und wie jeder große Fortschritt muss dieser in dir selbst beginnen.“","Einheit",[],["Piltover & Zhaun"],"Champion"],"03PZ010":["Innovative Imitatorin","Angriff: Gewähre mir alle Schlüsselwörter von Verbündeten.","","„Ich bin genau wie du, nur besser.“","Einheit",[],["Piltover & Zhaun"],"EPISCH"],"03PZ022":["Gib alles","Erhöhe Stärke und Leben aller Verbündeten auf den höchsten verbündeten Wert.\nGewähre allen Verbündeten andere verbündete Schlüsselwörter.","","„I know I know\nYou want some more\nIf you ready let’s go\nGiving it all“\n– Seraphine, „MORE“","Zauber",[],["Piltover & Zhaun"],"EPISCH"],"03PZ014":["Kalkulierte Kreationen","Erschaffe 1 Experimentierfreudiger Tüftler, Ballistik-Bot oder Nyandroid auf der Hand und gewähre ihm +1|+1.","","„Rationalität und Entscheidungsfreiheit trennen die Menschheit von ihren grundlegenden tierischen Instinkten.“\n– Viktor","Zauber",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"03PZ013":["Iterative Optimierung","Wähle einen Begleiter. Erschaffe eine Kopie von ihm mit +1|+1 auf der Hand.","","„Selbstverbesserung ist ein Spiel, in dem du der Gute und der Böse bist. Du kämpfst. Du denkst vielleicht sogar, dass du gewonnen hast. Aber letztendlich stehst du dir selbst immer am meisten im Weg.“\n– Innovative Imitatorin","Zauber",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"03PZ025":["Stresstest","Entferne Flüchtig von allen Karten auf der Hand. Wenn ich abgeworfen werde, ziehe 1 flüchtige Karte.","","„Es ist eigentlich ganz simpel. Ich habe den Stahlrahmen durch eine robustere Legierung ersetzt und die Stromkreise von den Scharnieren umgeleitet, damit sich die Systeme nicht immer kurzschließen. Kinderkram.“\n– Chefmechanikerin Zevi","Zauber",[],["Piltover & Zhaun"],"SELTEN"],"03PZ012":["Experimentierfreudiger Tüftler","","","„Genial! Neuer Arm! Wollte ich schon immer haben. Was jetzt? Grav-Räder als Beine? Elektrogürtel? METALLZÄHNE? Ne, warte, mein Gesicht lassen wir so. Ich mag mein Gesicht.“","Einheit",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"03PZ020":["Hexkern-Werk","Rundenbeginn: ALLE Spieler ziehen 1.","","„Sollen sie über meine Methoden sagen, was sie wollen. Den Fortschritt können sie nicht leugnen – das Licht meines Wissens strahlt wie ein Leuchtfeuer durch die Dunkelheit ihrer Ignoranz!“\n– Viktor","Wahrzeichen",[],["Piltover & Zhaun"],"SELTEN"],"03PZ002":["Nyandroid","","","„Ich habe mich durch Jahre der akademischen Forschung in Piltover geschlagen, nur um meine Technologien als ‚zu gefährlich‘ und mich selbst als ‚zu niedlich‘ abgetan zu sehen! Jetzt breche ich nach Zhaun auf, wo zumindest ein großer Verstand miaune Ambitionen teilt …“","Einheit",["KATZE"],["Piltover & Zhaun"],"SELTEN"],"03PZ011":["Nachbeben","Verursache 3 Schaden an einer Einheit oder zerstöre ein Wahrzeichen.","","„Dieser Lichtstrahl wird unseren Marsch auf Piltover leiten. Nichts wird sich unserer glorreichen Evolution in den Weg stellen!“\n– Viktor","Zauber",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"03PZ017":["Dreistrahliger Improbulator","Verursache 1 Schaden an einer Einheit. Beschwöre einen zufälligen Begleiter mit 1 Kosten. Während ich auf der Hand bin, erhöhe beide Werte um 1, wenn du eine Karte mit 3 Kosten ausspielst.","","„… und in eins, zwei, und DREI!!! Oh. Ach du liebes bisschen … Schon wieder ein unvorhersehbares Ergebnis?!“\n– Heimerdinger","Zauber",[],["Piltover & Zhaun"],"EPISCH"],"03PZ018":["Poro-Kanone","Wirf zum Ausspielen 1 Karte ab.\nErschaffe 2 Waghalsige Poros auf der Hand.","","Zwei flaumige Formen flogen elegant über die verzückten Zuschauer. Eine flauschige Wolke und der leichte Geruch von Backwaren folgte ihnen.","Zauber",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"03SI004":["Lauernde Schatten","Wähle einen Begleiter aus den obersten 4 Karten deines Decks.\nZiehe ihn, lege den Rest zurück ins Deck und erschaffe dann eine exakte vergängliche Kopie auf der Hand.","","„Los … umzingelt sie …“\n– Nocturne","Zauber",[],["Schatteninseln"],"SELTEN"],"03SI001":["Schattenhafte Verfolger","Nachteinbruch: Erschaffe eine Kopie von mir auf der Hand.","","„Erst waren es nur zwei Augen und eine einzige Stimme, die in der Finsternis zwitscherte. Jedes Mal, als ich hinsah, waren es mehr. Und sie waren wütender. Lauter. Als ich endlich den „Walzahn“ sah, rannte ich los.“\n– Beutejäger des Walzahns","Einheit",[],["Schatteninseln"],"EPISCH"],"03SI018":["Völlerei","Töte einen Verbündeten mit Letzter Wunsch und beschwöre einen Begleiter aus deinem Deck, der 1 mehr kostet.","","„ESSEN FASSEN!“\n– Gefräßiger Schlächter","Zauber",[],["Schatteninseln"],"SELTEN"],"03SI012":["Überfahrt verwehrt","Vernichte alle Einheiten, die in dieser Runde beschworen anstatt ausgespielt wurden.","","„Natürlich gibt es den Tod in Demacia. Wir sehen, wie unsere Lieben von ihm dahingerafft werden und dass er eines Tages auch uns holen wird. Aber auf diesen Inseln … Ich kann den Tod fast schmecken. Ich spüre ihn in meinen Lungen, wenn ich atme, ich höre ihn in meine Ohren flüstern. Hier ist er nichts Abstraktes. Er sitzt hier mit mir. Jetzt. Und er wird uns alle holen.“\n– Notizen von Jens Tommen, Historiker","Zauber",[],["Schatteninseln"],"SELTEN"],"03SI014":["Herannahende Schatten","Gewähre ALLEN Verbündetem in deinem Deck und auf der Hand +2|+2 und Vergänglich.","","„Geist oder Körper … ich fürchte, die Albträume der Schatteninseln werden uns alle irgendwann brechen und der Wahnsinn wird ewig herrschen.“\n– Notizen von Jens Tommen, Historiker","Zauber",[],["Schatteninseln"],"EPISCH"],"03SI016":["Lass nicht locker","Entziehe einer Einheit 1.\nErschaffe 2 Kopien von Lass nicht locker in deinem Deck. Verwandle nach jedem dritten Mal alle Kopien von mir überall in Pack deine Taschen.","","„We go hard, ’til we get it, get it\nWe go hard, we so in it, in it\nWe Pop Stars (Pop Stars), only winning, winning now\nAin’t nobody bringing us down, down, down, down“\n– Evelynn, „POP/STARS“","Zauber",[],["Schatteninseln"],"EPISCH"],"03SI007":["Schleier der Dunkelheit","Wenn du das nächste Mal in dieser Runde einen Verbündeten beschwörst, gib ihm in dieser Runde +1|+0 und Zauberschild.","","„Sobald du den Zahn verlässt, spürst du ihn. Fingerspitzen, die sanft wie der Regen deinen Nacken entlangstreichen. Diese Viecher bewegen sich auch nicht, wenn du auf sie zurennst. Die haben keine Angst vor meiner Klinge oder der Fackel. Vor nichts. Furchtbare Dinger.“\n– Beutejäger des Walzahns","Zauber",[],["Schatteninseln"],"GEWÖHNLICH"],"03SI005":["Nocturne","Nachteinbruch: Belege einen Gegner mit Verletzlich und gib Gegnern in dieser Runde -1|-0.","Du hast mit 5+ Nachteinbruch- oder bedrohlichen Verbündeten angegriffen.","„Es scheint, dass es – sobald genug Seelen erschüttert wurden – in unsere Welt durchbricht. Man kann nur hoffen, dass dieses Monster zurück in sein Reich geschickt werden kann … aber hier ist die Hoffnung schon vor langer Zeit gestorben, mit dem letzten Atemzug einer Königin und dem ewigen Schrei eines Königs.“\n– Notizen von Jens Tommen, Historiker","Einheit",[],["Schatteninseln"],"Champion"],"03SI006":["Bestie der Verdammnis","Nachteinbruch: Entziehe dem gegnerischen Nexus 2.","","Mit jeder neuen Nacht werden die Reisenden müder. Ihr Schlaf ist ruhelos, ihre Träume so echt. Der Schlaf ist nicht länger erholsam, sondern entzieht ihren Knochen mehr und mehr das Leben.","Einheit",[],["Schatteninseln"],"GEWÖHNLICH"],"03SI015":["Plagegeist","Letzter Wunsch: Erschaffe 2 Exemplare von mir im gegnerischen Deck.","","Die meisten Geister der Schatteninseln sind unfassbar schreckliche und grauenhafte Kreaturen. Aber einige wenige sind … nun ja … einfach nur wirklich, wirklich nervig.","Einheit",[],["Schatteninseln"],"GEWÖHNLICH"],"03SI003":["Unheimlicher Beobachter","Nachteinbruch: Gib mir in dieser Runde +2|+0 und Bedrohlich.","","Wenn die Sonne sich verdunkelt, erwachen die Schrecken dieses Orts, halten Ausschau und warten.","Einheit",["VOGEL"],["Schatteninseln"],"GEWÖHNLICH"],"03SI002":["Entsetzlicher Schrecken","Entziehe einem beliebigen Ziel 1.\nNachteinbruch: Erschaffe eine zufällige Nachteinbruch-Karte auf der Hand.","","„Jeder Tag, der vergeht, zehrt an meinem Geist, entreißt mir die Entschlossenheit, die mich dazu gebracht hat, diesen Ort aufzusuchen. Der Walzahn ist voller ausgemergelter Gestalten, die sämtlichen Antrieb verloren haben. Und je länger ich bleibe, desto mehr werde ich wie sie.“\n– Notizen von Jens Tommen, Historiker","Zauber",[],["Schatteninseln"],"GEWÖHNLICH"],"03SI010":["Nachtmähre","Nachteinbruch: Gewähre mir +1|+0 für jeden aktivierten Nachteinbruch in diesem Spiel.","","Jedes Mal, wenn die Sonne untergeht, breitet die Nacht ihre dunklen Schwingen aus und löscht die letzten Reste Hoffnung aus, die der Tag brachte.","Einheit",[],["Schatteninseln"],"SELTEN"],"03SI013":["Aufgezogener Nebel","Beschwöre einen Nebelgeist.","","Die Nebelgeister bewegen sich durch Ebenen, die dem menschlichen Auge verborgen bleiben, erscheinen ohne Warnung und bringen allen Verzweiflung, die ihnen begegnen.","Zauber",[],["Schatteninseln"],"GEWÖHNLICH"],"03IO025":["Faustwirbel","Gewähre einem Verbündeten +1|+0 und Direktangriff. Wenn er das Schlüsselwort bereits hat, gewähre ihm stattdessen Doppelangriff.","","„Oft, schnell und fest zuschlagen.“\n– Hörner des Drachen","Zauber",[],["Ionia"],"SELTEN"],"03IO017":["Pix!","Unterstützung: Ich gebe meinem unterstützten Verbündeten in dieser Runde +2|+1.","","„Pix ist KLASSE, er ist klein und cool und nett,\ner mag am liebsten Opossums und er mag auch … hrmhmhmhrmhmnunja!“\n– Lulu","Einheit",["FEE"],["Ionia"],"GEWÖHNLICH"],"03IO008":["Laune","Verwandle einen Begleiter in dieser Runde in ein Eichhörnchen mit 1|1 und lasse ihn verstummen.","","„Niedlibus!“\n– Lulu","Zauber",[],["Ionia"],"GEWÖHNLICH"],"03IO001":["Blumenkind","Wenn ich unterstützt werde, gewähre mir +2|+0.","","Jeder will einen Begleiter, aber keiner ist auf die Verantwortung vorbereitet. Man muss mit ihnen Gassi gehen, auf gesunde Ernährung achten … sie stubenrein bekommen. Ist eine Menge Arbeit.","Einheit",["FEE"],["Ionia"],"GEWÖHNLICH"],"03IO019":["Eigenwille","Wähle einen Verbündeten. Rufe ALLE anderen Einheiten und Wahrzeichen zurück.","","„Ich gehe meinen Weg allein.“\n– Einsame Geistliche","Zauber",[],["Ionia"],"EPISCH"],"03IO002":["Lulu","Unterstützung: Mein unterstützter Verbündeter wächst in dieser Runde bis auf 4|4.","Verbündete wurden 3+ Mal unterstützt.","„Keine Angst, Pix! Wir verlassen die Feenwiese und dann kriegt ALLES UND JEDER ein Niedlibus ab! Bist du bereit?“","Einheit",["YORDLE"],["Bandle","Ionia"],"Champion"],"03IO011":["Muckihörnchen","Schlag: Verdopple meine Stärke.","","Sein Geheimnis sind Nusspulver-Shakes. Und zwar vier am Tag.","Einheit",["FEE"],["Ionia"],"SELTEN"],"03IO009":["Leckeres Feenvolk","","","Energie: 104 kJ (25 kcal), Kohlenhydrate: 5,88 g, Zucker: 3,53 g, Ballaststoffe: 3 g, Fett: 0,18 g, Protein: 0,98 g, Wasser: 92 g …","Einheit",["FEE"],["Ionia"],"GEWÖHNLICH"],"03IO003":["Pfadfinder der Feen","Ausspielen: Gewähre einem Verbündeten Ungreifbar.","","„Pssst! Hier lang. Nach dem laufenden Baumhaus gehen wir nach links, dann einfach an den quasselnden Blumen vorbei. Lu, hörst du mir zu? Lu? Lu! LULU! Fütter. Sie. NICHT. Lass das sein.“","Einheit",["YORDLE"],["Ionia"],"SELTEN"],"03IO007":["Herbert Schlummerich","Unterstützung: Erschaffe einen angreifenden Murmelgnom mit den Werten meines unterstützten Verbündeten.","","Du sollst deinen Träumen folgen und sie nicht durch andauernde gemurmelte Beschwörungen manifestieren, während du durch einen uralten magischen Wald schlafwandelst. Ich meine, ERNSTHAFT.","Einheit",["YORDLE"],["Ionia"],"EPISCH"],"03IO010":["Junge Hexe","Unterstützung: Ich gebe meinem unterstützten Verbündeten in dieser Runde Direktangriff und +1|+0.","","Sir Quakerich Montague verließ sein Zuhause in der Hoffnung, eine große Aufgabe zu erfüllen oder die Gunst eines wichtigen Hauses zu erringen. Das Schicksal führte ihn jedoch in einen verborgenen Bandlewald, wo die junge Bri Sir Quakerich in einen Frosch verwandelte und ihn auf IHR großes Abenteuer mitnahm. Der arme Quak!","Einheit",[],["Ionia"],"GEWÖHNLICH"],"03IO020":["Neinibus!","Halte einen schnellen oder langsamen Zauber auf, der 3 oder weniger kostet.","","„Lass das, du blöder Schnuffelfluff! Sonst tust du den Antylopen weh!“\n– Lulu","Zauber",[],["Ionia"],"SELTEN"],"03IO022":["Gönn’s dir","Rufe einen Verbündeten zurück, um eine exakte vergängliche Kopie an seiner Stelle zu beschwören. Senke seine Kosten in dieser Runde auf 0.","","„More\nKnow I got it,\nSo here you go,\nYou look like you could use some more.“\n– Akali, „MORE“","Zauber",[],["Ionia"],"EPISCH"],"03IO018":["Flauschiger Hüter","Wenn ich unterstützt werde, gib mir in dieser Runde +0|+3.\nUnterstützung: Ich gebe meinem unterstützten Verbündeten in dieser Runde +3|+0.","","Das violette Feenvolk besteht aus freundlichen kleinen Kreaturen und wird von allen gemocht, die einer davon begegnen. Na ja, von fast allen.","Einheit",["YORDLE"],["Ionia"],"SELTEN"],"03DE008":["Leutnant der Drachenwache","Wenn ich beschworen werde und du einen sichtbaren Drachen hast, gewähre mir Herausforderer.","","„Als ich meine Waffenbrüder bei Zaunkönigs Wacht verlor, dachte ich, ich hätte auch meine Entschlossenheit verloren … doch anscheinend gibt es nichts, dass nicht durch einen Kampf in einem alten Soldaten wieder aufgerüttelt werden kann.“","Einheit",[],["Demacia"],"GEWÖHNLICH"],"03DE001":["Konfrontieren","Gewähre einem Verbündeten Herausforderer.\nWenn er ein Drache ist, ziehe 1.","","„Niemand wird uns entkommen!“\n– Shyvana","Zauber",[],["Demacia"],"GEWÖHNLICH"],"03DE015":["Steinerner Unterdrücker","ALLE Zauber kosten 1 mehr.","","Was als ein formloser, grob behauener Petrizitblock beginnt, wird durch die fähigen Hände eines Bildhauers schnell zu mehr. Dann wird ein Stück wahrhaft zum Leben erweckt.","Einheit",[],["Demacia"],"SELTEN"],"03DE006":["Kreischender Drache","","","Alle Kreaturen beschützen ihre Jungen, aber wenige sind so gut auf jede mögliche Bedrohung vorbereitet wie ein Drache.","Einheit",["DRACHE"],["Demacia"],"GEWÖHNLICH"],"03DE025":["Lava-Atem","Ein Verbündeter mit Zorn schlägt die 2 schwächsten Gegner nacheinander.","","Jahrhundertelang kannten die Demacianer den Zorn eines Drachen nur aus Legenden. Seit Zaunkönigs Wacht ist das anders.","Zauber",["ELEMENTAR"],["Demacia"],"SELTEN"],"03DE002":["Luftschlag","Ein Verbündeter und ein Gegner schlagen sich gegenseitig. Wenn der Verbündete ein Drache ist, heile ihn dann um 5.","","Als Ritter und Drache sich verwundet und keuchend trennten, schien Letzterer wieder zu Kräften zu kommen. Er roch Blut und wollte mehr.","Zauber",[],["Demacia"],"SELTEN"],"03DE011":["Shyvana","Angriff: Gib mir in dieser Runde +1|+1.","Drachenverbündete haben 16+ Schaden verursacht.","„Auf der einen Seite ist sie durch ihre Natur unser meistgehasster Feind. Ihresgleichen hat Demacia nur Schmerzen bereitet. Auf der anderen Seite vertraut der Prinz ihr und sie scheint in allen Belangen eine entschlossene Soldatin und eine wertvolle Verbündete zu sein. Ich hoffe nur, dass sie das Vertrauen, das wir ihr entgegenbringen, nicht ausnutzt.“\n– Seite aus Leutnant Jeriks Bericht über Zaunkönigs Wacht","Einheit",["DRACHE"],["Demacia"],"Champion"],"03DE003":["Grenzposten der Drachenwache","Wenn ich beschworen werde und du einen sichtbaren Drachen hast, mobilisiere dich.","","„Da, dort vorne! Ist das …?“\n„Sieht so aus.“\n„Wie kannst du dir da sicher sein?“\n„Man kann sie nicht verwechseln. Halt dir die Ohren zu, das wird laut.“\n– Anden und Yessenia","Einheit",[],["Demacia"],"SELTEN"],"03DE013":["Wachsame Brutmutter","","","„Vorsicht, Soldaten! Wenn wir vorsichtig sind und das Nest nicht stören, wird der Mutterdrache uns nicht angreifen. Wenn wir sie noch mehr reizen … dann solltet ihr dazu bereit sein, die Beine in die Hand zu nehmen.“\n– Anden Mayne, eierköpfiger Forscher","Einheit",["DRACHE"],["Demacia"],"GEWÖHNLICH"],"03DE005":["Eierköpfiger Forscher","Wenn ich beschworen werde, erschaffe einen zufälligen Drachen auf der Hand.","","Drachenei (Kreischender Drache, Draco Murmurationis) \nOrt: Von Anden Mayne auf einer Expedition gefunden. \nNotizen: Brutzeit unbekannt. Inkubation wird fortgeführt. Kürzlich Bewegungen im Ei festgestellt. Ei reagiert auf Wärme, Licht, Hammer. Aktuelle Studienergebnisse nicht eindeutig. \n– Notizen von Anden Mayne, eierköpfiger Forscher","Einheit",[],["Demacia"],"GEWÖHNLICH"],"03DE007":["Kadregrin der Höllendrache","Wenn ich beschworen werde, gewähre anderen Drachenverbündeten überall +4|+4.","","Als Demacia plötzlich Opfer mehrerer Drachenangriffe wurde, wusste Shyvana, dass der Höllendrache Kadregrin daran schuld war. Andere Drachen, die von seinem Mut und seiner mächtigen Flamme angespornt wurden, versetzten die Demacianer in Angst und Schrecken. ","Einheit",["DRACHE"],["Demacia"],"EPISCH"],"03DE012":["Für die Gefallenen","Wenn du eine Elite beschwörst, senke meine Kosten um 1.\nBeschwöre 1 Unerschrockene Vorhut pro Verbündeten, der in dieser Runde gestorben ist.","","„Wenn ein Soldat fällt, muss ein anderer seinen Platz einnehmen. Unser Banner darf nie fallen.“\n– Garen","Zauber",[],["Demacia"],"EPISCH"],"03DE014":["Scharfsicht","Gib einem Verbündeten in dieser Runde +1|+2 und Scharfsicht.","","Jeder, der es wagt, zu Demacias Mauern vorzudringen, sieht sich einer vollständigen Kompanie gegenüber – vorgewarnt und schwer bewaffnet.","Zauber",[],["Demacia"],"GEWÖHNLICH"],"03FR020":["Die Narbenebene","Wenn ein Verbündeter Schaden überlebt, gewähre ihm +1|+0 und Robust.","","Bei der Winterklaue gibt es viele ehrenhafte Orte, doch der wichtigste ist die Narbenebene, in der beschädigte Schiffe nach ihrer Rückkehr von Raubzügen zu Versammlungshallen für Krieger und ihre Mitstreiter umfunktioniert werden. Diese Schiffe stehen für den Stamm, der sie erbaut hat – widerstands- und anpassungsfähig.","Wahrzeichen",[],["Freljord"],"EPISCH"],"03FR007":["Räuber der Trolle","Wenn ich beschworen werde und du eine sichtbare Karte mit 8+ Kosten hast, gewähre mir +3|+0.","","Der Späher kniete bei einem zerfetzten Stückchen Stoff, das aus dem Schnee lugte. Der Geruch von menschlichem Schweiß und Rauch von Holzfeuern lag schwach in der kalten Luft.\nEr zog den Fetzen aus dem Schnee und sah an einem Ende etwas baumeln. Ein Talisman der Avarosa, stumpf und kalt unter dem stürmischen Himmel. ","Einheit",[],["Freljord"],"GEWÖHNLICH"],"03FR004":["Ermutigendes Gebrüll","Wähle eine Einheit auf der Hand, die du aufdeckst. Heile deinen Nexus in der Höhe ihrer Stärke.\nErleuchtet: Senke ihre Kosten auf 0.","","„Ausgewachsene Trolle haben dicke Häute und starke Knochen, die schnell heilen. Deshalb sind sie schreckliche, hartnäckige Gegner. Man muss sie direkt erledigen, sonst erholen sie sich und kämpfen weiter.“\n– Meisterschütze der Avarosa","Zauber",[],["Freljord"],"SELTEN"],"03FR017":["Augur der Ahnen","Ausspielen: Wenn du eine sichtbare Karte mit 8+ Kosten hast, gewähre einem Verbündeten Überwältigen und Erholung.","","Es heißt, dass nur wenigen Trollen die Schlachtrufe der Ahnen gelehrt werden, aber die, die sie kennen, rufen jene an, die vorher kamen, um ihren Gefährten außergewöhnliche Kraft zu verleihen.","Einheit",[],["Freljord"],"SELTEN"],"03FR006":["Trundle","Wenn ich beschworen werde, erschaffe 1 Eissäule auf der Hand.","Ich habe gesehen, wie du Eissäule ausgespielt hast.","Eine Fackel nach der anderen erleuchteten den Pass und ließen doch nur die Schatten dunkler werden. Dutzende von Trollen füllten ihn, vielleicht Hunderte, alle riesig, bedrohlich und tödlich.\n„Ich frage noch ein Mal“, knurrte Trundle, als er Knochensplitter auf eine Schulter wuchtete. „Gebt ihr auf … oder muss ich eure Schädel einschlagen?“","Einheit",[],["Freljord"],"Champion"],"03FR008":["Eisbeben ","Gib ALLEN Einheiten in dieser Runde -3|-0. Verursache 3 Schaden an ALLEN Einheiten.","","„Begrabt sie lebendig!“\n– Trundle","Zauber",["ELEMENTAR"],["Freljord"],"EPISCH"],"03FR002":["Schlachtruf der Trolle","Gib einem Verbündeten in dieser Runde +0|+2, um einem Gegner -2|-0 zu geben.","","Trollschlachtrufe sind sehr unterschiedlich. Sie sind von Gruppe zu Gruppe anders und oft völlig unverständlich. Eines haben sie aber gemeinsam: Man möchte nicht in der Nähe sein. ","Zauber",[],["Freljord"],"GEWÖHNLICH"],"03FR011":["Uzgar der Uralte","","","Sie konnten es fühlen, bevor sie es hörten – der Boden erzitterte unter ihren Füßen. Aber schon bald lag auch ein Geräusch wie ferner Donner in der Luft, der näher kam.\nMeryck hob den Kopf, die Augen aufgerissen, als er lauschte.\n„Was ist?“, fragte Anya drängend und zog ihren Bogen, aber Meryck rannte bereits auf dem Pfad zurück.\n„LAUF!“","Einheit",[],["Freljord"],"SELTEN"],"03FR005":["Verwüsterin der Trolle","Wenn ich beschworen werde und du eine sichtbare Karte mit 8+ Kosten hast, gewähre mir Erholung.","","Sobald sie zwischen den Hütten der Avarosa standen, riefen sie Hgar herbei. Lachend erhob sie Schneebrecher, um die hölzernen Behausungen kurz und klein zu schlagen.","Einheit",[],["Freljord"],"GEWÖHNLICH"],"03FR018":["Anrufung der Wildnis","Ziehe jeden Yeti, Poro und Elnuk aus den obersten 4 Karten in deinem Deck. Lege den Rest zurück ins Deck.","","„… Und dann kam ein RIIIIEEEESENGROSSER ELNUK aus dem Wald geflogen mit einem klitzekleinen Poro auf dem Rücken und da war ein NETTER YETI, der nur mit seinen Freunden spielen wollte, und die rannten alle den Berg runter und machten GROOOOAAARRRR und dann …“\n– Ingvar die Jüngere","Zauber",[],["Freljord"],"GEWÖHNLICH"],"03FR010":["Gesichter der Ahnen","Rundenbeginn: Wenn du eine sichtbare Karte mit 8+ Kosten hast, erhältst du in dieser Runde einen zusätzlichen Manastein.","","„Vorfahren, erwacht,\nEis beherrscht, Himmel kracht.\nVorfahren, erwacht,\nMacht sie schwach, und gebt uns Kraft.“\n– Schlachtruf der Trolle","Einheit",[],["Freljord"],"GEWÖHNLICH"],"03FR019":["Stimmen der Ahnen","Erhalte 2 leere Manasteine.\nZiehe aus den obersten 5 Karten deines Decks jede Karte, die 8+ kostet. Lege den Rest zurück ins Deck.","","Seit Generationen hören Siedler der Avarosa merkwürdige, unerklärliche Geräusche in den tosenden Winterstürmen. Als sie sich endlich weiter in den Norden wagten, entdeckten sie deren Ursprung: Uralte Troll-Monolithen, die in lange vergessenen Sprachen flüsterten und denen der Wind die Worte aus den aufgerissenen Kiefern blies.","Zauber",[],["Freljord"],"GEWÖHNLICH"],"03FR025":["Trollgaben","Gewähre einem Verbündeten Erholung. Wenn er das Schlüsselwort bereits hat, gewähre ihm stattdessen +2|+2.","","Bemitleide all diejenigen, die im Blut eines Trolles einen sicheren Sieg sehen.","Zauber",[],["Freljord"],"SELTEN"],"03FR022":["Mitreißende Show","Beschwöre 2 verschiedene zufällige Champions aus deiner Hand und deinem Deck. Erhöhe ihre Werte auf 10|10.","","„We got it all in our hands now\nSo can you handle what we’re all about?“\n– Ahri, „POP/STARS“","Zauber",[],["Freljord"],"EPISCH"],"04PZ001":["Ekko","Schlag: Erschaffe 1 flüchtigen Zeittrick auf der Hand.","Du hast 4+ Mal prophezeit. Wenn ich eine Stufe aufsteige, erschaffe 3 Chronobrüche in deinem Deck.","Es geht nicht darum, wie viel Zeit du hast, sondern, wie du sie einsetzt.","Einheit",[],["Piltover & Zhaun"],"Champion"],"04PZ005":["Grubenarbeiter der Chireaner","Wenn du einen anderen Grubenarbeiter der Chireaner beschwörst, vernichte mich und verwandle verbündete Grubenarbeiter der Chireaner überall in Kolonnen der Grubenwerke.","","Die ersten zhaunitischen Minenarbeiter, die die Chireaner entdeckten, hielten sie für scheue, einfach gestrickte Kreaturen. Doch im Laufe der Jahre gewöhnten sie sich an die Menschen und offenbarten ihnen ihre engen sozialen Bindungen und ihr intuitives Verständnis von Technologie.","Einheit",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"04PZ014":["Produktionsschub","Verbrauche zum Ausspielen dein gesamtes Mana. Beschwöre zufällige Geschütztürme, deren Gesamtkosten dem ausgegebenen Mana entsprechen.","","„Zu wenige Ressourcen?! Ich habe damals meine erste mechanische Apparatur aus weggeworfenen Uhrwerken und einem rostigen Thermalkondensator gebaut. Für einen findigen Wissenschaftler gibt es keine Ausreden!“\n– Heimerdinger","Zauber",[],["Piltover & Zhaun"],"SELTEN"],"04PZ003":["Zeitspuler","Wirf zum Ausspielen 1 Karte ab.\nVerursache 1 Schaden an einem Gegner oder dem gegnerischen Nexus und 1 an einem anderen.","","„Vorsicht!“\n– Ekko","Zauber",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"04PZ011":["Gezielte Ansage","Ziehe 1.\nErschaffe 1 Parallelkonvergenz in deinem Deck.","","„Die Zeitlinien aufteilen …“\n– Ekko","Zauber",[],["Piltover & Zhaun"],"EPISCH"],"04PZ002":["Fallendes Fellknäuel","Wenn ich beschworen werde, erschaffe 1 Hexitkristall in den untersten 10 Karten deines Decks.","","„ABER MEIN PLAAAAAANNN— MIAAUUU!“","Einheit",["KATZE"],["Piltover & Zhaun"],"SELTEN"],"04PZ020":["Defekter Tauschbot","Ausspielen: Tausche meine Werte mit denen einer anderen Einheit.","","„Ein neuer zweiarmiger Bandit? Haben sie die Fabrik nicht schon vor Jahren stillgelegt?“\n„Dachte ich. Irgendwas von wegen ‚rollende Bomben‘ und ‚unbeabsichtigte Flächenbrände‘.“\n„Ach.“\n„… Spielen wir eine Runde?“\n„Auf jeden Fall.“\n– Kasinobesucher aus Zhaun","Einheit",[],["Piltover & Zhaun"],"SELTEN"],"04PZ013":["Versuchs-Elnuk","Wenn ich beschworen werde, erschaffe einen zufälligen Elnuk in den obersten 6 Karten deines Decks.","","„OKAY, KLEINER KUMPEL, HALT DU EINFACH STILL, WÄHREND ICH DAS DING HIER UMLEGE UND BÄM! HA! ELNUKS FÜR IMMER! Wir brauchen mehr Gras. Und Platz.“\n– Praktische Perfektionistin","Einheit",["ELNUK"],["Piltover & Zhaun"],"SELTEN"],"04PZ010":["Parallele Zeitstränge","Gewähre Begleitern auf der Hand „Wenn du mich ausspielst, wähle 1 von 3 Begleitern mit meinen Kosten und verwandle mich in diesen Begleiter“.","","„Wir spielen nach MEINEN Regeln.“\n– Ekko","Zauber",[],["Piltover & Zhaun"],"EPISCH"],"04PZ016":["Bombastischer Pavian","Wenn ich beschworen werde, erschaffe 1 Flammenfresser! auf der Hand.","","Jinx hatte früher einen konventionelleren Lieferanten, aber die beiden hatten eine kleine Meinungsverschiedenheit. Und dann war der Lieferant nicht mehr ganz auf der Höhe. Weil er aus einem Fenster gefallen ist. Genauer gesagt, gefallen wurde. Mit einer Bombe. Von Jinx.","Einheit",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"04PZ007":["Zeittrick","Prophezeie, dann ziehe 1.","","„Die Zukunft ist, was ich draus mache …“\n– Ekko","Zauber",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"04PZ012":["Praktische Perfektionistin","Ausspielen: Prophezeie. Erschaffe 3 Kopien der ausgewählten Karte in deinem Deck.","","„Kay ist klasse. Sie hat so diese ‚Übung macht den Meister‘-Einstellung, weißt du? Und Junge, übt sie viel.“\n– Shomi","Einheit",[],["Piltover & Zhaun"],"SELTEN"],"04PZ017":["Glorreiche Evolution","Deine Karten kosten 1 weniger, haben Augmentieren, werden von Glorreiche Evolution erschaffen und sind jetzt Technologie.","","„Fortschritt ist alles. Ich werde diese Stadt in die Zukunft führen, ob sie bereit ist oder nicht.“\n– Viktor","Zauber",[],["Piltover & Zhaun"],"EPISCH"],"04PZ015":["Adaptatron 3000","Wenn du eine Technologie beschwörst, haben wir dieselben Schlüsselwörter.","","„Ah, ja! Der Adaptatron 3000! Anpassbar, originell UND ein echter Hingucker! Wenn er sprechen könnte, hätten wir sicherlich VIELE Gesprächsthemen.“\n– Heimerdinger","Einheit",["TECHNOLOGIE"],["Piltover & Zhaun"],"EPISCH"],"04PZ004":["Dropboarderin","Wenn du mich in einer Prophezeiung siehst, beschwöre mich.","","„Aah, Shomi ist ein Genie auf dem Hoverboard. Sie ist mal von einem Grubengrinder zu einem Bottomboard-Backslide gewechselt und dann mit einem Dreipunkt-Dreifachdip gesprungen! Oder so. Hey, was ich sagen will, es war einfach genial, okay?“\n– Praktische Perfektionistin","Einheit",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"04BW002":["Knochenspieß","Ein Verbündeter schlägt einen Gegner und wandert dann an die Spitze deines Decks.","","„Kleines Abschiedsgeschenk …“\n– Pyke","Zauber",[],["Bilgewasser"],"EPISCH"],"04BW007":["Jaullfisch","Ausspielen: Jeder Verbündete mit Lauern schlägt einen zufälligen Gegner.","","„Nichts geht über einen Jaullfisch, wenn man wissen will, wem man vertrauen kann – und wen man töten kann.“\n– Pyke","Einheit",["LAUERND"],["Bilgewasser"],"EPISCH"],"04BW001":["Rotflossen-Hammerkopf","Ausspielen: Belege einen Gegner mit Verletzlich.","","Wenn ein Hammerkopf den Kiel eines Schiffes zertrümmert, macht er das allem Anschein nach einfach zum Spaß. Nur selten verschlingt er im Anschluss die Besatzung, meist lässt er sie als Festmahl für andere Kreaturen zurück.","Einheit",["LAUERND"],["Bilgewasser"],"GEWÖHNLICH"],"04BW005":["Pyke","Wenn ich lauere, verwandle mich in Tod aus der Tiefe.","Verbündete Pykes haben 15+ Schaden verursacht.","„… Die Visionen sind zurück. Ich sehe seine verzweifelten Augen, die zu mir hoch starren, während sich die Kiefer des Jaullfischs um ihn schließen. Wir wollten rudern, aber das Boot war zu klein und die Bestie zu groß. Ich hatte keine Wahl. Ich musste seine Leine durchschneiden. Es musste sein.“\n– Blutgetränkter Brief","Einheit",["LAUERND"],["Bilgewasser"],"Champion"],"04BW010":["Monsterharpune","Plündern: Ich koste 2 weniger.\nVerursache 5 Schaden an einer Einheit.","","„Wir haben das Biest schon erwischt! Macht weiter, bis es sich nicht mehr rührt und das Wasser nicht mehr blau ist!“\n– Kaltblütige Quartiermeisterin","Zauber",[],["Bilgewasser"],"GEWÖHNLICH"],"04BW014":["Lunte legen","Beschwöre 1 Pulverfass.\nErschaffe 1 Hochjagen auf der Hand.","","„Hab alles vorbereitet, Käpt’n. Ein kleiner Funke, dann geht’s ab.“\n– Deckshelferin","Zauber",[],["Bilgewasser"],"GEWÖHNLICH"],"04BW011":["Gezinkte Würfel","Wenn du in der nächsten Runde Schaden am gegnerischen Nexus verursachst, klaue 1.","","„Na, was willst du aufs Spiel setzen, mein Freund?“\n– Tahm Kench","Zauber",[],["Bilgewasser"],"EPISCH"],"04BW015":["Säbelzähnchen","","","„Sehen nicht nach viel aus, ja, aber die sind blutdurstig. Und wenn du sie an dich ranlässt, wissen sie, wo sie’s bekommen, wenn sie größer sind. Zieh deine verdammten Handschuhe an.“\n– Jaull-Jäger","Einheit",["LAUERND"],["Bilgewasser"],"GEWÖHNLICH"],"04BW003":["Schnappkieferschwarm","Ausspielen: Ich beginne einen kostenlosen Angriff.","","„Tropf, tropf, tropf, tropf, nach unten fällt das Blut,\nSchwimm, schwimm, kommt der Schwarm, ertrinken wäre gut,\nSchnipp, schnapp, Zahn um Zahn, und alle müssen schrei’n,\ntief hinab, ins nasse Grab, für immer schlafend sein!“\n– Kinderreim aus Bilgewasser","Einheit",["LAUERND"],["Bilgewasser"],"GEWÖHNLICH"],"04BW009":["Bucht der Untiefen","Wenn Verbündete angreifen, bevor Lauern aktiviert wird, gewähre dem obersten Verbündeten in deinem Deck Lauern und die Unterart „Lauernd“.","","Die trügerischsten Lagunen von Bilgewasser wurden bald zur Heimat aller Arten von Schrecken aus der Tiefe. Dort liegen sie auf der Lauer und warten auf die nächste übermütige Besatzung, die die Warnungen des Hafenmeisters ignoriert.","Wahrzeichen",[],["Bilgewasser"],"SELTEN"],"04BW008":["Verschollene Reichtümer","Ziehe einen Schatz. Wenn du keinen ziehen kannst, erschaffe stattdessen 2 Schätze in deinem Deck.","","„Wir sind reich!“\n– Kaltblütiger Kaperer","Zauber",[],["Bilgewasser"],"SELTEN"],"04BW013":["Plünderergasse","Wenn mein Countdown herunterzählt, beschwöre einen zufälligen Begleiter mit 1 Kosten.\nCountdown 2: Gewähre Verbündeten mit 1 Kosten +2|+1 und Bedrohlich.","","„Du glaubst also, du hast das Zeug dazu, dich zu den Kaperern zu zählen, ja? Sehen wir noch, du Knirps. Wenn wir mit dir fertig sind, leistest du entweder deinen Beitrag, oder du fütterst die Biester unter den Wellen!\n– Bootsmann","Wahrzeichen",[],["Bilgewasser"],"SELTEN"],"04BW004":["Blutköder","Erschaffe 1 Schnappkieferschwarm an der Spitze deines Decks.","","„Wenn’s nach mir ginge, würde ich mich eher von ’nem Jaullfisch fressen lassen, bevor mich diese Mistviecher erwischen. Lieber mit einem Happs weg als meine Crew anbetteln, mich abzustechen, während die mich lebendig auffressen.“\n– Kaltblütiger Kaperer","Zauber",[],["Bilgewasser"],"GEWÖHNLICH"],"04BW016":["Rex’ Zerstörung","Ausspielen: Spiele pro gezogener Karte in dieser Runde Kanonensperrfeuer auf zufällig ausgewählte Gegner, bis zu 6 Mal.","","„… Rex?“\n– Bootsmann","Einheit",[],["Bilgewasser"],"SELTEN"],"04BW006":["Die Liste","Belege einen Gegner mit Verletzlich. Wenn er bereits verletzlich ist, beginnt der stärkste Verbündete einen kostenlosen Angriff, indem er diesen Gegner herausfordert.","","„Du hast ’nen Namen, ich hab ’ne Liste.“\n– Pyke","Zauber",[],["Bilgewasser"],"SELTEN"],"04IO008":["Tanzender Widerstand","Rufe eine Einheit zurück.\nKlingentanz (1).","","„Zeit für deinen Rückzug! Jetzt tritt jemand anderes ins Rampenlicht!“\n– Zinneia, stählernes Crescendo","Zauber",[],["Ionia"],"GEWÖHNLICH"],"04IO005":["Irelia","Wenn ich beschworen werde oder bei Rundenbeginn: Wenn du die Angriffsmarke hast, erschaffe 1 Makelloses Duett auf der Hand.","Du hast mit 14+ Verbündeten angegriffen.","„Einst studierten wir Kunst und Schönheit und unsere Herzen tanzten vor Freude. Doch als sie unsere Mauern einrissen und unser Blut vergossen, landeten wir auf dem Boden der Tatsachen …“","Einheit",[],["Ionia"],"Champion"],"04IO020":["Schwimmerschule","Ausspielen: Ziehe einen langsamen, Schnell- oder Sofortzauber.\nErleuchtet: Ich bin ungreifbar.","","Die seltsamen, verstörend schönen Himmelsgesänge der Wolkenschwimmer hielten einen Teil des schwarzen Nebels zurück … aber nur für eine gewisse Zeit.","Einheit",[],["Ionia"],"SELTEN"],"04IO004":["Aufblühende Klinge","Ausspielen: Klingentanz (2).","","„Es gibt Menschen, die eine Blume für verletzlich und zerbrechlich halten. Sie vergessen, wie viel Stärke man braucht, um sich an der bloßen Erde festzuklammern und mit jeder Blüte Hoffnung zu erwecken.“\n– Zinneia, stählernes Crescendo","Einheit",[],["Ionia"],"GEWÖHNLICH"],"04IO003":["Eine Klingenlänge voraus","Wähle einen Verbündeten, der gemeinsam mit den Klingen angreift. Klingentanz (3).","","„Haltet ihren Rückzug auf! Die Noxianer haben diesen Krieg begonnen, doch wir bringen ihn zu Ende.“\n– Irelia","Zauber",[],["Ionia"],"SELTEN"],"04IO015":["Tanzendes Tröpfchen","Wenn ich zurückgerufen werde, ziehe 1.","","„Wasser ist flexibel und anpassungsfähig – es nimmt immer die passendste Form an, fließt vorwärts oder zieht sich von der Küste zurück.“\n– Ionischer Mönch","Einheit",[],["Ionia"],"GEWÖHNLICH"],"04IO014":["Schattenlehrling","Wenn du einen vergänglichen Verbündeten beschwörst, gib mir in dieser Runde +1|+0.","","„Du bist Rauch – ein Flüstern im Wind. Deine Fäuste müssen wie Schatten mit der Dunkelheit verschmelzen. Jetzt noch mal!“\n– Meisterin Shi","Einheit",[],["Ionia"],"GEWÖHNLICH"],"04IO002":["Zinneia, stählernes Crescendo","Wenn du einen Klingentanz ausführst, greife ich mit den Klingen an.\nAusspielen: Klingentanz (1).","","„Versammelt euch, meine Lieben. Heute werden unsere Füße über den Boden gleiten, der uns ernährt hat – wie es unsere Familien uns gezeigt haben. Wir sind Ionias Kinder, und heute tanzen wir für die Kunst, die Freiheit und für einander!“","Einheit",[],["Ionia"],"EPISCH"],"04IO007":["Synkope","Tausche 2 Verbündete miteinander.","","„Ein Tanz ist die Einreihung in die harmonische Bewegung aller Dinge.“\n– Zinneia, stählernes Crescendo","Zauber",[],["Ionia"],"SELTEN"],"04IO011":["Führen und folgen","Rufe einen Verbündeten zurück, um 1 Makelloses Duett auf der Hand zu erschaffen.","","„Unsere Aufführung wird … unvergesslich werden.“\n– Zinneia, stählernes Crescendo","Zauber",[],["Ionia"],"GEWÖHNLICH"],"04IO013":["Heiliger Beschützer","Ausspielen: Gib einem Verbündeten in dieser Runde Barriere und ziehe einen Shen.\nVerbündete mit Barriere haben Doppelangriff.","","„Ebenso wie wir für das Land kämpfen, erhebt sich das Land selbst, um uns zu verteidigen. Wir ziehen Kraft aus dem Zorn der Erde und vertreiben unsere Feinde. Und so bleibt das Gleichgewicht erhalten.“\n– Ionischer Priester","Einheit",[],["Ionia"],"EPISCH"],"04IO012":["Schatten der Vergangenheit","Rufe alle Verbündeten zurück und beschwöre an ihrer Stelle je 1 Lebender Schatten.","","„Sollen sie nach Schatten schlagen, wo ihre Waffen kein Ziel finden.“\n– Zed","Zauber",[],["Ionia"],"SELTEN"],"04IO009":["Schwungvolle Tänzerin","Ausspielen: Klingentanz (1).","","„Was für eine Schande, Jungs! All diese Macht und kein Fünkchen Rhythmusgefühl? Wir können wohl doch nicht ALLE Stars sein …!“","Einheit",[],["Ionia"],"SELTEN"],"04IO001":["Feldmusikanten","Sobald du in einer Runde 3 andere Verbündete beschworen hast, fülle dein Zaubermana wieder auf und ziehe 1.","","Manchen dient Musik als gemeinsame Zuflucht vor Nöten und Gewalt. Für andere steht Musik für Widerstand.","Einheit",[],["Ionia"],"EPISCH"],"04IO006":["Küstenverteidiger","Wenn du einen anderen Verbündeten beschwörst, gib mir in dieser Runde +2|+0.","","Meine liebste Kay,\nheute Morgen kamen sie mit einer ganzen Schiffsflotte, die den Horizont zerschnitt und den Sonnenaufgang verdunkelte. Ihre Maschinen haben die Silberebenen in Brand gesteckt und nun verpestet dichter Rauch die Sommerluft. Wir können nicht mehr untätig zusehen. Harke oder Schaufel, Sichel oder Schwert – heute müssen wir unserem Schicksal entgegentreten.\nDenke immer daran, dass ich dich und unsere Heimat mehr liebe, als ich mit Worten ausdrücken kann.\n– Angebrannter Brief\n","Einheit",[],["Ionia"],"GEWÖHNLICH"],"04SH100":["Sorgfältige Vorbereitung","Lege zum Ausspielen eine Karte von der Hand zurück in dein Deck.\nProphezeie und erschaffe dann eine exakte Kopie der ausgewählten Karte auf der Hand.","","„Die Taten von heute pflanzen die Keime der Bäume von morgen.“\n– Tai, Angehender Chronomantiker","Zauber",[],["Shurima"],"GEWÖHNLICH"],"04SH070":["Unwürdig","Gib einem gegnerischen Begleiter in dieser Runde -4|-0.\nWenn du weniger Manasteine als dein Gegner hast, töte den Begleiter stattdessen.","","„Die Sonne wird wieder über Shurimas Gebiete strahlen.“\n– Stimme der Auferstandenen","Zauber",[],["Shurima"],"EPISCH"],"04SH081":["Sandweberin der Baccai","Ausspielen: Belege einen Gegner mit -1|-0 und Verletzlich.","","Jedes Korn, das sie fallen lässt, nimmt ihnen eine Sekunde ihres Lebens und nagt an ihnen wie der Wind.","Einheit",[],["Shurima"],"SELTEN"],"04SH077":["Stimme der Auferstandenen","Wenn du einen Champion auf die nächste Stufe gebracht hast, haben Verbündete +2|+0.","","„Ich habe sie vor langer Zeit sprechen gesehen.“ Der alte Soldat lächelte und seine Enkelin konnte es sich einen Augenblick lang vorstellen: Shurima, goldglänzend und der stolze Azir, der von der Stimme der Auferstandenen herbeigerufen worden war. „Sie weckte eine Leidenschaft in uns, die wir schon lange verloren geglaubt hatten.“","Einheit",[],["Shurima"],"EPISCH"],"04SH019":["Rek’Sai","Wenn ich lauere oder angreife: Gewähre Verbündeten mit Lauern überall +1|+0.\nRundenende: Lege mich in dein Deck.","Ich habe mit 10+ Stärke angegriffen.","„Der junge Jhuraa erforschte die Wüste, wie er es oft tat, und entdeckte in einer kleinen, verborgenen Höhle einige uralte Texte! Wir schickten sie zu einem Übersetzer in Ossamal, und die Schriftrollen … sie erzählen von einem uralten Schrecken, der unsere Vorfahren verfolgte. Eine Königin. Eine Xer’Sai-Königin!“\n– Fezhaur, Ältester von Vekaura","Einheit",["LAUERND"],["Shurima"],"Champion"],"04SH138":["Der Erlöser","Gib einem Verbündeten in dieser Runde +2|+1. Erschaffe 1 Rückkehr des Erlösers auf der Hand, wenn du in diesem Spiel einen Champion auf die nächste Stufe gebracht hast.","","„Alle haben gesagt, ich soll ihn nicht benutzen. ‚Niemand darf eine derart mächtige Waffe führen‘, hieß es.“\n– Akshan","Zauber",[],["Shurima"],"GEWÖHNLICH"],"04SH089":["Wüstenexpertin","Ausspielen: Zerstöre ein Wahrzeichen. Wenn es verbündet ist, beschwöre 1 Unausgeschlafener Felsenbär.","","„Kadira hat heute etwas kaputt gemacht! Schon wieder! Diesmal war es zwar nur eine Steinmauer, aber sie sah alt aus und bedeutete dem Vorfahren von irgendjemandem bestimmt etwas. Sie behauptet, die Mauern in Tereshni wären stabiler gebaut, aber ich bin trotzdem sehr wütend.“\n– Zaifas Tagebuch","Einheit",[],["Shurima"],"SELTEN"],"04SH015":["Raz Blutmähne","Angriff: Gib Gegnern in dieser Runde -2|-0.","","„Als dieses Kroko hier geboren wurde, schlossen die anderen Wetten ab, wie lange es überleben würde, weil sie dachten, es wäre eine schwächliche Missbildung. Niemand hat darauf gewettet, dass es alle seine Geschwister fressen würde. Hehe.“","Einheit",[],["Shurima"],"EPISCH"],"04SH058":["Sandwerkerin","Angriff: Beschwöre 1 angreifenden Sandsoldat.","","Wenigen wird das Wesen der Wüste gelehrt, und noch weniger erfahren, wie man über ihren Sand so gebietet wie Azir. Die Gabe zur Nutzung dieser Macht und das Wissen um die Geheimnisse des Sands vergibt Azir nur an seine treuesten und fähigsten Gefolgsleute.","Einheit",[],["Shurima"],"GEWÖHNLICH"],"04SH080":["Der Schwarm ruft","Lege zum Ausspielen eine Karte von der Hand an die Spitze deines Decks.\nErschaffe 2 zufällige Einheiten mit Lauern auf der Hand.","","„Möge die Sonne strahlen, und mögen die Xer’Sai schlummern.“\n– Gebet des Händlers","Zauber",[],["Shurima"],"GEWÖHNLICH"],"04SH035":["Zahltag","Erschaffe 1 Glücksfund auf der Hand.","","„Klar hatte ich gute und schlechte Tage, wie jeder andere auch. In diesem Beruf können die schlechten Tage richtig schlecht werden und die guten richtig lohnenswert.“\n– Sivir","Zauber",[],["Shurima"],"GEWÖHNLICH"],"04SH028":["Vorzeitliche Vorbereitungen","Ausspielen: Prophezeie.\nCountdown 2: Beschwöre 1 Uhrwerkler.","","Unter anderen Umständen würde man sie als verloren betrachten, unter dem Sand von Jahren begraben. Doch die Roboter wurden bedächtig platziert und warten nur darauf, erweckt zu werden.","Wahrzeichen",[],["Shurima"],"GEWÖHNLICH"],"04SH054":["Schatzsucherin","Wenn ich beschworen werde, erschaffe 1 Unruhige Sande auf der Hand.","","„Okay, Davu. Du gehst da rein, schnappst dir … was immer das ist, und dann machst du uns reich. Mich reich. Du machst mich reich. Alles klar? Und wenn das ein gefangenes Etwas ist, tut es mir echt leid.“","Einheit",[],["Shurima"],"GEWÖHNLICH"],"04SH002":["Todesbote der Baccai","Wenn du eine Einheit besiegst, gewähre mir +1|+0.","","„Nach ihrem gescheiterten Aufstieg sind alle Baccai geflohen oder wurden verschont und seither nicht wieder gesehen. Wer weiß, wie lange sie sich schon mit ihrem Schandmal befleckt in diesen dunklen Gräbern verstecken?“\n– Schriftgelehrter Kah’nir, Geschichte des Heers der Aufgestiegenen","Einheit",[],["Shurima"],"SELTEN"],"04SH042":["Schlafender Felsenbär","Countdown 3: Beschwöre 1 Unausgeschlafener Felsenbär.","","„MEIN NAME IST ZAIFA UND ICH SCHREIBE BLÖDES ZEUG IN MEIN BLÖDES BUCH, WENN ICH GLAUBE, DASS ALLE ANDEREN SCHLAFEN. SOGAR SAMI.“\n– Zaifas Tagebuch","Wahrzeichen",[],["Shurima"],"GEWÖHNLICH"],"04SH032":["Erbarmungslose Knochenbrecherin","Ruf: Ich koste 1 weniger und wenn ich beschworen werde, gewähre mir Überwältigen.","","Der Soldat streckte sich mühevoll nach seinem Speer, doch sie stützte sich schwerer auf seine Brust, bis er stöhnend aufgab. „Nein, nein“, mahnte sie ihn und ließ ihre geschärften Eckzähne mit einem durchtriebenen Lächeln aufblitzen, „der gehört jetzt mir.“","Einheit",[],["Shurima"],"GEWÖHNLICH"],"04SH055":["Ruinenläuferin","","","Bevor die Söldner und Grabräuber von Shurima die Gewölbe erkunden können, müssen sie lernen, wie man die offenkundigen Gefahren der Wüste überlebt. Zum einen ist das die gnadenlose Hitze; zum anderen eine Vielzahl an blutrünstigen Plünderern.","Einheit",[],["Shurima"],"GEWÖHNLICH"],"04SH039":["Zilean","Ausspielen: Erschaffe 4 Zeitbomben in deinem Deck. Prophezeie.","Ich habe gesehen, wie du 2+ verbündete Zeitbomben zerstört hast.","Über viele Jahre hinweg baute Zilean einen Verbund aus vielversprechenden jungen Magiern aus verschiedenen Zeiten auf, die alle sein Lebenswerk hätten vollenden können, falls das Undenkbare eintreten sollte. Als liebenswerter Mentor spornte er seine Zöglinge stets an, doch sobald er sich in die Einsamkeit zurückzog, legte sich seine Stirn in tiefe Sorgenfalten und eine Erschöpfung machte sich in seinen Augen breit, die nur diejenigen verstehen konnten, die bereits mehrere Leben hinter sich hatten.","Einheit",[],["Shurima"],"Champion"],"04SH073":["Taliyah","Ausspielen: Beschwöre eine exakte Kopie eines verbündeten Wahrzeichens.","Du hast 5+ Wahrzeichen beschworen.","„Der Nomade schreitet immer leichten Fußes, denn er wird nicht vom Gewicht von Wurzeln beschwert, und seine Heimat liegt auf ewig jenseits des Horizonts.“\n– Die Gesellschaften von Shurima","Einheit",[],["Shurima"],"Champion"],"04SH091":["Khahiri, der Schüler","Wenn ich beschworen werde, gewähre mir +1|+1, falls du in diesem Spiel prophezeit hast.","","„Denk an deine Ausbildung“, sagte Zilean mit ungewöhnlich sanfter und sogar ernster Stimme. „Bist du sicher, dass du bereit bist?“\nKhahiri lächelte seinen Mentor zuversichtlich an. „Ich bin bald wieder da. Und außerdem habe ich mich jahrelang täglich auf diesen Moment vorbereitet. Wenn nicht jetzt, wann dann?“","Einheit",[],["Shurima"],"GEWÖHNLICH"],"04SH024":["Salzsäule","Countdown 2: Beschwöre 1 Unausgeschlafener Felsenbär. Solltest du in diesem Spiel 4+ Wahrzeichen beschworen haben, gewähre dem stärksten Verbündeten +2|+2.","","Ein Salzminenarbeiter aus Shurima lernt schnell, aus welchen Vorkommen man abbauen kann und um welche man besser einen Bogen macht.","Wahrzeichen",[],["Shurima"],"GEWÖHNLICH"],"04SH003":["Azir","Wenn Verbündete angreifen, beschwöre 1 angreifenden Sandsoldat.","Du hast 12+ Verbündete oder Wahrzeichen beschworen.","„Als Azir sich zum Imperator von Shurima erhob, war er arrogant. Blind. Er sammelte seine Macht, um sich auf seinen Aufstieg vorzubereiten und nicht nur über Shurima, sondern die ganze Welt zu herrschen.“\n– Schriftgelehrter Kah’nir, Geschichte des Heers der Aufgestiegenen","Einheit",["AUFGESTIEGEN","VOGEL"],["Shurima"],"Champion"],"04SH011":["Xenotyp-Forscherinnen","Wenn ich beschworen werde, gewähre 3 zufälligen Verbündeten in deinem Deck +3|+3.","","Die Leere steckt voller Überraschungen, wächst jeden Tag weiter und findet neue Wege, in den Turm einzudringen. Sie ist unnachgiebig wie ein Dornengestrüpp, doch unendlich viel tödlicher. Demzufolge lässt sie sich kaum ergründen, denn dafür sind Forscher vonnöten, die ebenso gerissen und erfinderisch sind wie die Bedrohung selbst.","Einheit",[],["Shurima"],"SELTEN"],"04SH130":["Akshan","Wenn ich beschworen werde oder zuschlage: Beschwöre 1 Palast des Kriegsfürsten oder zähle ihn um 1 herunter.","Palast des Kriegsfürsten hat seinen Countdown beendet. Wenn ich eine Stufe aufsteige, beschwöre 1 Schätze des Kriegsfürsten.","„Der Kodex der Wächter ist voller komplizierter Einschränkungen. Sachen wie ‚Nimm nie ein Leben aus Rache‘ oder ‚Kämpfe für die Welt, nie für dich selbst‘. Was mich angeht …“","Einheit",[],["Shurima"],"Champion"],"04SH114":["Zorn der Wüste","Gewähre verbündeten Sandsoldaten überall +1|+0.\nBeschwöre 2 Sandsoldaten.","","Sie rasten nicht. Sie zögern nicht. Sie sind unnachgiebig, herzlos und unbeugsam.","Zauber",[],["Shurima"],"SELTEN"],"04SH067":["Renekton","Wenn ich einen Gegner herausfordere, gib mir in dieser Runde +2|+1.","Ich habe 10+ Schaden verursacht.","„Man könnte leicht vergessen, dass er einst ein Mensch war, denn das reptilische Antlitz passt so gut zu seiner Vorliebe für blutige Schlachten …“\n – Schriftgelehrter Kah’nir, Geschichte des Heers der Aufgestiegenen","Einheit",["AUFGESTIEGEN","REPTIL"],["Shurima"],"Champion"],"04SH120":["Denkbare Möglichkeiten","Erschaffe ein zufälliges Wahrzeichen mit Countdown auf der Hand oder zähle deine Wahrzeichen um 1 herunter.","","„Zeit ist vergänglich.“\n– Zilean","Zauber",[],["Shurima"],"SELTEN"],"04SH119":["Querschläger","Ruf: Ich koste 3 weniger.\nVerursache 5 Mal 1 Schaden an einem zufälligen Gegner oder dem gegnerischen Nexus.","","„Das könnte etwas ungemütlich werden.“\n– Sivir","Zauber",[],["Shurima"],"GEWÖHNLICH"],"04SH068":["Rufer der Xer’Sai","Ausspielen: Prophezeie.","","Nicht alle Xer’Sai sind zum Blutvergießen bestimmt. Manche können ihre Artgenossen mit durchdringenden Schreien rufen, was die Dünen und Sinne erschüttern lässt.","Einheit",["LAUERND"],["Shurima"],"GEWÖHNLICH"],"04SH093":["Geformter Stein","Gib einem Verbündeten in dieser Runde +1|+1.\nWenn du in diesem Spiel ein Wahrzeichen beschworen hast, gib ihm stattdessen +2|+1.","","„Mit der Hilfe des Landes WERDEN wir uns verteidigen!“\n– Taliyah","Zauber",[],["Shurima"],"GEWÖHNLICH"],"04SH079":["Sandorakel","Prophezeie.\nGib einem Gegner in dieser Runde -2|-0.","","„Ich habe mein Schicksal gesehen und dieses Mal wird man mich nicht aufhalten.“\n– Azir","Zauber",[],["Shurima"],"SELTEN"],"04SH038":["Felsensurfer","Wenn ich beschworen werde, beschwöre 1 Aufgewühlte Sande.","","„Heute machten wir uns auf die Reise nach Nashramae! Samir will die Große Sai noch vor dem nächsten Vollmond durchqueren und vermurkst ALLES! Ich wusste nicht, dass ein einfaches Sandbrett eine ganze Düne zum Einsturz bringen kann. Sami auch nicht. Ihm geht’s gut.“\n– Zaifas Tagebuch","Einheit",[],["Shurima"],"GEWÖHNLICH"],"04SH104":["Konservator","Ausspielen: Zähle ein verbündetes Wahrzeichen um 3 herunter.","","Immer wenn Zilean einen Moment der Ruhe sucht, kehrt er in Icathias letzten Garten zurück, wie er ihn in Erinnerung hat.","Einheit",[],["Shurima"],"SELTEN"],"04SH128":["Vekauranische Vagabundin","Wenn ich beschworen werde, beschwöre 1 Palast des Kriegsfürsten oder zähle ihn um 2 herunter.","","Najah fluchte verhalten, als sie Akshan unter einem Fenster im vierten Stock hängen sah. Der Kerl hatte sie geschlagen. Schon wieder. Sie drehte den Dolch in ihrer Hand und dachte nach, was sie zu ihm sagen sollte. Vielleicht würde er sie diesmal bemerken.","Einheit",[],["Shurima"],"GEWÖHNLICH"],"04SH109":["Treibsand","Gib in dieser Runde einem Gegner -4|-0 oder 2 Gegnern -1|-0. Deaktiviere ihre positiven Schlüsselwörter in dieser Runde.","","In Teilen der Wüste sind alte Ruinen im Sand versunken und haben Hohlräume gebildet, in denen sich unvorsichtige Reisende rasch wiederfinden könnten. ","Zauber",["ELEMENTAR"],["Shurima"],"GEWÖHNLICH"],"04SH043":["Formende Sande","Verursache 4 Schaden an einer Einheit.\nBeschwöre 2 Sandsoldaten.","","„Geht. Umzingelt sie. Sie können nicht gegen das Land selbst kämpfen.“\n– Azir","Zauber",[],["Shurima"],"SELTEN"],"04SH099":["Erhebe dich!","Beschwöre 1 Sandsoldat.\nErschaffe 1 flüchtiges Erhebe dich! auf der Hand.","","„Der Befehl wurde erteilt.“\n– Azir","Zauber",[],["Shurima"],"SELTEN"],"04SH048":["Das Allerheiligste","Ruf: Ich koste 3 weniger.\nCountdown 1: Erschaffe 2 Glücksfunde auf der Hand.","","„Manche Karten werden erst nach Jahren ganz und gar verstanden, manche Fallen erst nach Monaten entschärft, und manche Gewölbe muss man wochenlang durchwandern. Aber wenn man es geschafft hat, merkt man, dass es jede einzelne Sekunde wert war.“\n– Sivir","Wahrzeichen",[],["Shurima"],"GEWÖHNLICH"],"04SH056":["Profiteurin","Wenn ich beschworen werde, erschaffe 1 Glücksfund auf der Hand.","","„Mein Freund, für dich habe ich diese unvergleichliche Schönheit beschafft – direkt aus dem sagenumwobenen Grab der Imperatoren! Dem großen Renekton selbst habe ich sie entrissen und auf meinem Weg nach draußen wurde ich von zehn, nein zwanzig blutrünstigen Sauren-Reitern umzingelt! Wahrlich ein Wunder, dass ein solcher Schatz nun in deinem Besitz ist.“","Einheit",[],["Shurima"],"GEWÖHNLICH"],"04SH020":["Sivir","","Du hast 30+ Schaden verursacht.","Sivir bestritt ihr Leben als Söldnerin und lastete sich alle Gefahren und Vorzüge auf, die mit ihrer Entscheidung verbunden waren. Eine schicksalsschwere Expedition kostete sie beinahe alles, doch als ihr Blut in den Sand von Shurima sickerte, erweckte es eine uralte Macht, die sowohl sie als auch ihre Heimat zurück zu alter Größe führte.","Einheit",[],["Shurima"],"Champion"],"04SH057":["Inspirierende Marschallin","Wenn du einen anderen Verbündeten beschwörst, gib ihm in dieser Runde +2|+0.","","Es ist eine große Ehre, Azirs Segen zu empfangen – und eine noch größere, ihn in seinem Namen zu erteilen.","Einheit",[],["Shurima"],"SELTEN"],"04SH103":["Unbarmherzige Jägerin","Ausspielen: Belege einen Gegner mit Verletzlich.","","„So … Schön fest verschnürt. Renekton liebt es, wenn sich seine Mahlzeiten noch winden.“","Einheit",[],["Shurima"],"GEWÖHNLICH"],"04SH065":["Xerxa’Reth, Titan des Untergrunds","Angriff: Wenn ich 8+ Stärke habe, gib mir in dieser Runde Bedrohlich, Überwältigen und Zauberschild.","","„Es heißt, dass vor hunderten von Jahren an den Ufern des Flusses Khaleek eine große Handelsniederlassung namens Taraleek lag. Bis eines schicksalhaften Tages eine mächtige Bestie aus dem Boden brach und die Niederlassung und alle, die dort lebten, vernichtete. Aber was für ein Monster könnte so etwas vollbringen?“\n– Shurimanischer Geschichtsgelehrter","Einheit",["LAUERND"],["Shurima"],"EPISCH"],"04SH034":["Der Uhrzeiger","Wenn ich beschworen werde, erschaffe 2 Sekundenjahrhunderte auf der Hand.","","In den unteren Geschossen des Turms ist ein ständiges Grollen zu hören, da der Turmwächter – bekannt als der „Uhrzeiger“ – kontinuierlich das Uhrwerk aufzieht.","Einheit",[],["Shurima"],"EPISCH"],"04SH082":["Weg des Verfalls","Ziehe 1.\nFalls du in dieser Runde eine Einheit besiegt hast, entziehe dem gegnerischen Nexus 2.","","Sanddrescher werben ihre Rekruten meist aus den Rängen ihrer Gegner an. Wer ihren ersten Ansturm überlebt, darf beitreten oder sterben.","Zauber",[],["Shurima"],"SELTEN"],"04SH075":["Imperiale Phalanx","Mache Gegner in dieser Runde verletzlich und beschwöre 6 Sandsoldaten.","","„Meine Soldaten marschieren weiter.“\n– Azir","Zauber",[],["Shurima"],"EPISCH"],"04SH018":["Ritus der Dominanz","Töte einen Verbündeten oder zerstöre einen deiner Manasteine, um allen Gegnern in dieser Runde -2|-0 zu geben.","","„Wir kämpfen, sie bluten!“\n– Renekton","Zauber",[],["Shurima"],"SELTEN"],"04SH009":["Rasender Baccai","Ausspielen: Wenn du in diesem Spiel 4+ Einheiten besiegt hast, schlagen sich ein Gegner und ich gegenseitig.","","Ist ein Groll gehegt, kann er nicht einmal im Tod beigelegt werden.","Einheit",[],["Shurima"],"SELTEN"],"04SH049":["Auserkorener Poro","Rundenbeginn: Wenn du einen Champion auf die nächste Stufe gebracht hast, verwandle mich in Erhabener Poro.","","Sie wusste nicht genau, was sie da gefunden hatte … Aber es glänzte und sah nach einem Leckerbissen aus!","Einheit",["PORO"],["Shurima"],"GEWÖHNLICH"],"04SH045":["Erschöpfen","Gib einem Gegner in dieser Runde -2|-0 und mache ihn verletzlich.","","Wüstenbewohner wissen, wie sie der sengenden, erbarmungslosen Hitze der Sonne entgehen können. Die Unwissenden finden sich beeindruckend schnell ihrer Stärke und Energie beraubt.","Zauber",[],["Shurima"],"GEWÖHNLICH"],"04SH037":["Erschütterte Erde","Beschwöre 2 Aufgewühlte Sande.\nZiehe 1.","","So atemberaubend die Große Sai auch sein mag, die Schwachen haben in ihr nichts verloren. Viele mussten ihr Leben in den trügerischen Dünen geben, und nicht nur die Xer’Sai streckten viele nieder, auch das Land selbst verlangte seinen Anteil.","Zauber",["ELEMENTAR"],["Shurima"],"SELTEN"],"04SH107":["Triumph der Aufgestiegenen","Alle verbündeten Aufgestiegenen der Stufe 1 erreichen Stufe 2.","","„Die Zukunft wird von den Aufgestiegenen geschrieben werden!“\n– Azir","Zauber",[],["Shurima"],"EPISCH"],"04SH047":["Nasus","Ich habe +1|+1 pro Einheit, die du in diesem Spiel besiegt hast.","Ich habe auf einen Schlag mit 10+ Schaden zugeschlagen.","„Nasus’ neu gewonnener Segen ermöglichte es ihm, zahllose Lebensalter mit Studien und dem Sinnen über das Wesen von Leben und Tod zu verbringen. Doch diese verlängerte Lebenszeit sollte nach dem Fall Shurimas auch sein größter Fluch werden.“\n– Schriftgelehrter Kah’nir, Geschichte des Heers der Aufgestiegenen","Einheit",["AUFGESTIEGEN","HUND"],["Shurima"],"Champion"],"04SH097":["Konservatorin des Heiligtums","Ausspielen: Töte einen gegnerischen Begleiter. Wenn du in diesem Spiel 13+ Einheiten besiegt hast, töte stattdessen alle gegnerischen Begleiter und beschwöre eine Kopie von mir.","","Die Baccai haben die Aufgabe, das Allerheiligste mit seinen uralten Schätzen zu verteidigen und Sterbliche, die glauben, sie wären schlau oder mächtig genug, um vor dem Urteil der Konservatorin zu bestehen, vor sich selbst zu beschützen.","Einheit",[],["Shurima"],"EPISCH"],"04SH026":["Dünenkrieger","Wenn ich beschworen werde, beschwöre 1 Sandsoldat.","","„Wenn der Imperator befiehlt, gehorchen sowohl der Sand als auch ich.“","Einheit",[],["Shurima"],"GEWÖHNLICH"],"04SH102":["Goldene Botschafterin","Loyalität: Ziehe einen Champion und gewähre ihm +2|+2.","","„Unsere glänzende Zukunft liegt unter dem Sand, und es liegt an uns, Azir den Weg zu bereiten. Das goldene Imperium der Wüste wird wieder auferstehen!“","Einheit",[],["Shurima"],"GEWÖHNLICH"],"04SH001":["Angehender Chronomantiker","Ausspielen: Prophezeie.","","Während seiner Zeit als Student der Chronomantik musste Tai seine Unsicherheit mit seiner Hartnäckigkeit vereinbaren. Besser auf einen möglichen Sieg hoffen als sich zu viele Gedanken um eine Niederlage zu machen.","Einheit",[],["Shurima"],"GEWÖHNLICH"],"04SH022":["Dünenbrecher der Xer’Sai","","","Zwar sind alle Xer’Sai fähige Gräber, aber nur ihre Dünenbrecher haben die Masse und Kraft, um durch die Adern massiven Felsgesteins zu brechen, die sich durch die Große Sai ziehen, und so die Lande dahinter für die Jagd zu eröffnen.","Einheit",["LAUERND"],["Shurima"],"SELTEN"],"04SH030":["Zeitensprung","Gib einem verbündeten Champion „Wenn ich das nächste Mal in dieser Runde sterben würde, heile mich stattdessen vollständig und gewähre mir +3|+3“.","","„Wir können das Unvermeidliche nicht aufhalten … aber wir können es verzögern.“\n– Zilean","Zauber",[],["Shurima"],"SELTEN"],"04SH013":["Konservarium","Wenn ich beschworen werde, ziehe 1.\nCountdown 2: Ziehe 1.","","Zilean erklärt jenen, die er zum Turm führt, bis ins kleinste Detail, was sie wiederherstellen wollen. Der Konservator kann es ihnen zeigen, wenn auch nur für einen Augenblick.","Wahrzeichen",[],["Shurima"],"SELTEN"],"04SH062":["Vergrabene Sonnenscheibe","Spielstart: Beschwöre mich einmal aus deinem Deck, wenn alle deine Karten aus Shurima sind.\nCountdown 25: Erneuere die Sonnenscheibe.\nWenn ein verbündeter Aufgestiegener in diesem Spiel die nächste Stufe erreicht hat, zähle mich um 9 herunter.","","Als Azir die Sonnenscheibe der Hauptstadt von Shurima erblickte, erkannte er ihr Potenzial: Sie sollte Shurima wieder seinen ehemaligen Glanz verleihen.","Wahrzeichen",[],["Shurima"],"EPISCH"],"04SH016":["Verheerender Schlag","Ein Verbündeter schlägt eine Einheit.\nWenn sie stirbt, gewähre verbündeten Champions überall +2|+2.","","„Deine Seele wird gewogen.“\n– Nasus","Zauber",[],["Shurima"],"SELTEN"],"04SH125":["Vekauranische Tresorknackerin","Ausspielen: Gib einem Verbündeten in dieser Runde +2|+0, um einem Gegner in dieser Runde -2|-0 zu geben.","","Tena wartete geduldig, als der ätzende Speichel ihres Haustiers sich durch die vergoldeten Gitterstäbe des Hintereingangs des Palasts fraß. Direkt um die Ecke würde sie bald schon einen Hort unfassbar wertvoller Schätze finden – mehr als genug, um Vekauras einstigen Glanz wiederherzustellen.","Einheit",[],["Shurima"],"SELTEN"],"04SH108":["Bumerangklinge","Ein Verbündeter schlägt den stärksten und den schwächsten Gegner nacheinander.","","„Duck dich lieber!“\n– Sivir","Zauber",[],["Shurima"],"SELTEN"],"04SH066":["Zeit in einer Flasche","Prophezeie und zähle ein verbündetes Wahrzeichen um 2 herunter.","","„Wenn du die Zeit so betrachten würdest wie ich, wüsstest du, dass sie verändert werden kann.“\n– Zilean","Zauber",[],["Shurima"],"GEWÖHNLICH"],"04SH021":["Khahiri, der Zurückgekehrte","Wenn ich beschworen werde, erschaffe eine Kopie von mir in deinem Deck. Wenn du mich in einer Prophezeiung siehst, gewähre allen verbündeten Kopien von mir überall +2|+2.","","Khahiri war nur für einen Augenblick verschwunden, als er plötzlich zurückkehrte. Um nahezu ein Jahrzehnt gealtert und mit einer seltsamen, tödlich wirkenden Waffe ausgerüstet, war seine Rückkehr von Staunen und Sorge begleitet.","Einheit",[],["Shurima"],"SELTEN"],"04SH101":["Ergebener Rat","Rundenbeginn: Wenn du einen Champion auf die nächste Stufe gebracht hast, heile deine Champions und deinen Nexus um 2.","","„Ich habe Azir und meiner Heimat Shurima einen Eid geschworen! Wollt ihr es mir nicht gleichtun?“","Einheit",[],["Shurima"],"SELTEN"],"04SH012":["Geachteter Hierophant","Wenn ich beschworen werde, zähle deine Vergrabene Sonnenscheibe um 3 herunter.","","„Oh! Das ist Padjuman, einer der Ältesten von Nashramae! Ich denke, heute sind alle in unserer Stadt, Papa!“\n– Aufgeregter Zuschauer","Einheit",[],["Shurima"],"GEWÖHNLICH"],"04SH031":["Vielversprechende Zukunft","Gewähre einem verbündeten Wahrzeichen „Mein Countdown-Effekt wird zweimal aktiviert“.","","„Die Sterblichen verschwenden so viel Zeit mit Warten. Ich hoffe inständig, dass sie alle für ihre Geduld belohnt werden.“\n– Zilean","Zauber",[],["Shurima"],"EPISCH"],"04SH004":["Abwägung des Urteils","Verursache 2 Schaden an einem Champion oder 4 Schaden an einem Begleiter.","","„Ein Leben im Tausch für viele andere. Ein Leben verwelkt, damit andere gedeihen können.“\n– Nasus","Zauber",[],["Shurima"],"GEWÖHNLICH"],"04SH059":["Ritus der Negation","Töte einen Verbündeten oder zerstöre einen deiner Manasteine, um alle schnellen und langsamen gegnerischen Zauber sowie Fertigkeiten aufzuhalten.","","Die Analyse ist ein wichtiger Teil der Chronomantik, da viele Aktionen unterbrochen werden müssen, um über zukünftige Lösungen nachzudenken.","Zauber",[],["Shurima"],"EPISCH"],"04SH044":["Betreuer der Uhrwerke","Ausspielen: Zähle ein verbündetes Wahrzeichen um 2 herunter.","","Die Konstrukte, die Zileans Turm bewachen, trotzen der rauen Wüste schon seit Jahrtausenden, und das liegt nicht nur an ihrer cleveren Bauweise.","Einheit",[],["Shurima"],"GEWÖHNLICH"],"04SH076":["Uraltes Stundenglas","Vernichte einen Verbündeten, um an seiner Stelle 1 Stase-Statue zu beschwören, in der sich der Verbündete befindet.","","„Oh, Tai! Komm her! Wir könnten deine Hilfe gebrauchen!“\n– Xetsa, Xenotyp-Forscherin","Zauber",[],["Shurima"],"SELTEN"],"04SH118":["Unruhige Sande","Beschwöre 1 Sandstein-Stürmer.","","„Die Kiste selbst könnte etwas wert sein, ihr Inhalt sicherlich nicht. Damit will ich sagen: Es lohnt sich nicht, sie zu öffnen. Ich spreche hier aus Erfahrung.“\n– Sivir","Zauber",[],["Shurima"],"GEWÖHNLICH"],"04SH072":["Hydromantin","Wenn ich beschworen werde, gewähre verbündeten Champions und Wahrzeichen Zauberschild.","","„Ah, du hättest nicht erwartet, Wasser mitten in der Wüste vorzufinden. Nur keine Sorge. Komm, trinke nach Herzenslust und wasche deine Füße. Ruhe dich ein wenig im Schatten aus. Das hier ist Azirs neues Shurima und es ist eine Oase.“","Einheit",[],["Shurima"],"GEWÖHNLICH"],"04SH041":["Kundschafterin der Sai","Ausspielen: Prophezeie. Wenn du ein Wahrzeichen auswählst, gewähre mir Ungreifbar.","","„Vorhin gab es Ärger! Ein übler Sturm ist im Westen aufgezogen und Taliyah hat südlich Tunnel der Xer’Sai gefunden. Ich habe im Norden einen Tempel entdeckt und sind jetzt hinter seinen Terracottamauern in Sicherheit. Die anderen schlafen, und meine Flamme ermüdet langsam, wie ich. Ich hoffe auf schöne Träume.“\n– Zaifas Tagebuch","Einheit",[],["Shurima"],"GEWÖHNLICH"],"04SH005":["Blutrünstiger Marodeur","","","Die Sanddrescher machen nichts ohne ihre Kameraden. Kämpfen, jagen, töten … und essen.","Einheit",[],["Shurima"],"GEWÖHNLICH"],"04SH083":["Instinktive Vorahnung","Prophezeie.","","„Die Flosse bringt Furcht, aber die Zähne den Tod.“\n– Shurimanisches Sprichwort","Zauber",[],["Shurima"],"SELTEN"],"04SH092":["Die Zeit ist gekommen","Beschwöre 1 Uhrwerkler.\nBeschwöre 2, falls du in diesem Spiel prophezeit hast.","","„Komm her und zappel nicht so! Du hast Sand in den Zahnrädern.“\n– Tai, Angehender Chronomantiker","Zauber",[],["Shurima"],"GEWÖHNLICH"],"04SH046":["Sandstein-Chimäre","Ich koste 1 weniger für jedes Mal, wenn ein Verbündeter in diesem Spiel angegriffen hat.","","Nach Azirs Rückkehr erblickten die Shurimaner Tiere aus alten Legenden, aus Sand geformt und dennoch ehrfurchtgebietend.","Einheit",[],["Shurima"],"SELTEN"],"04SH105":["Sandverwehtes Grab","Wenn Verbündete angreifen, beschwöre 1 angreifenden Sandstein-Stürmer.","","Als sie durch die Schlucht zogen, sprach der Sandwerker die magischen Worte. Ein Windstoß zog durch den Canyon und wurde zum Donnergeräusch sich nähernder Hufe.","Wahrzeichen",[],["Shurima"],"SELTEN"],"04SH131":["Greifhaken","Ein Verbündeter, den du in dieser Runde anvisiert hast, schlägt einen Gegner.","","„Den Greifhaken sieht niemand kommen!“\n– Akshan","Zauber",[],["Shurima"],"SELTEN"],"04SH074":["Schlüpfling der Xer’Sai","","","Sobald eine Karawane lahmgelegt ist, ziehen sich die Jäger manchmal zurück und lassen die Schlüpflinge voranpirschen. Dabei schärfen die jungen Xer’Sai ihre Instinkte und lernen, welche Geräusche von der Wüste stammen und welche von ihrer Beute.","Einheit",["LAUERND"],["Shurima"],"GEWÖHNLICH"],"04SH137":["Schwirrender Schwarm","Wenn ich beschworen werde, erschaffe eine Kopie von mir auf der Hand, wenn du in diesem Spiel einen Champion auf die nächste Stufe gebracht hast.","","Die riesigen Skarabäen galten seit dem Fall des shurimanischen Imperiums als ausgestorben. Aber die kriechenden Ausläufer des Nebels gruben sich tief in die Sande und banden die uralten Kreaturen an Viegos Willen.\n","Einheit",[],["Shurima"],"EPISCH"],"04SH069":["Rücksichtsloser Räuber","Gib einem Verbündeten in dieser Runde +2|+0, um einen Gegner in dieser Runde verletzlich zu machen.","","„Reißt sie in Stücke!“\n– Renekton","Zauber",[],["Shurima"],"GEWÖHNLICH"],"04SH121":["Ritus der Anrufung","Töte einen Verbündeten oder zerstöre einen deiner Manasteine, um einen Champion zu ziehen.","","„Ein notwendiges Opfer.“\n– Nasus","Zauber",[],["Shurima"],"GEWÖHNLICH"],"04SH110":["Felsenweben","Manifestiere ein Wahrzeichen, das du dir leisten kannst.","","„Komm schon, es gibt so viel zu sehen!“\n– Taliyah","Zauber",["ELEMENTAR"],["Shurima"],"EPISCH"],"04SH051":["Podium des Imperators","Wenn Verbündete angreifen, beschwöre 1 angreifenden Sandsoldat.","","Die Sandwerker hoben ihre Hände, formten den Sand zu den vertrauten gepanzerten und gesichtslosen Soldaten zusammen und schufen daraus eine unermüdliche Armee, die bereit war, für ihren Gott-Imperator zu kämpfen. ","Wahrzeichen",[],["Shurima"],"SELTEN"],"04SH106":["Seelenfeuer","Gib Gegnern in dieser Runde -2|-0 und „Rundenende: Verursache 2 Schaden an mir“.","","„Ihre Seelen werden brennen.“\n– Nasus","Zauber",[],["Shurima"],"SELTEN"],"04SH129":["Vekauranischer Schläger","Schlag: Erschaffe 1 Glücksfund auf der Hand.","","„Okay, Barb. Das sind die letzten Wachen auf diesem Stockwerk, aber wir müssen uns immer noch bedeckt halten.“\n„BLARGH-BLAAA!“\n„Etwas leiser, Barbara.“\n„Blarb.“\n„Gutes Mädchen.“","Einheit",[],["Shurima"],"SELTEN"],"04FR006":["Inquisitor der Drachenkrieger","Wenn ich beschworen werde, beschwöre 1 Gefrorener Diener.\nRundenende: Wenn der Countdown irgendeiner deiner Gefrorenen Diener 4 oder weniger beträgt, zähle ihn auf 0 herunter.","","„Meine Herrin erscheint mir im Traum, ihre Stimme nahezu ein Flüstern. ‚Folge mir‘, gebietet sie. Diesem Befehl wage ich mich nicht zu widersetzen.“","Einheit",[],["Freljord"],"EPISCH"],"04FR012":["Unter Eis begraben","Vernichte jeden Gegner, um an ihrer Stelle je 1 Eisgrab zu beschwören, in dem der Gegner eingeschlossen ist.","","„Irgendwann überkommt die Kälte alle.“\n– Lissandra","Zauber",["ELEMENTAR"],["Freljord"],"EPISCH"],"04FR016":["Kriegsbeute","Gewähre einem Verbündeten +1|+2.\nPlündern: Gewähre ihm stattdessen +2|+4.","","„Ihr Avarosa wurdet von euren fruchtbaren Feldern verweichlicht. Erholt euch also heute Nacht, ihr erbärmlichen Schwächlinge, und während ihr von der morgigen Ernte träumt, werden wir sie euch entreißen.“\n– Narbenmutter Vrynna","Zauber",[],["Freljord"],"GEWÖHNLICH"],"04FR013":["Kälteresistenz","Erhalte einen leeren Manastein und gewähre einem Verbündeten +0|+2.","","„Hütet euch vor dem Eis … und noch mehr vor dem, was in ihm verborgen liegt!“\n– In die Wand einer freljordischen Taverne geritzt","Zauber",["ELEMENTAR"],["Freljord"],"GEWÖHNLICH"],"04FR005":["Lissandra","Wenn ich beschworen werde, beschwöre 1 Gefrorener Diener und zähle ihn um 2 herunter.","Du hast 2+ Verbündete mit 8+ Kosten beschworen. Wenn ich eine Stufe aufsteige, erschaffe 1 Wächter im Eis auf der Hand.","„Die Wächter lauern hinter diesen Mauern, in Eis gehüllt, eine Ewigkeit im Frost … und solange sie warten, gibt es Pläne, die ich in Bewegung setzen muss …“","Einheit",[],["Freljord"],"Champion"],"04FR011":["Der Kälte erlegen","Friere einen Gegner ein.\nBeschwöre 1 Gefrorener Diener.","","„Jeder reagiert anders auf Kälte. Wie sieht es bei dir aus?“\n– Lissandra","Zauber",["ELEMENTAR"],["Freljord"],"GEWÖHNLICH"],"04FR001":["Gefrorener Diener","Countdown 9: Beschwöre 1 Diener der Frostwächter.","","Bestimmt befanden sich in den Reihen von Trundles chaotischer Armee genug schwachköpfige Krieger, die man an der Front verheizen könnte. Lissandra benötigte jedoch etwas Ergebeneres, etwas, das einzig und allein ihr dienen würde …","Wahrzeichen",[],["Freljord"],"GEWÖHNLICH"],"04FR007":["Erstarren","Vernichte eine Einheit, um an ihrer Stelle 1 Eisgrab zu beschwören, in dem die Einheit eingeschlossen ist.","","„Knie nieder oder erstarre.“\n– Lissandra","Zauber",["ELEMENTAR"],["Freljord"],"SELTEN"],"04FR017":["Überlieferte Gaben","Gewähre dem obersten Verbündeten in deinem Deck +2|+2.\nErleuchtet: Gewähre stattdessen allen Verbündeten in deinem Deck +2|+2.","","Die unerbittliche Kälte und die tobenden Stürme von Freljord töten die meisten, die sich in dieses karge Land wagen. Doch wer dies übersteht, entdeckt in seinem Inneren eine Stärke, die ihn für den Rest seines Lebens antreibt.","Zauber",[],["Freljord"],"GEWÖHNLICH"],"04FR014":["Eisbedeckte Klamm","Wenn ich beschworen werde, heile deinen Nexus um 2.\nCountdown 1: Verursache 2 Schaden an ALLEN Einheiten.","","Merkwürdige Gebilde aus dunklem Eis wachsen auf jeder Oberfläche entlang des Abhangs. Eindringlinge müssen sich zweimal überlegen, ob sie sich den spitzen Kristallen nähern wollen.","Wahrzeichen",[],["Freljord"],"SELTEN"],"04FR009":["Eissplitter","Verursache 1 Schaden an ALLEM.","","„Ich werde die Welt unter Eis begraben.“\n– Lissandra","Zauber",["ELEMENTAR"],["Freljord"],"GEWÖHNLICH"],"04FR015":["Sagenhafter Poro","Wenn ich beschworen werde, gewähre Poroverbündeten ein zufälliges Schlüsselwort.","","Es gibt ein Wesen, das von allen Poros nur in Legenden erwähnt wird. Es heißt, dass er auf seinen Reisen würdigen Pelzfreunden magische Geschenke vermacht.","Einheit",["PORO"],["Freljord"],"SELTEN"],"04FR019":["Reifzahn-Rudelmutter","Wenn ich beschworen werde, beschwöre 1 Reifzahnrudel.","","Die Reifzahnwölfe umkreisten den Drüvask, tief zu Boden geduckt und vorsichtig. Der Gestank des Todes hing an ihm, durchdringend und überwältigend.","Einheit",["HUND"],["Freljord"],"SELTEN"],"04FR018":["Schauriger Behüter","Während ich auf der Hand bin, bei Rundenbeginn: Wenn du 2+ Yetis hast, beschwöre mich und erschaffe eine Kopie von mir in deinem Deck.\nAusspielen: Ziehe 1 Yeti.","","„… und die sind auch noch verstohlen! Als ich das letzte Mal draußen war, fand ich Unterschlupf in einer Höhle, nur um darin auf Jährlinge zu stoßen, die tief und fest schliefen. Wollte mich fernhalten, aber dann kam einer der Großen zurück, groß wie ein Berg und bedeckt von Eis! Hör mir zu, denn …“\n– Babbelnder Björg","Einheit",["YETI"],["Freljord"],"EPISCH"],"04FR010":["Drei Schwestern","Erschaffe 1 Blitzfrost, Zorn des Nordens oder Erstarren mit Flüchtig auf der Hand.","","Die freljordischen Schwestern Avarosa, Serylda und Lissandra geboten über unglaubliche Macht, setzten sie aber auf unterschiedliche Art ein – jede von ihnen voller Gnade, Kriegslust oder Bosheit.","Zauber",[],["Freljord"],"SELTEN"],"04NX002":["Geflüsterte Worte","Ruf: Ich koste 2 weniger.\nZiehe 2.","","Vor den Neuigkeiten kommen die Gerüchte. Vor den Gerüchten die Tat. Vor der Tat … der Plan.","Zauber",[],["Noxus"],"SELTEN"],"04NX010":["Dorn der Schwarzen Rose","Wenn ich beschworen werde, erschaffe 1 Intrige auf der Hand.","","„Aelana, meine teuerste Freundin und Kollegin! Hast du mit Fürst Duin gesprochen?\n… Ach, was für ein Jammer. Ich hatte mich schon so auf ein Treffen gefreut. Ich hoffe, er hält sich heute Nacht zurück. Wäre doch nicht auszudenken, wenn dem alten Knaben etwas passieren würde …“\n– Fürstin Auvray, Spionin der Schwarzen Rose","Einheit",[],["Noxus"],"GEWÖHNLICH"],"04NX021":["Ehemaliger Vergelter","Wenn du mich anvisierst, gewähre mir +1|+0.","","Nach zahllosen Kämpfen hatte Beryn geschworen, nie wieder sein Schwert zu erheben, auch wenn es seinen Tod bedeuten würde. Doch als ein seltsamer Nebel durch Noxus zog und Thea übernahm, wusste er, dass er sein Versprechen brechen musste. Er würde sie befreien, koste es, was es wolle.","Einheit",[],["Noxus"],"SELTEN"],"04NX022":["Vergelterin der Zerstörung","Wenn ich beschworen werde, erschaffe 1 Nächtlicher Überfall auf der Hand.","","Als sie ihre Strafe verbüßt hatte, wusste Thea, dass sie nie wieder zu ihrem Volk zurückkehren konnte. Der Krieg – und Noxus – hatten sie verändert, sie zu einer Mörderin gemacht. Sie würde keinen Frieden finden. Stattdessen nutzte sie ihre neuen Fähigkeiten und verdiente Geld in den Arenen.","Einheit",[],["Noxus"],"SELTEN"],"04NX015":["Blutige Machenschaften","Ruf: Ich koste 2 weniger.\nEin Verbündeter mit 5+ Stärke schlägt einen Gegner.","","„Die größten Gefahren lauern im Verborgenen.“\n– LeBlanc","Zauber",[],["Noxus"],"GEWÖHNLICH"],"04NX019":["Wehrhafter Schnapper","Wenn mich ein Gegner abwehrt, gib mir in dieser Runde +3|+0.","","Der junge General war von der Widerstandskraft der Kreatur überrascht, die sie an der Küste von Ionia gefunden hatten. Er bestand darauf, sie mit nach Hause zu nehmen, um herauszufinden, wie stark sie wirklich war.","Einheit",["REPTIL"],["Noxus"],"EPISCH"],"04NX008":["Versierter Taktiker","Ruf: Ich koste 2 weniger.\nWenn ich beschworen werde, mobilisiere dich.","","In den inneren Kammern der schwarzen Rose verschieben noxianische Adelige ihre Spielsteine und in weiter Ferne werden ihre Opfer ermordet.","Einheit",[],["Noxus"],"SELTEN"],"04NX006":["Spionin der Schwarzen Rose","Ruf: Wenn ich beschworen werde, verwandle mich in eine exakte Kopie des stärksten Verbündeten, der in dieser Runde zugeschlagen hat.","","„Ein Geheimnis ist nur so viel wert, wie jemand dafür bezahlen will.“","Einheit",[],["Noxus"],"EPISCH"],"04NX001":["Imitation","Ruf: Ich koste 3 weniger.\nWenn du in dieser Runde deinen nächsten Zauber ausspielst, kopiere ihn auf dieselben Ziele.","","Nachahmung ist schmeichelhaft, und Schmeichelei kann durchaus tödlich sein.","Zauber",[],["Noxus"],"SELTEN"],"04NX004":["LeBlanc","","Ich habe gesehen, wie du 15+ Schaden verursacht hast. Wenn ich eine Stufe aufsteige, erschaffe ein Spiegelbild auf der Hand.","„Aber, aber, kein Grund für Streit zwischen uns. Vorerst werden wir nichts übereilen. Wir beraten uns, sobald wir von unserem Gesandten gehört haben. Schließlich …“","Einheit",[],["Noxus"],"Champion"],"04NX016":["Warnende Weberin","Angriff: Gib Spinnenverbündeten in dieser Runde +2|+0.","","„Nur zu, meine Teure. Lass die anderen deinen Ruf hören. Du weißt, wie sehr er sie verzückt. Und du weißt, dass mir das gefällt.“\n– Elise","Einheit",["SPINNE"],["Noxus"],"SELTEN"],"04NX007":["Atakhan, Vorbote des Untergangs","Ausspielen: Belebe den stärksten toten Verbündeten wieder.\nAngriff: Gewähre mir Stärke in Höhe der gesamten Stärke aller Verbündeten.","","Ein namenloser Schrecken ragte über ihnen in der rauchgefüllten Kammer auf. Die Magier sangen in einem disharmonischen Chor, die Furcht in ihren Stimmen ließ sie fieberhaft und angestrengt klingen. Das Monster atmete die wachsende Angst tief ein und jeder Atemzug verlieh ihm schreckliche Macht.","Einheit",[],["Noxus"],"EPISCH"],"04NX018":["Scharlachroter Blutschakal ","Wenn du das nächste Mal einen Verbündeten beschwörst, verursache 1 Schaden an ihm und gewähre mir +1|+1.","","„Weißt du, sie geben keine guten Haustiere ab. Der kleinste Kratzer ihrer Klauen reicht, um Blut zu vergießen … aber mir macht das nichts aus.“\n– Clara, Scharlachrote Adeptin","Einheit",["KATZE"],["Noxus"],"GEWÖHNLICH"],"04NX003":["Siegel der Bosheit","Ruf: Ich koste 2 weniger.\nVerursache 2 Schaden an einem beliebigen Ziel.","","Sobald die Schlacht gewonnen ist, darf man nicht zögern. Man muss seinen Feind verfolgen und auslöschen.","Zauber",[],["Noxus"],"GEWÖHNLICH"],"04NX017":["Zusammenrottung","Beschwöre 2 Marodeure der Legion.","","Die Soldaten von Noxus hinterlassen nur selten Überlebende. Die Marodeure noch seltener.","Zauber",[],["Noxus"],"GEWÖHNLICH"],"04NX009":["Dornenklinge","Gib einem Verbündeten in dieser Runde +5|+0.","","„Ihr werdet euch anmutig und rücksichtsvoll verhalten. Ihr werdet schmeicheln, ihr werdet entwaffnend sein. Ihr werdet lernen. Und wenn es soweit ist, werdet ihr zuschlagen, und ihr WERDET töten.“\n– LeBlanc","Zauber",[],["Noxus"],"GEWÖHNLICH"],"04SI005":["Kindred","Wenn du in einer Runde zum ersten Mal eine Einheit besiegst, markiere ich den schwächsten Gegner.\nRundenende: Töte die von mir markierten Einheiten.","Ich habe gesehen, wie du 2+ von mir markierte Einheiten besiegt hast.","Es war einst ein einsamer Mann\nDer sich mittendurch zerspalt’\nAus einem wurden zwei, neu geboren\nUnd so waren sie nie allein.","Einheit",[],["Schatteninseln"],"Champion"],"04SI055":["Viego","Wenn in einer Runde zum ersten Mal ein anderer Verbündeter stirbt, beschwöre 1 Einfallender Nebel.","Ich habe gesehen, wie Verbündete mit insgesamt 20+ Stärke gestorben sind.","„Etwas an dem jungen König verstört mich zutiefst. Etwas in seinem Herzen … ein Hunger, der nicht gestillt, ein Bedürfnis, das nicht erfüllt werden kann.“\n– Aus den Aufzeichnungen von Nunyo Necrit von Camavor","Einheit",[],["Schatteninseln"],"Champion"],"04SI016":["Geisterparasit ","Ausspielen: Töte einen Verbündeten, um 2 zu ziehen.","","Sie lauern im Schatten und warten darauf, dass man einnickt oder nicht aufpasst. Dann kommen ihre Klauen, ein klaffender Schlund und am Schluss die Dunkelheit.","Einheit",[],["Schatteninseln"],"GEWÖHNLICH"],"04SI007":["Der Äthergryph","Ausspielen: Töte einen Verbündeten, um einen Gegner zu töten.","","„Da sich meine Zeit an diesem Ort zu Ende neigt, denke ich nunmehr nicht über meinen ersten, sondern meinen zweiten Tod nach. Welche Seele wird sich als letzte an meinen Namen erinnern? Und wenn sie ebenfalls hier zu Boden fällt … was wird dann aus mir?“\n– Angesehener Wohltäter","Einheit",["VOGEL"],["Schatteninseln"],"SELTEN"],"04SI011":["Bis zur Dämmerung","Ziehe 1.\nNachteinbruch: Aktiviere den Nachteinbruch-Effekt eines Verbündeten und ignoriere dabei jegliche Anvisierungen.","","„Komm, Kind. Du brauchst keine Angst zu haben.“\n– Mutter der Masken","Zauber",[],["Schatteninseln"],"SELTEN"],"04SI018":["Der Gewundene Wald","Sobald ich gesehen habe, wie 3+ Verbündete mit Bedrohlich oder Nachteinbruch angegriffen haben, zerstöre mich, um Ekelschlund zu beschwören.","","Sein Altar mag leise schlummern, sein Pfad stinkt nur nach Aas,\ndoch da im Dunkel lauert es, das Biest, das man vergaß.","Wahrzeichen",[],["Schatteninseln"],"EPISCH"],"04SI015":["Meerskarabäus","Letzter Wunsch oder wenn ein anderer Verbündeter stirbt: Entsorge 1.","","„Los, Leute, hievt die Fallen hoch! Und vergesst nicht: Wenn ihr einen von diesen Meerskarabäen seht, schneidet ihr das Tau durch und macht bei der nächsten weiter. Ich riskiere doch nicht das Schiff für die halb verzehrte Beute dieser Biester!“\n– Kapitän aus Bilgewasser","Einheit",["SEEUNGEHEUER"],["Schatteninseln"],"SELTEN"],"04SI004":["Die Schwingen und die Welle","Ausspielen: Spiele mich als Erste Welle oder Letzter Hauch aus.","","Die Kinkou kennen nur zwei Götter: Die erste Welle, die das Leben in ihrem warmen Wasser wiegt, und den letzten Hauch, der es mit seinem frostigen Seufzen an sich reißt.","Einheit",[],["Schatteninseln"],"EPISCH"],"04SI017":["Lied der Inseln","Gewähre einem Verbündeten Lebensraub, Bedrohlich und Vergänglich.","","„Komm, Kind. Sieh durch meine Augen und erlebe meine Gefühle. Fürchte die Finsternis nicht.“\n– Der Wiederentfacher","Zauber",[],["Schatteninseln"],"GEWÖHNLICH"],"04SI054":["Camavora-Soldatin","Wenn ich beschworen werde, beschwöre 1 Einfallender Nebel.","","Die Soldaten Camavors marschierten im Leben an Viegos Seite, und dann erneut im Tod, ihre Treue ungebrochen.","Einheit",[],["Schatteninseln"],"GEWÖHNLICH"],"04SI001":["Gnadenfrist des Lamms","Gib dem schwächsten Verbündeten in dieser Runde „Ich kann keinen Schaden erleiden oder sterben“.","","„Erstrahle noch ein letztes Mal.“\n– Lamm","Zauber",[],["Schatteninseln"],"EPISCH"],"04SI056":["Vernichtender Nebel","Entziehe 2 Gegnern 2.","","„Ich werde mir nehmen, was ich will, und mich allem entledigen, was ich nicht will.“\n– Viego","Zauber",[],["Schatteninseln"],"SELTEN"],"04SI012":["Astralfuchs","Ausspielen: Töte einen Verbündeten, um 3 Schaden am gegnerischen Nexus zu verursachen.","","Eine Handvoll targonischer Stämme spricht vom Fuchs, einem Gott des Todes, der als einsamer Stern am Nachthimmel steht. Der Legende nach steigt der Fuchs bei jedem Tod auf den Berg hinab und nimmt die Seele mit in den Himmel, um sein eigenes dunkles Sternbild zu erschaffen.","Einheit",[],["Schatteninseln"],"GEWÖHNLICH"],"04SI029":["Verzweiflung","Wähle eine Einheit, die deinen Nexus schlägt, dann töte sie.","","„Ich habe alles gegeben, um sie zu finden, und doch ist es nicht genug.“\n– Viego","Zauber",[],["Schatteninseln"],"GEWÖHNLICH"],"04SI009":["Seelenweber","Wenn ich beschworen werde, gewähre mir +1|+1 und Bedrohlich, falls in dieser Runde ein Verbündeter gestorben ist.","","„Es war einmal ein junger Pechvogel, der einer Spinnenfrau den Hof machte und nie gedacht hätte, dass er in ihrem Netz landen würde …“","Einheit",["SPINNE"],["Schatteninseln"],"GEWÖHNLICH"],"04SI013":["Mutter der Masken","Ausspielen: Töte einen Verbündeten, um mir seine Werte und Schlüsselwörter zu gewähren.","","Die Mutter der Masken soll Kindred erschaffen haben, so wie sie alle Verkörperungen des Todes erschaffen hatte. Aber von wem hat sie ihre Maske bekommen, wenn sie sie nicht selbst hergestellt hat?","Einheit",[],["Schatteninseln"],"GEWÖHNLICH"],"04SI021":["Wütender Viperwyrm","Um mich auszuspielen, schlage einen Verbündeten oder verursache 3 Schaden an deinem Nexus.","","Erst dachten die demacianischen Soldaten, dutzende Klauen über die Kacheln des Platzes kratzen zu hören. Erst als sie durch den Wachturm brach, erkannten sie, dass die vielen Gliedmaßen zu einer einzigen Kreatur gehörten.","Einheit",["DRACHE"],["Schatteninseln"],"GEWÖHNLICH"],"04SI002":["Spirituelle Reise","Töte eine Einheit, belebe sie dann wieder.","","„Das ist nur ein Zwischenspiel.“\n– Lamm","Zauber",[],["Schatteninseln"],"SELTEN"],"04SI053":["Invasive Hydraranke","Wenn ich beschworen werde oder Rundenbeginn: Beschwöre 1 Einfallender Nebel.","","Maokai arbeitete unermüdlich, um Leben auf den Schatteninseln zu erschaffen. Die Zwiespältigkeit des Nebels macht seine Ironie nicht weniger grausam.","Einheit",[],["Schatteninseln"],"EPISCH"],"04SI003":["Verblassendes Symbol des Todes","Wenn ich beschworen werde, beschwöre 1 Beute.","","Wer außer denjenigen, auf denen der Fluch der Unsterblichkeit lastet, könnte seinen eigenen Todesgott vergessen? Und wovor könnte sich ein Todesgott mehr fürchten als vergessen zu werden? ","Einheit",[],["Schatteninseln"],"GEWÖHNLICH"],"04SI028":["Camavora-Drache","Um mich auszuspielen, schlage einen Verbündeten oder verursache 3 Schaden an deinem Nexus.\nWenn ich eine andere Einheit töte, entziehe dem gegnerischen Nexus 1.","","Jahrhundertelang suchte der schwarze Nebel Kreaturen überall auf der Welt und beeinflusste sie, formte sie neu; schuf aus ihnen albtraumhafte Versionen ihres einstigen Selbst.","Einheit",["DRACHE"],["Schatteninseln"],"SELTEN"],"04MT014":["Auge der Ra-Horak","Countdown 1: Betäube die 2 schwächsten Gegner.\nTagesanbruch: Beschwöre eine Kopie von mir mit Countdown 2.","","„Möge die Sonne uns mit ihrem Licht segnen. Die Schwachen und Unwürdigen werden unter ihrem Blick zurückweichen!“\n– Priesterin der Solari","Wahrzeichen",[],["Targon"],"SELTEN"],"04MT008":["Malphite","Ausspielen: Betäube einen Gegner.","Du hast Wahrzeichen für insgesamt 10+ Mana beschworen. Wenn ich eine Stufe aufsteige und du die Angriffsmarke hast, erschaffe 1 Unaufhaltsame Wucht auf der Hand.","„Daf ift der lepfte Halt auf Kiefels Targon-Tour! Daf ift PAPA! Er ift der GRÖFFTE von Targonf Riefen und er fingt voll gut. Aber nicht auf ihn draufklettern! Die Spfitzen kitzeln ihn und ef wär echt blöd, wenn er nieft, wenn du halb oben bift!“\n– Abenteuer mit Kiesel, Teil 6","Einheit",[],["Targon"],"Champion"],"04MT010":["Sternenbesetzter Gipfel","Countdown 2: Erschaffe 2 zufällige himmlische Karten auf der Hand, die 3 oder weniger kosten.","","Jene, die den Targon erklimmen, erwartet die herrlichste Aussicht über Runeterra. Und je höher sie klettern, umso reichhaltiger wird dieser Lohn.","Wahrzeichen",[],["Targon"],"SELTEN"],"04MT005":["Kiesel","Sobald du in diesem Spiel ein Wahrzeichen beschworen hast, gewähre mir +2|+2.","","„Okay, alfo, hallo, ich bin Kiefel und ich pfeig euch heute Targon! Ef ift waaaahnfinnig groff und hoch, alfo habt ihr hoffentlich alle Pfuhe zum Wandern an! Lof GEHPFT!“\n– Abenteuer mit Kiesel, Teil 1","Einheit",[],["Targon"],"GEWÖHNLICH"],"04MT009":["Wendelstufen","Countdown 3: Erschaffe 1 Saat der Stärke auf der Hand.","","„Hier ift die erfte Attraktion der Tour! Ich nenne daf den Kniewabbler, weil UIIII find da viele Ftufen! Und auch eine coole Aufficht, und daf ift das Befte an Targon. Okay, LOF GEHPFT!“\n– Abenteuer mit Kiesel, Teil 2","Wahrzeichen",[],["Targon"],"SELTEN"],"04MT001":["Steinschlagpfad","Countdown 2: Vernichte den schwächsten Gegner.","","„Okay, dann pafft mal AAALLE gut auf, weil daf if ein TIEFER FALL und ich bin pfon ein paar Mal hier runter gefallen und GLAUBT MIR, da geht ef echt weit runter! Und ich bin aus Ftein, also hüpfe ich nur ein biffchen, aber ihr nicht … also pafft gut … Oooh, da ift Kliff! Fagen wir hallo!“\n– Abenteuer mit Kiesel, Teil 3","Wahrzeichen",[],["Targon"],"GEWÖHNLICH"],"04MT018":["Verängstigter Steinbock","Wenn ich unterstützt werde, gib mir und meinem unterstützenden Verbündeten in dieser Runde +1|+1.","","„Fürchte nicht den heulenden Wind,\nDer bläst über Tal und Berg, mein Kind.\nHab keine Angst und mach die Äuglein zu,\nMein Liebling, Mutter wacht, geh nun zur Ruh.“\n– Schlaflied vom Targon","Einheit",[],["Targon"],"GEWÖHNLICH"],"04MT004":["Blauer Wächter","Letzter Wunsch: Beschwöre 1 Grat der Erkenntnis.","","„Okay, fagt alle mal „HALLO, BLAU!“ HALLO, BLAU! Okay, einmal dachte ich, daff er „HALLO, BLAU!“ pfurückgefagt hätte, aber wo ich fo drüber nachdenke, war daf nur mein Echo. NA JA, er ift wirklich magiff und fo, und blau, also MUFF er auch gar nicht reden, wenn du mich fragft! OKAY BIF BALD BLAU, LOF GEHPFT!“\n– Abenteuer mit Kiesel, Teil 5","Einheit",[],["Targon"],"GEWÖHNLICH"],"04MT013":["Sonnenfalke der Solari","Tagesanbruch: Betäube den stärksten Gegner.","","Die Solari glauben, dass es die schillernden Sonnenfalken des Targon waren, die die Aufmerksamkeit des Unsterblichen Feuers auf sich zogen und sie zu ihrem Zyklus aus Tod und Wiedergeburt inspirierten.","Einheit",["VOGEL"],["Targon"],"GEWÖHNLICH"],"04MT003":["Erdelementar","Sobald du in diesem Spiel 4+ Wahrzeichen beschworen hast, gewähre mir +3|+0.","","„Also, daf if KLIFF! Er iff’n groffer Kerl, der pfon ECHT LANGE hier rumrennt, daf kannfte dir merken. Ich weiff, er fieht echt cool auf und pfeint nett zu fein, aber der hat ein pfweres Päckchen zu tragen und manchmal fällt daf auf Leute, alfo AUFPAFFEN, okay? Danke und weiter gehpft!“\n– Abenteuer mit Kiesel, Teil 4","Einheit",[],["Targon"],"GEWÖHNLICH"],"04MT002":["Steinbrecher","Ausspielen: Wenn du in diesem Spiel 4+ Wahrzeichen beschworen hast, verursache 4 Schaden an einem Gegner und 2 am gegnerischen Nexus.","","Hin und wieder erwachen die großen Kolosse von Targon aus ihrem Schlaf und machen sich zu den neuen Gebieten an der Spitze des großen Berges auf. Dieses Ereignis geht nie ruhig vonstatten und ist selten sicher.","Einheit",[],["Targon"],"EPISCH"],"04MT006":["Sternenklare Erleuchtung","Ersuche.\nWenn du einen himmlischen Verbündeten hast, ersetze dein Deck mit 20 Exemplaren von Erblickt das Unendliche.","","„Schau, Kulun! Die Sterne haben so viele Geschichten zu erzählen! Welche lesen wir heute, hm?“\n– Mondträumerin","Zauber",[],["Targon"],"EPISCH"],"04MT012":["Ruf des Schicksals","Gewähre einem Verbündeten auf der Hand +8|+8.","","„Akzeptiere dein Schicksal und leuchte so hell, wie niemand es für möglich gehalten hätte.“\n– Taric","Zauber",[],["Targon"],"EPISCH"],"04MT007":["Bodenschlag ","Betäube einen Gegner. Verursache 3 Schaden an ihm, falls du in diesem Spiel ein Wahrzeichen beschworen hast.","","„Huuch, jupp, da wackelt nur der Boden, daf ift nicht Papa, der nix mit den Händen macht, NIEMALF OKAY, lof weiter im TAKT!“\n– Kiesel","Zauber",["ELEMENTAR"],["Targon"],"SELTEN"],"04MT015":["Fügung des Himmels","Tagesanbruch: Erschaffe eine zufällige Nachteinbruch-Karte auf der Hand.\nNachteinbruch: Erschaffe eine zufällige Tagesanbruch-Karte auf der Hand.","","So ist der Kreislauf von Nacht und Tag, eines folgt stets auf das andere.","Zauber",[],["Targon"],"GEWÖHNLICH"],"04DE004":["Unermüdliche Fährtensucherin","Wenn du eine Elite beschwörst, senke meine Kosten um 1.","","Obwohl die Noxianer ihre Falle gut vorbereitet hatten, kannten die demacianischen Späher die Wälder doch am besten. Jeder abgeknickte Ast, jeder Fußabdruck war ein Hinweis, der sie zu ihrem Prinzen führte.","Einheit",["ELITE"],["Demacia"],"SELTEN"],"04DE014":["Drachenfutter","Wenn du einen Drachen ausspielst, schlägt er mich und du ziehst 1.","","„Dieses Kreischen, das man von dort oben hören kann? Das war kein Vogel, mein Junge. Das war der Jagdruf eines Drachen.“\n– Demacianischer Bauer","Einheit",[],["Demacia"],"GEWÖHNLICH"],"04DE001":["Ehrwürdiger Fürst","Wenn ich zum ersten Mal einen Gegner herausfordere, gib mir in dieser Runde Barriere.","","Nachdem er vom Verschwinden seines Sohnes erfahren hatte, beauftragte König Jarvan III. seinen treuen Freund Fürst Barrett Buvelle, einen Suchtrupp zusammenzustellen. Der Prinz kehrte wohlbehalten zurück. Fürst Buvelle, zum unendlichen Leid des Königs, nicht.","Einheit",["ELITE"],["Demacia"],"GEWÖHNLICH"],"04DE012":["Feldbeförderung","Wenn du das nächste Mal in dieser Runde eine Einheit ausspielst, gewähre ihr Späher. Sie ist jetzt eine Elite.","","Wenn der Wert eines Demacianers auf die Probe gestellt wird, zeigt er sich der Situation gewachsen.","Zauber",[],["Demacia"],"GEWÖHNLICH"],"04DE003":["Kataklysmus","Ein Verbündeter beginnt einen kostenlosen Angriff, indem er einen Gegner herausfordert.","","„Für den König!“\n– Jarvan IV.","Zauber",[],["Demacia"],"SELTEN"],"04DE002":["Goldene Ägide","Gib einem Verbündeten in dieser Runde Barriere.\nMobilisiere dich.","","„Einmal noch, Soldat Demacias!“\n– Jarvan IV.","Zauber",[],["Demacia"],"SELTEN"],"04DE006":["Kampfbereitschaft","Gewähre einem Verbündeten +1|+1.","","„Ich könnte dir ein paar Dinge beibringen.“\n– Fürst Buvelle","Zauber",[],["Demacia"],"GEWÖHNLICH"],"04DE008":["Jarvan IV.","Wenn du angreifst, bezahle meine Kosten, um mich zu beschwören und den stärksten Gegner herauszufordern.","Verbündete haben 3+ Schläge von gegnerischen Blockern überlebt.","Die Noxianer wussten, wohin Prinz Jarvans Jagd ihn führen würde. Sie wussten, wie viele Demacianer an seiner Seite stehen würden, und sie wussten, dass seine Ehre ihn an der Flucht hindern würde. Der Hinterhalt war gelegt.","Einheit",["ELITE"],["Demacia"],"Champion"],"04DE005":["Cithria, Herrin der Lüfte","Wenn ich beschworen werde, verdopple Stärke und Leben anderer Verbündeter und gewähre ihnen Herausforderer.","","„Wen außer die Herrin der Lüfte hätte Demacia sonst schicken können, um seinen Prinzen zu retten?“\n– König Jarvan III.","Einheit",["ELITE"],["Demacia"],"EPISCH"],"04DE020":["Drachenwache der Zerstörung","Wenn ein Verbündeter mit Zorn eine Einheit tötet, gewähre ihm zusätzlich +1|+1.","","Der Nebel ergriff Gregems Verstand und zwang ihn, Zaunkönigs Wacht wieder und wieder zu durchleben. Angestachelt durch lange verborgene Bitterkeit und Wut wandte er sich gegen die Kameraden, die einst an seiner Seite standen.","Einheit",[],["Demacia"],"GEWÖHNLICH"],"04DE010":["König Jarvan III.","Wenn ich beschworen werde, ziehe einen Jarvan IV.\nWenn er bereits ausgespielt ist, gib Verbündeten stattdessen in dieser Runde Herausforderer und Späher.","","„Verratet mir, was würde ein Vater opfern, um seinen Sohn zu retten? Besser noch, was würde ein König opfern?“\n– LeBlanc","Einheit",["ELITE"],["Demacia"],"EPISCH"],"04DE016":["Kadregrin, Drache der Zerstörung","Ausspielen: Gewähre einem Verbündeten Herausforderer und +1|+1.","","Kadregrin brachte Furcht und Zerstörung, lange bevor der schwarze Nebel Demacia erreichte. Unter Viegos Befehl jedoch sollten seine Fähigkeiten sämtliche Armeen des gestürzten Königs verstärken.","Einheit",["DRACHE"],["Demacia"],"SELTEN"],"04DE013":["Imposantes Steinhorn","Gegnerische Zauber oder Fertigkeiten verursachen keinen Schaden an mir.","","Überlieferungen zufolge stammen die großen Steinhörner aus einer Zeit, als der Petrizitwald noch jung war. Ihre verzweigten Geweihe bestehen aus einem ähnlichen Material wie die nunmehr uralten Bäume.","Einheit",[],["Demacia"],"GEWÖHNLICH"],"04DE015":["Flinkschwingen-Staffel","Ausspielen: Erschaffe 1 Silberschwingen-Vorhut, Blendender Ansturm oder Flinkfeder-Aufspürer auf der Hand.\nAngriff: Gib anderen herausfordernden Verbündeten in dieser Runde +1|+1.","","Der bloße Anblick einer Flinkschwingen-Staffel inspiriert die demacianischen Soldaten auf dem Schlachtfeld weit unter ihnen. Wenn sie durch die Wolken brechen, werden die Kämpfer am Boden ermutigt und sind bereit für die Schlacht.","Einheit",["ELITE","VOGEL"],["Demacia"],"EPISCH"],"04DE007":["Reumütige Knappin","Wenn ich beschworen werde und du eine sichtbare Elite hast, erschaffe 1 Zerschlissenes Banner auf der Hand.","","Erst, als sie die Stadtmauern erreicht hatte, fiel sie zu Boden. Die Unerschrockene Vorhut würde dem König ihre Nachricht überbringen, und der König würde den Prinz retten. So würde sie für ihr Fehlverhalten büßen und ihre Ehre wieder sichern.","Einheit",[],["Demacia"],"GEWÖHNLICH"],"04DE009":["Galanter Reiter","Wenn ich zum ersten Mal einen Gegner herausfordere, verwandle mich in Kavallerie der Vorhut.","","Als der Befehl erteilt wurde, wurden alle demacianischen Soldaten auf die Suche nach dem Prinzen entsendet. Es war höchste Eile geboten.","Einheit",["ELITE"],["Demacia"],"SELTEN"],"05BC058":["Kennen","Wenn ich beschworen werde, erschaffe 1 Mal des Sturms auf der Hand.","Du hast in diesem Spiel den gleichen Verbündeten 5+ Mal beschworen.","Kennen hat das Brüllen eines noch unsichtbaren … Irgendetwas auch gehört. Ob Mensch oder Monster spielte keine Rolle. Die Kinkou würden ihr Land um jeden Preis beschützen.","Einheit",["YORDLE"],["Bandle","Ionia"],"Champion"],"05BC010":["Hai-Trainer","Wenn Verbündete angreifen, beschwöre 1 angreifenden Kurzzahn.","","Der Abend des Trainers läuft immer gleich ab. Fisch und Bier zum Abendessen, ein schöner Zug aus der Blasenpfeife und dann ein Küsschen auf die Schnauze und eine Gutenachtgeschichte für seine Haie.","Einheit",["YORDLE"],["Bandle","Bilgewasser"],"SELTEN"],"05BC102":["Zerzauster Zauberer","Rundenbeginn: Fülle 1 Zaubermana wieder auf.","","Wenn kein Schmerz schlimmer ist als der, sich an Papier zu schneiden, dann versteht niemand Schmerzen besser als ein Bibliothekar.","Einheit",["YORDLE"],["Bandle"],"GEWÖHNLICH"],"05BC230":["Geisterportal","Wirf zum Ausspielen 1 Karte ab. Gewähre Verbündeten +1|+1.","","„Ich kann mir nie merken, wie diese Dinger funktionieren.“\n– Poppy","Zauber",[],["Bandle"],"GEWÖHNLICH"],"05BC099":["Fitness-Späher","Wenn ich beschworen werde, gewähre mir +1|+1 pro Yordle-Verbündeten, den du hast.","","„Was mein Geheimnis ist? Frag meinen Bizeps. Der übernimmt das Reden.“","Einheit",["YORDLE"],["Bandle"],"SELTEN"],"05BC133":["Tristana","Ich habe +1|+0 für jeden Multiregion-Verbündeten, den du in diesem Spiel beschworen hast.\nWenn du einen Multiregion-Verbündeten beschwörst, gewähre ihm +1|+0.","Du hast 5+ Multiregion-Verbündete beschworen.","„Okay, Plan A: Wir sprengen uns rein und fangen an zu schießen. Wenn das nicht klappt, kommt Plan B: Wir sprengen uns raus und schießen weiter. Dann sammeln wir uns und gehen zu Plan C über, der im Prinzip Plan A ist …“","Einheit",["YORDLE"],["Bandle"],"Champion"],"05BC023":["Miniti","Rundenende: Wenn du in dieser Runde Schaden am gegnerischen Nexus verursacht hast, verwandle mich in Megati.","","Was Minitis mögen: Nickerchen auf den warmen Sommersteinen in den Ländereien des Nakotak-Stammes. Was Minitis nicht mögen: Von frechen Yordle von diesen Sommersteinen geschubst werden …","Einheit",[],["Bandle"],"EPISCH"],"05BC029":["Yuumi","Rundenbeginn: Gewähre der Einheit, die ich begleite, +1|+1. Gewähre ansonsten mir +1|+1.","Ich oder die Einheit, die ich begleite, haben 3 Mal angegriffen.","Yuumi musste zugeben, dass sie Buch trotz der ganzen Aufregung sehr gerne mochte. Sie mochte seinen Geruch. Sie mochte seine Zeichnungen. Sie mochte es sogar, durch seine Portale zu springen! … aber nichts war so gut, wie Norra sicher und geborgen wieder zu Hause zu haben.","Einheit",["FEE","KATZE"],["Bandle","Targon"],"Champion"],"05BC078":["Elektroharpune","Wirf zum Ausspielen 1 Karte ab. Verursache 2 Schaden an einer Einheit und 2 am gegnerischen Nexus.","","„Eine Spitzenshow!“\n– Rumble","Zauber",[],["Bandle"],"SELTEN"],"05BC106":["Beleidigte Seegurke","","","„Obwohl sie recht klein ist, hat die Seegurke einen riesigen Appetit und scheint obendrein ein gehöriges Verhaltensproblem zu haben.“\n– Umwelttagebuch des Conchologen, Tag 17","Einheit",[],["Bandle","Bilgewasser"],"GEWÖHNLICH"],"05BC161":["Gnar","Schlag: Erschaffe 1 Stupsstock auf der Hand oder senke seine Kosten um 2, wenn du schon einen hast.","Rundenende: Du hast in dieser Runde Schaden am gegnerischen Nexus verursacht.","Vor langer Zeit gediehen Gnar und seine Sippe im Nakotak-Tal. Es war ein unschuldiger Ort, von den Gefahren der Moderne unberührt. Ein Unglück, dass die Zeit Gnar diesen Ort raubte. Ein Glück, dass die Zeit in Bandle nicht immer ganz genau funktioniert.","Einheit",["YORDLE"],["Bandle","Freljord"],"Champion"],"05BC073":["Einfallsreiche Chemikerin","Wenn ich beschworen werde, beschwöre 1 Behelfsbombe.","","Giselle war Professor Heimerdingers beste Schülerin, bis sie von Ziggs seltsamen Experimenten in Zhaun hörte. Dann hieß es nur noch „Hexplosionen“ hier und „könnten Sie mich für ein Praktikum empfehlen“ da. ","Einheit",["YORDLE"],["Bandle"],"GEWÖHNLICH"],"05BC039":["Grummeliger Grenadier","Loyalität: Beschwöre einen zufälligen Yordle-Begleiter, der 3 oder weniger kostet.","","„Alice hier hat zwei Schuss: Einer zur Begrüßung, der andere zum Abschied. Willst du sie treffen?“","Einheit",["YORDLE"],["Bandle"],"SELTEN"],"05BC148":["Furchtloses Feenvolk","Wenn ich beschworen werde und du in diesem Spiel 4+ Mal Schaden am gegnerischen Nexus verursacht hast, gewähre mir 4 Mal Einschlag.","","Außen fluffig, innen zäh und hart.","Einheit",["FEE"],["Bandle","Piltover & Zhaun"],"GEWÖHNLICH"],"05BC119":["Vasall","Letzter Wunsch: Erschaffe beim nächsten Rundenbeginn eine Kopie von mir auf der Hand.","","„Ein wahrer Superschurke hat nie genug Vasallen! Kleine Untergebene, die nicht aufmucken, jedem Befehl gehorchen und immer für weitere Anweisungen zurückkommen.“\n– Auszug aus Kapitel 2 von „Das Einmaleins des Superschurken“ von Fürst Veigar","Einheit",[],["Bandle","Schatteninseln"],"GEWÖHNLICH"],"05BC019":["Regenbogenfisch","","","Der Regenbogenfisch war froh, etwas Aufklärung aus der Luft betreiben zu können, auch wenn er dafür höher als je zuvor springen musste. Um Yuumis hungrigem Blick zu entgehen, würde er aber jede Mühe auf sich nehmen.","Einheit",["FEE"],["Bandle"],"GEWÖHNLICH"],"05BC093":["Veigar","Wenn ich beschworen werde, erschaffe 1 Finsternis auf der Hand, wenn du keine hast. Rundenbeginn: Gewähre deiner Finsternis überall 1 zusätzlichen Schaden.","Du hast 12+ Schaden mit Finsternis verursacht.","„Diese Welt wird mich fürchten. Sie wird meine Narben für alle Ewigkeit tragen. Sie wird unter dem Gewicht meiner Macht in die Knie gehen. Sie wird erzittern unter dem Schatten meiner gewaltigen Größe!“\n– Auszug aus Kapitel 1 von „Das Einmaleins des Superschurken“ von Fürst Veigar","Einheit",["YORDLE"],["Bandle","Schatteninseln"],"Champion"],"05BC007":["Steinstapler","","","Yordle haben das mit der Schwerkraft noch nicht so ganz durchschaut. Andererseits hat die Schwerkraft auch so ihre Schwierigkeiten, Bandle zu durchschauen.","Einheit",["YORDLE"],["Bandle"],"GEWÖHNLICH"],"05BC174":["Freundschaft!","Gib einem Verbündeten in dieser Runde Barriere oder Zauberschild.","","„Ich werde dich beschützen, dank meiner wilden und wahnsinnigen … Miau!“\n– Yuumi","Zauber",[],["Bandle"],"SELTEN"],"05BC185":["Muschelspiel","Fülle dein Zaubermana wieder auf. Gib einem Verbündeten in dieser Runde Ungreifbar und +1|+1.","","„Ich habe GESEHEN, wie sie unter die linke Muschel gesteckt wurden, aber wenn ich diese Muschel WÄHLE, ist sie leer. Langsam bekomme ich das Gefühl, dieses Spiel könnte abgekartet sein …“\n– Umwelttagebuch des Conchologen, Tag 14","Zauber",[],["Bandle"],"SELTEN"],"05BC096":["Tenor des Terrors","Wenn ich beschworen werde und du in diesem Spiel eine erschaffene Karte ausgespielt oder eine Einheit mit einem Zauber getötet hast, beschwöre 1 Bass der Bürde.","","Wenn Veigar den Ton angeben wollte, waren diese beiden immer bereit, ihm zu helfen. Sie kannten sie alle. Außer die mixolydischen.","Einheit",["YORDLE"],["Bandle","Schatteninseln"],"SELTEN"],"05BC088":["Rumble","Ausspielen: Wirf bis zu 3 Karten ab, um verbündeten Rumbles überall Einschlag für die erste, Direktangriff für die zweite und Zauberschild für die dritte Karte zu gewähren.","Ich habe gesehen, wie Mecha-Yordle-Verbündete 12+ Schaden verursacht haben.","„Uuuund damit sollte sie fertig sein.“\n„FEHLER.“\n„WAS?! Ich hab das doch gerade behoben!“\n„SYSTEMVERSAGEN STEHT BEVOR.“\n„Ausschalten. AUSSCHALTEN!“\n– Rumble und Tristy","Einheit",["MECHA","YORDLE"],["Bandle","Noxus"],"Champion"],"05BC056":["Anhängerin der Böe","Wenn ich beschworen werde, erschaffe 1 Wolkenhaltung auf der Hand.","","„Die Technik unserer Schule leitet sich aus der Kontrolle der Atmung ab. Wie auch der stärkste Sturm aus einfachem Wind geboren wird.“","Einheit",["YORDLE"],["Bandle"],"SELTEN"],"05BC190":["Arena-Mechakommentator","Angriff: Ich gebe anderen angreifenden Verbündeten in dieser Runde +2|+0.","","„Wie ich die Schreierei für die Matches jede Nacht durchhalte? Mit Maschinenöl gurgeln. Fünf Minuten jeden Morgen und Abend.“","Einheit",["YORDLE"],["Bandle","Noxus"],"EPISCH"],"05BC042":["Lilabeerenshake","Erhöhe einen Verbündeten in dieser Runde auf 3|3.","","„Ich war mal wie du – konnte nicht mal ’nen Poffpilz stemmen. Aber dann fand ich ‚Shake: von Lilabeere‘. Da ist alles drin, was ein Yordle braucht, um vom Weichei zum Helden zu werden. Wenn du also hart trainiert hast, tank einen ‚Shake‘ und werd so muskulös wie ich!“\n– Gedruckte Werbeanzeige","Zauber",[],["Bandle"],"GEWÖHNLICH"],"05BC205":["Ereignishorizont","Betäube einen Gegner und betäube alle Gegner mit 2 oder weniger Stärke.","","„Bleib … genau so …“\n– Veigar","Zauber",[],["Bandle"],"GEWÖHNLICH"],"05BC223":["Verlockende Falle","Wähle 1 von 3 Einheiten oder Zaubern aus dem gegnerischen Deck und verstecke je 3 Giftige Poffpilze auf allen Kopien davon.","","„Regel 986: Fallen sind KEIN Spielzeug … aber Spaß machen sie trotzdem!“","Zauber",[],["Bandle"],"SELTEN"],"05BC091":["Arena-Promoter","Ausspielen: Wirf 1 Karte ab, um einen Mecha-Yordle zu manifestieren und seine Kosten um 1 zu senken.","","„TICKETS! HOLT EUCH EURE TICKETS! JEEEEETZT! ZUM HALBEN PREIS! Oh Mann, wenn ich die Tickets nicht verkaufe, macht mich der Boss einen Kopf kürzer … wortwörtlich.“","Einheit",["YORDLE"],["Bandle"],"GEWÖHNLICH"],"05BC163":["Ziggs","Angriff: Ich verursache 1 Schaden an meinem Blocker und dem gegnerischen Nexus.","Du hast 4+ verbündete Wahrzeichen zerstört.","„Wir müssen UNBEDINGT einen guten Eindruck hinterlassen. Der neue Sicherheitsinspektor kommt vorbei, und du weißt, was das bedeutet!“\n„Keine Explosionen?“\n„WAS?! Nein! Das bedeutet, wir jagen Zeug in die Luft, wo er es nicht mitkriegt! ‚Keine Explosionen‘ … bist du verrückt?!“\n– Ziggs und Otto","Einheit",["YORDLE"],["Bandle","Shurima"],"Champion"],"05BC151":["Spiegelmagierin","Wenn du einen erschaffenen Begleiter ausspielst, beschwöre eine exakte Kopie. Wenn du einen erschaffenen Zauber ausspielst, kopiere ihn auf dieselben Ziele.","","„Oh ja, sie gebietet über die Spiegel. Sie lässt meine Entwürfe noch erhabener aussehen und mit nur einer kleinen Lichtreflektion kann sie einem gewissen Jemand sogar ein Stück dringend notwendiger Vertikalität verleihen …“\n– Stolzierender Schneidermeister","Einheit",["YORDLE"],["Bandle"],"EPISCH"],"05BC027":["Hexplosives Minenfeld","Wenn ich beschworen werde oder du mich zerstörst, betäube den stärksten Gegner.","","„Was meinst du mit ‚Das sieht nicht sicher aus‘?“\n– Ziggs","Wahrzeichen",[],["Bandle"],"GEWÖHNLICH"],"05BC200":["Yordle-Portal","Wirf zum Ausspielen 1 Karte ab. Manifestiere einen Yordle, der 3 oder weniger kostet, und beschwöre ihn.","","„Lass niemals einen Schützen zurück!“\n– Tristana","Zauber",[],["Bandle"],"GEWÖHNLICH"],"05BC021":["Springende Bombe","Verursache 2 Schaden an einer Einheit oder 1 Schaden an zwei Gegnern.","","„Deckung, Granate!“\n– Ziggs","Zauber",[],["Bandle"],"GEWÖHNLICH"],"05BC167":["Bandle-Kommando","Nexusschlag: Erschaffe 1 Hungrige Eulenkatze auf der Hand.","","„Ich baller mich durch die Stadt, bis ich die Kinder ins Bett bringen muss!“","Einheit",["YORDLE"],["Bandle"],"GEWÖHNLICH"],"05BC179":["Yordle-Waldhüter","Angriff: Gewähre Verbündeten mit gleicher oder weniger Stärke +0|+1.","","„Poppy! Hervorragende Umsetzung unserer neuen Taktik. Was hältst du davon, wenn wir sie ‚Erdnuss-Blütensturm‘ nennen?“\n„Ich, ähm, hab doch nur den Fiesling mit meinem Hammer verkloppt. Können wir sie nicht ‚Hammer‘ nennen?“\n„So haben wir schon die letzten drei genannt!“\n– Kip und Poppy","Einheit",["YORDLE"],["Bandle","Demacia"],"EPISCH"],"05BC214":["Megainferno-Bombe","Verursache 1 Schaden an allen Gegnern. Wiederhole das einmal.","","„Bringt mir … ‚Die Große‘!“\n– Ziggs","Zauber",[],["Bandle"],"SELTEN"],"05BC221":["Pilzring","Wenn ich beschworen werde oder bei Rundenbeginn: Gib mir in dieser Runde Stärke in Höhe der Anzahl anderer Feenverbündeter, die sich auf dem Spielfeld befinden oder begleiten.","","Die kleinen Kerlchen sind putzig und pilzhübsch.","Einheit",["FEE"],["Bandle","Ionia"],"SELTEN"],"05BC041":["Poppy","Angriff: Gewähre Verbündeten mit gleicher oder weniger Stärke +1|+1.","Ich habe 3 Mal mit Verbündeten angegriffen.","Bescheidenheit ist ein Zeichen der Heldenhaftigkeit, aber viele Historiker sind sich einig, dass Poppy es ein wenig übertreibt.","Einheit",["YORDLE"],["Bandle","Demacia"],"Champion"],"05BC176":["Pirschende Projektile","Gewähre einem Verbündeten +1|+0. Verursache 1 Schaden an einem Gegner.","","„Wuuuuuuusch!“\n– Yuumi","Zauber",[],["Bandle"],"SELTEN"],"05BC105":["Bandle-Schützen","Ich koste 1 weniger für jeden Multiregion-Verbündeten, den du in diesem Spiel beschworen hast.\nWenn ich beschworen werde, gewähre mir 3 Mal Einschlag.","","Der beste Trupp.","Einheit",["YORDLE"],["Bandle"],"SELTEN"],"05BC066":["Flinke Feder","","","„W … o … i … s … t … N … o … r … r … a …? Gute Güte, was soll ich nur sagen?“\n– Mausverwalter","Einheit",["FEE"],["Bandle"],"GEWÖHNLICH"],"05BC177":["Papierkunstdrache","","","„Noch einmal falten und fertig! Das hier ist eine Giraffe! Sie heißt Socke.“ \n„Warum ‚Socke‘?“ \n„Norra liebt Socken, also wird sie auch sie lieben!“\n– Mausverwalter","Einheit",["FEE"],["Bandle"],"EPISCH"],"05BC136":["Krempel","Wirf zum Ausspielen 1 Karte ab.\nManifestiere einen Mecha-Yordle.","","„Schrott. Müll. Abfall … Hey, genau DAVON rede ich doch die ganze Zeit!“\n– Rumble","Zauber",[],["Bandle"],"GEWÖHNLICH"],"05BC164":["Giftpfeil","Verursache 1 Schaden an einem beliebigen Ziel und verstecke 3 Giftige Poffpilze im gegnerischen Deck.","","„Haha! Mitten ins Schwarze!“\n– Teemo","Zauber",[],["Bandle"],"GEWÖHNLICH"],"05BC194":["Der Bandlebaum","Rundenbeginn: Erschaffe einen Begleiter aus einer neuen Region auf der Hand. Wenn ich Verbündete aus 10 Regionen gesehen habe, gewinnst du das Spiel.","","Der Bandlebaum erstreckt sich meilenweit in den Himmel und ist aus dem Herzen der Stadt nicht wegzudenken. Für manche Yordle sind seine dicken, knorrigen Zweige ein Hoffnungsschimmer, für andere ist der Baum ein bedrohlicher und geheimnisvoller Monolith. Doch alle sind sich einig, dass ein Blick auf den Bandlebaum ein Blick in die Seele eines sehr alten und mächtigen Wesens ist.","Wahrzeichen",[],["Bandle"],"EPISCH"],"05BC127":["Rissu, der stille Sturm","Wenn ich beschworen werde, beschwöre 1 Sturmwolke.","","Die Erschaffung der Sturmwolken hatte viel Zeit gekostet. Zeit, die Rissu nicht hatte. Ihre Hände arbeiteten fieberhaft, während sich die Anomalie immer weiter näherte. Ein paar Wolkenfetzen hier, ein paar Blitze dort und dann … KRACH! BUMM! Sie hatte es geschafft, aber würde es ausreichen?","Einheit",["YORDLE"],["Bandle"],"EPISCH"],"05BC216":["Yordle-Konstruktion","Zerstöre ein Wahrzeichen oder erschaffe 2 zufällige Multiregion-Begleiter auf der Hand.","","„Festhalten – es läuft!“\n– Bomber-Zwillinge","Zauber",[],["Bandle"],"GEWÖHNLICH"],"05BC212":["Sicherheitsinspektor","Rundenbeginn: Erschaffe 1 Inspektion bestanden! auf der Hand.","","Ursprünglich war Wilfred skeptisch. Er war aber auch grundsätzlich skeptisch. Er war sogar bis zum Schluss skeptisch – doch dann bewiesen Ziggs und die anderen Hexplosionsexperten, dass sie ein Feuerwerk veranstalten können, das die Welt noch nicht gesehen hat. ","Einheit",["YORDLE"],["Bandle"],"SELTEN"],"05BC141":["Heroischer Refrain","Gib 2 Verbündeten in dieser Runde +2|+1.","","„‚Da standen die Helden, Rücken an Rücken –‘“\n„– Hintern an Hintern! Hehehehehe!“\n„N-nein! Peppy, wenn du schon dazwischenrufen musst, tu es bitte in weniger dramatischen Momenten!“\n– Geschichten vom Yordle-Lagerfeuer","Zauber",[],["Bandle"],"GEWÖHNLICH"],"05BC209":["Abwehrreflex","Setze die Werte einer Einheit in dieser Runde auf 1|6.","","Gockelinde ist normalerweise ein treues und unerschütterliches Reittier. Wird es aber Strapazen ausgesetzt, verhält es sich gelegentlich … ungewöhnlich.","Zauber",[],["Bandle"],"GEWÖHNLICH"],"05BC210":["Flammenspeier","Gewähre einem Verbündeten +2|+0 und Einschlag.","","„Wenn sie nicht schreien, dann ist es noch nicht heiß genug! Heh heh.“\n– Rumble","Zauber",[],["Bandle"],"GEWÖHNLICH"],"05BC013":["Raffinierte Tentakel","Dein Gegner wirft seine Karte mit den niedrigsten Kosten ab.","","„Notiz an mich selbst: Bei der nächsten Expedition sollte ich alle Wertsachen in die VORDEREN Taschen packen.“\n– Umwelttagebuch des Conchologen, Tag 19","Zauber",[],["Bandle"],"GEWÖHNLICH"],"05BC100":["Poffpilz-Welpe","Schlag: Verstecke 3 Giftige Poffpilze im gegnerischen Deck.","","„Was ist, Junge? Zwei Rekruten waren im Wald unterwegs und sind über ein gruseliges Grasmonster gestolpert und jetzt sterben sie vielleicht einen langsamen, schmerzhaften Tod? Führ mich hin!“\n– Teemo","Einheit",["HUND"],["Bandle"],"GEWÖHNLICH"],"05BC098":["Durchgeknallter Katalysator","Schlag: Gewähre deiner Finsternis überall 1 zusätzlichen Schaden.","","Finsternis kommt in allen Formen und Größen. Manche davon ÜBERRASCHEND niedlich.","Einheit",["YORDLE"],["Bandle"],"GEWÖHNLICH"],"05BC122":["Yordle-Neuling","Wenn du einen anderen Yordle beschwörst, gib mir in dieser Runde +2|+0.","","„Riesus grasicus. Diese schrecklichen Kreaturen tarnen sich, indem sie wie normales Gras herumliegen und jeden angreifen, der dummerweise auf sie tritt. Wer ihnen begegnet, sollte unbedingt weglaufen!“\n– Ava Überflieger","Einheit",["YORDLE"],["Bandle"],"GEWÖHNLICH"],"05BC120":["Yordle-Hauptmann","Wenn du einen anderen Verbündeten mit gleicher oder weniger Stärke beschwörst, gewähre ihm +1|+1.","","„Abenteuer zu erleben heißt, Bösewichte zu finden und sie zu Freunden zu machen!“","Einheit",["YORDLE"],["Bandle"],"GEWÖHNLICH"],"05BC046":["Donnerfaust","Wenn ich beschworen werde und du in diesem Spiel eine Donnerfaust beschworen hast, verwandle mich in Masa, Krachender Donner.","","Als Masa die Übungspuppe traf, fuhr aus seiner Faust ein greller Blitz, der das Holz zerbarst und die Haare auf seiner Hand versengte. Er zerrte an dem Seil und holte die Bronzefaust zurück. Währenddessen dachte er über sein Training nach. Er war nun endlich bereit. Plötzlich ertönte ein lautes Brüllen in der Ferne.","Einheit",["YORDLE"],["Bandle"],"GEWÖHNLICH"],"05BC018":["Überheblicher Chevalier","","","„Neunhundertachtundneunzig … neunhundertneunundneunzig … eintausend! Das wär’s, Gockelinde, du siehst so wunderbar aus wie immer. Okay, jetzt bin ich dran!“","Einheit",["YORDLE"],["Bandle","Demacia"],"SELTEN"],"05BC132":["Donnerschuss","Ich koste 2 weniger, wenn du eine Tristana hast oder in diesem Spiel Karten aus 4+ Regionen ausgespielt hast.\nVerursache 3 Schaden an einer Einheit.","","In jedem Peng ist ein Bumm, das darauf wartet, geboren zu werden.","Zauber",[],["Bandle"],"GEWÖHNLICH"],"05BC168":["Gefleckte Kröte","Rundenende: Wenn du in dieser Runde Schaden am gegnerischen Nexus verursacht hast, verwandle mich in Giga-Gromp.","","Die Yordle des Nakotak-Tals haben über mehrere Generationen hinweg versucht, ihre Gromp-Nachbarn zu verstehen. Erst versuchte Häuptling Hegabo, sie mit einem Stock anzustupsen. Danach versuchte Häuptling Babobu, sie mit einem Stock anzustupsen. Häuptling Nakotak hatte einen völlig anderen Plan: Er wollte sie mit einem Stock anstupsen.","Einheit",[],["Bandle"],"SELTEN"],"05BC014":["Kleindaktylus","Rundenende: Wenn du in dieser Runde Schaden am gegnerischen Nexus verursacht hast, verwandle mich in Terrordaktylus.","","Die Kreaturen des Nakotak-Tals sind so vielfältig und lebhaft wie das Land, das sie bewohnen … und mindestens so explosiv.","Einheit",["VOGEL"],["Bandle"],"GEWÖHNLICH"],"05BC138":["Handwerkshörnchen","Wenn du zum ersten Mal eine Karte abwirfst oder Schaden am gegnerischen Nexus verursachst, gewähre mir +2|+1.","","„Na schön, guter Kampf. War eine klasse Show. Jetzt räumt den Müll weg und … äh, ihr kennt das Prozedere ja: Alles, was sich wiederverwerten lässt, kommt in die Werkstatt und dann verkaufen wir es wieder! HAHAHA!“\n– Karl, Arena-Boss","Einheit",[],["Bandle"],"GEWÖHNLICH"],"05BC198":["Gruppenfoto","Verursache 1 Schaden an einer Einheit. Wenn du 4+ Verbündete hast, verursache stattdessen 2 Schaden.","","„Okay, das hier ist für das Rundschreiben. Und dieses Mal bitte lächeln! Eins … zwei … drei …!“\n– Tristana\n","Zauber",[],["Bandle"],"GEWÖHNLICH"],"05BC181":["Wolkenhaltung","Gib einem Verbündeten in dieser Runde +2|+0 und „Rundenende: Rufe mich zurück“.","","„Atme tief durch und finde neue Stärke!“\n– Anhängerin der Böe","Zauber",[],["Bandle"],"GEWÖHNLICH"],"05BC160":["Proto-Poro","","","Die urzeitlichen Poros hatten viel dickere Schädel als ihre Nachfahren. Dadurch waren sie zwar etwas dümmer, aber sie konnten bessere Kopfnüsse verteilen.","Einheit",["PORO"],["Bandle","Freljord"],"GEWÖHNLICH"],"05BC005":["Algenschwestern","Nexusschlag: Erschaffe 1 Streich auf der Hand.","","„Du meine Güte, ich hatte soeben den seltsamsten Traum. Gerade schlage ich mich durch die Algen und suche nach meinem Muschelhut, da höre ich eine wundervolle Melodie. Und bevor ich mich versah, sitze ich hier, den Stift in der Hand, und schreibe diese Worte. Ich erinnere mich nicht, mich für ein Nickerchen hingesetzt zu haben …“\n– Umwelttagebuch des Conchologen, Tag 22","Einheit",[],["Bandle"],"SELTEN"],"05BC020":["Hilfsbibliothekarin","Nexusschlag: Ziehe einen Zauber, der 3 oder weniger kostet.","","„Jelly ist meine BESTE FREUNDIN! Also, nach dir, Buch. Und Norra. Okay, Jelly ist meine DRITTBESTE FREUNDIN. Das ist trotzdem ziemlich gut, oder?!“\n– Yuumi","Einheit",["FEE"],["Bandle"],"GEWÖHNLICH"],"05BC049":["Conchologe","Ausspielen: Manifestiere 1 Zauber aus deinen Regionen, der 3 oder weniger kostet.","","„Oh, welch ein Freudentag! Eine Expedition in die Tiefe! Ich bin sicher, das wird … meer Spaß machen als ich je hatte! Hoho!“\n– Umwelttagebuch des Conchologen, Tag 1","Einheit",["YORDLE"],["Bandle"],"SELTEN"],"05BC001":["Minimorph","Verwandle eine Einheit in ein Mini-Miniti mit 3|3 und lasse sie verstummen.","","„Oh-ho! Wie putzig! Wie herzallerliebst! Wie WINZIG!“\n– Veigar","Zauber",[],["Bandle"],"SELTEN"],"05BC026":["Versteckte Passagen","Ich koste 2 weniger, wenn du in diesem Spiel 2+ Karten erschaffen hast. Ziehe 2.","","Nur wenige Außenseiter kennen den Weg nach Bandle, aber seltsame Markierungen an Steinen und Bäumen in Runeterra bieten jenen Hinweise, die wissen, wonach sie Ausschau halten müssen.","Zauber",[],["Bandle"],"GEWÖHNLICH"],"05BC152":["Unbeeindruckte Reisende","Wenn ich beschworen werde, ziehen ALLE Spieler 1 Karte. Dann wirft dein Gegner seine teuerste Karte ab.","","„Schlechtester. Ausflug. Aller. Zeiten.“\n– Elle","Einheit",["YORDLE"],["Bandle","Piltover & Zhaun"],"GEWÖHNLICH"],"05BC070":["Ava Überflieger","Wenn ich beschworen werde oder Rundenende: Verstecke 3 Giftige Poffpilze im gegnerischen Deck.\nFallen auf gegnerischen Karten werden bei Aktivierung verdoppelt.","","„Regel 378: Ein guter Späher ist stets tapfer, stets vorbereitet und stets mutig!“","Einheit",["YORDLE"],["Bandle"],"EPISCH"],"05BC015":["Glutechse","Rundenende: Wenn du in dieser Runde Schaden am gegnerischen Nexus verursacht hast, verwandle mich in Lavaechse.","","„Iss die Schote!“, brüllte Nakotak (wahrscheinlich). „Nein, iss DU die Schote!“, antwortete Jojo (ebenfalls wahrscheinlich). Als sie stritten, huschte eine kleine Echse auf der Jagd nach einer noch kleineren Fliege vorüber. Die beiden Yordle sahen die Echse an, dann die Schote, dann einander. Würde es Glühbirnen geben, wäre eine angegangen.","Einheit",["REPTIL"],["Bandle"],"GEWÖHNLICH"],"05BC145":["Yordle-Knappin","Ausspielen: Erschaffe 1 Winziges Pilum oder 1 Winziger Schild auf der Hand.","","„Mein Pilum gehörte auch mal einem großen Helden … ich hab Poppy es mal kurz halten lassen!“","Einheit",["YORDLE"],["Bandle"],"GEWÖHNLICH"],"05BC140":["Poroschlitten","Angriff: Beschwöre 1 zufälligen angreifenden Poro mit 1 Kosten.","","„Und dann war DER kleene Poro so ‚Da lang!‘ und deshalb sind dann alle zum Horizont, und die anderen Poros sind hinterher und haben ihr bestestes getan, mitzuhalten!“\n– Ingvar die Jüngere","Einheit",["PORO"],["Bandle","Freljord"],"EPISCH"],"05BC129":["Arena-Boss","","","„Die Dummen sterben nie aus, und ich nehm ihnen alles ab, was sie besitzen … diese Mech-Arena wird eine GOLDMINE.“","Einheit",["YORDLE"],["Bandle","Noxus"],"GEWÖHNLICH"],"05BC004":["Otterpus","Wenn ich beschworen werde, erschaffe 1 Streich auf der Hand.","","„Die neugierigen und verspielten Otterpus sind sehr fröhliche Tiere. Oder sagt man Otterpi? Hm, hatte ich nicht noch ein drittes Sandwich eingepackt?“\n– Umwelttagebuch des Conchologen, Tag 7","Einheit",[],["Bandle"],"GEWÖHNLICH"],"05BC155":["Anhänger der Funken","Wenn du einen anderen Verbündeten beschwörst, gewähre mir +1|+0.","","„Kleine Funken werden zu einem tosenden Feuer. Wir sind die Glut deiner Zerstörung!“","Einheit",["YORDLE"],["Bandle"],"SELTEN"],"05BC104":["Urzeitliche Stärke","Gewähre einem Verbündeten +2|+2 und Einschlag.","","Ja, er ist sehr niedlich. Ja, man kann ihn leicht reizen. Nein, du willst ihn nicht reizen.","Zauber",[],["Bandle"],"GEWÖHNLICH"],"05BC218":["Hilfe der Feen","Erschaffe 1 Hungrige Eulenkatze auf der Hand und gewähre dann Feenverbündeten auf der Hand +1|+1.","","„Wer füttert ständig diese Dinger?“\n– Poppy","Zauber",[],["Bandle"],"SELTEN"],"05BC192":["Bomber-Zwillinge","Wenn ich beschworen werde, erschaffe ein zufälliges Wahrzeichen auf der Hand, das 2 oder weniger kostet.","","Der Flinkfuß-Bomberator X machte genau das, wofür er gebaut wurde: Chaos stiften. Außerdem lässt er sich kinderleicht seitlich parken. ","Einheit",["YORDLE"],["Bandle","Shurima"],"GEWÖHNLICH"],"05BC162":["Häuptling Nakotak","Wenn sich ein Verbündeter verwandelt, heile ihn vollständig und gewähre ihm +1|+1 und Einschlag.","","Häuptling Nakotak ernannte sich selbst zum Anführer des Stamms, nachdem er in den Schneewehen des Landes einen großen Dinosaurierknochen gefunden hatte. Niemand wusste davon, dass Dinosaurierknochen einen zum Anführer des Stammes machen würden, aber es interessierte auch niemanden. Also wurde es Nakotak.","Einheit",["YORDLE"],["Bandle"],"SELTEN"],"05BC032":["Schimmernde Laterne","Die erste Fee, die du in einer Runde ausspielst, kostet 2 weniger.","","„Laterne folgt Norra, Mondmotten folgen Laterne, Mäuse folgen Mondmotten! Folgt, folgt!“","Einheit",["FEE"],["Bandle"],"SELTEN"],"05BC166":["Stupsstock","Verursache 1 Schaden an einem beliebigen Ziel. Ziehe 1.","","Die erste Regel für Experimente: Stupse es an und warte, was passiert.","Zauber",[],["Bandle"],"GEWÖHNLICH"],"05BC006":["Das Arsenal","Wenn ich beschworen werde, gewähre mir ein zufälliges Schlüsselwort für jedes verbündete Wahrzeichen, das du in diesem Spiel zerstört hast.\nWenn du ein verbündetes Wahrzeichen zerstörst, gewähre mir ein zufälliges Schlüsselwort.","","Wo Ziggs auch hinging, folgte ihm Arnie und bildete mit seiner ruhigen Art den natürlichen Gegenpol zu Ziggs’ chaotischer Leidenschaft. Er kümmerte sich darum, die Munition nachzuliefern, löschte Feuer und hielt Ziggs’ Ohren zu, wenn dieser (unausweichlich) vergaß, seinen Hörschutz zu tragen. ","Einheit",["YORDLE"],["Bandle"],"EPISCH"],"05BC110":["Gelehrter Kletterer","","","„Ja, ja, du hast mir erzählt, wie sehr sie Tee, Socken, dich, Knöpfe und das Sammeln von Kleinkram mag, aber du hast mir immer noch nichts darüber erzählt, wie sie AUSSIEHT!“ ","Einheit",["YORDLE"],["Bandle","Targon"],"GEWÖHNLICH"],"05BC063":["Tornadokriegerin","Wenn ich beschworen werde, gewähre mir +1|+0 und ein zufälliges Schlüsselwort.\nIch behalte die Werte-Buffs und Schlüsselwörter, wenn ich zurückgerufen werde.","","Mit Atemübungen und durch die Kanalisierung ihres inneren Zorns in einen tobenden Wirbelsturm aus tödlichen Klingen behält die Tornadokriegerin ihre Ruhe bei. ","Einheit",["YORDLE"],["Bandle"],"GEWÖHNLICH"],"05BC217":["Feensprössling","Manifestiere eine Fee und gewähre ihr +1|+1.","","Jedes Lebewesen braucht Nahrung. Die Feen sind keine Ausnahme, aber es ist nicht immer einfach zu sagen, wie sie sie verwenden.","Zauber",[],["Bandle"],"SELTEN"],"05BC180":["Beschleunigen","Rufe eine Einheit mit 3 oder weniger Stärke zurück.","","„Wir sind schnell! Wir sind der Wind!“\n– Kennen","Zauber",[],["Bandle"],"GEWÖHNLICH"],"05BC040":["Trödeltausch","Manifestiere 1 Otterpus oder einen von 2 Zaubern aus deinen Regionen, die 3 oder weniger kosten.","","„Nimm sofort die Finger von meinem Sandwich!“\n– Conchologe","Zauber",[],["Bandle"],"SELTEN"],"05BC213":["Prügel","Verursache 1 Schaden an einem Gegner und betäube ihn.","","„Ahanga!“\n– Gnar","Zauber",[],["Bandle"],"GEWÖHNLICH"],"05BC208":["Heroischer Ansturm","Ein Verbündeter schlägt einen Gegner. Wenn er überlebt, betäube ihn.","","„Aus dem Weg!“\n– Poppy","Zauber",[],["Bandle"],"SELTEN"],"05BC085":["Bilgeratten-Racker","Ausspielen: Wirf 1 Karte ab, um einen Mecha-Yordle zu manifestieren und ihm Zauberschild zu gewähren.","","„Sei bitte leiser! Ich kann mich kaum beim Geldzählen hören!“\n– Karl, Arena-Boss","Einheit",["YORDLE"],["Bandle"],"SELTEN"],"05BC112":["Knallzapfenkeimling","Ausspielen: Gib mir in dieser Runde Barriere oder gewähre mir Einschlag.","","Die Knallzapfenkeimlinge sind scheue Kreaturen. Ihr erster Instinkt ist die Flucht, aber wenn sie bedroht werden …","Einheit",["FEE"],["Bandle","Ionia"],"GEWÖHNLICH"],"05BC135":["Doppeltreffer","Ein Verbündeter schlägt einen Gegner. Wenn es ein Multiregion-Verbündeter ist, schlägt er den Gegner erneut.","","„Die Buchecker M1-85: vollautomatisches Gewehr vom Kaliber Buche mit Bandleholz-Zielfernrohr und Lilabeerenlackierung. Oh ja, Mama macht heute Abend was Leckeres!“\n– Bandle-Kommando","Zauber",[],["Bandle"],"GEWÖHNLICH"],"05BC084":["Blechpiepser","Ausspielen: Wirf 1 Karte ab, um einen Mecha-Yordle zu manifestieren.","","Kleine Statur, GROẞER Charakter.","Einheit",[],["Bandle"],"GEWÖHNLICH"],"05BC184":["Muntere Minnesänger","Wenn ich beschworen werde, erschaffe 1 Hungrige Eulenkatze auf der Hand.","","„Dieses Lied beruht\nAuf Poppy voll Heldenmut!\nPoppy, die Wilde, ein edles Gebilde, Poppy, die … gut kämpfen tut!“ \n– Durchgestrichene Zeile aus dem ‚Liederbuch von Reginaldactyl und Faltimisquee, wahrlich meisterhafte Minnesänger‘","Einheit",["YORDLE"],["Bandle"],"GEWÖHNLICH"],"05BC116":["Bürgermeister von Bandle","Die erste Multiregion-Einheit, die du in einer Runde ausspielst, kostet 1 weniger.\nAusspielen: Manifestiere einen Multiregion-Begleiter.","","Es ist nicht klar, ob Bandle jemals wirklich einen Bürgermeister gewählt hat, aber ein gigantischer Schnurrbart wäre auf jeden Fall eine Voraussetzung.","Einheit",["YORDLE"],["Bandle"],"EPISCH"],"05BC111":["Yordlekompanie ","Gib Verbündeten in dieser Runde +2|+2. Wenn du Karten aus 4+ Regionen ausgespielt hast, gib Verbündeten stattdessen +3|+3.","","„Wir … sehen gerade echt cool aus.“\n– Tristana","Zauber",[],["Bandle"],"SELTEN"],"05BC224":["Transposition","Rufe einen Verbündeten zurück. Der nächste Verbündete mit gleichen oder niedrigeren Kosten, den du in dieser Runde ausspielst, kostet stattdessen 0.","","„Ein schneller Körper, ein schneller Geist!“\n– Kennen","Zauber",[],["Bandle"],"SELTEN"],"05BC130":["Hitzkopf","Angriff: Gewähre dem obersten Champion in deinem Deck +1|+1 und ein zufälliges Schlüsselwort.","","Ottos Grillfeiern sind berüchtigt. Er liebt zwar nichts mehr als das Grillen, aber seine Gäste haben nur die Wahl zwischen „Gut durch“ und „Extrem gut durch“.","Einheit",["YORDLE"],["Bandle","Shurima"],"GEWÖHNLICH"],"05BC191":["Richtspruch der Hüterin","Lege eine gegnerische Einheit an die Spitze des gegnerischen Decks.","","„Und komm nicht zurück!“\n– Poppy","Zauber",[],["Bandle"],"SELTEN"],"05BC052":["Geliebtes Gerümpel","Fülle deine Hand mit zufälligen Karten. Sie kosten 0 und sind flüchtig. Du kannst in dieser Runde nur 3 weitere Karten ausspielen.","","Für einen Menschen ist es Schrott, aber für einen Yordle ein riesiger Haufen Ersatzteile.\n","Zauber",[],["Bandle"],"SELTEN"],"05BC050":["Benemone","Wenn ich beschworen werde, erschaffe 2 Streiche auf der Hand.","","„Jene, die zu Übelkeit neigen, sollten sich diesem sanften Riesen SEHR vorsichtig nähern. Eure Innereien werden es euch danken … Apropos: Ich hätte dieses zweite Pilzsandwich wirklich nicht essen sollen …“\n– Umwelttagebuch des Conchologen, Tag 3","Einheit",[],["Bandle"],"GEWÖHNLICH"],"05BC094":["Düsterbirnen-Akolyth","Wenn ich beschworen werde, erschaffe 1 Finsternis auf der Hand, wenn du keine hast.","","„Ja, ich bin mir durchaus sicher, dass der Knabe auf dem Dach einige Geschichten zu erzählen hat. Wir wissen alle, dass er viel zu sagen hat. Wir haben nur leider keine Ahnung, WAS er eigentlich sagt.“\n– Stolzierender Schneidermeister","Einheit",["YORDLE"],["Bandle"],"GEWÖHNLICH"],"05BC146":["Bandle-Malerin","Ausspielen: Wirf 1 Karte ab, um einen Multiregion-Begleiter auf der Hand zu erschaffen, und senke seine Kosten um 1.","","„Als Malerin kopiert man nicht einfach, was man sieht, sondern man drückt aus, WIE man die Welt sieht. Und jetzt gerade sehe ich, dass du dich wieder bewegt hast. Halt doch bitte still!“","Einheit",["YORDLE"],["Bandle","Piltover & Zhaun"],"GEWÖHNLICH"],"05BC235":["Yordle-Schmied","Angriff: Gib Verbündeten mit gleicher oder weniger Stärke in dieser Runde Direktangriff.","","„Poppy hört mir nie zu, also pass auf: Es geht nicht um den Hammer, sondern um den Yordle, der ihn schwingt.“\n","Einheit",["YORDLE"],["Bandle"],"GEWÖHNLICH"],"05BC175":["Spazierendes Teleskop","Ausspielen: Manifestiere eine himmlische Karte, die 3 oder weniger kostet, eine epische Karte oder einen Multiregion-Begleiter.","","Das Seltsamste war nicht, dass das Teleskop aufstand, sich streckte und langsam herumlief, sondern, dass es darauf bestand, sich warm anzuziehen und sich einen gemütlichen Schal suchen musste.","Einheit",["FEE"],["Bandle","Targon"],"SELTEN"],"05BC182":["Blitzartiger Ansturm","Rufe einen Verbündeten zurück, um 2 Schaden an einem beliebigen Ziel zu verursachen.","","„Erst das Krachen, dann der Knall!“\n– Kennen","Zauber",["ELEMENTAR"],["Bandle"],"SELTEN"],"05BC069":["Belehrender Yordle","Angriff: Erschaffe 1 flüchtigen Giftpfeil auf der Hand.","","Wenn er einmal in Fahrt gekommen ist …","Einheit",["YORDLE"],["Bandle"],"SELTEN"],"05BC057":["Stolzierender Schneidermeister","Wenn ich beschworen werde, senke die Kosten deiner Finsternis überall um 1.","","„Es ist bei der Versammlung einer Kabale wichtig, dass jedes manische Mitglied etwas Einzigartiges zum Superbösewichtsein beitragen kann. Einer meiner Mitschurken hat beispielsweise einen mörderisch guten Stil …“\n– Auszug aus Kapitel 4 von „Das Einmaleins des Superschurken“ von Fürst Veigar","Einheit",["YORDLE"],["Bandle"],"SELTEN"],"05BC108":["Yordle-Erkunder","Wenn du einen anderen Yordle beschwörst, gewähre ihm +1|+0.","","„Unschätzbar ist der Ruhm der Erforschung, aber die größten Entdeckungen sind immer … äh … profitabel.“","Einheit",["YORDLE"],["Bandle"],"GEWÖHNLICH"],"05BC183":["Großvater Fee","Wenn ich beschworen werde, erschaffe 1 Hungrige Eulenkatze auf der Hand.\nWenn du eine weitere Fee beschwörst, gewähre ihr +1|+0.","","„Kommt her und lauscht meiner Idee\nDer traurigen Geschichte von Großvater Fee.\nJeden Tag fütterte er die Vögel\nMit einer Mischung aus Körnern und Knödeln …“\n– Fabel aus Bandle","Einheit",["FEE"],["Bandle","Ionia"],"SELTEN"],"05BC188":["Neugieriges Muschelvolk","Wenn du eine Karte aus einer zufälligen Auswahl wählst, die kein Champion ist, erschaffe eine Kopie auf der Hand und senke ihre Kosten um 1.","","Das bekanntermaßen scheue Muschelvolk versteckt sich gerne in seiner Schale, bis seine Neugier zu stark wird. Sobald sie sich raustrauen, lassen sie ihren verspielten Persönlichkeiten freien Lauf und spielen mit Vorliebe Streiche, indem sie die Geräusche anderer Meereskreaturen nachahmen.","Einheit",[],["Bandle"],"EPISCH"],"05FR001":["Düsterwolf-Schamane","Rundenende: Wenn du in dieser Runde Schaden am gegnerischen Nexus verursacht hast, verwandle mich in Düsterwolf-Berserker.","","„Wir sterben nicht als Feiglinge! Wir sterben mit ausgefahrenen Klauen und wild gebleckten Zähnen! Nur so ehren wir den Wolf!“\n– Hyara die Allsehende","Einheit",[],["Freljord"],"GEWÖHNLICH"],"05FR002":["Mammut-Schamane","Rundenende: Wenn du in dieser Runde Schaden am gegnerischen Nexus verursacht hast, verwandle mich in Mammut-Berserker.","","Bei Bedrohungen durch Raubtiere rottet sich eine Mammutherde um ihre Kälber und trächtigen Kühe. Aus diesem Grund bitten die Schamanen des großen Mammutgeistes nicht nur um die körperliche Stärke dieser Geister, sondern auch um ihre Stärke der Gruppe, mit der sie ihre Familie beschützen können.","Einheit",[],["Freljord"],"SELTEN"],"05FR013":["Udyr","Wenn ich beschworen werde oder zuschlage: Erschaffe 1 Haltungswechsel auf der Hand oder senke seine Kosten auf 0, wenn du schon einen hast.","Du hast Haltungswechsel 3+ Mal ausgespielt.","„Die Geister formen unsere Welt genauso wie wir und unsere Welt formt die Geister. Indem wir ihre Kraft nutzen, nutzen wir auch die uns innewohnende Kraft.“","Einheit",[],["Freljord"],"Champion"],"05FR016":["Ruf der Schamanin","Erschaffe 2 flüchtige Haltungswechsel mit 0 Kosten auf der Hand.","","„Sie werden sich zeigen ... Große Geister mit Klauen und Reißzähnen, Schuppen und Federn. Dann erzittert ihr vor Furcht und Schock und ihr werdet erkennen, dass uns die alten Götter nicht vergessen haben.\"\n– Hyara die Allsehende","Zauber",[],["Freljord"],"GEWÖHNLICH"],"05FR012":["Hyara die Allsehende","Wenn ich beschworen werde, erschaffe 1 Haltungswechsel auf der Hand.\nDer erste Haltungswechsel, den du in einer Runde ausspielst, kostet 0.","","Hyara die Allsehende, die große Schamanin, wurde von allen verehrt. Sie verlor ihr Augenlicht vor langer, langer Zeit und sieht die Welt nun durch die Augen der Falken und Adler hoch oben in den Bergen. Besorgniserregende Visionen trieben sie aus den Bergen hervor. Sie hofft aber inständig, dass die Omen nur Visionen bleiben.","Einheit",[],["Freljord"],"SELTEN"],"05FR014":["Der Zorn Freljords","Ausspielen: Friere einen Gegner ein.\nGegner mit 3 oder weniger Stärke sind abwehrunfähig.","","„Ich war da, vor so vielen Jahren. Erst kam die Kälte, beißend und unerbittlich. Dann ein Sturm, tosend und erbarmungslos. Zum Schluss ertönte ein Gebrüll, das so schrecklich war, dass es mir in die Knochen schnitt. Ich fiel auf meine Knie und betete, dass wir keinen Fehler begangen haben mögen. Einen großen Geist anzurufen, ist eine Einladung für seine Rache … und eine Hoffnung an seine Gnade.“\n– Hyara die Allsehende","Einheit",[],["Freljord"],"EPISCH"],"05FR017":["Das innere Tier","Gib einem Verbündeten in dieser Runde +1|+1. Erschaffe 1 Haltungswechsel auf der Hand.","","„Kommt, Geister, kommt …“\n– Udyr","Zauber",[],["Freljord"],"GEWÖHNLICH"],"05FR006":["Hauertrommler","Ausspielen: Verursache 1 Schaden an BEIDEN Nexus.","","Nur wenige Schamanenfamilien haben der Winterklaue so lange wie die von Chuluun gedient. Als Schamane des großen Walrosses ist er Verkünder und Bote der Schätze des Meeres … und seiner Gefahren. ","Einheit",[],["Freljord"],"GEWÖHNLICH"],"05FR015":["Entfesselte Geister","Gewähre Verbündeten überall +1|+1. Verursache dann 1 Schaden an ALLEM.","","„Ihr Ahnen, stärkt uns gegen die sich nähernde Kälte und treibt unsere Feinde mit Stürmen aus Eis und Feuer hinfort. Denn wir haben weder euch noch eure Ehre vergessen.“\n– Gebet der Düsterwolf-Schamanen","Zauber",[],["Freljord"],"SELTEN"],"05FR005":["Knochenorakel","Wenn ich Schaden überlebe, verursache 1 Schaden am gegnerischen Nexus.","","Nur wenige kennen die Zukunft so gut wie die Schamanen, die dem Elch der Knochen dienen. Noch weniger ertragen das Wissen um den bevorstehenden Tod derer, die nach diesen Weissagungen trachten.","Einheit",[],["Freljord"],"GEWÖHNLICH"],"05FR004":["Ausgefuchste Wanderin","Wenn ich beschworen werde, erschaffe 1 Haltungswechsel auf der Hand.","","„Eifrig und vorsichtig. Schnell und leise. Der Weg des Fuchses ist die Freude am Sehen, aber dabei nicht gesehen zu werden. Auf Reisen und im Krieg ehrt ein weiser Führer die, die dem Fuchsgeist folgen. Denn keine Schlacht lässt sich ohne Wegbereiter und Späher gewinnen.“\n– Narbenmutter Vrynna","Einheit",[],["Freljord"],"GEWÖHNLICH"],"05IO003":["Umherziehender Ältester","Ich koste 2 weniger für jede Einheit, die du in dieser Runde zurückgerufen hast.","","„Himon’she, es ist mir eine Ehre, mit dir zu reisen. Die anderen sagen, dass du unsagbar weise wärst. Wohin zieht es dich?“\n„Ach je, ich bin eigentlich nur dir gefolgt!“\n– Ahri und der umherziehende Älteste","Einheit",[],["Ionia"],"GEWÖHNLICH"],"05IO004":["Ahri","Angriff: Tausche mich beim ersten Angriffsschlag mit dem Verbündeten rechts von mir und rufe ihn dann zurück.","Du hast 5+ Einheiten zurückgerufen.","Sie suchte sich selbst in den Geheimnissen der anderen. Sie sah sich selbst durch die Augen so vieler Leute. Während sie sich dem Wald näherte, fragte sie sich, ob er auch nur eine weitere Linse sein würde – oder ob sie endlich einen Spiegel gefunden hatte.","Einheit",[],["Ionia"],"Champion"],"05IO023":["Bezaubern","Rufe einen Verbündeten zurück, um einen Gegner in dieser Runde verletzlich zu machen.","","„Erzähl mir ein Geheimnis.“\n– Ahri","Zauber",[],["Ionia"],"GEWÖHNLICH"],"05IO020":["Windsänger","Ausspielen: Rufe eine Einheit zurück.","","Das Chaos gibt den Schwächsten Klauen. Ein Wolf jagt seine Beute, wird aber von einem herabgefallenen Ast aufgehalten. Ein Falke stürzt vom Himmel herab und wird von einem Windstoß weggeweht. Wir sind der Ast. Wir sind der Windstoß.","Einheit",[],["Ionia"],"GEWÖHNLICH"],"05IO007":["Tausendschwänziger Sai’nen","Wenn ich beschworen werde, ziehe 2 und gib Verbündeten in dieser Runde +1|+1.","","Der Wald gibt seine Geheimnisse bereitwillig preis, aber nur wenige haben den Mut, ihn um etwas zu bitten.","Einheit",[],["Ionia"],"EPISCH"],"05IO021":["Setzling der Götterweide","Ausspielen: Rufe einen Verbündeten zurück, um eine vergängliche Kopie von ihm zu beschwören.\nCountdown 3: Beschwöre eine weitere vergängliche Kopie von ihm.","","Einst wuchs die Götterweide im Omikayalan. Was nun aus diesem Ort entspringt, kann stärker oder aber schwächer sein. Es zählt nur, dass es neu ist.","Wahrzeichen",[],["Ionia"],"SELTEN"],"05IO024":["Kinder des Waldes","Rufe einen Verbündeten zurück oder gib 8 Mana aus, um vergängliche Kopien der 3 stärksten Begleiter zu beschwören, die du in diesem Spiel zurückgerufen hast.","","Erinnerungen haben Reißzähne.","Zauber",[],["Ionia"],"EPISCH"],"05IO001":["Hüterin der Wälder","Wenn ich beschworen werde, gib mir in dieser Runde +1|+0 und Ungreifbar.","","„Es heißt, du redest nicht, um andere von der Bürde deines Wissens zu bewahren. Hmm … Ich wette, du hattest einfach nur die ständige Fragerei satt.“\n– Ahri","Einheit",[],["Ionia"],"GEWÖHNLICH"],"05IO025":["Majestätische Matriarchin","Wenn du in einer Runde zum ersten Mal einen Begleiter zurückrufst, beschwöre eine exakte vergängliche Kopie von ihm.","","Geheimnisse sind spannender als ihre Lösungen.","Einheit",[],["Ionia"],"SELTEN"],"05IO026":["Die Beklagte","Nexusschlag: Rufe mich zurück.","","Wer sich an der Jagd erfreut, muss auch innehalten und um die Gejagten trauern können.","Einheit",[],["Ionia"],"SELTEN"],"05IO006":["Sieben Leben","Beschwöre 1 Bewacher der Grenzen.","","Der Wald brauchte einen Bewacher. Er brauchte jemanden, der an seinen Grenzen für Jahre oder Jahrhunderte Wache stehen konnte, ohne sich fortzubewegen. Gai’sh meldete sich freiwillig und bewies prompt seine Hingabe mit einem zehn Jahre währenden Nickerchen.","Zauber",[],["Ionia"],"EPISCH"],"05IO002":["Umhang der Erinnerung","Wähle einen Verbündeten, der von gegnerischen Schnellzaubern, langsamen Zaubern oder Fertigkeiten (nur ein verbündetes Einzelziel) anvisiert wird. Halte sie auf.","","Ein Pfeil kennt weder die Absichten des Jägers, noch den Wert einer Beute.","Zauber",[],["Ionia"],"GEWÖHNLICH"],"05SH014":["Xerath","Wenn du ein verbündetes Wahrzeichen zerstörst, verursache 1 Schaden am schwächsten Gegner.","Du hast 4+ verbündete Wahrzeichen zerstört.","„Einst waren die beiden Freunde, doch die Zeit und ihre gegenseitige Zuneigung ließ sie zu Brüdern werden. Ohne Xerath an seiner Seite wäre Azir niemals dort, wo er heute ist.“\n– Schriftgelehrter Kah’nir, Geschichte des Heers der Aufgestiegenen","Einheit",["AUFGESTIEGEN"],["Shurima"],"Champion"],"05SH017":["Vorbotin des Magus","Wenn ich beschworen werde und du in diesem Spiel 4+ verbündete Wahrzeichen zerstört hast, gewähre deinen Champions überall +2|+2 und Überwältigen.","","Die Vorbotin breitete ihre Arme aus und blickte zur Sonne auf, die Shurima in ein blutrotes Licht tauchte. „Gelobt sei der aufgestiegene Magus“, stieß sie glückselig hervor und ihre Stimme hallte im Ring aus verfallenen Säulen wider. „Gelobt sei Xerath!“","Einheit",[],["Shurima"],"SELTEN"],"05SH011":["Hingebungsvoller Getreuer","Letzter Wunsch: Beschwöre 1 Sarkophag.","","Die wunderschönen Verzierungen des Grabs waren für die Verbannten und Toten nicht mehr als ein schwacher Trost.","Einheit",[],["Shurima"],"SELTEN"],"05SH022":["Wüstenduell","Gib einem Gegner in dieser Runde -2|-0. Ein Verbündeter und dieser Gegner schlagen sich gegenseitig.","","„Ein Reisender, der die Wüste nicht fürchtet, kennt sie nicht.“\n– Shurimanisches Sprichwort","Zauber",[],["Shurima"],"GEWÖHNLICH"],"05SH003":["Obelisk der Macht","Countdown 3 oder wenn ich beschworen werde oder du mich zerstörst: Gewähre dem stärksten Verbündeten +2|+0.","","Aus dem Sand erhoben sich funkensprühende und knisternde Säulen – konvertierte Orte der Macht, die Xeraths ohnehin schon mächtige Armee weiter verstärken würden.","Wahrzeichen",[],["Shurima"],"GEWÖHNLICH"],"05SH016":["Akolyth der Verheerung","Ausspielen: Zerstöre ein verbündetes Wahrzeichen, um verbündeten Akolythen der Verheerung überall +1|+1 zu gewähren.","","Alle Akolythen von Xerath tauschten einen Teil von sich gegen Macht ein, doch seine mächtigsten Anhänger waren kaum mehr als Hüllen, die sowohl als Verbindung als auch Machtquellen für die Energie ihres neuen Herrschers dienten.","Einheit",[],["Shurima"],"GEWÖHNLICH"],"05SH018":["Im Dienste der Verwüstung","Beschwöre 1 Stase-Statue, um darin alle verbündeten Einheiten und Wahrzeichen zu verwahren, die in dieser Runde gestorben sind oder zerstört wurden.","","Magische Energie verschwindet nicht. Sie wird umfunktioniert.","Zauber",[],["Shurima"],"EPISCH"],"05SH012":["Erhobener Altar","Countdown 3 oder wenn du mich zerstörst: Beschwöre 1 Dami’yin der Entfesselte.","","„An jedem Ort der Macht soll sich ein Obelisk erheben, durch den sich der aufgestiegene Magus die Macht unter dem Sand zunutze machen kann.“\n– Herold des Magus","Wahrzeichen",[],["Shurima"],"EPISCH"],"05SH020":["Konstrukt der Verwüstung","Erschaffe 1 Akolyth der Verheerung oder 1 Obelisk der Macht auf der Hand.","","„Ich werde Shurima nach meinem Ebenbild formen.“\n– Xerath","Zauber",[],["Shurima"],"GEWÖHNLICH"],"05SH015":["Sandseherin","Wenn ich beschworen werde, ziehe 1. Wenn du ein Wahrzeichen ziehst, wiederhole diesen Effekt.","","Der Horizont vor ihr war von Energie erfüllt. Wo andere nur Sand und Schlamm sahen, sah sie die Kraftadern – ein Gitter aus blendender Energie, das sie nur ergreifen musste.","Einheit",[],["Shurima"],"EPISCH"],"05SH004":["Entfesselte Energie","Gib einem Verbündeten in dieser Runde +2|+1, oder zerstöre ein verbündetes Wahrzeichen, um einem Verbündeten in dieser Runde +4|+2 zu geben.","","„Ich werde der Wüste ihre Macht entreißen und alle zerstören, die sich mir in den Weg stellen!“\n– Xerath","Zauber",[],["Shurima"],"GEWÖHNLICH"],"05SH002":["Vorläufer des Verfalls","Wenn du ein verbündetes Wahrzeichen zerstörst, gewähre mir +1|+1.","","Die Akolythen waren bereits sehr erfahren, bevor sie Xerath aufsuchten. Doch nachdem sie gelernt hatten, was er einst selbst lernte, waren sie unaufhaltbar.","Einheit",[],["Shurima"],"GEWÖHNLICH"],"05SH007":["Arkanes Ritual","Zerstöre ein verbündetes Wahrzeichen oder einen deiner Manasteine, um 4 Schaden an einer Einheit zu verursachen.","","„Ein kleines Opfer im Austausch für große Macht.“\n– Xerath","Zauber",[],["Shurima"],"SELTEN"],"05NX009":["Verlorene Seele","Wenn ich beschworen oder abgeworfen werde, erschaffe 1 Wiedergängerin der Zwillingsklinge auf der Hand.","","Die Demacianer krochen zu ihrem Schutzwall zurück, nur um dabei zuzusehen, wie der Tod selbst über ihre Mauern hereinbrach. Obwohl es ihnen gelang, einen Teil der grauen Legion zu töten, erwies sich die dunkle Welle des Krieges schnell als unaufhaltsam.","Einheit",[],["Noxus"],"EPISCH"],"05NX006":["Zurückgebrachter Grenadier","Wirf 1 Karte ab, um mich auszuspielen.\nWenn ich abgeworfen werde, beschwöre eine exakte Kopie von mir.","","„In unserer Mitte befindet sich eine Unregelmäßigkeit. Obwohl die meisten ihre Rückkehr ins Leben verabscheuen, scheint dieses Exemplar nicht nur sein Schicksal zu verstehen, sondern sich auch über die sich daraus ergebenden Gelegenheiten zu freuen. Faszinierend.“\n– Notizen von Dr. Esslanger","Einheit",[],["Noxus"],"GEWÖHNLICH"],"05NX005":["Uralter Kriegstreiber","Wenn ich abgeworfen werde, gewähre deinem stärksten Verbündeten +2|+0.","","Als die Macht von Fürstin Noradi wuchs, fragte sie sich, ob sich diese Macht auch in den Leichen der ältesten Grüften von Noxus manifestieren würde. In den Hüllen fand sie ein schwaches Flackern des Lebenslichts, aber in diesen matten Flammen tanzten immer noch die Schatten des Krieges.","Einheit",[],["Noxus"],"SELTEN"],"05NX001":["Sion","Wenn ich abgeworfen werde, gewähre deinem stärksten Verbündeten Überwältigen und lege mich in dein Deck.\nIch habe pro Karte, die du in diesem Spiel abgeworfen hast, +1|+0 (max. +7|+0).","Du hast 35+ Stärke abgeworfen oder beschworen.","Sion sah kurze Ausschnitte aus unklaren Erinnerungen. Legionen, die vor ihm standen. Auszeichnungen. Kronen. Krieg. Das Todesröcheln eines Königs. Das große Nichts. Blut. Jedoch verschwanden die Erinnerungen so schnell, wie sie gekommen waren – wie verblasste Schleifen im Wind.","Einheit",[],["Noxus"],"Champion"],"05NX003":["Salz und Stiche","Wirf zum Ausspielen 1 Karte ab.\nBeschwöre 1 Zurückgebrachter Grenadier und gib ihm in dieser Runde +2|+0.","","„Komm zurück, mein Kind …“\n– Dr. Esslanger, nachdenklicher Mediziner","Zauber",[],["Noxus"],"SELTEN"],"05NX015":["Gefallener Vergelter","Wenn ich beschworen werde, belege den schwächsten Gegner mit Abwehrunfähig.\nLetzter Wunsch: Erschaffe 1 Erweckter Vergelter auf der Hand.","","„Die ersten Minotauren, die ich wiederbelebte, waren gutmütige, nutzlose Wesen. Weder die Klänge des Krieges noch der drohende Tod konnten ihre Sinne anregen.“\n– Notizen von Dr. Esslanger","Einheit",[],["Noxus"],"SELTEN"],"05NX019":["Für den Ruhm!","Ruf: Ich koste 3 weniger. Beschwöre 2 Ruhmsuchende Trifarianerinnen.","","Jene, die nach Ruhm streben, werden vor nichts Halt machen, ihn zu erlangen.","Zauber",[],["Noxus"],"SELTEN"],"05NX013":["Gefallener Reiter","Wenn ich abgeworfen werde, erschaffe 1 Erweckter Reiter auf der Hand.","","„Die Brutalität des Basilisken ließ sich erst zügeln, nachdem wir die Rüstung des Reiters mit Schwarzschattenblättern eingerieben hatten. Die Pflanzen stammen genau wie diese Bestien aus dem Hinterland und haben nicht nur einen penetranten Geruch, sondern sind auch giftig.“\n– Notizen von Dr. Esslanger","Einheit",[],["Noxus"],"GEWÖHNLICH"],"05NX012":["Zügelloser Kriegsschrei","Wirf zum Ausspielen 1 Karte ab. Töte den schwächsten Gegner.","","„Verbündete, Gegner … Völlig egal.“\n– Sion","Zauber",[],["Noxus"],"GEWÖHNLICH"],"05NX014":["Waffen der Verlorenen","Verursache 3 Schaden an einer Einheit und beschwöre 1 Trifarianischer Schildbrecher.","","„Schildbrecher!“\n– Sion","Zauber",[],["Noxus"],"GEWÖHNLICH"],"05NX004":["Leibarzt","Ausspielen: Wirf 1 Karte ab, um eine Einheit zu ziehen.","","Dr. Esslanger war einst ein angesehener Mediziner im Ruhestand, der sich seinen Ruf durch jahrelange harte Arbeit verdient hatte. Doch erst als eine junge Adelige zu ihm gebracht wurde, deren Blut der Verrat schwarz gefärbt hatte, begann er, Noxus wahrhaftig zu dienen.","Einheit",[],["Noxus"],"GEWÖHNLICH"],"05NX016":["Die Herrin des Blutes","Wenn ein nicht-flüchtiger Verbündeter auf der Hand abgeworfen wird, erschaffe eine flüchtige Kopie von ihm auf der Hand.","","Fürstin Faris Noradi führte ihre graue Legion im Schutze der Dunkelheit aus der noxianischen Hauptstadt. Nach drei harten, blutigen Wochen näherte sich die Legion schließlich dem demacianischen Außenposten, den ihre Späher entdeckt hatten. Es war Zeit für eine Demonstration.","Einheit",[],["Noxus"],"EPISCH"],"05NX002":["Noble Rebellin","Gewähre mir +2|+1, sobald du in diesem Spiel 3+ Karten abgeworfen hast.","","„Was könnte einen vermeintlichen Verräter besser zur Loyalität zwingen als der Anblick eines ermordeten Verschwörers, der unter dem noxianischen Banner wieder zum Leben erweckt wurde? Sie werden alle dienen, auf die eine oder andere Art.“\n– Die Herrin des Blutes","Einheit",[],["Noxus"],"GEWÖHNLICH"],"05BW005":["Nami","Wenn du einen Zauber ausspielst, gewähre dem schwächsten anderen Verbündeten, der nicht bewegungsunfähig ist, +1|+0.","Du hast 5+ Zauber mit einer verbündeten Nami auf dem Spielfeld ausgespielt.","„Hast du dich verabschiedet, junge Gezeitenruferin?“ „Ja, Großmutter.“ „Hast du Angst?“ „… Ja, Großmutter.“ „Gut. Angst zu haben bedeutet, vorsichtig zu sein. Aber vertraue dir selbst, so, wie wir dir vertrauen. Geh jetzt. Und möge die Strömung dich leiten.“","Einheit",[],["Bilgewasser"],"Champion"],"05BW006":["Ebbe","Verursache 2 Schaden an einem zufälligen Gegner oder dem gegnerischen Nexus und erschaffe 1 Flut auf der Hand.","","„Achte auf die Laune der Gezeiten …“\n– Nami","Zauber",["ELEMENTAR"],["Bilgewasser"],"GEWÖHNLICH"],"05BW002":["Reisender Sandabenteurer","","","„Klar, ein paar von denen jagen uns, aber die jagen alles. Aber die meisten Landwandler, die ich kennengelernt habe, wollten auch nur im großen blauen Nass ihren Spaß haben, genau wie wir. Wir sind uns doch alle ähnlich.“","Einheit",[],["Bilgewasser"],"GEWÖHNLICH"],"05BW008":["Bewacher des Abgrunds","Wenn du einen Zauber ausspielst, gib mir in dieser Runde +2|+0.","","„Viele aus unserem Stamm finden Loto etwas beunruhigend. Sie sehen nur einen unermüdlichen Kämpfer und seinen abwesenden, sorgenvollen Blick. Aber ich weiß, was er wirklich in seinem Herzen trägt – Angst, er wäre nicht stark genug, uns zu retten … und unvergleichliche Liebe.“\n– Tama, Sängerin der Marai","Einheit",[],["Bilgewasser"],"GEWÖHNLICH"],"05BW011":["Flottenadmiralin Shelly","Wenn du in einer Runde 2 Zauber ausspielst, gewähre anderen Verbündeten +1|+1.","","„PAFF GUT AUF, FOLDAT. ICH HAB ÜBER DREIHUNDERT FEINDE AUFM GEWISSEN UND BIN DER BEFTE ADMIRAL IN DER MARINE. WENN ICH FAGE, DU FOLLST FWIMMEN, DANN FWIMMST DU, VERFTANDEN? OKAY DANKE!“","Einheit",[],["Bilgewasser"],"EPISCH"],"05BW003":["Flutwelle","Verursache 1 Schaden an zwei unterschiedlichen, zufällig anvisierten Gegnern und erschaffe 1 Hereinbrechende Welle in deinem Deck.","","„Ozeane, kommt herbei!“\n– Nami","Zauber",["ELEMENTAR"],["Bilgewasser"],"SELTEN"],"05BW004":["Avatar der Gezeiten","Wenn du einen Manastein erhalten würdest, fülle stattdessen dein Zaubermana auf.\nWenn du einen Zauber ausspielst, erschaffe einen zufälligen Zauber auf der Hand, der 3 oder weniger kostet, und gewähre ihm Flüchtig.","","Für die Marai ist der Leo’lei ein Vorbote großer Veränderungen. Man sagt, dass jeder Schlag seiner anmutigen Flügel den Gezeitenstrom beeinflusst.","Einheit",[],["Bilgewasser"],"EPISCH"],"05BW001":["Beschützerin der Marai","Wenn ich beschworen werde, beschwöre einen zufälligen Begleiter mit 1 Kosten.","","Die Marai haben nur selten das Verlangen, ihre Heimat zu verlassen. Doch Ai’las Herz war seit ihrer Geburt von Neugier erfüllt – und obwohl ihre Pflicht sie an ihren Stamm bindet, träumt sie immerzu von dem Tag, an dem sie wirklich frei sein kann.","Einheit",[],["Bilgewasser"],"SELTEN"],"05BW010":["Stammmutter der Marai","Wenn ich beschworen werde, erschaffe 5 zufällige Zauber mit 6+ Kosten in deinem Deck und senke ihre Kosten auf 3.","","Die Heimat der Marai wird vom himmlischen Licht eines Mondsteins beschützt. Alle hundert Jahre beginnt sein Licht zu schwinden und ein neuer Gezeitenrufer wird ausgesendet, einen anderen zu finden – denn ohne ihn würde das Volk der Marai in Finsternis versinken und den Schrecken zum Opfer fallen, die in den Tiefen lauern.","Einheit",[],["Bilgewasser"],"GEWÖHNLICH"],"05BW013":["Sängerin der Marai","Wenn ich beschworen werde und du in dieser Runde einen Zauber ausgespielt hast, gewähre mir Ungreifbar.","","„Der Ozean weiß, zurück kommt die Welle,\nvertraut der Ebbe, der Flut und der Quelle.\nHier trifft die Welle mit Wut auf den Strand, \nder Ozean erstürmt das erzitternde Land.“\n– Vers aus ‚Serenade für die Gezeitenruferin‘","Einheit",[],["Bilgewasser"],"SELTEN"],"05PZ015":["Bikerin der Gerechtigkeit","Immer wenn dein Gegner eine Karte zieht, verstecke 1 Blitzbombenfalle in den obersten 8 Karten des gegnerischen Decks.","","„Die Ermittlerin wurde dabei beobachtet, wie sie eine Verdächtige verfolgte und sie mit hoher Geschwindigkeit in ihre Falle trieb. Nach der Festnahme zeigte sich die Ermittlerin selbst wegen Geschwindigkeitsübertretung an und bezahlte anschließend die Strafe. Sie verkündete (auf dramatische Art), dass ‚die Gerechtigkeit keine Einbahnstraße sei‘.“\n– Auszug aus dem Bericht eines Wachtmeisters","Einheit",[],["Piltover & Zhaun"],"EPISCH"],"05PZ012":["Archivarin der Wache","Ausspielen: Wähle einen Zauber aus den obersten 5 Karten deines Decks und erschaffe eine exakte flüchtige Kopie davon auf der Hand. Lege dann diese 5 Karten zurück in dein Deck.","","Ohne Anhaltspunkte sind Kommissare nutzlos. Die Aufgabe eines Archivars besteht darin, alle Informationen zu sammeln und Möglichkeiten zu erschaffen, die es zuvor nicht gab.","Einheit",[],["Piltover & Zhaun"],"SELTEN"],"05PZ026":["Fließband","Beschwöre 2 Arbeiter der Schmiede.","","„Schichtwechsel!“\n– Vorarbeiterin der Schmiede","Zauber",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"05PZ019":["Großfahndung","Wähle einen Spieler, der seine günstigste Karte abwirft und 3 zieht.","","„Alles hat seinen Preis.“\n– Corina Veraza","Zauber",[],["Piltover & Zhaun"],"EPISCH"],"05PZ031":["Albus Ferros","Wenn ich beschworen werde, ziehe Jayce. Angriff: Verursache 3 Schaden am gegnerischen Nexus. Erhöhe ihn um 1 pro ausgespielten Zauber mit 6+ Kosten in diesem Spiel.","","„Der großzügige Albus Ferros hat sich einmal mehr ins Rampenlicht gedrängt, indem er in einem dramatischen Wettstreit die Klans Cadwalder und Giopara überbietet und sich das Recht gesichert hat, die Hextor-Forschung von Jayce zu finanzieren. ‚Ein guter Tag für Ferros ist ein guter Tag für Piltover‘, wie man so sagt, und gestern war in der Tat ein ausgezeichneter Tag für den Klan Ferros!“\n– Auszug aus einer Sponsorenanzeige in der Piltover-Tageszeitung","Einheit",[],["Piltover & Zhaun"],"EPISCH"],"05PZ027":["Schockstoß","Verursache 3 Schaden an einem Gegner oder dem gegnerischen Nexus und 3 an einem anderen.","","„Feuer!“\n– Jayce","Zauber",[],["Piltover & Zhaun"],"SELTEN"],"05PZ022":["Jayce","Ausspielen: Gewähre mir Direktangriff oder Herausforderer.","Du hast zwei Zauber mit 6+ Kosten ausgespielt. Wenn ich eine Stufe aufsteige, erschaffe ein Beschleunigungstor auf der Hand.","„Rosa, wie du weißt, könnte diese leistungsformende Technologie die Welt verändern.“\n„Wahrhaft bahnbrechend, Jayce. Wie diese Nebeninhiberatoren ineinandergreifen. Es ist atemberaubend.“\n„Wie wahr, wie wahr. Das hat sich alles Axel ausgedacht! Nicht wahr, mein Bester?“\n„Ach, du kennst mich doch. Ich prahle nicht gerne.“","Einheit",[],["Piltover & Zhaun"],"Champion"],"05PZ017":["Grubendünste","Verursache 2 Schaden an einer Einheit. Falls du in dieser Runde deiner Hand 2+ Karten hinzugefügt hast, verursache stattdessen 3 Schaden.","","„Lass sie lieber eine Minute auslüften. Grünschnäbel ertragen den Geruch nicht. Aber lass mich dir eines sagen … Sobald du dich daran gewöhnt hast, gibt es nichts Vergleichliches!“\n– Poffpilz-Händler","Zauber",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"05PZ013":["Piltover-Friedensstifter","Verursache 2 Schaden an einer Einheit und verstecke 2 Blitzbombenfallen in den obersten 8 Karten des gegnerischen Decks.","","„Hier ist MEINE Visitenkarte.“\n– Caitlyn","Zauber",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"05PZ020":["Hinterhalt","Gib einem Verbündeten in dieser Runde +2|+0. Falls du in dieser Runde deiner Hand 2+ Karten hinzugefügt hast, gib ihm in dieser Runde Ungreifbar.","","„Wir bewegen uns im Schutz der Rauchschleudern und umstellen den Ort …“\n– Caitlyn","Zauber",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"05PZ024":["Ferros-Finanzier","Ausspielen: Manifestiere einen Zauber mit 6+ Kosten aus deinen Regionen.","","„Das einzig Gute an der Finanzierung durch den Ferros-Klan ist, dass ich mit Reggie zusammenarbeiten kann. Der Mann ist nicht nur unglaublich kompetent, er ist auch ein echt klasse Typ.“\n– Auszug aus Jayce’ Tagebuch","Einheit",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"05PZ010":["Schlagkräftige Informationen","Verstecke 2 Blitzbombenfallen in den obersten 8 Karten des gegnerischen Decks.\nZiehe 1.","","„Auf mein Signal.“\n– Caitlyn","Zauber",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"05PZ014":["Corina, Verbrechergenie","Ausspielen: Verstecke 5 Blitzbombenfallen in den obersten 5 Karten des gegnerischen Decks oder aktiviere die Effekte aller Fallen in den obersten 5 Karten des gegnerischen Decks.","","Corina lächelte, als Piltovers Wachtmeister die Tür eintraten und ihre wertvollen Blumen zertrampelten, die daraufhin giftige Pollen freisetzten. Alles verlief genau nach Plan.","Einheit",[],["Piltover & Zhaun"],"EPISCH"],"05PZ002":["Insiderwissen","ALLE Spieler ziehen 2.","","„Das ist ein beliebter Fall. Gerade eben erst war ein Kerl hier, der ihn sich ebenfalls angesehen hat. Viel Spaß damit!“\n– Archivarin der Wache","Zauber",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"05PZ021":["Die Schmiede von morgen","Wenn ich beschworen werde, beschwöre 1 Arbeiter der Schmiede. Wenn du einen Zauber mit 6+ Kosten ausspielst, zerstöre mich und fülle dein Zaubermana wieder auf.","","Wenn Piltover von Erfindungen angetrieben wird, dann sind seine Schmieden der Motor.","Wahrzeichen",[],["Piltover & Zhaun"],"SELTEN"],"05PZ025":["Vorarbeiterin der Schmiede","Schlag: Fülle 1 Zaubermana wieder auf.","","„Zwei Dinge sind nötig, um eine Idee vom Papier in die Realität umzusetzen. Geld ist die eine Hälfte der Gleichung und die andere Hälfte ist eine gute Schmiede. Damit sind aber nicht nur gute Werkzeuge und Anlagen in der Schmiede gemeint. Wenn der Vorarbeiter keinen Plan von irgendetwas hat, dann bleibt deine Idee auf dem Papier.“\n– Jayce","Einheit",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"05PZ006":["Caitlyn","Schlag: Verstecke 2 Blitzbombenfallen in den obersten 8 Karten des gegnerischen Decks.","5+ deiner Fallen wurden aktiviert.","Caitlyn war schon immer eine hartnäckige und gründliche Ermittlerin – so konnte sie sich in den Reihen von Piltovers Vollstreckern schnell nach oben arbeiten. Doch als der Fall einer gewissen „C“ aufkam, an dem sich zahlreiche andere Vollstrecker die Zähne ausgebissen hatten, schien es beinahe so, als hätte Caitlyn endlich ihren Meister gefunden. Beinahe.","Einheit",[],["Piltover & Zhaun"],"Champion"],"05PZ004":["Polizeitrupp","Wenn ich beschworen werde, erschaffe 1 Großfahndung auf der Hand.","","Vom leisen Entladen auf der Straße bis hin zur Vorbereitung des Rammbocks war alles im Handumdrehen bereit. Es ging nur noch darum, Caitlyns Signal abzuwarten.","Einheit",[],["Piltover & Zhaun"],"SELTEN"],"05PZ009":["Verdeckter Polizeiagent","Nexusschlag: Verstecke 2 Blitzbombenfallen in den obersten 8 Karten des gegnerischen Decks.","","Zayne Asako musste wie alle Kinder in den brutalen und düsteren Unterstraßen von Zhaun schnell erwachsen werden. Nachdem er seinen Bruder durch die sinnlose Bandenkriminalität verlor, schloss er sich Piltovers Vollstreckern an – in der Hoffnung, dass Vernunft und Ordnung seine Heimat endlich sicher machen würden.","Einheit",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"05PZ016":["Kurzer Prozess","Lege einen gegnerischen Begleiter in das gegnerische Deck, dann zieht dein Gegner 1.","","Piltover ist die Heimat einiger der größten Genies in Runeterra. Die Gefängnisse von Piltover sind ebenfalls die Heimat einiger der größten Genies in Runeterra.","Zauber",[],["Piltover & Zhaun"],"SELTEN"],"05PZ030":["Hextech-Anomalie","Wenn du mich ziehst oder auf der Hand erschaffst oder bei Rundenbeginn: Während ich auf der Hand bin, verwandle mich in einen zufälligen Zauber mit 6+ Kosten.","","„… die Umwandlung von Hextech in einen stabilen Zustand war die größte Hürde, die ich überwinden musste. In den meisten Nächten schien es, als hätten sich die Kristalle und das Hexit gegen mich verschworen. Erst nach umfangreichen Tests und Versuchen konnte ich die Komponenten dazu bringen, harmonisch zusammenzuarbeiten …“\n– Auszug aus Jayce’ Tagebuch","Zauber",[],["Piltover & Zhaun"],"SELTEN"],"05PZ028":["Ferros-Himmelskreuzer","Gewähre mir +2|+0, sobald du in diesem Spiel einen Zauber mit 6+ Kosten ausgespielt hast.","","„Die Leute in der Stadt verehren die ‚Intelligenz‘. Aber was bringt dir der größte Verstand ohne die Mittel, ihn zum Ausdruck zu bringen? Nein. Ich werde Piltover wahre Größe zeigen. Ich werde über sie hinauswachsen. Ich werde die Sonne verdunkeln. Und das alles wird meinen Namen tragen.“\n– Albus Ferros","Einheit",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"05PZ038":["Raketensalve","Verursache 4 Schaden an einem Gegner und 1 Schaden an allen anderen Gegnern.","","„Sie sollen nach oben fliegen, nicht IN ALLE RICHTUNGEN! Du liebe Güte!“\n– Heimerdinger","Zauber",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"05PZ035":["Miefender Wusel","Letzter Wunsch: Erschaffe eine Kopie von mir im gegnerischen Deck, auf der sich 2 Giftige Poffpilze befinden.","","Der Gestank eines Wusels während der Poffpilz-Hochsaison ist mit nichts zu vergleichen. Stell dir einen offenen Abwasserkanal voller alter Fische und fauler Eier vor – und das ist erst der Anfang.","Einheit",[],["Piltover & Zhaun"],"SELTEN"],"05PZ029":["Hextech-Helfer","Gewähre Tech-Verbündeten überall +1|+0, sobald du in diesem Spiel einen Zauber mit 6+ Kosten ausgespielt hast.","","Der Hextech-Helfer wurde eigentlich entwickelt, um Rohstoffe durch Piltover zu transportieren, aber im Laufe der Zeit haben die Bewohner ihn richtiggehend ins Herz geschlossen. Jayce’ Schmiedemannschaft gab ihm den Spitznamen „Nugget“, ein Lord aus Piltover spendete ihm angeblich einen Hut und vorbeikommende Kinder schmücken ihn immer wieder mit allen möglichen Sachen, die sie gerade zur Hand haben.","Einheit",["TECHNOLOGIE"],["Piltover & Zhaun"],"SELTEN"],"05SI014":["Archiv der Reue","Rundenbeginn: Erschaffe auf der Hand eine flüchtige Kopie eines nicht-flüchtigen Zaubers, den du in der letzten Runde ausgespielt hast.","","Die Gesegneten Inseln vergessen. Die Schatteninseln erinnern sich. Die Schatteninseln vergessen. Die Gesegneten Inseln erinnern sich.","Wahrzeichen",[],["Schatteninseln"],"EPISCH"],"05SI013":["Nebelwärter","Wenn du in einer Runde zum ersten Mal eine Einheit mit einem Zauber tötest, beschwöre 1 vergänglichen Nebelgeist.","","Der schwarze Nebel hält seine Opfer in endlosen Kreisläufen aus selbstauferlegten Qualen gefangen. Tek und Kana nutzen die Nebelfänger, um den Seelen die Möglichkeit zu geben, sich selbst aus diesen Kreisläufen zu befreien.\n","Einheit",[],["Schatteninseln"],"SELTEN"],"05SI009":["Senna","Wenn ich beschworen werde oder angreife: Erschaffe 1 Finsternis auf der Hand, wenn du keine hast. Das Tempo deiner Schadens- und Killzauber ist erhöht auf schnell.","Ich habe gesehen, wie du 3+ Einheiten mit Zaubern getötet hast oder wie ein verbündeter Lucian gestorben ist.","„Ein Wächter zu sein bedeutet, zu kämpfen. Sich selbst oder seine Liebsten zu verlieren. Doch es bedeutet noch mehr. Es bedeutet, zu leben. Für sich selbst … und für seine Liebsten.“","Einheit",[],["Schatteninseln"],"Champion"],"05SI016":["Schattendämmerung","Töte eine Einheit und gib allen Gegnern in dieser Runde -2|-0.","","„Kein Schatten ohne Licht. Kein Tod ohne das Leben.“\n– Senna","Zauber",[],["Schatteninseln"],"GEWÖHNLICH"],"05SI004":["Hüter auf den Inseln","Wenn du in einer Runde zum ersten Mal eine Einheit mit einem Zauber tötest, verursache 2 Schaden am gegnerischen Nexus.","","„Nichts ist treuer als ein Hund.“\n– Eine Weisheit, die jede Seele kennt","Einheit",[],["Schatteninseln"],"SELTEN"],"05SI012":["Wächterin der Solari","Wenn ich beschworen werde, erschaffe 1 Finsternis auf der Hand, wenn du keine hast.","","„Ich kann die Sonne nicht mehr spüren. Aber ich habe meine Erinnerungen an sie – und das ist genug.“","Einheit",[],["Schatteninseln"],"GEWÖHNLICH"],"05SI008":["Wächterin der Ixtali","Wenn ich beschworen werde, erschaffe 1 Finsternis auf der Hand, wenn du keine hast. Wenn du in dieser Runde deine nächste Finsternis ausspielst, kopiere sie und sie visiert den gegnerischen Nexus an.","","„Senna, du hast mich gefragt, warum ich mich an diesem Kampf beteilige. Der Nebel hat mir nichts genommen und bedroht auch meine Heimat nicht. Er existiert, obwohl er nicht existieren sollte. Ich will wissen, warum. Muss ich denn etwas empfinden, um mich deinem Zweck anschließen zu können?“","Einheit",[],["Schatteninseln"],"SELTEN"],"05SI003":["Durchdringende Finsternis","Entziehe einer Einheit 5.","","„Das Leben zieht den Tod an.“\n– Senna","Zauber",[],["Schatteninseln"],"GEWÖHNLICH"],"05SI010":["Dess & Ada","Wenn ich beschworen werde, erschaffe 1 Finsternis auf der Hand, wenn du keine hast. Deine nächste Finsternis in dieser Runde kostet 0 und erhält „Ich verursache Schaden an allen gegnerischen Zielen“.","","„Noch ein Albtraum?“\n„So schlecht war er nicht. Du bist nicht vorgekommen.“\n„Idiotin. Was war der schlechte Teil?“\n„Du bist nicht vorgekommen.“","Einheit",[],["Schatteninseln"],"EPISCH"],"05SI011":["Aufstrebende Wächterin","Wenn du zum ersten Mal eine Einheit mit einem Zauber tötest, gewähre mir +2|+1.","","Was der Nebel wohl sieht, wenn er Maeve erblickt? Überschwänglichkeit, Selbstsicherheit, unbändigen Optimismus? Sein Verlangen, diese herausfordernde Flamme zum Erlöschen zu bringen, muss grenzenlos sein. Denn was könnte der Tod mehr fürchten als das Leben?","Einheit",[],["Schatteninseln"],"GEWÖHNLICH"],"05SI015":["Wächter der Buhru","Wenn du zum ersten Mal eine Einheit mit einem Zauber tötest, gewähre mir +2|+1.","","Die Philosophien der Buhru und der Wächter stimmen in einem entscheidenden Punkt überein: Alles muss enden und manche Dinge müssen beendet werden.","Einheit",[],["Schatteninseln"],"GEWÖHNLICH"],"05MT004":["Camphor, der Zweifel","Wenn ich beschworen werde und du Verbündete in 4 verschiedenen Runden anvisiert hast, gewähre mir Zauberschild, Überwältigen und Herausforderer.","","Seit Jahrhunderten sucht die Dämonin Camphor das Land Targon heim und raubte ihren Opfern genau die Stärken, die sie ausmachten. Den Mächtigen nahm sie ihre Stärke, den Weisen ihre Weisheit. Doch sie hatte kein Interesse an diesen Gaben. Vielmehr labte sie sich am Leid, den Zweifeln und dem Elend, das sie damit auslöste. Camphor war ein Monster, wie es im Buche steht.","Einheit",[],["Targon"],"EPISCH"],"05MT006":["Verwundete Weißflamme","","","„Targonier brauchen keine weiteren Beweise für die Grausamkeit der Götter. Seht euch nur an, was sie uns angetan haben! Seht euch an, was sie unseren geliebten Kameraden angetan haben!“\n– Pantheon","Einheit",["DRACHE"],["Targon"],"SELTEN"],"05MT008":["Schildsprung","Gewähre einem Verbündeten +1|+1 und betäube einen Gegner.","","Pantheon war geübt im Kriegshandwerk wie kein Zweiter. Nach zahllosen Kämpfen wusste er, dass seine Gegner stets auf seinen Speer und nur selten auf seinen Schild achten würden.","Zauber",[],["Targon"],"SELTEN"],"05MT014":["Himmlisches Wunder","Betäube 2 Gegner.","","„Der Nachthimmel von Targon ist wundersam und voller unvorstellbarer Schönheit. Nur zu leicht kann man sich beim Betrachten dieser Weite verlieren, unwissend, wie weit sich die Sterne erstrecken und welche Wesen auf einen zurückblicken könnten …“\n– Kletterer aus Targon","Zauber",[],["Targon"],"GEWÖHNLICH"],"05MT003":["Pantheon","","Du hast Verbündete in 5+ verschiedenen Runden anvisiert.","Hier steht Atreus, dessen Freiheit von genau den Aspekten genommen wurde, die er so sehr verehrte. Hier steht die Glut des Krieges, die Atreus Geschenke gemacht hat, die nur die wenigsten Sterblichen verstehen können. Hier steht ein Mann, der bereit ist, für das zu kämpfen und zu sterben, was er so sehr verehrt.","Einheit",[],["Targon"],"Champion"],"05MT013":["Iula","Ausspielen: Gewähre einem Verbündeten Zauberschild oder Überwältigen. Wenn nicht, gewähre es mir.","","Iula erinnert sich noch immer an die tiefe Trauer, die sie nach dem Tod ihres Ehemanns verspürte. Als Pantheon zu ihr kam und sie fragte, ob sie ihm dabei helfen würde, die Kreatur zu vernichten, die sich an genau diesem Leid ergötzte, antwortete sie rasch und bestimmt.","Einheit",[],["Targon"],"GEWÖHNLICH"],"05MT009":["Bande der Schlacht","Gewähre 2 Verbündeten +2|+2.","","Der Kampf gegen die Götter schien zwecklos zu sein, doch durch all die Narben und all die Schreie lernten die wenigen Mutigen Lektionen. Die Götter dachten immer nur an sich selbst und hatten die Bedeutung von Kameradschaft vergessen. Und genau das sollte ihre Waffe und ihre Rüstung sein.","Zauber",[],["Targon"],"GEWÖHNLICH"],"05MT010":["Erblindete Mystikerin","Ausspielen: Gewähre einem Verbündeten +1|+1 und lasse einen gegnerischen Begleiter verstummen.","","Eshiyme war einst ein angesehenes Orakel, das ihre Visionen einsetzte, um Menschen in Not zu helfen. Doch Camphor stahl ihre Gabe und wollte sich an ihrer unvermeidlichen Pein laben. Die Dämonin hatte allerdings die tapfere Eshiyme gewaltig unterschätzt.","Einheit",[],["Targon"],"GEWÖHNLICH"],"05MT002":["Wir halten zusammen","Gib 2 Verbündeten in dieser Runde +1|+2.","","„In den Banden unserer Kameradschaft finden wir unsere Stärke.“\n– Pantheon","Zauber",[],["Targon"],"SELTEN"],"05MT012":["Befreiter Koloss","Wenn ich beschworen werde oder angreife: Erschaffe 1 Juwel auf der Hand.","","Die Kolosse sind uralte und hoch verehrte Beschützer der heiligsten Stätten Targons. Ihnen Leid zuzufügen ist eine direkte Beleidigung des Berges selbst. Sie zu foltern ist ein Verbrechen, das kein Targonier verzeihen kann.","Einheit",[],["Targon"],"GEWÖHNLICH"],"05MT011":["Gegen alle Erwartungen","Wenn dein Gegner mehr Einheiten als du hat, gewähre einem Verbündeten +1|+1 für jede zusätzliche gegnerische Einheit.","","Diese tapferen Gesellen wussten, dass sie sich auf einen Kampf mit Wesen von unbegreiflicher Stärke eingelassen hatten. Sie wussten, dass ihnen der Tod gewiss war. Aber trotzdem nahmen sie den Kampf an.","Zauber",[],["Targon"],"EPISCH"],"05MT005":["Sagensucher","","","Tor spürte, wie das Leben mit jedem Herzschlag aus ihm wich. Doch in dieser bedrückenden und lauernden Dunkelheit, in der er sich auf seinen Tod vorbereiten sollte, fand er stattdessen einen Sinn. Er würde sich dem Tod nicht nur bereitwillig stellen, sondern auch die Dämonen mit zu ihm nehmen, die seinem Leben so frühzeitig ein Ende gesetzt hatten. Seither erinnert man sich so an ihn. Seither ist das Tors Sage.","Einheit",[],["Targon"],"GEWÖHNLICH"],"05DE003":["Gorlith der Unbezwingbare","Ausspielen: Tausche mein Leben mit dem Leben deines Nexus.\nIch kann nicht von Gegnern abgewehrt werden, die weniger Leben als ich haben.","","„Ein ehrenhafter Tribut an die Verstorbenen, doch nie Vergessenen: Wenn die Demacianer sehen, wie die Sonnenstrahlen von ihm reflektiert werden, werden sie von Hoffnung erfüllt, und der unbeugsame Geist, der zu seinem Bau geführt hat, wird durch ihn weiterleben.“ \n– Plakette in der Arbeitsstätte der Durand","Einheit",[],["Demacia"],"EPISCH"],"05DE009":["Galio","Wenn ich beschworen werde, gewähre anderen Verbündeten +0|+3.","Rundenende: Verbündete haben 25+ Gesamtleben.","Viele Jahre nach seiner Erschaffung schlummerte Galio empfindungslos und bewusstlos. Erst als er durch Magie zum Leben erweckt wurde, erlebte er das berauschende Gefühl des Kampfes und wusste, dass er am Leben war. Von nun an vermisste er diese wundervollen Empfindungen schmerzlich, wenn er sich schlafen legen musste.","Einheit",[],["Demacia"],"Champion"],"05DE020":["Schild von Durand","Gewähre einem Verbündeten +0|+3. Gewähre ihm beim nächsten Rundenbeginn +0|+2.","","Schon der bloße Anblick Galios reicht aus, um die mutigen Herzen der Demacianer zu inspirieren.","Zauber",[],["Demacia"],"SELTEN"],"05DE021":["Macht der Vorhut","Verbrauche zum Ausspielen dein gesamtes Mana. Beschwöre 1 Unerschrockene Vorhut und erhöhe ihre Werte auf diesen Betrag. Wenn 9+ Mana ausgegeben wurde, gewähre anderen verbündeten Eliteeinheiten +2|+2.","","Wenn alle Hoffnung verloren scheint, setzen die Soldaten von Demacia auf die Vorhut.","Zauber",[],["Demacia"],"EPISCH"],"05DE017":["Winde des Krieges","Heile einen Verbündeten vollständig. Dann schlagen sich der Verbündete und ein Gegner gegenseitig.","","„Dann machen wir weiter!“\n– Galio","Zauber",[],["Demacia"],"SELTEN"],"05DE010":["Bildhauerin der Durand","Wenn du einen anderen Verbündeten beschwörst, gewähre ihm +0|+1.","","„Dem ungeübten Auge mag das entgehen, aber die großartigste Arbeit eines Künstlers besteht im allerkleinsten Feinschliff.“","Einheit",[],["Demacia"],"GEWÖHNLICH"],"05DE013":["Petrizit-Hirsch","Unterstützung: Ich erleide in dieser Runde sämtlichen Schaden meines unterstützten Verbündeten.","","Der Waldhüterin auf ihrem Hirsch folgte ein Petrizit-Wächter, der die Kreatur, der er nachempfunden war, um Größenordnungen überragte.","Einheit",[],["Demacia"],"EPISCH"],"05DE015":["Bergdrache","Zorn gewährt mir +0|+2 statt +1|+1.","","Trotz ihres Aussehens geraten die Bergdrachen nur schwerlich in Rage. Ihre stoische Ruhe vor den anderen Bergwesen macht sie zu den natürlichen Beschützern dieser sonst sehr angreifbaren Gruppe.","Einheit",["DRACHE"],["Demacia"],"EPISCH"],"05DE019":["Architekt der Durand","Unterstützung: Ich gebe meinem unterstützten Verbündeten in dieser Runde +0|+2 und Formidabel.","","„Die Waldhüterin Ulmenherz hat uns schlimme Neuigkeiten überbracht“, sagte der Architekt ruhig und konzentrierte sich darauf, die Pergamentrollen zusammenzurollen, um das Zittern seiner Hände zu verbergen. Er drehte sich zu den wartenden Bildhauern um und nickte ihnen zu. „Es scheint, die Zeit ist gekommen, dass die ungesehenen Beschützer Demacias aus ihren Verstecken hervorkommen.“","Einheit",[],["Demacia"],"SELTEN"],"05DE014":["Meisterschülerin der Durand","Ausspielen: Gewähre einem Verbündeten +0|+1 und Robust.","","Shireen schaute beim Geräusch des sich nähernden Hufgetrappels von ihrer Arbeit auf. Die Eile der Waldhüterin sorgte bei ihr für ein mulmiges Gefühl, weckte aber auch ihre Neugier. Sie bat ihren Petrizit-Vogel, sich in die Lüfte zu erheben und der Waldhüterin zu folgen.","Einheit",[],["Demacia"],"GEWÖHNLICH"],"05DE012":["Petrizit-Breitschwinge","Wenn du einen anderen Verbündeten beschwörst, gewähre mir Herausforderer.","","Als die Breitschwinge über sie hinwegfegte, fingen die erschöpften demacianischen Soldaten an zu jubeln. Dieses majestätische Geschöpf verlieh ihnen neue Kraft.","Einheit",[],["Demacia"],"SELTEN"],"05DE018":["Petrizit-Hund","","","„Es ist immer wieder schön, mit anzusehen, wie sie zum Leben erwachen. Man vergisst leicht, wie unterschiedlich sie doch sind. Ihre Persönlichkeiten sind Spiegel ihres Schöpfers.“\n– Bildhauerin der Durand","Einheit",[],["Demacia"],"GEWÖHNLICH"],"06NX024":["Fürst Wildmähne","Ausspielen: Verursache 2 Schaden an einem Gegner.\nDeine Schnellzauber, langsamen Zauber und Fertigkeiten haben „Wenn ich Schaden an einem betäubten oder verletzten Gegner verursache, stirbt er“.","","„Akt Zwei: Ein doppelzüngiger Fürst, der kaum mehr besitzt als einen geraubten Kashuri-Handschuh, verzaubert seine ionischen Zuschauer. Seine Maske ist allerdings wenig ausgefeilt und leicht zu durchschauen. Er bettelt um sein Leben, schiebt Unwissenheit vor. Die eiserne Hand, mit der er herrschen wollte, ist leer.“","Einheit",[],["Noxus"],"SELTEN"],"06NX033":["Taktische Ausführung","Betäube 2 Gegner oder gib 6 Mana aus, um einen General der Legion zu beschwören.","","Die richtige Einsatzplanung ist die erste große Entscheidung vor jeder Schlacht. Ein guter Kommandant weiß, der Schlüssel zum Sieg ist …","Zauber",[],["Noxus"],"SELTEN"],"06NX012":["Annie","Angriff: Ich verursache 2 Schaden an meiner Abwehr. Wenn sie tot oder weg ist, verursache ich stattdessen 2 Schaden am gegnerischen Nexus.","Ich habe gesehen, wie du 6 Schnellzauber, langsame Zauber oder Fertigkeiten ausgespielt hast. Wenn ich eine Stufe aufsteige, erschaffe Tibbers auf der Hand.","Vor über einem Jahrzehnt entkam Amoline Kiosar mit einem unschätzbar wertvollen und strahlenden Schatz aus dem Rabendorn-Konservatorium. Die Häscher von Rabendorn haben seitdem jeden Winkel des Reichs nach ihr abgesucht, aber kein einziges Gerücht über ihren möglichen Aufenthaltsort erwies sich als wahr. Viele Jahre später kam das Gerücht von einem verirrten, zornentbrannten Mädchen hoch oben in den nördlichen Eisenstachel-Bergen auf und Fynn Retrick packte widerwillig seine Sachen, um ihm auf den Grund zu gehen. Er ging davon aus, dass er nichts finden würde. Wie falsch er damit liegen sollte.","Einheit",[],["Noxus"],"Champion"],"06NX029":["Die graue Apotheke","Wenn ein Verbündeter mit 5+ Stärke stirbt, erschaffe einen zufälligen Begleiter mit 5+ Stärke auf der Hand.","","„Heute ertappte ich mich dabei, wie ich an meine kleine Klinik in Heidenhöhe dachte und über all die Jahre nachgrübelte, die ich mit dem Versuch der Enträtselung der Geheimnisse der Physiologie verbracht habe. Jahre! Ich bin nun schon seit einigen Monaten bei Fürstin Noradi angestellt, aber mir ist sehr bewusst, dass ich damals nichts gelernt habe. Wie einfältig war ich doch. Wie glücklich.“\n– Notizen von Dr. Esslanger","Wahrzeichen",[],["Noxus"],"EPISCH"],"06NX032":["Gehorsamer Drachenhund","Wenn ein Verbündeter angreift, greife ich mit ihm an.","","„Drachenhunde sind etwas ganz Besonderes, nicht wahr? So begierig darauf, zu gefallen. So formbar. Wenn doch nur meine Feinde ebensolche Qualitäten besäßen.“\n– Dorn der Schwarzen Rose","Einheit",["HUND"],["Noxus"],"GEWÖHNLICH"],"06NX030":["Deserteur der Legion","Ich erhalte alle Überall-Buffs von Verbündeten.","","„Akt Eins: Ein Ex-Soldat, der nach dem Raub eines uralten Kashuri-Artefakts seinen Posten aufgegeben hat, versteckt sich in einer Qayanvi-Bar, arrogant und sturzbetrunken. Wenn er nur wüsste, dass der gestohlene Schatz seinem wahren Besitzer alles, was er sieht, haarklein zuflüstert! Sein Leben rinnt dahin wie zu viel Wein. Noxianisches Rot auf ionischem Gold.“","Einheit",[],["Noxus"],"SELTEN"],"06NX013":["Zauberlehrling","Ausspielen: Betäube einen Gegner oder verursache 2 Schaden an ihm, wenn er bereits betäubt ist.","","„Schüler: Sydell Kythera\nLehrer: J. Wollough\nBericht: Ich wurde am linken Unterarm von einer Spinne gebissen. Sydell behauptet, dass es sich um ein Missverständnis handelt, aber sein Grinsen widerlegt seine Unschuld. Ihm wurden zwei zusätzliche Wochen Strafarbeit (im Refektorium) auferlegt.“\n– Rabendorn-Disziplinarkarte","Einheit",["SPINNE"],["Noxus"],"GEWÖHNLICH"],"06NX040":["Trifarianische Trainingsarena","Wenn in einer Runde zum ersten Mal ein Verbündeter mit 5+ Stärke angreift, mobilisiere dich.","","„Auf meinen Befehl wirst du kämpfen. Falls du deinen Kampfpartner tötest, finde einen neuen! Wenn du scheiterst, dann stirb mit dem Wissen, dass dein Tod Noxus gestärkt hat! Trifarianische Soldaten … beginnt!“\n– Trifarianische Beurteilerin","Wahrzeichen",[],["Noxus"],"EPISCH"],"06NX028":["Rabendorn-Konservatorium","Countdown 11: Erschaffe 1 Tybaulk auf der Hand.\nZähle mich für jeden von dir ausgespielten Schnellzauber, langsamen Zauber oder Fertigkeit in diesem Spiel um 1 herunter.","","„… dich hat sicherlich schon die Kunde vom kolossalen Versagen der Rosenwarte-Akademie erreicht. Ich erwarte, dass du aus den Fehlern deiner Schwesterschule lernst. Ich erwarte von dir, dass du die Institution auf eine Art und Weise leitest, die dem Reich dienlich ist.“\n– Ein verbrannter Brief aus den Ruinen des Konservatoriums","Wahrzeichen",[],["Noxus"],"SELTEN"],"06NX014":["Abfackeln","Wähle eine Einheit. Wenn sie das nächste Mal in dieser Runde 1 oder mehr Schaden erleidet, töte sie.","","Rektorin Telsi sprach ausgiebig über die noxianischen Dogmen, was bei den Schülern vor ihr immer größere Langeweile und Unruhe auslöste. Doch wo die meisten ihr Temperament zurückhielten, ließ Annie ihrem freien Lauf. Erst mit Rauch, dann mit Feuer.","Zauber",["ELEMENTAR"],["Noxus"],"GEWÖHNLICH"],"06NX031":["Gefangener Yeti","Ruf: Ich koste 4 weniger.","","Der Menge stockte der Atem, als die zwei gefesselten Yetis in Bordents legendäre Kampfarena gebracht wurden. Niemand hielt die Bestien für stark genug, ihre Ketten zu sprengen, weil niemand von ihnen jemals einen Yeti gesehen hatte.","Einheit",["YETI"],["Noxus"],"GEWÖHNLICH"],"06NX009":["Gefangener Graurücken","Angriff: Ich verursache 3 Schaden an meinem Blocker. Wenn er tot oder weg ist, verursache ich stattdessen 3 Schaden am gegnerischen Nexus.","","„Dritter Akt: Eine grausame Hüterin und ihr Haustier. Der Graurücken ist sogar in seinem brutalen Zweck schuldlos – das Artefakt, das er trägt, zwingt ihn zur Unterwerfung. Die Hüterin weigert sich, zu schreien, als sie an ihr Haustier verfüttert wird. Wären doch nur alle Noxianer in ihrem Niedergang so edel.“","Einheit",[],["Noxus"],"GEWÖHNLICH"],"06NX015":["Manaseelenschüler","Wenn du in einer Runde zum ersten Mal einen Schnellzauber, langsamen Zauber oder eine Fertigkeit ausspielst, spiele ich Magische Glut aus.","","„Daani habe ich vor ein paar Jahren zum ersten Mal gesehen. Ist ganz nett. Hat auch eine nette Familie. Bei meinem letzten Besuch in seinem Dorf fand ich den armen Daani aber ganz allein auf dem Dorfplatz sitzen. Er sagte, er wartet auf die Heimkehr seiner Familie. Der arme Tropf musste schon seit Monaten dort gesessen haben. Ich brachte es nicht übers Herz, ihm zu sagen, was ich vor Kurzem gesehen hatte …“\n– Flynn Retrick","Einheit",[],["Noxus"],"GEWÖHNLICH"],"06NX037":["Noxus-Tellstones","Erschaffe 1 flüchtige Eiserne Entschlossenheit, Wirbelnder Tod oder Waffen der Verlorenen auf der Hand.","","„Clara, Schätzchen, du muss das Blut von den Marken wischen.“\n– Ophelia Noradi, scharlachrote Aristokratin","Zauber",[],["Noxus"],"SELTEN"],"06NX008":["Die Präfektin","Wenn du einen Schnellzauber, einen langsamen Zauber oder eine Fertigkeit ausspielst, gewähre mir +1|+0.","","„Viele Kinder sind in einem Alter, in dem ihre natürlichen Neigungen sie dazu bringen, gegen förmliche Führung zu rebellieren. Ein Glück also, dass die Ältesten von ihnen vom Rest geliebt und von uns geformt werden können. Wenn die Schüler unsere Lektionen ignorieren, werden wir sie durch sie erteilen.“\n– Rektorin Telsi","Einheit",[],["Noxus"],"EPISCH"],"06MT044":["Lumihorn der Solari","Tagesanbruch: Gib anderen Verbündeten in dieser Runde +0|+2.","","Lumihörner werden aus Sternen geboren und einige brennen heißer als andere.","Einheit",[],["Targon"],"GEWÖHNLICH"],"06MT036":["Konsultierung des Himmels","Heile deine Verbündeten vollständig und erhöhe dann ihre Stärke auf den Wert ihres Lebens.","","„Wir müssen zunächst uns selbst gegenüber Mitgefühl zeigen. Der Rest wird folgen.“\n– Soraka","Zauber",[],["Targon"],"EPISCH"],"06MT039":["Drachenhort","Countdown 3: Beschwöre Inviolus Vox.","","„Man erzählt sich, dass die himmlischen Drachen von den Nebeln selbst geboren werden, sie entspringen vollständig gebildet dem kosmischen Staub. Aber wie sollten wir Sterblichen das wissen? Aus der Ferne sehen wir nichts als ihr Licht.“\n– Verkünderin der Drachen","Wahrzeichen",[],["Targon"],"EPISCH"],"06MT045":["Himmlisches Dreigestirn","Ersuche je eine himmlische Karte mit niedrigen, mittleren und hohen Kosten.","","„Die Sterne, sie sagen großes Potenzial voraus. Etwas kommt. Welche Form werden sie annehmen? Ich kann es nicht wissen! Was glaubst du, Kulun?“\n– Mondträumerin","Zauber",[],["Targon"],"SELTEN"],"06MT043":["Targon-Tellstones","Erschaffe 1 flüchtiges Erblickt das Unendliche, Stille oder Segen des Targon auf der Hand.","","„Es ist seltsam, Shorin … Ich muss den Stein nicht einmal umdrehen, um genau zu wissen, welches Sternbild auf ihm gemalt ist.“\n– Tyari der Reisende","Zauber",[],["Targon"],"SELTEN"],"06MT029":["Esmus, Atem der Welt","Wenn ich beschworen werde, verstecke 1 Glocke auf der obersten Karte deines Decks.\nUnterstützung: Gewähre meinem unterstützten Verbündeten +1|+1.","","„… aber ich habe gehört, dass Esmus vom Beschützer persönlich erschaffen wurde, und mit ihrer Geburt kam der Klang in diese Welt!“\n„Lüge, sage ich! Jeder weiß, dass Esmus das Gesicht einer alten Sängerin trägt, die das Herz eines Engels und die Stimme der Toten hatte … bis Bard selbst ihr eine Stimme reiner Schönheit geschenkt hat!“\n„Lüge, sage ich! Esmus ist …“\n– Ein Beispiel von „die Geburt von Esmus“, einem bei Barden beliebtem Spiel","Einheit",[],["Targon"],"GEWÖHNLICH"],"06MT038":["Das gewundene Licht","Nachteinbruch: Gib anderen Verbündeten in dieser Runde +2|+1 und Überwältigen.","","„Mutter Mond, gib uns deine Stärke,\nDie Finsternis mag uns umgeben,\nDoch mit deinem Licht werden wir obsiegen.“\n– Gebet der Lunari","Einheit",[],["Targon"],"GEWÖHNLICH"],"06MT047":["Mystischer Vortex","Wenn ich beschworen werde oder mein Countdown herunterzählt, verstecke 3 Glocken in deinem Deck. Countdown 2: Ziehe 1.","","„Dann hab ich’s geseh’n – Tausende von ihnen, wie sie singen und hin und her tanzen. Dann seh’ ich ’nen Lichtblitz und sie sind alle weg und der Tempel mit ihnen – nicht ein Stein zu sehen. Und in meinen Händen? Tja, der Alte Gaff hatte ’ne Glocke in der Hand.“\n– Erzählung des Alten Gaff, Teil 3","Wahrzeichen",[],["Targon"],"SELTEN"],"06MT041":["Sternenhundrudel","Meine Auserwählt-Buffs werden verbündeten Sternenhundrudeln überall gewährt.","","Die Sternenhunde konnten von Bergsteigern auf ihrer Reise weder angelockt oder überredet werden. Sie blieben distanziert, augenscheinlich immun gegen die Magie des Berges.","Einheit",["HUND"],["Targon"],"GEWÖHNLICH"],"06MT049":["Mikhaels Segen","Gewähre einem Verbündeten +1|+2 und entferne alle negativen Schlüsselwörter von ihm.","","Wer die Glocke läuten hört, ist ergriffen von der Reinheit ihres Klangs.","Zauber",[],["Targon"],"SELTEN"],"06RU025":["Evelynn","Herkunft: Umarmung der Qual.\nWenn ich beschworen werde, beschwöre 1 zufällige Hülle.","Wenn ich sehe, wie du oder ein Verbündeter eine verbündete Hülle tötet, gib mir in dieser Runde ihre positiven Schlüsselwörter, und ich steige eine Stufe auf.","Die Pupillen der Priesterin weiteten sich, und ihre Hand zitterte nervös. Sie war bereit. Dies war der Moment, den Evelynn herbeigesehnt hatte wie keinen anderen. Sie grinste und wandte langsam das Gesicht ab. Dann begannen wie immer die Schreie.","Einheit",[],["Runeterra"],"Champion"],"06RU001":["Bard","Herkunft: Der umherziehende Beschützer.\nAngriff: Verstecke 3 Glocken in deinem Deck.","Du hast die Gesamtwerte von ausgespielten oder auf der Hand befindlichen Verbündeten um 20+ erhöht.","„Jupp, der alte Gaff hat viele komische Sachen gesehen. Beim ersten Mal war’s der Beschützer selbst, schätz’ ich mal. Wie eine Sternschnuppe am Himmel sah er aus. War so, als hätte die ganze Welt für ’ne Minute angehalten. Da war’n nur er und ich …“\n– Erzählung des Alten Gaff, Teil 1","Einheit",[],["Runeterra"],"Champion"],"06RU002":["Jhin","Herkunft: Der Virtuose.\nAngriff: Verursache 2 Schaden an allen betäubten Gegnern.","Du hast 12+ Schnellzauber, langsame Zauber oder Fertigkeiten ausgespielt.","„Ouvertüre: Wir beginnen in der Stadt Qayanvi, wo ein alter Meister einen jungen Schüler zu sich ruft. Ihm wurde der Auftrag erteilt, eine Gruppe niederträchtiger Schurken zu erledigen und gestohlene heilige Artefakte zurückzubringen. Der Schauspieler wartet gespannt, nimmt aber seinen Platz noch nicht ein. Für den Moment bereitet er sich nur vor und wartet an der Seite.“","Einheit",[],["Runeterra"],"Champion"],"06FR029":["Vor Angst erstarrt","Friere einen Gegner ein und beschwöre 1 Reifzahnrudel.","","Mit der Kälte kommen die Reifzahnwölfe und sie müssen nicht schneller sein als ihre Beute … sie müssen lediglich abwarten.","Zauber",["ELEMENTAR"],["Freljord"],"EPISCH"],"06FR033":["Jagender Eber","Letzter Wunsch: Erhalte einen leeren Manastein.","","Der Kreislauf von Leben und Tod sieht in Freljord anders aus. Die unwirtliche Landschaft sorgt dafür, dass fast nichts verschwendet wird.","Einheit",[],["Freljord"],"GEWÖHNLICH"],"06FR038":["Flügel des Kryophönix","Verursache 3 Schaden an ALLEN Einheiten.\nErleuchtet: Verursache stattdessen 3 Schaden an allen Gegnern und heile deinen Nexus um 3.","","Im Schatten der Flügel des großen Kryophönix jubelten ihre Anhänger und ihre Feinde erzitterten.","Zauber",["ELEMENTAR"],["Freljord"],"SELTEN"],"06FR030":["Vorbote der Diener","Ausspielen: Beschwöre 1 Gefrorener Diener oder zähle alle deine Gefrorenen Diener um 1 herunter.","","Der seltsame pfeifende Ruf der Kreatur über ihnen war kaum hörbar, doch als er von den Felswänden der Schlucht hallte, ging er den Spähern durch Mark und Bein. Vor ihren Augen bildeten sich Risse auf der Oberfläche des Eises, unregelmäßig und schnell.","Einheit",["VOGEL"],["Freljord"],"GEWÖHNLICH"],"06FR039":["Brutalität der Wildklaue","Verwandle einen verbündeten Begleiter in 1 Alpha-Wildklaue.","","„Großer Geist der Wildklaue, gewähre uns deine Kraft!“\n– Udyr","Zauber",[],["Freljord"],"SELTEN"],"06FR028":["Revna, die Wissenshüterin","Wenn ich beschworen werde, gewähre Einheiten in deinem Deck meine Werte und ziehe dann eine Einheit mit 5+ Stärke.","","Die Wissenshüter der Avarosa sind oft erfahrene Älteste des Stammes, Beschützer des Volks und langjährige Geschichtenerzähler. Sie erhalten die Tradition von Jagd und Kampf durch Geschichten und Lieder am Leben. ","Einheit",[],["Freljord"],"EPISCH"],"06FR037":["Knackendes Eis","Gewähre einem Gegner „Friere mich beim nächsten Rundenbeginn ein“.","","Man muss stets die Eisfläche prüfen, bevor man sie betritt, so dick sie auch aussehen mag.","Zauber",["ELEMENTAR"],["Freljord"],"GEWÖHNLICH"],"06BC045":["Wandelschnupfstaub!","Gib Verbündeten in dieser Runde +1|+1. Wenn sie erschaffen sind, gib ihnen stattdessen +2|+2.","","„HALLO! ICH PILZ ICH SPRECHEN ICH WEIẞ NICHT WARUM ODER WIE ODER WAS PASSIERT BITTE LASS MICH PILZ SEIN. BITTE. DANKE. TSCHÜSS!“\n– Pilz","Zauber",[],["Bandle"],"EPISCH"],"06BC036":["Paparo der Große","Ausspielen: Manifestiere einen Yordle.\nAngriff: Gewähre Yordle-Verbündeten +1|+0.","","„ALLE lieben Paparo! Jeden Sommer bringt er uns Souvenirs aus der ganzen Welt, und sie sind immer entweder lecker, hübsch oder abgedreht! Manchmal alles zusammen!“\n– Ava Überflieger","Einheit",["YORDLE"],["Bandle"],"EPISCH"],"06BC040":["Bandle-Tellstones","Erschaffe 1 flüchtige Yordle-Konstruktion, Heroischer Refrain oder Elektroharpune auf der Hand.","","Yordle sind immer für ein Spiel zu haben … aber wundere dich nicht, wenn sich mittendrin die Regeln ändern!","Zauber",[],["Bandle"],"SELTEN"],"06BC039":["Die Bombe platzt","Verursache 2 Schaden an einer Einheit und beschwöre 1 Behelfsbombe.","","„Das ist nicht gut“, sagte Giselle leise und ging in Deckung.","Zauber",[],["Bandle"],"GEWÖHNLICH"],"06BC044":["Kosmische Bindung","Verursache 2 Schaden an einem Gegner und betäube einen anderen. Verstecke 6 Glocken in deinem Deck.","","„Mama, wo geht der Beschützer hin?“\n„Überallhin, mein Schatz. So weit das Auge reicht.“\n„Warum?“\n„Ach, Liebling. Frag nicht, warum. Nicht einmal unsere weisesten Ältesten verstehen die Methoden des Beschützers …“\n– Mutter und Kind","Zauber",[],["Bandle"],"SELTEN"],"06BC026":["Byrd, der Glockenläuter","Wenn ich beschworen werde, verstecke 1 Glocke auf der obersten Karte deines Decks.","","„… das zweite Mal war ’n Großes. Ich hab den Boden geschrubbt, als ich auf einmal seh, wie sich mein Essen über den Tisch ergießt und die Töpfe un’ Pfannen durch die Tür wegwatscheln! Bin ihnen so schnell ich konnte hinterher und hab sie bei diesem Tempel gefunden. Die ham die Regale durchwühlt, als würden sie nach was suchen.“\n– Erzählung des Alten Gaff, Teil 2","Einheit",[],["Bandle"],"GEWÖHNLICH"],"06BC030":["Annäherungspoffpilz","Verursache 1 Schaden an einer Einheit. Falls in dieser Runde eine deiner Fallen oder Segen aktiviert wurde, verursache stattdessen 3 Schaden.","","„Wenn er leuchtet, sollte man das Weite suchen!“\n– Bandle-Späher-Regel 463","Zauber",[],["Bandle"],"GEWÖHNLICH"],"06BC031":["Maduli, der Pförtner","Wenn ich beschworen werde, verstecke 1 Glocke auf der obersten Karte deines Decks und verdopple dann die Segen in deinem Deck.","","„Hat mir ’nen ganz schönen Schreck eingejagt. Überall wuchsen Arme raus. Zähne so groß wie Felsen. Oh, und als diese Kreatur mit dem Schlägel über seine Zähne gefahren ist, ertönte so ’ne gruselige Melodie, dass ich dachte, ich sterbe. Bin um mein Leben gerannt. Aber erst, als ich sie gesehen hab’ … Löcher im Himmel! Waren sicher Hunderte!“\n– Erzählung des Alten Gaff, Teil 4","Einheit",[],["Bandle"],"SELTEN"],"06BC035":["Der Papierbaum","Wenn ein Verbündeter mit einer Ausrüstung oder Begleitung angreift, gewähre ihr +1|+0.","","Die Blätter des Papierbaums schimmern mit derselben Feenmagie, die den Baum selbst erschaffen hat. Und wie die Vögel, die ihre Form inspiriert haben, finden sie glitzernde Dinge unwiderstehlich anziehend.","Wahrzeichen",[],["Bandle"],"SELTEN"],"06IO005":["Grausames Theater","Rufe eine Einheit mit 3 oder weniger Leben zurück.","","„Kunstfertigkeit darf nicht überstürzt werden.“\n– Jhin","Zauber",[],["Ionia"],"GEWÖHNLICH"],"06IO038":["Moralische Unterstützung","Ich koste 2 weniger, wenn du in diesem Spiel einen Verbündeten unterstützt hast. Gib einem Verbündeten in dieser Runde Barriere.","","„Vertraue auf das Gleichgewicht. Gehe zwischen den Welten.“\n– Shen","Zauber",[],["Ionia"],"GEWÖHNLICH"],"06IO012":["Ruf der Kinkou","Beschwöre jetzt oder beim nächsten Rundenbeginn 1 Hüterin der Masken. Ziehe 1.","","„Dank alter Masken sehen junge Augen klar.“\n– Hüterin der Masken","Zauber",[],["Ionia"],"GEWÖHNLICH"],"06IO009":["Hinterhalt der Drachen","Beginne einen kostenlosen Angriff mit 2 Drachlingen.","","„Offenbartes Verlangen.“\n– Die Drachenmeisterin","Zauber",[],["Ionia"],"GEWÖHNLICH"],"06IO033":["Sturm der Klingen","Rest des Spiels: Wenn du einen Klingentanz ausführst, beschwöre eine weitere angreifende Klinge.\nKlingentanz (1).","","„Führe den Tanz, ich folge!“\n– Schwungvolle Tänzerin","Zauber",[],["Ionia"],"EPISCH"],"06IO004":["Die Schöpferin","Ausspielen: Rufe eine Einheit mit weniger Stärke als ich zurück.","","„Die Schöpferin ist eine außergewöhnliche Erschafferin. Eine legendäre Handwerkerin! Ihre Kunst beispiellos! Ihre Umsetzung makellos! Es ist eine große Ehre, in ihrer Gegenwart zu sein, geschweige denn, ein von ihr erschaffenes Instrument zu führen.“\n– Zeugin der Kashuri","Einheit",[],["Ionia"],"SELTEN"],"06IO010":["Windumhüllte Anhöhe","Wenn ich beschworen werde, ziehe Yasuo und betäube den stärksten Gegner.\nWenn du die Angriffsmarke erhältst, betäube den stärksten Gegner.","","Für die meisten bedeutet Frieden ein glückliches Zuhause und die warme Ruhe in den Armen des Partners. Für Yasuo ist es der seltene Augenblick, wenn der Wind sich beruhigt und Aussichten statt Rückblicke bietet. ","Wahrzeichen",[],["Ionia"],"EPISCH"],"06IO036":["Ionia-Tellstones","Erschaffe 1 flüchtiges Grausames Theater, Ritual der Erneuerung oder Geeinter Halt auf der Hand.","","„Deinen Gegner lesen zu können, ist unverzichtbar, sogar außerhalb von Kämpfen. Aber der wichtigste Zweck eines Spiels ist, Spaß zu haben. Und jetzt hol mir mein Fußbad!“\n– Inspirierender Mentor","Zauber",[],["Ionia"],"SELTEN"],"06IO003":["Die Bühnenassistentin","Ausspielen: Betäube einen Gegner.","","„Vierter Akt: Eine junge Priesterin wird Teil unserer Erzählung. Ihre Geschichte ist tragisch, vermittelt durch die blassen Lippen jener, die sie verraten hat. Da sie unbedingt für ihr Vergehen Buße tun will, trägt sie in ihren Armen eine schwere Bürde, ein goldenes Geschenk für die Noxianer, die sie in ihrem Land willkommen geheißen hat. Wir fragen uns: War es die Reue, die ihr Herz gebrochen hat, oder die Kugel?“","Einheit",[],["Ionia"],"GEWÖHNLICH"],"06IO035":["Schülerin der Kinkou","Wenn ein anderer Verbündeter Barriere erhält, gib mir in dieser Runde Barriere, falls ich keine habe.","","„Heiße das Gleichgewicht überall willkommen. Geist, Körper, Seele. Widerstehe dem stürmischen Drang der Jugend. Erweitere deine Perspektive.“\n– Shen","Einheit",[],["Ionia"],"SELTEN"],"06PZ032":["Klappernder Klimperkasten","Wähle einen von 2 neuen Zaubern mit 2 Kosten aus, der auf der Hand erschaffen wird, und setze seine Kosten in dieser Runde auf 0. Wiederhole das zweimal.","","Zhauns erster Klimperkasten war erstaunlich zuverlässig. Sein einziger Nachteil bestand darin, dass niemand herausfinden konnte, wie man die Lautstärke regelt.","Zauber",[],["Piltover & Zhaun"],"EPISCH"],"06PZ042":["Böse Imperfektionistin","Ausspielen: Wähle eine Karte auf der Hand. Erschaffe 4 exakte Kopien von ihr in deinem Deck und senke ihre Kosten um 1.","","„Zum heutigen Tag kann ich nur sagen, dass es hätte besser laufen können. Das muss reichen. Mein zukünftiges Ich … du weißt, was wir getan haben.“\n– Kays Tagebuch","Einheit",[],["Piltover & Zhaun"],"EPISCH"],"06PZ025":["Einsamkeit","Wenn ich beschworen werde, beschwöre 1 zufällige Hülle.\nWenn du einen Verbündeten mit 1 Kosten beschwörst, gewähre ihm ein zufälliges Schlüsselwort.","","„Auf meinem Weg nach Hause vom Entresol sah ich erneut die arme Vagabundin schluchzend in einer kleinen Gasse. Dass so viele sie gar nicht beachten, bricht mir ebenso das Herz wie ihre Notlage an sich. Sollten sich unsere Wege morgen erneut kreuzen, werde ich ihr helfen, so gut ich kann.“\n– Notizen aus Lady Sempescus Tagebuch","Einheit",[],["Piltover & Zhaun"],"SELTEN"],"06PZ043":["Piltover-Tellstones","Erschaffe 1 flüchtiges Nachbeben, Hextech-Transmogulator oder Tag des Fortschritts! auf der Hand.","","„Sie werden nirgendwo auf der Welt bessere Spielsteine finden, guter Mann. Meine Tochter hat unglaublich viel Herzblut in jedes kleine Detail gesteckt.“\n– Corin Reveck ","Zauber",[],["Piltover & Zhaun"],"SELTEN"],"06PZ027":["Exklusive Einladung","Erschaffe 1 flüchtige Ominöse Gestalt oder Chempunk-Shredder auf der Hand und senke die Kosten um 1.","","Die besten Nachtabenteuer in Zhaun kann man nur auf Einladung erleben. Wenn du nicht dazugehörst, dann solltest du eine richtig große Nummer sein, um reinzukommen. Oder anderswo ein Ticket finden.","Zauber",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"06PZ038":["Recycelte Tarntechnologie","Gewähre einem Verbündeten Ungreifbar und „Nexusschlag: Ziehe 1“.","","„Ihr werdet nicht GLAUBEN, was ich heute gefunden habe!“\n– Grubenbastler","Zauber",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"06PZ039":["Geborgener Schrott","Wirf zum Ausspielen bis zu 2 Karten ab. Erschaffe entsprechend viele Begleiter aus deinen Regionen, die 1 mehr kosten, und senke ihre Kosten um 1.","","In den Tiefen von Zhaun sind die Einheimischen gezwungen, geborgenen Schrott zu brauchbaren Materialien weiterzuverarbeiten. Nach jahrzehntelanger Übung können sie das mittlerweile ziemlich gut.","Zauber",[],["Piltover & Zhaun"],"SELTEN"],"06BW006":["Illaoi","Angriff: Krakenruf (1), dann addiere in dieser Runde die Stärke deines stärksten Tentakels zu meiner.","Ich habe gesehen, wie verbündete Tentakel oder ich 15+ Schaden verursacht haben.","Das „Auge von Nagakabouros“ ist lediglich ein Name, doch Illaoi sieht ihn als Herausforderung, so zu leben, als wäre ihre Göttin ein dauerhafter – und schnell gelangweilter – Begleiter.","Einheit",[],["Bilgewasser"],"Champion"],"06BW036":["Hafenratte","Ich habe +1|+0 für jede Runde, in der du Schaden am gegnerischen Nexus verursacht hast.","","„In Bilgewasser gibt’s keinen blutigeren Ort als die Bucht. Schau dir nur diese Ratten an. Mit Blut aufgezogen. Können nicht genug von dem Zeug kriegen. Gruselige kleine Viecher.“\n– Kaltblütiger Kaperer","Einheit",[],["Bilgewasser"],"EPISCH"],"06BW038":["Südsee-Walross","Sobald du in der Tiefe bist, heile deine Verbündeten und deinen Nexus um 3.","","„Was will es?!“\n„Es … es will die Orangen!“\nBei der Bärtigen Dame, GIB IHM EINFACH DEN GANZEN KORB!“\n– Vom Pech verfolgte Matrosen","Einheit",["SEEUNGEHEUER"],["Bilgewasser"],"GEWÖHNLICH"],"06BW030":["Auge von Nagakabouros","Krakenruf (2).\nZiehe 2.","","Nagakabouros ist eine Göttin der Fürsorge – vorausgesetzt, man überlebt ihre Anbetung.","Zauber",[],["Bilgewasser"],"GEWÖHNLICH"],"06BW011":["Nagakabouros","Wenn ich beschworen werde oder bei Rundenbeginn: Krakenruf (2). Wenn dann dein stärkstes Tentakel 12+ Stärke hat, erschaffe 1 Nagakabouros’ Wutanfall auf der Hand.","","„Die Schlangenmutter. Der Große Kraken. Die Bärtige Dame. Nagakabouros kümmert sich wenig um Namen und noch weniger um die rastlosen Toten.“\n– Illaoi","Einheit",[],["Bilgewasser"],"EPISCH"],"06BW021":["Predigt des Flutstroms","Verursache 3 Schaden an einer gegnerischen Einheit.\nKrakenruf (3).\nVerursache 1 Schaden am gegnerischen Nexus.","","„Wir lernen als Kinder, uns mit den gefährlichen Gewässern zu bewegen. Wer scheitert, stirbt. Es ist natürlich, dass die erste Prüfung einer Priesterin darin besteht, diese Lektion zu vergessen; mit aller Kraft gegen die Tiefenströmung anzukämpfen. Denn eine Verkünderin der Wahrheit ist nicht der Schwimmer – sie ist die Strömung.“\n– Illaoi","Zauber",[],["Bilgewasser"],"EPISCH"],"06BW045":["Blut im Wasser","Verursache 1 Schaden an einem beliebigen Ziel, dann mobilisiere dich.","","Nicht viel hält die kreisenden Haie in der Bucht der Untiefen auf Abstand. Sobald sie Blut geschmeckt haben, wollen sie mehr.","Zauber",[],["Bilgewasser"],"GEWÖHNLICH"],"06BW028":["Tentakelschlag","Krakenruf (2), dann schlagen sich dein stärkstes Tentakel und ein Gegner gegenseitig.","","„Das Leben ist eine Prüfung. Und Schmerz ist öfter unser Lehrer, als uns lieb ist.“\n– Illaoi","Zauber",[],["Bilgewasser"],"SELTEN"],"06BW035":["Die Stimme der Meere","Angriff: Krakenruf (1) und gib deinem stärksten Tentakel in dieser Runde Überwältigen.","","Um Nagakabouros zu beschwören, wird kein Ritual oder Brauch benötigt. Sie erhört den Ruf jener, deren Seelen sich dem Ozean anpassen können, jeder Woge, jeder Welle. Diesem Kampf können nur wenige standhalten.","Einheit",[],["Bilgewasser"],"SELTEN"],"06BW015":["Erhörtes Gebet","Krakenruf (2), oder gib stattdessen 5 Mana für Krakenruf (4) aus.","","Gebete an Nagakabouros drehen sich nicht um Bittgesuche und auch nicht darum, etwas zu erhalten. Ihr Segen ist dem Leben nicht unähnlich: Gib alles, kämpfe und lass nicht locker, und manchmal wirst du belohnt.","Zauber",[],["Bilgewasser"],"GEWÖHNLICH"],"06BW007":["Wachsamer Götze","Rundenbeginn: Verursache 2 Schaden an mir. Krakenruf (1).","","Wenn die Schrecken aus den Schatteninseln strömen, leuchtet der Götze hell – ein strahlendes Signal am Horizont.","Einheit",[],["Bilgewasser"],"GEWÖHNLICH"],"06BW037":["Abkassieren","Manifestiere einen Begleiter, den du dir leisten kannst.","","„Also schön, Baz. Bist du sicher, dass du es erneut versuchen willst?“\n„Aller guten Dinge sind drei, Gav. Außerdem haben wir schon gegen alles gekämpft, was diese stinkende Stadt zu bieten hat.“\n„Gekämpft und verloren, Baz.“\n– Baz und Gav, angehende Kopfgeldjäger","Zauber",[],["Bilgewasser"],"EPISCH"],"06BW041":["Betrügen","Wähle 1 von 2 Karten, die keine Champions sind, aus der Hand des Gegners und erschaffe eine Kopie auf deiner Hand. Plündern: Ich koste 1 weniger.","","„FÜNF Asse? Ich hab wohl schon wieder gewonnen!“\n– Billardbetrüger","Zauber",[],["Bilgewasser"],"SELTEN"],"06BW016":["Buhru-Patrouille","Wenn ich beschworen werde, Krakenruf (3).","","Das Leben ist in seiner Einfachheit am schönsten. Die salzige Gischt im Gesicht, Vogelgesang in den Ohren … und ein unkomplizierter Feind am Horizont.","Einheit",[],["Bilgewasser"],"GEWÖHNLICH"],"06BW009":["Buhru-Anführer","Ausspielen: Ein Verbündeter mit 1 Kosten beginnt einen kostenlosen Angriff.","","„Rufe dir die Weisheit des Ozeans in Erinnerung! Wenn du dich nicht bewegst, wirst du bewegt! Folge meiner Stimme, wenn du dich verirrt hast – denn dein Feind kennt sicherlich seinen Weg.“ ","Einheit",[],["Bilgewasser"],"SELTEN"],"06BW043":["Bilgewasser-Tellstones","Erschaffe 1 flüchtiges Mehr Pulver!, Verspielter Täuscher oder Köder auswerfen auf der Hand.","","„Versuch bloß nicht, einen Bluff von jemandem in ’ner Partie Stones aufzudecken. Bilgewasser steckt voller guter Lügner. Wenn du gewinnen willst, musst du auf ihre Hände achten.“\n– Twisted Fate","Zauber",[],["Bilgewasser"],"SELTEN"],"06BW018":["Steem","Wenn ich beschworen werde, beschwöre 1 zufällige Hülle.\nWenn du einen Verbündeten mit 1 Kosten beschwörst, belege den stärksten Gegner mit Verletzlich.","","Evelynns erste Begegnung mit Steem war eine heftige, aufregende Angelegenheit. Sie erinnerte sich, wie er mit unverhohlenem Genuss gelächelt hatte, als sie seine Haut abtrennte, und wie er sie genauso eifrig leiden ließ, als er an der Reihe war. Nachdem Evelynn Steem schließlich überwältigt hatte, beschloss sie, den niederen Dämon nicht zu vernichten, sondern für immer an sich zu binden. Vielleicht, so dachte sie, könnten sie ihre gemeinsame Vorliebe für Gemetzel mit der Welt teilen.","Einheit",[],["Bilgewasser"],"GEWÖHNLICH"],"06SH014":["Monstrum der Leere","Wenn ich beschworen werde, gewähre mir alle positiven Schlüsselwörter, die Verbündete in diesem Spiel hatten.\nWenn ein Verbündeter ein neues positives Schlüsselwort hat, gewähre es mir.","","„Wir hatten schon Geschichten über Durchbrüche der Leere gehört und über die Vernichtung, die sie bringen. Aber so etwas selbst zu sehen … Ich weiß nicht, ob meine Augen diesen Anblick jemals vergessen können – oder mein Herz diesen Schrecken.“\n– Überlebender von Belveth","Einheit",[],["Shurima"],"EPISCH"],"06SH016":["Herold des Schwarms","Ausspielen: Gewähre einer Einheit und mir die positiven Schlüsselwörter des anderen.","","„Es sprach zu mir, als … als würde es mich kennen. Als wollte es, dass ich … etwas treffe …“\n– Kai’Sa","Einheit",[],["Shurima"],"SELTEN"],"06SH009":["Kai’Sa","Wenn ich beschworen werde oder bei Rundenbeginn: Wenn du die Angriffsmarke hast, erschaffe 1 Zweite Haut auf der Hand.","Du hast dich entwickelt.","Nur wenige Tage zuvor hatte Kai’Sa bemerkt, wie ihre zweite Haut mit neuer Aufregung erfüllt war und sie mit wachsendem Nachdruck zur Küste von Shurima zog. Etwas stimmte nicht, und als Kai’Sa sich Belveth näherte, erkannte sie rasch das volle Ausmaß des Schreckens.","Einheit",[],["Shurima"],"Champion"],"06SH048":["Ritus des Übergangs","Manifestiere ein verbündetes Wahrzeichen, das in diesem Spiel zerstört wurde, und beschwöre es.","","„Ein Augenblick, erstarrt in der Zeit.“\n– Zilean","Zauber",[],["Shurima"],"GEWÖHNLICH"],"06SH037":["Witterklaue der Baccai","Ausspielen: Belege einen Gegner mit Verletzlich.\nWenn ein Gegner herausgefordert wird, gib ihm in dieser Runde -2|-0.","","Ihr Verstand erodierte wie Dünen im Wind. An seiner Stelle begann eine Saat der Wut zu einem Zorn heranzuwachsen, den kein Wüstenwasser stillen konnte.","Einheit",[],["Shurima"],"GEWÖHNLICH"],"06SH008":["Älteste von Belveth","","","Shalatai taumelte angesichts des Schreckens vor ihr. Da lag Ferai, die Tochter des freundlichen Fleischers, tot und zerschmettert. Neben ihr lag Gorrub, der Sohn des Fischers, der seine leblosen Hände immer noch nach seiner Liebsten ausstreckte. So viele Erinnerungen ausgelöscht. So viele Leben verloren. Mit verzerrtem Gesicht wandte Shalatai sich dem Unheil zu, bereit, ihr Leben zu geben, um den Rest ihrer Leute zu retten.","Einheit",[],["Shurima"],"GEWÖHNLICH"],"06SH042":["Shurima-Tellstones","Erschaffe 1 flüchtiges Rücksichtsloser Räuber, Abwägung des Urteils oder Seelenfeuer auf der Hand.","","„Bei Tellstones geht es nie darum, wer gewinnt. Es geht nur darum, wie großartig du während des Spiels aussiehst.“\n– Akshan","Zauber",[],["Shurima"],"SELTEN"],"06SH050":["Sand der Zeit","Gib Gegnern in dieser Runde -2|-0. Erschaffe 1 flüchtiges Sekundenjahrhundert auf der Hand.","","Der Sand der Zeit fließt gnadenlos und rücksichtslos dahin. Ihm wohnt eine grauenvolle Gleichgültigkeit inne, doch nicht jedes Wesen ist ein Sklave seiner ungeheuerlichen Machenschaften …","Zauber",[],["Shurima"],"SELTEN"],"06SH049":["Ruf des Ruhms","Ich koste 2 weniger für jeden unterschiedlichen aufgestiegenen Verbündeten, den du in diesem Spiel beschworen hast.\nManifestiere eine Karte aus dem Deck des Imperators, die 9 oder weniger kostet.","","„Das ist unser Werk – seht, was wir erreicht haben!“\n– Azir","Zauber",[],["Shurima"],"SELTEN"],"06SH036":["Kammer der Erneuerung","Wenn du einen Champion beschwörst, zerstöre mich, um ihm +2|+1 und Zauberschild zu gewähren.","","Als Nasus aus dem Sarkophag stieg, waren seine Wunden vollständig verheilt und er war bei klarem Verstand. Er verfasste ein paar Notizen und blickte auf die hoch über ihm hängenden Sarkophage. Dabei dachte er über den mentalen Zustand der monströsen Abscheulichkeiten in ihnen nach. Die Zeit würde zeigen, ob diese Magie die Baccai vom Wahnsinn befreien konnte. Eine Magie, gegen die sich die anderen Aufgestiegenen früher ausgesprochen hatten. Aber sie waren nun fort, im Gegensatz zu Renekton und seinem Irrsinn. Nasus schrieb noch ein paar weitere Worte und hoffte, endlich einen Weg gefunden zu haben, um seinen Bruder zu retten.","Wahrzeichen",[],["Shurima"],"EPISCH"],"06SH011":["Superenergie","Gewähre einem Verbündeten Überwältigen und Zauberschild.","","„Ich zeige dir, wie man kämpft.“\n– Kai’Sa","Zauber",[],["Shurima"],"GEWÖHNLICH"],"06SH017":["Leerenprojektil","Verursache 1 Schaden an einem Begleiter. Wenn du dich entwickelt hast, verursache stattdessen 3 Schaden an einer Einheit.","","„Tut weh, was?“\n– Kai’Sa","Zauber",[],["Shurima"],"SELTEN"],"06SH007":["Begleiter der Leere","Während ich auf der Hand bin, habe ich ein zufälliges Schlüsselwort, das sich jede Runde ändert. Wenn ich beschworen werde, gewähre mir dieses Schlüsselwort.","","Dharna erinnerte sich, wie sie an diesem Morgen die Fenster geöffnet und das frisch gebackene Brot gerochen hatte. Unten an der Straße hatten Fischer bereits begonnen, den Fang des Tages hinauf zu den Mittagsmärkten zu schleppen. Sie erinnerte sich, dass sie gelächelt hatte, mit dem Gedanken, es würde ein schöner Tag werden.","Einheit",[],["Shurima"],"GEWÖHNLICH"],"06SH010":["Leeren-Blaster","","","Der Ausbruch der Leere in der Stadt Belveth kam plötzlich und war erschreckend. Die meisten Zivilisten hatten große Angst vor dem Chaos, das rasch über die Stadt kam, und flohen in Sicherheit, so schnell sie konnten. Die meisten, aber nicht Koyemi.","Einheit",[],["Shurima"],"GEWÖHNLICH"],"06SH034":["Dominanz","Wenn ich beschworen werde, beschwöre 1 zufällige Hülle.\nWenn du einen Verbündeten mit 1 Kosten beschwörst, gewähre ihm +1|+0.","","Manchmal wollen sich die Mächtigen einfach nur machtlos fühlen.","Einheit",[],["Shurima"],"EPISCH"],"06DE045":["Inspirierendes Licht","Gewähre Verbündeten Kampfgeist.","","„Genug versteckt! Komm ins Licht und scheine hell mit mir!“\n– Lux","Zauber",[],["Demacia"],"GEWÖHNLICH"],"06DE038":["Fürst Eldred, Anführer der Magiesuchenden","Andere Verbündete und dein Nexus haben Robust.\nWenn ein Verbündeter Schaden überlebt, gewähre ihm +1|+1.","","„Ich habe dein eindringliches Flüstern zufällig mitgehört, liebe Gattin. Ich rate dir zu mehr Vorsicht, wenn du an einem solchen öffentlichen Ort Familienangelegenheiten besprichst. Du kannst nie sicher sein, wer alles lauscht.“","Einheit",[],["Demacia"],"EPISCH"],"06DE037":["Königlicher Erlass","Gib einem Verbündeten in dieser Runde +2|+2 und Herausforderer oder beschwöre 1 Ehrwürdiger Fürst.","","„Sofort, König Jarvan. Es wird mit allen Mitteln erledigt.“\n– Barrett Buvelle, Ehrwürdiger Fürst","Zauber",[],["Demacia"],"SELTEN"],"06DE035":["Petrizitsäule","ALLE Zauber kosten 2 mehr.\nCountdown 2.","","Magiesuchende errichten in ihren Basen riesige Obelisken aus Petrizit, um dafür zu sorgen, dass sogar die mächtigsten Magier völlig hilflos sind.","Wahrzeichen",[],["Demacia"],"GEWÖHNLICH"],"06DE042":["Demacia-Tellstones","Erschaffe 1 flüchtige Prismatische Barriere, Festnehmen oder Für Demacia! auf der Hand.","","„Warum wird es ‚Gambit des Königs‘ genannt? Königinnen gehen auch Risiken ein!“\n– Cithria von Wolkenfeld","Zauber",[],["Demacia"],"SELTEN"],"06DE036":["Argwöhnischer Brutvater","Angriff: Ziehe eine Einheit. Wenn sie ein Drache ist, beschwöre sie angreifend.","","„Zum Glück hat meine Forschung ergeben, dass Brutväter meistens ein gutes Stück entfernt von ihrem Nachwuchs jagen. Sollte das Männchen zurückkehren, wären wir alle Drachenfutter, versteht sich! Haha!“\n– Anden Mayne, Eierköpfiger Forscher","Einheit",["DRACHE"],["Demacia"],"EPISCH"],"06DE030":["Tödliche Verlockung","Beschwöre 1 zufällige Hülle und gewähre ihr +1|+0.","Missing Translation","„Komm näher, Liebes …“\n– Evelynn","Zauber",[],["Demacia"],"GEWÖHNLICH"],"06SI012":["Gwen","Angriff: Wenn ein anderer Verbündeter Stärke durch Geweiht erhält, erhalte ich sie ebenfalls. Entziehe dem gegnerischen Nexus 2.","Ich habe 10+ Schaden verursacht.","Gwen schnipp-schnipp-schnippte sich den Weg durch den schwarzen Nebel und fand es sehr merkwürdig, wie er den Bereich vollständig einhüllte. Am Ende ragte das verzauberte Pfarrhaus aus dem düsteren Wald empor wie ein Leuchtturm. Kein Wunder, dass Gwen davon angezogen wurde. Überaus seltsam – und gleichzeitig großartig!","Einheit",[],["Schatteninseln"],"Champion"],"06SI020":["Hassausbruch","Töte einen Verbündeten, um 3 Schaden an einer Einheit zu verursachen, und wenn Evelynn zum Spielstart in deinem Deck war, beschwöre eine zufällige Hülle.","","„Sei so laut wie du willst.“\n– Evelynn","Zauber",[],["Schatteninseln"],"SELTEN"],"06SI013":["Ewige Tänzerinnen","Angriff: Belebe eine angreifende vergängliche Kopie des stärksten toten Verbündeten außer Ewige Tänzerinnen wieder, der höchstens meine Stärke hat.","","Es ist stets einfacher, sich jemandem auf der Tanzfläche anzuschließen, als sie als Erstes zu betreten. Die Zwillinge jedoch zeigen den anderen immer gerne, wie es geht.","Einheit",[],["Schatteninseln"],"EPISCH"],"06SI037":["Schatteninseln-Tellstones","Erschaffe 1 flüchtiges Zeichen der Inseln, Spirituelle Reise oder Zerfallen auf der Hand.","","„Glänzende … Dekorationen. Marken … Regeln lernen. Seltsames Spiel. Atemberaubend … unvergleichliche Handwerkskunst … unvergesslich.“\n– Hinterlassenes Tagebuch","Zauber",[],["Schatteninseln"],"SELTEN"],"06SI040":["Albtraumhafte Rückkehr","Belebe den stärksten toten verbündeten Begleiter wieder und gewähre ihm Vergänglich und Bedrohlich. Gib Gegnern in dieser Runde -1|-0.","","Geistern können für eine gewisse Zeit vertrieben werden, aber sie kehren stets zurück.","Zauber",[],["Schatteninseln"],"EPISCH"],"06SI027":["Einfädeln","Töte einen Verbündeten, um Schaden in Höhe seiner Stärke an einem Gegner zu verursachen.","","„Nadeln raus!“\n– Gwen","Zauber",[],["Schatteninseln"],"GEWÖHNLICH"],"06SI018":["Vora","Wenn ich beschworen werde, beschwöre 1 zufällige Hülle.","","Im Gegensatz zu anderen Dämonen, die ihre Opfer mit falschen Versprechungen anlocken, ist Vora zu unkonzentriert in ihrer Gier, zu überwältigt vom eigenen Verlangen. Sie ist kein Raubtier, das seiner Beute nachstellt, sondern eine wilde Bestie, die gefüttert werden muss.","Einheit",[],["Schatteninseln"],"SELTEN"],"06SI015":["Versammelt die Band","Beschwöre 2 Gespenstische Bands.","","„Immer lebhaft bleiben! Schneller!“\n– Dirigent des Nebels","Zauber",[],["Schatteninseln"],"GEWÖHNLICH"],"06SI030":["Förmliche Einladung","Erschaffe Kopien von 2 verbündeten Begleitern auf der Hand, die in diesem Spiel gestorben sind.","","„Da wären wir, meine Liebe. Ich habe gehört, das soll heute Abend eine prachtvolle Angelegenheit werden, und ich nehme an, wir werden viele vertraute Gesichter sehen!“\n– Geisterhafter Feiernder","Zauber",[],["Schatteninseln"],"SELTEN"],"06SI026":["Dirigent des Nebels","Letzter Wunsch: Erschaffe 1 Gespenstische Band auf der Hand.","","„Spielt weiter, Freunde! Dieses Konzert wird lebendiger als jedes andere zuvor!“","Einheit",[],["Schatteninseln"],"SELTEN"],"06SI033":["Verfluchtes Grab","Countdown 2: Belebe den stärksten toten Verbündeten wieder.","","Das Klirren von Schwertern, die auf Schilde treffen, war wie die Totenglocke. Es lockte Geister an, deren Bindung an diese Welt noch nicht ganz durchtrennt war und deren Willen selbst der Tod nicht besänftigen konnte.","Wahrzeichen",[],["Schatteninseln"],"EPISCH"],"06SI016":["Überschwänglicher Gastgeber","","","„Du bist HERZLICH EINGELADEN zur Feier deines Lebens – dem MITTERNACHTSFEST. Schließe dich uns im PORZELLANPFARRHAUS an, wo wir trinken, tanzen und uns vergnügen werden! (Die Feierlichkeiten enden pünktlich, wenn die Uhr 13 schlägt.)“ \n– Eine Einladung in eleganter Handschrift","Einheit",[],["Schatteninseln"],"SELTEN"],"06SI028":["Phantom-Butler","","","Was wäre eine schicke Feier ohne schicke Getränke?","Einheit",[],["Schatteninseln"],"GEWÖHNLICH"],"06SI043":["Schattenwuchs","Entsorge 3.\nEntziehe einer Einheit 2.","","Selbst auf den Schatteninseln finden alte Gewächse einen neuen Sinn.","Zauber",[],["Schatteninseln"],"GEWÖHNLICH"],"06SI022":["Geisterhafter Geliebter","","","Ob er nun ein Geist, eine Erinnerung oder ein Traum war, etwas an ihm wirkte vertraut …","Einheit",[],["Schatteninseln"],"GEWÖHNLICH"],"06SI019":["Sultur","Wenn ich beschworen werde, beschwöre 1 zufällige Hülle.","","„Hüte dich vor jenen auf diesen unheimlichen Inseln, die lächeln. Vielleicht sind sie noch nicht lange genug hier, um die Brutalität dieses Orts zu begreifen. Vielleicht sind sie verrückt. Vielleicht sind sie etwas gänzlich anderes. Aber hüte dich.“\n– Notizen von Jens Tommen","Einheit",[],["Schatteninseln"],"GEWÖHNLICH"],"06NX022":["Verantwortung des Legionärs","Ziehe einen Verbündeten mit 5+ Stärke oder erhöhe einen Verbündeten in dieser Runde auf 5 Stärke.","","„Nur wenige erhalten die Gelegenheit, in der trifarianischen Legion zu dienen. Verschwende diese Chance nicht.“\n– Trifarianische Beurteilerin","Zauber",[],["Noxus"],"EPISCH"],"06NX019":["Noxianischer Überläufer","Angriff: Erhöhe meine Stärke in dieser Runde auf die des stärksten ausgerüsteten Verbündeten.","","„Hab wieder diese Träume, mit dieser Stimme im Dunkeln. Zehn Jahre … ein ganzes verfluchtes Jahrzehnt als gehorsamer Hund des Imperiums. Geh dorthin. Töte das. Und wofür? Den Ruhm von Noxus? Ruhm ist eine hübsche Lüge und ich bin auf sie hereingefallen. Aber nicht mehr. Kayn hat mir einen anderen Weg gezeigt und er führt zur Rache.“\n– Tagebuch von Royce, der Schlächter","Einheit",["KULTIST"],["Noxus"],"GEWÖHNLICH"],"06NX023":["Ionische Meisteranglerin","Wenn ich beschworen werde, improvisiere ich.","","Trisks Leben geriet aus den Fugen, als sie bei ihrem Angelturnier irgendwie einen prustenden Jax am Haken hatte. Er weigert sich, über den Vorfall zu sprechen, aber das Seeungeheuer, vor dem Trisk ihn gerettet hat, wird jedes Mal größer, wenn sie die Geschichte erzählt.","Einheit",["WAFFENMEISTER"],["Noxus","Ionia"],"GEWÖHNLICH"],"06NX044":["Schleichende Fadenzieherin","Angriff: Erhöhe die Stärke anderer angreifender Verbündeter in dieser Runde auf meine Stärke.","","„Eine gute Mutter bringt ihren Kindern das Jagen bei. Aber eine bessere Mutter … jagt für sie.“\n– Elise","Einheit",["SPINNE"],["Noxus"],"GEWÖHNLICH"],"06NX041":["Scharlachrote Taube","Unterstützung: Verursache 1 Schaden an meinem unterstützten Verbündeten, um mir in dieser Runde +1|+1 zu geben.","","„Es macht Spaß, die Vögel zu füttern. Ich habe mit dem armen Feoward gewettet, dass sie so gierig wie ein Bruchzahnbasilisk Blut trinken würden, und siehe da: Die Tauben sind wahre Noxianer!“\n– Edvin Cortain, Scharlachroter Kurator","Einheit",["VOGEL"],["Noxus"],"EPISCH"],"06NX020":["Die Balliste der Düsteren","Du kannst 8 Mana ausgeben, um mich als Naganeka von Zuretta auszuspielen.","","Die Steppen des östlichen Valoran waren als unfruchtbar bekannt; ungeeignet, das Volk der Noxii zu beheimaten oder zu ernähren. Doch als die Jahrhunderte verstrichen, wurde ein neues Imperium gegründet, das sich ausdehnen wollte. Karge Länder wurden mithilfe neuer Ackerbautechniken wieder fruchtbar und Waffen, die einst sicher vergraben geglaubt waren, wurden wieder freigelegt.","Ausrüstung",["DÜSTERER"],["Noxus"],"EPISCH"],"06NX039":["Festmahl der Nachtschwärmer","Verursache 2 Schaden an einem Verbündeten, um Verbündeten in dieser Runde +2|+0 zu geben.","","„Es ist erst ein Festmahl, wenn jemand zu schreien beginnt. Also schrei, mein Junge.“\n– Vladimir","Zauber",[],["Noxus"],"GEWÖHNLICH"],"06NX026":["Großhämmer","","","Vessid ist nicht der schnellste Vergelter von Bordent, aber wenn seine Großhämmer ihr Ziel finden, bleibt von seinen Gegnern nicht viel übrig, das zurückschlagen könnte.","Ausrüstung",[],["Noxus"],"GEWÖHNLICH"],"06NX034":["Wütende Klinge","Ein ausgerüsteter Verbündeter schlägt einen Gegner.","","„Brüder im Blut, wieder vereint!“\n– Noxianischer Überläufer","Zauber",["KULTIST"],["Noxus"],"SELTEN"],"06NX036":["Runenknappe","Wenn ich beschworen werde, schmiede neu.","","Über Monate hatte er in Kälte und Regen geschuftet, eine undankbare Aufgabe ohne absehbares Ende. Und dennoch kam es. Endlich würde er etwas aus sich machen.","Einheit",[],["Noxus"],"GEWÖHNLICH"],"06NX027":["Brutales Gefecht","Zerstöre die Ausrüstung eines Gegners. Ein Verbündeter und dieser Gegner schlagen sich gegenseitig.","","„Eins, zwei, da schreit er,\nder Soldat im Feuer brennt,\ndrei, vier, wie er lodert,\nweil Tibbers jedes Feuer kennt!“\n– Annie","Zauber",[],["Noxus"],"SELTEN"],"06MT035":["Xolaani die Blutweberin","Ich habe +2|+2 für jeden Verbündeten, der mit erhöhter Stärke gestorben ist.\nVerstärkt (16): Verwandle mich in Xolaani, Geißel des Aspekts.","","Xolaani sah zu, als Anaakco auf seine Knie fiel, unterworfen von dem Gegner, den er so verzweifelt zu zerstören versuchte. Langsam glich sich sein Herzschlag an den der anderen an. Ein weiteres Herz zu kontrollieren. Ein weiterer Körper zu befehligen.","Einheit",["DÜSTERER"],["Targon"],"EPISCH"],"06MT007":["Seraphischer Wyvern","Verstärkt (5): Überwältigen.","","„Ah, jetzt sehe ich es … die Formen im Berg waren nur Spuren – Verbindungen für die Wesen aus dem Reich hinter den Sternen …“\n– Wissenshüter Skai’en","Einheit",["DRACHE"],["Targon"],"SELTEN"],"06MT037":["In Stahl versiegelt","Vernichte einen Verbündeten und erschaffe 1 Entfremdete Form mit seinen Werten.","","Die gefallenen Götterkrieger, die in diesen Waffen eingesperrt sind, konnten nicht einfach besiegt werden, also wurden sie stattdessen gefangen.","Zauber",[],["Targon"],"SELTEN"],"06MT031":["Mihira, Aspekt der Gerechtigkeit","Rundenende: Gewähre Verbündeten auf dem Spielfeld und auf der Hand +1|+1.\nVerstärkt (5): Ungreifbar, Lebensraub und Überwältigen.","","„Manche verehren die Aspekte als Götter. Andere sehen sie als Boten aus der jenseitigen Welt. Wieder andere fürchten sie … und vielleicht zu Recht.“\n– Wissenshüter Skai’en","Einheit",[],["Targon"],"EPISCH"],"06MT010":["Göttlicher Richtspruch","Gib einem Verbündeten in dieser Runde „Ich kann keinen Schaden erleiden oder sterben“.\nGib allen Verbündeten in dieser Runde +1|+0.","","„Schutz der rechtschaffenen Flamme!“ – Kayle","Zauber",[],["Targon"],"SELTEN"],"06MT016":["Geflügelter Bote","Verstärkt (3): Ungreifbar.","","„Ja … ich erkenne dich. Die Nachricht, die du überbringst … sie kann nur ein Ruf sein.“\n– Ryze","Einheit",[],["Targon"],"GEWÖHNLICH"],"06MT015":["Läuternde Flammen","Gewähre 2 Verbündeten auf der Hand +2|+2.","","„Das Böse wird brennen!“\n– Kayle","Zauber",[],["Targon"],"GEWÖHNLICH"],"06MT042":["Dämmerblauer Beschützer","Tagesanbruch: Gib Verbündeten mit Tagesanbruch in dieser Runde +1|+1.\nNachteinbruch: Gewähre Verbündeten mit Nachteinbruch +1|+0.","","Im Zwielicht und kurz vor Sonnenaufgang ist die Eule zu hören. Ihr Ruf erinnert an die Schwellenorte zwischen Dämmerung und Tagesanbruch.","Einheit",["VOGEL"],["Targon"],"SELTEN"],"06MT008":["Kayle","Ich habe +1|+0 für jedes Mal, wenn ein Verbündeter mit erhöhter Stärke angegriffen hat.\nWenn ich beschworen werde, gewähre Verbündeten +1|+0.\nVerstärkt (6): Direktangriff.","Rundenbeginn: Ich habe 11+ Stärke.","„Die Demacianer kennen sie als die Geflügelte Beschützerin, doch jene von uns, die in Targon unter der Schatzkammer der Sterne leben, kennen sie als die Tochter der Gerechtigkeit, die einen göttlichen Zweck verfolgt und ein Schwert aus Sternenfeuer führt.“\n– Wissenshüter Skai’en","Einheit",[],["Targon"],"Champion"],"06MT004":["Wandernder Hirte","Ausspielen: Wähle einen Verbündeten, der dann improvisiert. Wenn nicht, improvisiere ich.","","Jax hat Chaska geholfen, seine Herde vor einem tobendem Feenvolk zu retten. Anschließend hat Chaska Jax vor einem tobendem Feenvolk gerettet. Sie reisen gemeinsam, solange keiner von ihnen eigene Wege einschlägt.","Einheit",["WAFFENMEISTER"],["Targon","Bandle"],"GEWÖHNLICH"],"06MT017":["Göttlicher Beauftragter","Verstärkt (3): Lebensraub.","","„Man sagt, dass Mihira einen Teil von sich selbst zurückließ, als sie diesen Ort verließ – eine heilige, hell lodernde Flamme. Jahrelang hat meine Familie dieses Feuer gehegt, in der Hoffnung, dass sie eines Tages zurückkehrt.“","Einheit",[],["Targon"],"SELTEN"],"06MT040":["Der Schutz der Weite","Sobald du in diesem Spiel einen Verbündeten ausgerüstet hast, koste ich 2 weniger.\nGib einem Verbündeten in dieser Runde Zauberschild.","","Blicke in den Nachthimmel und konzentriere dich auf einen kleinen Streifen am Firmament. Stell dir jetzt all jene vor, die dort gelebt haben, das gesamte Wissen und die gesamte Erfahrung unzähliger Jahrtausende. Stell dir vor, wie all diese Informationen in einem Splitter aufbewahrt sind, der in deine Handfläche passt. Wie viel Weisheit du damit besitzen würdest. Wie viel Macht.","Zauber",["KULTIST"],["Targon"],"SELTEN"],"06MT034":["Himmlischer Einschlag","Vernichte eine Einheit oder ein Wahrzeichen. Heile deinen Nexus um 3.","","„Wer eilt zu uns in unserer Stunde der Not?“\n– Shurimanischer Ältester","Zauber",[],["Targon"],"SELTEN"],"06MT033":["Drakonische Bande","Mein Träger ist ein Drache.","","Viele rufen die Macht der Drachen, doch sie manifestiert sich in Runeterra auf verschiedenste Weise. Wer die Macht eines himmlischen Drachen anruft, entdeckt möglicherweise eine innere Stärke, die so hell und heiß brennt wie ein Stern.","Ausrüstung",[],["Targon"],"GEWÖHNLICH"],"06MT053":["Großzügige Juwelenschmiedin","Wenn du einen Zauber ausspielst, gewähre einem zufälligen Verbündeten auf der Hand +1|+1.","","Mit gütigem, aber hinter einem Schleier verborgenem Blick bietet sie jenen, die sich auf ihre Pilgerreise vorbereiten, kristallene Gebetsperlen an. Sie verlangt nichts von ihnen, denn der Preis wird auf dem Berg bezahlt.","Einheit",[],["Targon"],"EPISCH"],"06MT006":["Der Magnetstein der Düsteren","Unterstützung: Gewähre meinem unterstützten Verbündeten +1|+1.\nDu kannst 8 Mana ausgeben, um mich als Horazi auszuspielen.","","Vielleicht dachten jene, die die Düstere gefangen hielten, dass Horazis aufbrausender Wille eingedämmt sei, wenn sie die legendäre Kriegerin in einer Kugel aus Sternenmetall begraben würden. Doch als sich ihr General regte, erwachte auch Horazi, und sie erkannte, dass selbst die uralten Beschützer des Targon von Versprechen aus der Ferne verleitet werden konnten.","Ausrüstung",["DÜSTERER"],["Targon"],"EPISCH"],"06MT018":["Gesetzeshüter","Ausspielen: Betäube Gegner mit weniger Stärke als ich.","","„Ich fürchte, der Tag ist endlich gekommen … die Gerechtigkeit kehrt auf goldenen Flügeln zurück, und sie bringt eine strahlende Armee mit sich!“\n– Wissenshüter Skai’en","Einheit",[],["Targon"],"GEWÖHNLICH"],"06MT052":["Himmlischer Segen","Gewähre einem ausgespielten Verbündeten und einem Verbündeten auf der Hand Kampfgeist.","","„Durch göttliche Gnade.“\n– Kayle","Zauber",[],["Targon"],"GEWÖHNLICH"],"06MT032":["Lunari-Kultistin","Wenn ich beschworen werde oder sobald du in diesem Spiel einen Verbündeten ausgerüstet hast, erschaffe 1 Juwel auf der Hand.","","Sie wollte den Konflikt zwischen Sonne und Mond, zwischen Tag und Nacht beilegen. Der Bogen bot Macht, aber für einen schrecklichen Preis – sie verschwor sich ihm dennoch, in der Hoffnung, der Krieg würde dadurch endgültig beendet werden. ","Einheit",["KULTIST"],["Targon"],"GEWÖHNLICH"],"06RU008":["Jax","Herkunft: Großmeister der Waffen.\nAutomatisch ausrüsten: Das Licht von Icathia.","Ausgerüstete Verbündete haben mit 16+ Gesamtstärke angegriffen.","Vor Jahrhunderten verlor Jax seine Heimat an die Leere. Jetzt reist er durch die Welt auf der Suche nach Kriegern mit der Willensstärke – und der Unverfrorenheit –, sich eines Tages diesem schrecklichen Feind zu stellen.","Einheit",["WAFFENMEISTER"],["Runeterra"],"Champion"],"06RU006":["Ryze","Herkunft: Der Runenmagier.\nWenn ich beschworen werde oder bei Rundenbeginn: Erschaffe 2 Erforschen der Vergangenheit in deinem Deck.","Ich sehe 3+ verschiedene Weltrunen.","Ryze erklomm den Grat, begleitet von Kayles stillem Diener. Er blickte hinunter auf ein vom Krieg vernarbtes Land und sah unten die Monster der Düsteren Krieg führen. Jahrhundertelang hatte er zugesehen, als die Menschheit von einer Katastrophe in die nächste schlitterte. Was, dachte er, wenn seine Anstrengungen zwecklos waren und Runeterra zum Sterben verurteilt war?","Einheit",[],["Runeterra"],"Champion"],"06RU005":["Kayn","Herkunft: Der Schatten des Todes.\nAutomatisch ausrüsten: Die Kriegssense der Düsteren.\nWenn ich einen Gegner töte, heile mich um 2.","Ich habe zweimal zugeschlagen. Wenn ich eine Stufe aufsteige, rufe mich zurück.","Als ein weiterer Körper fiel, stieß Kayn ein hämisches Lachen aus, in dem Wissen, dass er bald die zweite Waffe der Düsteren entfesseln würde, die unterhalb lag. In ihm wuchs Rhaasts Erwartung an. Er wusste, dass Kayns Ende nahte.","Einheit",["DÜSTERER"],["Runeterra"],"Champion"],"06RU026":["Aatrox","Herkunft: Der Weltenvernichter.\nAutomatisch ausrüsten: Die Klinge der Düsteren.\nWenn ich beschworen werde oder zuschlage: Heile deinen Nexus um 2 und erschaffe 1 Weltenvernichter auf der Hand, wenn du keinen hast.","Du hast Weltenvernichter ausgespielt.","Sogar über Kontinente hinweg fühlte Aatrox, dass sie erwachte. Wie der Hass immer noch brannte. Er hatte bereits ihre Statuen zerstört, jetzt könnte er einen letzten Krieg gegen den Feigling von Icathia führen und dieser erbärmlichen Existenz ein Ende setzen, wenn er sie vernichtete.","Einheit",["DÜSTERER"],["Runeterra"],"Champion"],"06RU009":["Varus","Herkunft: Der Pfeil der Vergeltung.\nAutomatisch ausrüsten: Der Bogen der Düsteren.","Du hast 7+ Verbündete anvisiert.","Was wäre, wenn der Mensch, der zum Düsteren wurde, sich mit der Zeit an sich selbst erinnerte, angeregt durch die sterblichen Stimmen in seinem Inneren? Was wäre, wenn er diese Stimmen nicht völlig überwinden, sondern ihnen stattdessen glauben würde?","Einheit",["DÜSTERER"],["Runeterra"],"Champion"],"06FR004":["Lehrling des Waffenschmieds","Wenn du zum ersten Mal einen Verbündeten ausrüstest, schmiede ihn.","","Ornn erschuf die lebende Schmiede vor vielen, vielen Jahren und sucht erst seit Kurzem nach ihr. Er hätte nie gedacht, dass sie nach einem neuen Besitzer suchen und alleine davonziehen würde.","Einheit",[],["Freljord"],"GEWÖHNLICH"],"06FR011":["Ornn","Ausspielen: Rüste mich mit einer exakten Kopie der Ausrüstung eines Verbündeten oder der stärksten Ausrüstung auf der Hand aus.\nAngriff: Schmiede mich zweimal.","Ein Verbündeter hat auf einen Schlag mit 8+ Schaden zugeschlagen.","Würde jemand Ornn fragen, warum er so wenig Geduld hatte, würde er einfach antworten, dass er diese sehr wohl besaß. Enorme Geduld sogar, weshalb seine Arbeit unvergleichlich war. Er hatte ganz einfach keine Geduld für LEUTE. Aber niemand fragte, also antwortete er auch nie.","Einheit",[],["Freljord"],"Champion"],"06FR035":["Immer hilfsbereit","Gib einem Verbündeten in dieser Runde +0|+3. Wenn er verletzt ist, gib ihm stattdessen +2|+3.","","„Keine Angst, kleiner Poro. Ich bin bei dir!“\n– Braum","Zauber",[],["Freljord"],"GEWÖHNLICH"],"06FR034":["Die schonungslose Kälte","Friere den stärksten Gegner ein. Falls du in diesem Spiel einen Verbündeten ausgerüstet hast, kopiere mich.","","Anaakca bewegte sich so schnell, dass Freljord selbst ihr zu folgen schien. Wer ihr Massaker überlebte, spürte schon bald, wie seine Haut einfror und sein Herz stehen blieb.","Zauber",["KULTIST"],["Freljord"],"GEWÖHNLICH"],"06FR018":["Der Speer der Düsteren","Angriff: Gewähre den obersten 2 Verbündeten in deinem Deck +1|+1.\nDu kannst 8 Mana ausgeben, um mich als Anaakca auszuspielen.","","„Kriegsmutter, der Griff des Winters hat sich geschlossen. Die Avarosa sind aus ihren Außenposten geflohen. Im Norden ist das Meer … unser einziger Weg führt uns in den Osten.“\n„Hör nicht auf ihn, Kriegsmutter. In dieser Richtung ist die Blässe und hinter ihr die flüsternde Wildnis. Besser sterben, als dieses verfluchte Land betreten.“\n„Wie glücklich für euch beide, dass ihr nicht über das Schicksal meines Volkes entscheiden müsst.“\n„Das stimmt, Kriegsmutter. Aber vielleicht gibt es einen dritten Weg. Lass mich in den Osten reisen. Besser ein Späher fällt der Finsternis anheim als unser ganzes Volk.“\n– Kriegsmutter Sejuani im Rat mit ihren Generälen","Ausrüstung",["DÜSTERER"],["Freljord"],"EPISCH"],"06FR012":["Berufene Kunsthandwerkerin","Wenn ich beschworen werde, erschaffe 1 Zeit und Hingabe auf der Hand.","","„Meine Mutter hat mir von Ornn erzählt, so wie ihre Mutter ihr erzählt hatte, und davor ihre Mutter … und jetzt werde ich dir von ihm erzählen. Hör gut zu. Unterbrich mich nicht. Vor langer Zeit, hinter einem weiten, heißen, tosenden Meer …“","Einheit",[],["Freljord"],"GEWÖHNLICH"],"06FR005":["Ornns Schmiede","Wenn ich beschworen werde oder Rundenbeginn: Erschaffe 1 flüchtige Zeit und Hingabe auf der Hand.","","Alleine in der Schmiede in der Wiege des Feuers mit nichts als dem Geräusch des langsam strömenden geschmolzenen Flusses unter ihm und dem Klang des Hammers auf einem Amboss … das gefiel ihm ziemlich.","Wahrzeichen",[],["Freljord"],"SELTEN"],"06FR040":["Beschützer der Stämme","Wenn ich beschworen werde, gewähre Verbündeten +1|+1 für jede unterschiedliche Unterart, die du in diesem Spiel beschworen hast.","","„… und da war eine GROẞE Kreatur, die sich um aaaaaalle KLEINEN Kreaturen kümmerte …“\n– Ingvar, die Jüngere","Einheit",[],["Freljord"],"EPISCH"],"06FR020":["Zerbrechen","Verursache 1 Schaden an ALLEM oder zerstöre die Ausrüstung einer Einheit.","","Die Kälte verschont nichts und niemanden.","Zauber",["ELEMENTAR"],["Freljord"],"SELTEN"],"06FR027":["Schlitterndes Wollmammut","Verstärkt (8): Erholung.","","Trolle sind zwar nicht gerade für ihre Intelligenz bekannt, aber sie können überraschend raffiniert sein.","Einheit",[],["Freljord"],"SELTEN"],"06FR032":["Feuerblut-Geschenk","Heile deinen Nexus um 4 und gewähre allen Verbündeten und Ausrüstungen in deinem Deck +1|+1. Ziehe 1 von ihnen.","","„Komm, wärme dich am Feuer.“\n– Feuerblut-Schmiedeheiler","Zauber",[],["Freljord"],"EPISCH"],"06FR022":["Feuerbalg","Schmiede einen Verbündeten und verursache 1 Schaden an ALLEN Einheiten, dann wiederhole das einmal.","","„Ein eiserner Wille wird geschmiedet!“\n– Ornn","Zauber",["ELEMENTAR"],["Freljord"],"SELTEN"],"06FR021":["Schmollender Poro","Verstärkt (3): Überwältigen, Erholung und Robust.","","„Na los, du musst deine Medizin nehmen! Erst dann geht’s dir wieder besser!“\n– Ingvar die Jüngere","Einheit",["PORO"],["Freljord"],"GEWÖHNLICH"],"06FR023":["Geschmiedeter Koloss","Wenn ich zum ersten Mal ausgerüstet werde, erschaffe eine Kopie mit 4 Kosten von mir auf der Hand. Gewähre ihr die Werte der Ausrüstung.","","Obwohl er es niemals zugeben würde, war Ornn mit den Kolossen durchaus zufrieden. Sie erfüllten den Zweck, denen er ihnen aufgetragen hatte, und vor allem sprachen sie nicht.","Einheit",[],["Freljord"],"EPISCH"],"06FR008":["Feuerblut-Schmiedeheiler","Ausspielen: Schmiede einen Verbündeten zweimal und heile ihn und deinen Nexus um 3.","","Die Feuerblüter waren weg, alle von ihnen, als Ornn beschloss, die Welt zu verlassen. Generationen verstrichen und ihr Name war so gut wie vergessen. In letzter Zeit kamen aber die Erzählungen von Ornn wieder ans Tageslicht und man flüsterte davon, dass einige wieder zu den Traditionen der Feuerblüter zurückgekehrt waren.","Einheit",[],["Freljord"],"GEWÖHNLICH"],"06FR009":["Erfahrener Waffenschmied","Ausspielen: Schmiede einen Verbündeten.","","Als Fiske zum ersten Mal einen Lehrling in Betracht zog, stellte er sich jemanden vor, der seinem Handwerk ergeben war, stark und geschickt. Kindra war nichts davon. Sie war eine Tagträumerin. Sie wollte lieber spielen als arbeiten. Sie war ständig mit ihrer kleinen Schildkröte beschäftigt. Allerdings … lernte sie. Und das zählte.","Einheit",[],["Freljord"],"GEWÖHNLICH"],"06FR024":["Knochenkeule","","","„Zersplittern!“\n– Tarkaz der Stammeslose","Ausrüstung",[],["Freljord"],"GEWÖHNLICH"],"06FR017":["Eistal-Kultist","Deine ausgerüsteten Verbündeten haben Überwältigen.","","Die Winterklaue hatte recht. Die Avarosa WAREN zu verweichlicht. Es war Zeit für einen neuen Anführer, der Freljord nicht durch Frieden vereinen, sondern darüber herrschen will. ","Einheit",["KULTIST"],["Freljord"],"SELTEN"],"06FR041":["Berührung des Winters","Erhalte einen leeren Manastein. Erleuchtet: Ich koste 1. Ziehe 1.","","Eigentümliche Runen pulsieren aus den Facetten des Juwels in deiner Hand. Mit einem schaurigen Blitz strahlt ihr Licht aus der Oberfläche und ergreift eisig deinen Arm. Aber dieser Frost ist nicht kalt, sondern belebend, als würde die Kälte selbst dich mit ihrer Essenz erfüllen. ","Zauber",["ELEMENTAR"],["Freljord"],"EPISCH"],"06FR036":["Wilde Mystik","Erhalte einen leeren Manastein.\nBeschwöre 1 Animalischer Mystiker.","","„Die Geister. Die Sterne … Sie führen uns erneut zusammen.“\n– Hyara die Allsehende","Zauber",[],["Freljord"],"EPISCH"],"06BC015":["Norra","Nexusschlag: Verstecke 1 Geheimnisvolles Portal in den obersten 4 Karten deines Decks.","Du hast 6+ erschaffene Verbündete beschworen.","Norra arbeitete schnell, immer ihre Heimat in den Gedanken. Portalarbeit war bekanntermaßen eine knifflige Angelegenheit, und sie hatte noch nicht mal ihre erste Tasse Tee. Aber Norra liebte Rätsel, besonders solche, durch die sie sich hoffnungslos in kleinen Dimensionen zwischen Raum und Zeit verlor. Sie arbeitete schneller und dachte dabei an ihre Katze, die sich bestimmt Sorgen um sie machte und auf ihr Abendessen wartete.","Einheit",["YORDLE"],["Bandle"],"Champion"],"06BC043":["Porogeschichten","Erschaffe 3 zufällige Poros mit 1 Kosten auf der Hand.","","„… UND DANN MEINTE DER PORO SO: ‚HEY, DU, ICH WILL AUCH SNACKS!‘ ALSO HAM SICH DIE POROS BEI DER GROẞEN POROVERSAMMLUNG GETROFFEN UND ÜBER DIE GANZEN POROPROBLEME GEREDET WIE WO SIN DIE SNACKS UND WARUM GIBT ES NICHT MEHR POROS UND …“\n– Ingvar die Jüngere","Zauber",[],["Bandle"],"GEWÖHNLICH"],"06BC051":["Bananen-Blaster","Ausspielen: Verursache Schaden in Höhe meiner Stärke an einer Einheit.","","„HEY! BRAUCHT JEMAND EINE DOSIS MAGNESIUM?“\n– Nanners, Augenblicke vor dem „Vorfall“ ","Einheit",["YORDLE"],["Bandle"],"SELTEN"],"06BC047":["Eines für Alle","Gib einem ausgerüsteten oder begleiteten Verbündeten in dieser Runde die Werte und Schlüsselwörter seiner Ausrüstung oder Begleitung, und wechsle sie zu einem anderen Verbündeten.","","Man möchte meinen, ein Schäfer hätte nichts auf dem Schlachtfeld verloren, aber sein Können ist überraschend nützlich. Man muss sich nur die Kämpfer als Schafe vorstellen, die gehütet werden wollen.","Zauber",["WAFFENMEISTER"],["Targon","Bandle"],"SELTEN"],"06BC019":["Die Teemeisterin","Wenn ich beschworen werde, verstecke 1 Geheimnisvolles Portal in den obersten 4 Karten deines Decks.","","Ashane war einst eine berühmte Teemacherin, bevor sie sich in Weltenend wiederfand. Als sie mit neuen Geschmacksrichtungen experimentierte, wurde sie von einer ungünstigen Mischung aus zwei Blättern in einen tiefen Schlummer versetzt – sie träumte seltsame Träume von merkwürdigen Kreaturen und unmöglichen Strukturen, deren Silhouetten vor einem endlosen Horizont aufragten. Als sie aber aufwachte, stellte sie fest, dass es nicht nur ein Traum war.","Einheit",["FEE"],["Bandle"],"GEWÖHNLICH"],"06BC029":["Der Stab der Düsteren","Schlag: Fülle 1 Zaubermana wieder auf.\nDu kannst 8 Mana ausgeben, um mich als Baalkux auszuspielen.","","Der Bandlewald schien perfekt dafür geeignet zu sein, eine Waffe der Düsteren zu verstecken, haben sie behauptet. Im Bandlewald verirrt man sich aufs Schlimmste und die Yordle wissen, dass sie sich einer derart niederträchtigen Bosheit nicht nähern dürfen. Aber die Targonier waren sich der Wirksamkeit solch seltsamer Magie und ihren Auswirkungen auf die örtliche Pflanzenwelt nicht bewusst.","Ausrüstung",["DÜSTERER"],["Bandle"],"EPISCH"],"06BC038":["Schlagartiger Ausbruch","Sobald du in diesem Spiel einen Verbündeten ausgerüstet hast, koste ich 2 weniger.\nErhöhe einen Verbündeten in dieser Runde auf 4|4.","","„In uns steckt so viel Macht.“\n– Varus","Zauber",["KULTIST"],["Bandle"],"SELTEN"],"06BC017":["Portalpurzeln","Verstecke 2 Geheimnisvolle Portale in den obersten 4 Karten deines Decks.\nZiehe 1.","","„Ich sollte öfter die Niedrigen Wege nehmen! Ich Dummerchen stoße mir ständig meinen Kopf an …“\n– Norra","Zauber",[],["Bandle"],"SELTEN"],"06BC020":["Origamischneider","Gib mir +1|+0 für jede deiner Fallen oder Segen, die in dieser Runde aktiviert wurden.","","Die Magie der Papierkunst kann etwas unberechenbar sein. Sie dreht sich gleichermaßen um die Absicht, etwas Neues zu erschaffen, als auch um das Verlangen der Schöpfung, geformt zu werden.","Ausrüstung",[],["Bandle"],"SELTEN"],"06BC028":["Blühender Kultist","Sobald du in diesem Spiel einen Verbündeten ausgerüstet hast, gewähre mir Ungreifbar.","","Person, Pflanze, Tier … der zerstörerische Einfluss des Düsteren verschont nichts und niemanden.","Einheit",["KULTIST"],["Bandle"],"GEWÖHNLICH"],"06BC021":["Krimskramskonstrukt","Letzter Wunsch: Verstecke 1 Geheimnisvolles Portal in den obersten 4 Karten deines Decks.","","Er wurde erst vor einem Tag geboren, doch Marv – wie ihn Norra liebevoll nannte – war sehr stolz darauf, ihr als Assistent zu dienen. Allerdings bestand er darauf, als „Krimskrams“ und nicht als „Müll“ bezeichnet zu werden, da Letzteres einen negativen Beiklang hatte.","Einheit",["FEE"],["Bandle"],"GEWÖHNLICH"],"06BC042":["Seltsame Gestaltenwandler","Wenn sich ein verbündeter Begleiter in einen anderen Begleiter verwandelt, verwandle mich in eine exakte Kopie von ihm.","","Vom Chamäleon gesehen, vom Chamäleon kopiert.","Einheit",[],["Bandle"],"SELTEN"],"06BC023":["Verwirrende Wegweiser","Nimm einen schnellen oder langsamen Zauber zurück auf die Hand oder zerstöre die Ausrüstung einer Einheit. Ziehe 1.","","„Du liebes bisschen! War es diese Richtung oder diese … oder überhaupt diese da? Ich kann mir das nie merken!“\n– Norra","Zauber",[],["Bandle"],"SELTEN"],"06BC041":["Skrappys Teilesammelsurium","Wenn ich abgeworfen werde, beschwöre mich. Wenn du einen Mecha-Yordle beschwörst, gewähre ihm ein zufälliges Schlüsselwort.","","Groß oder klein, unbelebt oder nicht, wenn du ein Dingsda gefunden haben willst, versuche es bei Skrappy! Aber frage sie nicht, wo es ist, sie glaubt nämlich nicht an Inventare.","Wahrzeichen",[],["Bandle"],"SELTEN"],"06BC011":["Magische Reise","Verstecke 1 Geheimnisvolles Portal in den obersten 4 Karten deines Decks und verstecke 1 Glocke auf der obersten Karte in deinem Deck.","","Bard streift durch die verschiedenen Welten, wie es ihm beliebt. Er lauscht im Wissen, dass sich ein großer Konflikt nähert – einer, der das Lied der Schöpfung verstummen lassen könnte.","Zauber",[],["Bandle"],"GEWÖHNLICH"],"06BC032":["Umfangreiche Sammlung","Verstecke für jeden Verbündeten 1 Geheimnisvolles Portal und 3 Glocken in den obersten 10 Karten deines Decks und verstecke 1 Blitzbombenfalle und 3 Giftige Poffpilze im gegnerischen Deck.","","„Portale, Portale überall!“\n– Norra","Zauber",[],["Bandle"],"EPISCH"],"06BC024":["Aufseher von Weltenend","Wenn in einer Runde zum ersten Mal eine deiner Fallen oder Segen aktiviert wird, gib Verbündeten in dieser Runde +1|+1 und Einschlag.","","Gaspar war der erste Yordle, der in Weltenend ankam. Viele Jahre lang wanderte er alleine inmitten der verschlungenen Pfade und Portale, die alle nirgendwohin zu führen schienen. Da er niemandem das gleiche Schicksal wünscht, hilft er jetzt verirrten Reisenden, ihren Weg nach Hause zu finden.","Einheit",["FEE"],["Bandle"],"SELTEN"],"06BC033":["Mechapulverisierer","Wirf zum Ausspielen 1 Karte ab.","","„Seht! Aus dem Wrack einer versunkenen Fähre habe ich den Boxhandschuh geborgen. Aus den Tiefen der Stadt, die sie Zhaun nennen, habe ich Federn geholt und in den Schmieden von Demacia habe ich Metall gefunden! Dies ist wahrlich eine Schöpfung der Welt!“\n– Paparo der Große","Ausrüstung",[],["Bandle"],"GEWÖHNLICH"],"06BC016":["Lebende Bibliothek","Wenn ich beschworen werde und in dieser Runde eine deiner Fallen oder Segen aktiviert wurde, ziehe 1.","","Da er es als seine Pflicht sieht, sich unermessliches Wissen anzueignen, sammelt er Folianten von verschiedenen Reisenden, die durch Weltenend gekommen sind. Leider scheint ihm all das Wissen zu Kopf gestiegen zu sein.","Einheit",["FEE"],["Bandle"],"GEWÖHNLICH"],"06IO044":["Unbeschwerte Himmelssängerin","Wenn ich beschworen werde, senke die Kosten von Zaubern in deinem Deck um die Hälfte (aufgerundet).","","„Manche suchen mit Meditation nach Frieden. Andere suchen nach Wissen zur Selbstbetrachtung. Jene, die ihre Mitte durch Ausdruck finden, durch Kreation – jene können auch anderen Frieden bringen.“\n– Karma","Einheit",[],["Ionia"],"EPISCH"],"06IO013":["Wuju-Stil","Gib einem Verbündeten in dieser Runde +2|+0.\nErschaffe 1 Meditieren auf der Hand.","","„Ein Schlag von vielen.“\n– Master Yi","Zauber",[],["Ionia"],"SELTEN"],"06IO023":["Der Fächer der Düsteren","Angriff: Beschwöre 1 angreifenden Drachling.\nDu kannst 9 Mana ausgeben, um mich als Praa der Grenzgänger auszuspielen.","","„In der Brücke zwischen den Welten habe ich seit langer Zeit einen Schatten verspürt, der vor stillem Zorn pulsiert. Ich weiß es zwar besser, als ihm in die Finsternis nachzujagen, aber dieser Puls wurde in letzter Zeit stärker, schneller, und ich fürchte, dass die Kreaturen des Geisterreichs schon bald nach ihm suchen werden.“\n– Shen","Ausrüstung",["DÜSTERER"],["Ionia"],"EPISCH"],"06IO029":["Der Geist des Wuju","Fluss: Ich koste 2 weniger.\nWenn ich beschworen werde, ziehe einen Zauber.","","„Meister Doran glaubte, dass jedes Auge des Geists des Wuju einzigartige Einblicke in das Wesen einer Person gewährt. Aber so sehr ich mich auch bemühe, die Linsen meines Helms nehmen nur verschiedene Grüntöne wahr. Was übersehe ich?“\n– Lui, Schülerin von Doran","Einheit",[],["Ionia"],"GEWÖHNLICH"],"06IO037":["Die Schwarze Flamme","Ausspielen: Halte einen Verbündeten fest. Wenn du in einer Runde zum ersten Mal angreifst, beschwöre eine angreifende vergängliche Kopie von ihm.","","„Was ist schon ein Leben, wenn nicht nur ein Schatten der Existenz? Nimm die Finsternis in dich auf und du wirst ewig leben.“\n– Zed","Wahrzeichen",[],["Ionia"],"EPISCH"],"06IO031":["Seelenschwert","Fluss: Ich koste 2 weniger.","","„Klinge und Körper.“\n– Master Yi","Ausrüstung",[],["Ionia"],"GEWÖHNLICH"],"06IO014":["Vastayanischer Schüler","Nexusschlag: Rufe mich zurück und verwandle mich in Wind der Schimon.","","Ting grinste, als die Angreifer in den Tempel strömten. Endlich hatte er die Gelegenheit, sich selbst zu beweisen! Erst Wukong, dann Yi … beide hatten seinen Talenten keine Beachtung geschenkt. Sollen doch die anderen laufen und nach ihrem „Meister“ suchen! Er war bereit. Er war der Wind der Schimon. ","Einheit",[],["Ionia"],"EPISCH"],"06IO008":["Master Yi","Rundenbeginn: Senke die Kosten eines Zaubers auf der Hand um 1 und Fluss: Gewähre allen verbündeten Master Yis überall +2|+0.","Verbündete Master Yis haben 12+ Schaden verursacht.","Master Yis Gedanken schweiften zur Waffe der Düsteren. Seit ihrer Entdeckung war er vor einer schrecklichen Vorahnung erfüllt. Einige seiner Schüler hatten ein zu reges Interesse an ihr gezeigt, also ließ er die gebogenen Klingen tief im Tempel verborgen bewachen. Mit etwas Anstrengung verdrängte er diese Gedanken aus seinem Kopf und fuhr mit seiner Meditation fort. Alles, was zählte, war, die Lehren von Wuju weiterzugeben, und Jun zeigte großes Potenzial.","Einheit",[],["Ionia"],"Champion"],"06IO040":["Technik der Zwillingswinde","Wähle einen Begleiter. Beschwöre eine exakte vergängliche Kopie von ihm. Wenn er ein Gegner ist, betäube ihn.","","Für die Ionier ist der Wind das launenhafteste aller Elemente. Launenhaft, aber nicht unzähmbar. ","Zauber",[],["Ionia"],"SELTEN"],"06IO011":["Jun, das Wunderkind","Wenn ich zum ersten Mal ausgerüstet werde, gib mir in dieser Runde Barriere und Lebensraub.","","Auf sein Zeichen entfesselte Jun eine Reihe von Schlägen, die Yi selbst nicht hätte präziser führen können. Er wich dem Angriff zwar geschickt aus, aber er verbeugte sich vor ihr mit einem stolzen Lächeln.","Einheit",[],["Ionia"],"SELTEN"],"06IO015":["Die Zeugin","Fluss: Ich koste 2 weniger.\nAusspielen: Betäube einen Gegner.","","Welche Rolle spielt sie in dieser merkwürdigen und grausamen Darbietung? Sie ist mehr als nur Publikum, sie beobachtet, ist die Linse, durch die alles dringt und vor Wahrheit und Schönheit bestehen muss. Die Zeugin!","Einheit",[],["Ionia"],"GEWÖHNLICH"],"06IO030":["Nebelfall","Wenn ich beschworen werde, ziehe eine Ausrüstung.\nWenn zum ersten Mal in einer Runde ein nicht ausgerüsteter Verbündeter ausgerüstet wird, fülle 2 Zaubermana wieder auf.","","„Nebelfall ist geheiligter Boden. Die Schwerter befinden sich seit Jahrhunderten an diesem Ort … und ich glaube fest daran, dass jede Klinge, die mit einem Gedicht an ihrem Heft hier gelassen wird, die Geister ihrer verlorenen Besitzer einlädt, sie mit ihrem Segen zu erfüllen.“\n– Schülerin von Doran, handgeschriebene Schriftrolle","Wahrzeichen",[],["Ionia"],"SELTEN"],"06IO034":["Folgenreiche Wahl","Wenn du in diesem Spiel einen Verbündeten ausgerüstet hast, koste ich 1 weniger.\nGib einem Verbündeten in dieser Runde +2|+0 oder +0|+2.","","Tränen der Wut strömten über Juns Gesicht, als sie die Körper auf dem Boden betrachtete. Sie hatte sie im Stich gelassen. Sie hatte ihren Meister im Stich gelassen. Und jetzt blieb ihr nur noch eine Wahl …","Zauber",["KULTIST"],["Ionia"],"SELTEN"],"06IO028":["Unwiderstehlicher Köder","Gib einem Verbündeten in dieser Runde Herausforderer. Wenn er ausgerüstet ist, ziehe 1.","","Mit dem richtigen Köder kann man alles anlocken.","Zauber",["WAFFENMEISTER"],["Ionia","Noxus"],"SELTEN"],"06IO025":["Fanatiker der Schattenklinge","Sobald du in diesem Spiel einen Verbündeten ausgerüstet hast, erschaffe 1 Schattenteufel auf der Hand.","","In der Finsternis hatte er sie gesehen – eine Waffe, die den Schatten durchtrennen konnte. Und in diesem Moment hörte er eine Stimme nach ihm rufen, fern, aber mächtig. Er folgte ihr zu Kayn, von der Wahrheit ihrer Worte geleitet.","Einheit",["KULTIST"],["Ionia"],"GEWÖHNLICH"],"06IO039":["Flattermaki der Navori","Ausspielen: Beschwöre 1 Brigant der Navori oder gib anderen Verbündeten in dieser Runde +1|+1.","","Der Flattermaki hat seinen Brigantenfreund an einem Winterabend kennengelernt, als die beiden die Reste eines verlassenen Lagerfeuers teilten. Am Ende der Woche hatten die beiden eine gemeinsame Vorliebe für Unfug und ein starkes Interesse am goldenen Glitzern von Münzen gefunden.","Einheit",[],["Ionia"],"GEWÖHNLICH"],"06IO032":["Unwürdige Seele","Fluss: Ich koste 2 weniger.\nRufe eine Einheit oder ein Wahrzeichen zurück. Wenn sich andere Karten daran befinden, zerstöre diese zuerst.","","„Du bist der Macht nicht würdig, die du in den Händen hältst.“\n– Rhaast","Zauber",[],["Ionia"],"SELTEN"],"06IO001":["Schülerin von Doran","Wenn ich beschworen werde, erschaffe 1 Vorbereitung auf der Hand.","","„Ich habe mir so viel Wissen angeeignet, wie ich nur konnte, um diese heilige Kunst fortzuführen. Was Doran betrifft und seinen Meister und seinen Meister vor ihm … Ich hoffe, ihre Geister werden meinen Hammer leiten.“\n– Schülerin von Doran, handgeschriebene Schriftrolle","Einheit",[],["Ionia"],"GEWÖHNLICH"],"06IO016":["Drachenruferin","Rundenbeginn: Fluss: Beschwöre Das Empyreum und gewähre ihm Vergänglich.","","„Die Form des Wassers reflektiert die Form deiner Wünsche. Sag mir, Wanderer … was siehst du?“","Einheit",[],["Ionia"],"EPISCH"],"06PZ034":["Hexvernichter","Verursache 6 Schaden an einer Einheit. Wenn sie sterben würde, vernichte sie stattdessen.","","Für einige Kreaturen ist der Tod einfach nicht genug.","Zauber",[],["Piltover & Zhaun"],"SELTEN"],"06PZ006":["Zugabe","Erschaffe einen zufälligen neuen Zauber mit 2 Kosten auf der Hand, senke seine Kosten um 2 und gib ihm Flüchtig.","","Es gibt nichts Befriedigenderes als einen guten Widerhall.","Zauber",[],["Piltover & Zhaun"],"SELTEN"],"06PZ021":["Seraphine","Wenn ich beschworen werde, erschaffe einen zufälligen neuen Zauber mit 2 Kosten auf der Hand.","Du hast 9+ neue Zauber ausgespielt.","Seraphine und ihr Vater sprachen nie über ihre „geheimen“ Ausflüge in die Unterstadt oder über ihre subtilen Upgrades ihrer Bühne. Sie war sicher, er würde ihr die Teilnahme am Grunge-Musikduell von Zhaun verbieten, aber eines Abends schob er den Flyer unter ihrer Tür hindurch. Sie lächelte und machte sich an die Arbeit.","Einheit",[],["Piltover & Zhaun"],"Champion"],"06PZ040":["Hinterhof-Bar","Wenn ich beschworen werde, beschwöre 1 Hinterhof-Barkeeper.\nDeine neuen Karten kosten 1 weniger.","","Nachdem er das letzte Glas abgetrocknet hatte, ließ der Barkeeper einen Moment lang seinen Blick über seine Bar schweifen. An diesem Ort, in dieser Heimat fern der Heimat, wurden so viele Fremde zu Freunden und er wurde von so vielen wilden Nächten gezeichnet. Der Barkeeper lächelte. Sie war nicht perfekt, aber sie gehörte ihm.","Wahrzeichen",[],["Piltover & Zhaun"],"EPISCH"],"06PZ008":["Die Harfe der Düsteren","Du kannst 8 Mana ausgeben, um mich als Styraatu auszuspielen.","","Als die Targonier überlegten, wo sie die Waffen der Düsteren verteilen sollten, schlug einer von ihnen die Lande vor, die später als Zhaun bekannt werden sollten. Tief vergraben in den Wänden der verschlungenen Höhlenwege wäre ein perfekter Ort, so dachten sie. Weit außerhalb der Reichweite der Menschen. Aber nicht der Chireaner.","Ausrüstung",["DÜSTERER"],["Piltover & Zhaun"],"EPISCH"],"06PZ018":["Den Ton angeben","Verursache 2 Schaden an einer Einheit. Wenn du 6+ andere neue Zauber in diesem Spiel ausgespielt hast, verursache 1 Schaden an einer anderen Einheit.","","Einfach und sauber.","Zauber",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"06PZ014":["Fanclub-Präsidentin","Ausspielen: Manifestiere einen Zauber mit 5 Kosten und setze seine Kosten auf 2.","","„Es geht nicht darum, wie groß deine Stimme ist, du musst ein großes Herz haben!“\n– Fanclub-Präsidentin","Einheit",[],["Piltover & Zhaun"],"SELTEN"],"06PZ030":["Inspirierte Pläne","Angriff: Erschaffe einen neuen Zauber mit 2 Kosten auf der Hand und gewähre ihm Flüchtig.","","„O je, das klingt nach Regen.“\n„Was? Dad, draußen scheint die Sonne.“\n„Schnell, deck die Blaupausen ab! Da zieht ein BRAINSTORM auf!“\n„Daaaaaad!“\n– Seraphine & ihr Vater","Ausrüstung",[],["Piltover & Zhaun"],"SELTEN"],"06PZ046":["Formel","Ziehe 2. Fülle dein Zaubermana wieder auf.","","„Magie ist nichts als die wissenschaftliche Wahrheit, die darauf wartet, entdeckt zu werden.“\n– Jayce","Zauber",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"06PZ007":["Ehrgeiziger Kultist","Sobald du in diesem Spiel einen Verbündeten ausgerüstet hast, erschaffe einen neuen Zauber mit 2 Kosten auf der Hand und setze seine Kosten in dieser Runde auf 0.","","„Ich war immer bereit, für die Wissenschaft Opfer zu bringen. Das persönliche Risiko war mir egal, denn die grenzenlose, unerschöpfliche Macht, die ich daraus gewann, war die Mühe mehr als wert.“","Einheit",["KULTIST"],["Piltover & Zhaun"],"GEWÖHNLICH"],"06PZ041":["Gerissenes Kätzchen","Wenn ich beschworen werde und erschaffen wurde, ziehe 1 und gewähre mir +2|+1.","","Wenn sie nicht gerade mitten am Tag schlafen oder sich mitten in der Nacht übergeben, veranstalten Katzen immer irgendeinen Unfug.","Einheit",["KATZE"],["Piltover & Zhaun"],"GEWÖHNLICH"],"06PZ036":["Die Zhaun-Diva","Ausspielen: Verursache 1 Schaden an allen Gegnern. Wenn du in diesem Spiel 6+ neue Zauber ausgespielt hast, verursache stattdessen 3 Schaden.","","„Zhaun! Ich hoffe, eure Stimmbänder sind geölt, der Laden wird nämlich gleich noch mal untergehen!“\n– Zhaun-Diva","Einheit",[],["Piltover & Zhaun"],"SELTEN"],"06PZ010":["Akustiker","Schlag: Erschaffe einen zufälligen neuen Zauber mit 2 Kosten auf der Hand.","","Einst hat er davon geträumt, Zhaun zu verlassen und die Welt mit einem Lied in seinem Herzen zu bereisen. Jetzt schlief die Welt in ihrem Zimmer und wartete auf die Lieder, die der Morgen bringen würde.","Einheit",[],["Piltover & Zhaun"],"EPISCH"],"06PZ022":["Schlagzeugsolo","Ziehe 2.\nFluss: Senke die Kosten dieser Karten um 1.","","In der Musik dreht sich alles um Timing, aber hin und wieder musst du einfach nur loslassen.","Zauber",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"06PZ029":["Beliebter Hit","Gib einem Verbündeten in dieser Runde +2|+0 und Direktangriff.\nFluss: Erschaffe einen neuen Zauber mit 2 Kosten auf der Hand.","","„Ich kann euch nicht hören, Zhaun!“\n– Seraphine","Zauber",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"06PZ020":["Hörnchen, der Hextechniker","Nexusschlag: Senke die Kosten des teuersten Zaubers auf der Hand um 1.","","Sein Name stand in keiner der Blaupausen und er wurde in keinem Song erwähnt, aber die Eingeweihten waren sich einig: Hörnchen war das Herz des gesamten Betriebs.","Einheit",[],["Piltover & Zhaun"],"EPISCH"],"06PZ009":["Kaustischer Riff","Fluss: Ich koste 2 weniger.\nVerursache 1 Schaden an allen Gegnern.","","Es braucht schon einen besonderen Klang, um Zhauns Rasseln und Scheppern zu übertönen, aber der Diva gelingt das immer.","Zauber",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"06PZ037":["Der aggressive Missklang","Verursache 1 Schaden an einer Einheit. Falls du in diesem Spiel einen Verbündeten ausgerüstet hast, kopiere mich mit demselben Ziel.","","Wenn Misstöne die Kakofonie der Zerstörung sind, dann metzle weiter.","Zauber",["KULTIST"],["Piltover & Zhaun"],"SELTEN"],"06PZ019":["Zhaun-Türsteher","Rundenbeginn: Fluss: Fülle 2 Zaubermana wieder auf.","","Wenn es nach ihm ginge, käme NIEMAND rein.","Einheit",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"06PZ033":["Gatalysator v1.0","Deine Zauber und Fertigkeiten verursachen 1 Schaden zusätzlich.","","„Ort: Sektor 3, Unterweg 19B\nGegenstand: Illegale Schusswaffe\nAnmerkungen: Während Operation: Grubenlicht konfisziert. Waffe ist höchst gefährlich. Äußerste Vorsicht geboten.“\n– Einsatzbericht eines Wachtmeisters von Piltover","Ausrüstung",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"06BW029":["Schiffbrüchiger aus Piltover","Wenn ich beschworen werde, improvisiere ich.","","Pesh hat Jax bei einer Rauferei im Hafen kennengelernt, und ihre rechtzeitige Flucht verdanken sie eher den Umständen als ihrer Zusammenarbeit. Doch Pesh hat Jax seither immer transportiert, weil in Jax’ Nähe Dinge kaputtgehen. Und wenn Pesh etwas lieber mag als guten Schrott, dann kaputte Dinge, die repariert werden müssen.","Einheit",["WAFFENMEISTER"],["Bilgewasser","Piltover & Zhaun"],"GEWÖHNLICH"],"06BW034":["Schwermetall","Zerstöre die Ausrüstung einer Einheit und verursache 2 Schaden an ihr.","","„WER WIRFT IN EINER KNEIPENSCHLÄGEREI EINEN ANKER?! WAS STIMMT MIT EUCH NICHT?!!“\n– Barkeeper in Bilgewasser","Zauber",[],["Bilgewasser"],"SELTEN"],"06BW027":["Die Teile und das Ganze","Wirf zum Ausspielen 1 Karte ab. Ziehe 2 und wenn du eine Ausrüstung abgeworfen hast, beschwöre 1 Icathianisches Trugbild.","","Jax’ Crew ist der Beweis dafür, dass ein Ganzes mehr sein kann als die Summe seiner Teile. Trotzdem besteht Pesh auf eine andere Philosophie: Manchmal sind Teile für sich alleine ziemlich toll.","Zauber",["WAFFENMEISTER"],["Bilgewasser","Piltover & Zhaun"],"SELTEN"],"06BW039":["Die unendliche Welle","Sobald du in diesem Spiel einen Verbündeten ausgerüstet hast, koste ich 2 weniger.\nZiehe 2 und gewähre ihnen Flüchtig.","","Obwohl Ibaaros’ alte Knochen sich langsam bewegten, preschte das Gewässer vor ihm mit einer kaum zu begreifenden Geschwindigkeit voraus.","Zauber",["KULTIST"],["Bilgewasser"],"SELTEN"],"06BW026":["Buhru-Kultistin","Wenn ausgerüstete Verbündete angreifen, verursache 1 Schaden am gegnerischen Nexus.","","Es war unwichtig, woher die Macht stammte – das kümmerte ihre Göttin nicht. Wichtig war nur der Ruhm, den das Töten von Monstern ihr brachte.","Einheit",["KULTIST"],["Bilgewasser"],"GEWÖHNLICH"],"06BW014":["Die Harpune der Düsteren","Angriff: Ziehe beim nächsten Rundenbeginn 1 Karte und gewähre ihr Flüchtig.\nDu kannst 9 Mana ausgeben, um mich als Ibaaros auszuspielen.","","„Halte von der Straße von Daray dich fern,\nwo dich Wind und Wasser täuschen bis zum Kern,\nwo Fisch und Vogel selten sind und gar nicht gern,\nweil’s dort gar dunkel ist, trotz hellem Stern.“\n– Reim aus Bilgewasser","Ausrüstung",["DÜSTERER"],["Bilgewasser"],"EPISCH"],"06BW004":["Seelenprüfung","Mache einen Gegner in dieser Runde verletzlich. Wenn er in dieser Runde stirbt, verursache 1 Schaden am gegnerischen Nexus.","","„Wie wirst du abschneiden?“\n– Illaoi","Zauber",[],["Bilgewasser"],"SELTEN"],"06BW044":["Listiger Molchfisch","Nexusschlag: Ziehe 1 Karte und gewähre ihr Flüchtig.","","„Fiese diebische kleene Monster sind se. Aber immerhin schnell zu sehen, wenn sie was geklaut ham.“","Einheit",["REPTIL"],["Bilgewasser"],"GEWÖHNLICH"],"06BW047":["Schelmische Marai","Wenn du einen Zauber ausspielst, beschwöre 1 Pulverfass.","","„Bibi ist ein bisschen … abgedreht, das steht fest. Aber gerade das lieben wir an ihr!“\n– Ai’la, Beschützerin der Marai","Einheit",[],["Bilgewasser"],"SELTEN"],"06BW023":["Gezacktes Entermesser","Plündern: Ich koste 2 weniger.","","„Wie man so sagt, setzt nichts einem Streit in Bilgewasser schneller ein Ende als ein Säbel.“\n„Außer vielleicht eine Pistole.“\n„Halt’s Maul, Baz.“\n– Baz und Gav, angehende Kopfgeldjäger","Ausrüstung",[],["Bilgewasser"],"GEWÖHNLICH"],"06BW042":["Schiffsladung","Verursache 2 Schaden an einer Einheit. Ziehe beim nächsten Rundenbeginn pro verursachten Schaden 1 Karte und gewähre ihnen Flüchtig.","","„Rex kümmert sich um das Bumms, keine Sorge – und ich kümmere mich um den Schatz. Ich kümmere mich auch um Rex’ Anteil, sonst wird er versuchen, ihn in die Kanone zu stecken, und das geht nie gut aus.“\n– Bootsmann","Zauber",[],["Bilgewasser"],"EPISCH"],"06BW040":["Auge Gottes","Angriff: Krakenruf (2).","","„Beweise dich unter ihrem Blick!“\n– Illaoi","Ausrüstung",[],["Bilgewasser"],"SELTEN"],"06SH032":["Vergrabene Waffenkammer","Countdown 2: Erschaffe 1 Schatz des Sandes auf der Hand.","","„Warum musst du alles anfassen?“\n„Was? Glaubst du, dass das eine Falle ist? Glaubst du, eine Steinkugel würde einfach aus dem Nichts–“\n„LAAAUUF!“\n– Argus und Silvio, Grabräuber","Wahrzeichen",[],["Shurima"],"GEWÖHNLICH"],"06SH035":["Der Altar des Blutes","Wenn du eine Einheit besiegst, senke die Kosten der nächsten Düsteren-Einheit, die du ausspielst, um 1.","","Der Altar pulsierte wieder mit Leben und schüttelte den Sand mit einem langsamen, stetigen Rhythmus ab. Alle Anhänger von Xolaani spürten tief im Herzen denselben Schlag. Jeder Muskel, jeder Gedanke, jeder Augenblick … sie konnte sie alle kontrollieren.","Wahrzeichen",[],["Shurima"],"SELTEN"],"06SH046":["Reliquiar des Akolythen","Wenn ich beschworen werde, erschaffe 1 Akolyth der Verheerung auf der Hand. Wenn du mich zerstörst, erschaffe 1 Reliquiar des Akolythen in den obersten 5 Karten deines Decks.","","„Unsere Hände formen die Wüste!“\n– Akolyth der Verheerung","Wahrzeichen",[],["Shurima"],"SELTEN"],"06SH033":["Fluch des Grabs","Prophezeie. Gib einer Einheit in dieser Runde „Ich erleide doppelten Schaden und wenn ich sterben würde, vernichte mich stattdessen“.","","„Nur Narren streben nach Macht, die ihre Kontrolle übersteigt.“\n– Xerath","Zauber",[],["Shurima"],"SELTEN"],"06SH028":["Leerenportal","Wenn du einen Verbündeten beschwörst oder ein Verbündeter stirbt, gewähre 3 Verbündeten in deinem Deck jedes seiner positiven Schlüsselwörter.","","Der Herold des Schwarms erhob zwei Hände vor dem riesigen Gebilde vor ihm. „EIN THRON“, schrie er, „FÜR EINE KAISERIN.“ Das Leerenportal oben pulsierte voll Leben. Bald.","Wahrzeichen",[],["Shurima"],"EPISCH"],"06SH005":["Verlassener Baccai","Ausspielen: Prophezeie. Wenn du einen Düsteren oder eine Ausrüstung auswählst, gewähre mir +1|+1.","","In seiner Hand umklammerte er einen geflochtenen Gürtel, ein Geschenk von Rhaast vor ihrer Aufstiegszeremonie – doch selbst als er die Macht des Düsteren verehrte, trug er in seinem animalischen Herz eine geheime Feindseligkeit.","Einheit",["KULTIST"],["Shurima"],"GEWÖHNLICH"],"06SH056":["Geißeln","Töte ALLE Begleiter.","","Manchmal wirst du vom Licht angezogen, und manchmal das Licht von dir.","Zauber",[],["Shurima"],"SELTEN"],"06SH040":["Gewissenlose Wiederbelebung","Sobald du in diesem Spiel einen Verbündeten ausgerüstet hast, koste ich 2 weniger. Belebe den stärksten toten verbündeten Champion wieder.","","„Du wirst niemals sterben, weil ich es niemals zulasse.“\n– Xolaani","Zauber",["KULTIST"],["Shurima"],"EPISCH"],"06SH021":["Getarnter Schrecken","Ausspielen: Ich schlage einen Gegner.","","Der Angriff ging weiter; größere und noch wildere Kreaturen stürmten aus dem Tor, das immer größer wurde. Die Stadt Belveth war verloren, so wollte es das grausame Schicksal, aber ihr Name sollte weiterleben.","Einheit",[],["Shurima"],"SELTEN"],"06SH051":["Felsenbärenhirtin","Wenn du einen anderen Verbündeten beschwörst, zähle dein Wahrzeichen mit dem höchsten Countdown um 1 herunter.\nWenn ich beschworen werde, beschwöre 1 Schlafender Felsenbär.","","„Die Felsendubbies behandeln Sadira wie eine von ihnen. Dieser Frechdachs würde sofort mit ihnen weglaufen, wenn ich nicht aufpasse!“\n– Kadira, Wüstenexpertin","Einheit",[],["Shurima"],"SELTEN"],"06SH055":["Priesterin des Wüstenlichts","Rundenbeginn: Verursache 4 Schaden an mir. Ziehe einen Champion und gewähre ihm +2|+2. Wenn dein Deck mit 6+ verschiedenen Champions begonnen hat, beschwöre ihn stattdessen.","","Die Getreuen halten Stand, während das Böse aufzieht, und kanalisieren mit ihrer letzten Kraft das Licht der Gerechtigkeit. Ein verzweifelter Ruf nach Erlösung, von dem sie wissen, dass er erhört wird, bevor die Finsternis sie verschlingt.","Einheit",[],["Shurima"],"EPISCH"],"06SH004":["Die Blutsicheln der Düsteren","Letzter Wunsch: Wenn mein Träger kein Diener der Düsteren ist, beschwöre 1 Diener der Düsteren.\nDu kannst 6 Mana ausgeben und einen Verbündeten töten, um mich als Xolaani auszuspielen.","","Als die Schlacht weiter tobte, wendete sich Jun verzweifelt und schwer verwundet an die Stimme, die in ihren Gedanken flüsterte. „Du wirst niemals sterben“, sagte sie so sanft wie ein Sommerregen, „weil ich es niemals zulassen werde.“","Ausrüstung",["DÜSTERER"],["Shurima"],"EPISCH"],"06SH038":["Schwingende Gleve","Schlag: Erschaffe 1 Glücksfund auf der Hand.","","„Wenn du etwas willst, jage es gnadenlos.“\n– Ruinenläuferin","Ausrüstung",[],["Shurima"],"GEWÖHNLICH"],"06DE048":["Verteidigender Dachsbär","","","„Wenn du ein Freund bist, bist du hier willkommen, aber wehe jenem, der mit verdorbenem Herzen dieses Reich betritt, denn er wird die Vergeltung seines mächtigen Beschützers fühlen!“","Einheit",["ELITE"],["Demacia"],"GEWÖHNLICH"],"06DE024":["Fang!","Gib einem Verbündeten in dieser Runde +1|+1 oder rüste einen Verbündeten mit einer Ausrüstung auf der Hand aus, die 2 oder weniger kostet.","","Diese Aktion ist schmerzhafter, wenn die Gruppe noch nicht gegessen hat.","Zauber",["WAFFENMEISTER"],["Demacia","Freljord"],"SELTEN"],"06DE025":["Gutherziger Rekrut","Wenn ich beschworen werde, gib ausgerüsteten Verbündeten in dieser Runde Barriere.","","„Der Junge ist ein Risiko. Ich war dagegen, ihn auf unsere Jagd mitzunehmen, weil er die üble Kreatur immer noch als seine ‚Schwester‘ bezeichnet. Seine Naivität ist nahezu abstoßend. Dennoch empfinde ich auch Mitleid für ihn. Das Ganze wird zumindest eine wichtige Lektion für ihn sein.“\n– Aus dem Tagebuch von Sirius Rowill, eigensinniger Waldhüter","Einheit",[],["Demacia"],"SELTEN"],"06DE033":["Entwaffnende Stille","Zerstöre die Ausrüstung einer Einheit und wenn sie ein Begleiter ist, lasse sie verstummen.","","„Das hast du dir selbst zuzuschreiben.“\n– Fürst Eldred, Anführer der Magiesuchenden","Zauber",[],["Demacia"],"SELTEN"],"06DE039":["Donner von Icathia","Beschwöre 2 Icathianische Trugbilder und rüste sie mit bis zu 2 Ausrüstungen auf der Hand aus, die 2 oder weniger kosten.","","Jax hat in zahllosen Träumen Seite an Seite mit seinem verlorenen Stamm gekämpft. Einige Kämpfe gewinnen sie, andere verlieren sie, aber sie sind immer zusammen.","Zauber",["WAFFENMEISTER"],["Demacia"],"SELTEN"],"06DE011":["Die Ägide der Düsteren","Du kannst 5 Mana ausgeben, um mich als Joraal auszuspielen.","","„Mein Sohn, hör gut zu. Dieser Schild darf niemals berührt werden. Vor langer Zeit erhielt unser Haus ihn als Geschenk, unter der Bedingung, dass wir ihn sicher verwahren und nicht benutzen. Ich trage die Verantwortung für ihn, und wenn mein Leben endet, geht sie auf dich über. Hörst du mir zu? Du darfst nie wieder zu ihm hinaufklettern. Du darfst ihn nie berühren.“\n„Aber Mama, die Stimme darin … sie ruft mich. Sie klingt so traurig.“\n„… Das macht es umso wichtiger, mein Sohn.“\n– Lady Fortis und ihr Sohn","Ausrüstung",["DÜSTERER"],["Demacia"],"EPISCH"],"06DE021":["Vayne","Wenn ich beschworen werde oder bei Rundenbeginn: Erschaffe 1 Hechtrolle auf der Hand oder senke ihre Kosten um 1, wenn du schon eine hast.","Ich habe gesehen, wie du 4 Mal angegriffen hast.","„Unser Ziel war einst ein Mensch, ist also klüger als ein normales Tier. Eine falsche Bewegung könnte unser aller Tod bedeuten. Bleibt in Sichtweite voneinander, meldet alles, was euch verdächtig vorkommt – aber denkt vor allem daran …“","Einheit",[],["Demacia"],"Champion"],"06DE043":["Zuverlässiger Widderhund","Wenn du zum ersten Mal eine Elite beschwörst, gewähre mir +2|+2.","","„Sie ist nicht so schnell wie eine Silberschwinge, aber du wirst staunen, wie schnell sie ihre kurzen Beine tragen.“\n– Cithria, Herrin der Lüfte","Einheit",["HUND"],["Demacia"],"GEWÖHNLICH"],"06DE018":["Verdammen","Wenn du in dieser Runde 2+ Mal angegriffen hast, koste ich 5 weniger. Ein Verbündeter schlägt einen Gegner.","","„Läuternde Bolzen.“\n– Vayne","Zauber",[],["Demacia"],"GEWÖHNLICH"],"06DE041":["Stärke der Champions","Gib Verbündeten in dieser Runde +4|+4 und mobilisiere dich.","","„In die Schlacht mit glühendem Herzen!“\n– Lux","Zauber",[],["Demacia"],"EPISCH"],"06DE026":["Icathianische Mythen","Erschaffe 1 Icathianisches Trugbild auf der Hand, das in dieser Runde 0 kostet, oder erschaffe 1 Goldener Pfannenwender auf der Hand.","","Der Legende nach war der ursprüngliche Besitzer des Goldenen Pfannenwenders eine Meereskreatur mit außergewöhnlichen kulinarischen Fähigkeiten – und sie wollte ein Krieger werden, so stark und furchtlos wie Jax.\n\nAndere, glaubwürdigere Legenden erzählen uns, dass diese Legende komplett von einem gewissen Koch erfunden wurde, der VIEL zu tief ins Glas geschaut hatte.","Zauber",[],["Demacia"],"SELTEN"],"06DE044":["Petrizitstürmer","Gegnerische Zauber oder Fertigkeiten verursachen keinen Schaden an mir.","","„Nichts ist stärker als Petrizit.“\n– Architekt der Durand","Einheit",[],["Demacia"],"SELTEN"],"06DE017":["Fischschlacht","Ein Verbündeter und ein Gegner schlagen sich gegenseitig oder ein ausgerüsteter Verbündeter schlägt einen Gegner, dann wird seine Ausrüstung entfernt.","","„Fisch ins Gesicht!“\n– Ionische Meisteranglerin","Zauber",["WAFFENMEISTER"],["Demacia"],"GEWÖHNLICH"],"06DE040":["Verlockende Aussicht","Wähle einen Begleiter oder eine Ausrüstung aus den obersten 4 Karten deines Decks. Ziehe die gewählte Karte und lege den Rest zurück ins Deck.","","Ein sanftes, verführerisches Flüstern erzeugt tief im Herzen ein Verlangen. Wie ein Splitter schwärt sie und wächst zu Hunger heran. Aus Hunger wird Sünde, die wiederum den Tod bringt. Und so geht der Kreislauf weiter.","Zauber",["KULTIST"],["Demacia"],"GEWÖHNLICH"],"06DE028":["Blutverfluchte Harpyie","Ausspielen: Rüste mich mit einer Ausrüstung auf der Hand aus, die 2 oder weniger kostet.\nWenn ich das erste Mal ausgerüstet sterben würde, heile mich stattdessen vollständig und zerstöre die Ausrüstung.","","„Kian, wenn du das hier liest … bin ich hoffentlich tot. Ich kann nicht kontrollieren, was mit mir passiert. Das Blut unter meinen Nägeln lässt sich nicht wegwaschen. Alles juckt. Ich kratze und kratze, aber nichts hilft. Es tut weh. Ich will nur, dass es aufhört. Falls ich irgendwie überlebe, musst du mir versprechen, dass du die Suche nach mir aufgibst.\n\nIch würde um Vergebung bitten, aber ich verdiene sie nicht. Behandle Mutter gut, ja?“\n– Zerknüllter Brief, gefunden in einer zerrissenen Tasche","Einheit",[],["Demacia"],"EPISCH"],"06DE027":["Eigensinniger Waldhüter","Angriff: Gib ausgerüsteten Verbündeten in dieser Runde +1|+1.","","„Janan, richtig? Was kannst du mir über Sirius erzählen?“\n„Oh, Waldhüter Rowill? Vor einigen Jahren wurde ihm sein Titel aberkannt. Er hatte wohl jeden Befehl verweigert. Er machte, was er will, und akzeptierte kein ‚Nein‘.“\n„Aha.“\n„Warum hast du erlaubt, dass er sich dieser Jagd anschließt?“\n„Habe ich gar nicht.“\n„Aber warum … oh, natürlich. Fantastisch.“\n– Vayne und Janan, verwitwete Jägerin","Einheit",[],["Demacia"],"SELTEN"],"06DE019":["Verwitwete Jägerin","Ausspielen: Rüste mich mit einer Ausrüstung auf der Hand aus, die 2 oder weniger kostet.","","„Obgleich die Frau als Kämpferin fähig genug zu sein scheint, ist ihre Trauer frisch und droht sie zu überwältigen. Verzweiflung ist in der Tat eine starke Motivation – ich muss es wissen – aber derart ungezügelt? Vielleicht will sie sterben …“\n– Aus dem Tagebuch von Sirius Rowell, eigensinniger Waldhüter","Einheit",[],["Demacia"],"GEWÖHNLICH"],"06DE032":["Demacianischer Stahl","","","Schwert und Schild, wie sie von Demacias behelmten Waffenbrüdern bevorzugt werden.","Ausrüstung",[],["Demacia"],"GEWÖHNLICH"],"06DE029":["Verlässlicher Elkin","Wenn zum ersten Mal ein Verbündeter ausgerüstet wird, gewähre mir Robust.","","„Zurück, widerwärtige Kreatur! Wenn du Puritas’ makellosem Fell auch nur ein Haar krümmst, werde ich dafür sorgen, dass du EWIGE QUALEN erleidest!“\n– Sirius Rowill, eigensinniger Waldhüter","Einheit",[],["Demacia"],"GEWÖHNLICH"],"06DE010":["Überläuferin der Waldhüter","Sobald du in diesem Spiel einen Verbündeten ausgerüstet hast, gewähre mir Späher.","","Die Jahre der Unterdrückung ihrer magischen Fähigkeiten haben in ihr einen unvorstellbaren Selbsthass heraufbeschworen, den sie ihren Opfern zuteil werden ließ. Nachdem sie von den Waldhütern desertiert war, war ihr Zorn ziellos, bis eine Stimme in der Dunkelheit sie rief. Sie sprach von einer neuen Ordnung, in der sie ihrer Grausamkeit freien Lauf lassen konnte.","Einheit",["KULTIST"],["Demacia"],"SELTEN"],"06DE006":["Kampfkoch","Wenn ich beschworen werde, improvisiere ich, dann schmiede mich.","","Breshi dachte, dass er nach seiner Zeit in der Armee von Demacia in den Ruhestand gehen und in einer ruhigen Dorfkneipe kochen würde. Jax hat seinen Ruhestand mit einer Kneipenschlägerei und einer besonders schlechten Meinung zu hartgekochten Eiern ruiniert. Seither hat sich Breshi einer neuen Aufgabe verschrieben: Jax etwas Geschmack beizubringen.","Einheit",["WAFFENMEISTER"],["Demacia","Freljord"],"GEWÖHNLICH"],"06DE034":["Treuer Wolfshund","Wenn ein Verbündeter in dieser Runde gestorben ist, koste ich 2 weniger.\nAusspielen: Rüste mich mit einer Ausrüstung auf der Hand aus, die 2 oder weniger kostet, und schmiede mich.","","„Ich hatte Maggie, seit sie ein Welpe war. Sie mag nun alt sein, aber ihr Verstand ist immer noch so scharf wie eine frisch geschliffene Klinge. Ich würde mein Leben für sie geben – und ich weiß, dass sie ihres für mich geben würde.“\n– Janan, verwitwete Jägerin","Einheit",["HUND"],["Demacia"],"GEWÖHNLICH"],"06SI045":["Seelenspaltung","Töte einen Verbündeten, um 2 vergängliche Kopien von ihm zu beschwören.","","Sie haben sie sowieso nicht verwendet.","Zauber",[],["Schatteninseln"],"SELTEN"],"06SI007":["Die Hellebarde der Düsteren","Töte einen Verbündeten, um mich auszuspielen.\nDu kannst 10 Mana ausgeben, um mich als Taarosh auszuspielen.","","Taarosh stemmte sich gegen die Wände seiner Zelle und hörte den Ruf seines Generals. Er würde ihm folgen, egal wie.","Ausrüstung",["DÜSTERER"],["Schatteninseln"],"EPISCH"],"06SI034":["Schreckgestalt der Echos","Rundenende: Gewähre für jeden Verbündeten, der in dieser Runde gestorben ist, allen verbündeten Kopien von ihnen überall +1|+1.","","„Ich weiß nicht, welch üble Magie sie einsetzen, und ich WILL es auch nicht wissen. Ich muss nur eines wissen: Sollten sie sich erheben, werden sie getötet. Erneut.“\n– Hüter auf den Inseln","Einheit",[],["Schatteninseln"],"EPISCH"],"06SI029":["Unheilvoller Speer","Wenn ein Verbündeter in dieser Runde gestorben ist, koste ich 2 weniger.","","„Es kann keine Gerechtigkeit geben … nur Rache.“\n– Kalista","Ausrüstung",[],["Schatteninseln"],"GEWÖHNLICH"],"06SI032":["Finitum","Töte eine Einheit mit insgesamt 4 oder weniger Stärke und Leben oder zerstöre die Ausrüstung einer Einheit.","","Welche Gestalt auch immer der Tod auf den Schatteninseln annimmt, möge er gnädig schnell sein.","Zauber",[],["Schatteninseln"],"SELTEN"],"06SI031":["Klingen der Gefallenen","Gib einem Verbündeten in dieser Runde „Letzter Wunsch: Beschwöre 1 Icathianisches Trugbild mit meiner Ausrüstung“.","","Manchmal ist das Beste, was man für einen gefallenen Verbündeten tun kann, seine Waffe zu nehmen und weiterzukämpfen.","Zauber",["WAFFENMEISTER"],["Schatteninseln","Shurima"],"SELTEN"],"06SI014":["Opulentes Foyer","Wenn ich beschworen werde, beschwöre 1 Gespenstische Band.\nRundenbeginn: Wenn du die Angriffsmarke hast, beschwöre 1 Gespenstische Band.","","„Die Spieler sind bereit, die Bühne steht, unser Publikum wartet – Maestro, bitte!!“\n– Überschwänglicher Gastgeber","Wahrzeichen",[],["Schatteninseln"],"EPISCH"],"06SI038":["Erlöstes Wunderkind","Angriff: Beschwöre 1 angreifende Gespenstische Band.","","Das Streben nach Perfektion war einschränkend, reglos. Perfektion lebte nicht, konnte nicht atmen. Perfekte Imperfektion hingegen – danach lohnte es sich zu streben.","Einheit",[],["Schatteninseln"],"SELTEN"],"06SI003":["Fireth, Todesengel des Sandes","Wenn ich beschworen werde, improvisiere ich.","","Jax fragte Fireth in den ersten Wochen ihrer gemeinsamen Reise oft nach ihrem Namen, aber sie knurrte immer nur: „Ich bin der Todesengel!“ Breshi fand eine interessante Lösung – er buk einfach einen Kuchen und brauchte dafür den Namen des stärksten Gruppenmitglieds, um richtig feiern zu können.","Einheit",["WAFFENMEISTER"],["Schatteninseln","Shurima"],"EPISCH"],"06SI006":["Hüterin der Kiste","Sobald du in diesem Spiel einen Verbündeten ausgerüstet hast, gewähre mir Lebensraub.","","„Die Kiste gibt ihre Geheimnisse nicht freiwillig preis, Shieda Kayn. Für sie muss ein hoher Preis bezahlt werden. Aber wenn du den Mut hast, in den Schatten der Schatten zu blicken, wirst du sehen, dass wundervolle und schreckliche Dinge in ihr verborgen liegen.“\n– Ysdra, Hüterin der Kiste","Einheit",["KULTIST"],["Schatteninseln"],"GEWÖHNLICH"],"06SI039":["Form der Furcht","Töte einen Verbündeten, um 1 Einfallender Nebel zu beschwören.","","Nur ein Narr würde in der Hoffnung, eine vertraute Form zu erblicken, in den schwarzen Nebel starren.","Zauber",[],["Schatteninseln"],"GEWÖHNLICH"],"06SI042":["Unvergänglicher Ritter","Wenn ich Vergänglich erhalten würde, gewähre mir stattdessen +1|+1.","","Soldaten, die in ihrem Leben ausgebildet wurden, Bestrafung standzuhalten, waren im Tod nur noch pflichtbewusster und fähiger – unbeirrt von Kälte, Schmerz oder Furcht.","Einheit",[],["Schatteninseln"],"SELTEN"],"06SI036":["Vollkommene Verwüstung","Töte ALLE Einheiten außer verbündete Düstere und ausgerüstete Verbündete.","","Als sie zu ihren Waffen griff, verließ ihre Menschlichkeit sie, und eine hasserfüllte Essenz nahm ihren Platz ein, die den seelenlosen Körper füllte, der einst die Schülerin Jun war. Sie schwappte durch sie, über sie, um sie und heraus in die Welt und weckte die schlummernde Düstere.","Zauber",["KULTIST"],["Schatteninseln"],"SELTEN"],"06SI046":["Beharrliche Patrouille","Letzter Wunsch: Ziehe 1.",""," „… und so wache ich, in alle Ewigkeit, denn meine Pflicht geht über Leben und Tod hinaus.“","Einheit",[],["Schatteninseln"],"GEWÖHNLICH"],"06SI041":["Mondheller Talhüter","Wenn du einen vergänglichen Verbündeten beschwörst, gewähre ihm +1|+0.\nNachteinbruch: Beschwöre 1 Sprössling.","","Weitab der Ufer der Schatteninseln liegen längst tot geglaubte Wäldchen, gekrümmt und bewegungslos für alle, die nicht ganz genau hinsehen – aber jene, die es tun, bemerken, dass sich in der vom Mondlicht getränkten Erde neues Leben rührt.","Einheit",[],["Schatteninseln"],"GEWÖHNLICH"],"07PZ009":["Augmentierter Uhrwerkler","Ausspielen: Prophezeie, ziehe dann 1 Karte und senke ihre Kosten um 1.","","„An diesem kleinen Kerlchen musste ich nur etwas tüfteln. Neue Zahnräder hier, ein neuer Arm da, und schon ist er wieder wie frisch gebaut. Die Zeit ist ein Geschenk, von dem jeder etwas mehr kriegen soll, sage ich.“\n– Ekko","Einheit",[],["Piltover & Zhaun"],"EPISCH"],"07PZ017":["Blitzbombenhändler","Wenn du einen Zauber ausspielst, verstecke 1 Blitzbombenfalle in den obersten 8 Karten des gegnerischen Decks.","","„… Und weißt du, warum diese Babys besser sind als Pilze? Du entscheidest, wann sie explodieren! Wenn DAS mal kein Preis-Leistungs-Verhältnis ist!“","Einheit",[],["Piltover & Zhaun"],"SELTEN"],"07PZ005":["Rohrsprenger","Verursache 1 Schaden an einem Gegner und dem gegnerischen Nexus. Wirf bis zu 2 Karten ab, um den Schaden pro abgeworfener Karte um 1 zu erhöhen.",""," „Okay, okay, das funktioniert vielleicht nur ein Mal, aber vertrau mir, das wird ein Knaller!“\n– Jinx","Zauber",[],["Piltover & Zhaun"],"SELTEN"],"07NX009":["Stilvoller Schuss","Verursache 1 Schaden am gegnerischen Nexus. Wenn in dieser Runde das nächste Mal ein Verbündeter den Nexus schlägt, erschaffe 1 Stilvoller Schuss auf der Hand.","","„Niemand könnte mit mir mithalten, nicht einmal, wenn ich nur Stöcke und Steine hätte. Mit meiner Ausrüstung? Probier’s gar nicht erst.“\n– Samira","Zauber",[],["Noxus"],"EPISCH"],"07NX008":["Elegante Klinge","Plündern: Gewähre mir +2|+0.","","„Mein Honorar ist hoch und ich arbeite nicht für jeden. Wenn du das Glück hast, mich anzuheuern, bekommst du Eleganz, Anmut und Klingen, die ihr Ziel nie verfehlen. Aber vor allem bekommst du Stil. Denn wer tötet nicht am liebsten mit Flair?“","Einheit",[],["Noxus"],"GEWÖHNLICH"],"07NX014":["Pirouette","Plündern: Ich koste 2 weniger.\nVerursache 1 Schaden an einem beliebigen Ziel und betäube einen Gegner.","","„Was? Ich habe mich gedehnt. Sag bloß nicht, ich hätte dich beim Dehnen umgebracht.“\n– Elegante Klinge","Zauber",[],["Noxus"],"SELTEN"],"07NX007":["Samira","Plündern oder Schlag: Erschaffe 1 Flair auf der Hand, wenn du keines hast.","Ich habe gesehen, wie du 6 Karten ausgespielt hast. Wird zurückgesetzt, wenn du eine Runde mit der Angriffsmarke beginnst.","„Ich bin immer auf der Jagd nach irgendeinem Ziel, das seine Schulden nicht bezahlen kann. Und wenn du vor diesen Schulden wegläufst, machst du dir die falschen Feinde – diejenigen, die mich rufen.“","Einheit",[],["Noxus"],"Champion"],"07NX006":["Schicker Schönling","Plündern: Verdopple meine Stärke.",""," „Also, normalerweise lege ich gerne ein paar Regeln fest – wie ‚Pfoten weg von Haaren und Gesicht‘, aber wem mache ich was vor? Du wirst mir kein Haar krümmen.“","Einheit",[],["Noxus"],"GEWÖHNLICH"],"07NX015":["Dame, die Draufgängerin","Plündern: Gewähre Verbündeten +1|+0.","","„Ah, Dame. Sie hat einen Hang zum Dramatischen. Manche rümpfen vielleicht die Nase vor etwas Bombast, aber wenn sie in ihrem Element ist, sahnen wir alle ab.“\n– Elegante Klinge","Einheit",[],["Noxus"],"GEWÖHNLICH"],"07NX003":["Keine Kompromisse","Gib einem Verbündeten in dieser Runde +2|+0.\nPlündern: Gib ihm stattdessen +2|+1.",""," „Indari hat ein paar Beziehungen spielen lassen, um uns ohne Ärger reinzubringen. Hoffen wir, dass wir auf dem Weg raus Zeit haben, selbst Ärger zu machen.“\n– Samira","Zauber",[],["Noxus"],"GEWÖHNLICH"],"07NX004":["Exzellente Erfinderin","Wenn ich beschworen werde, aktiviere alle verbündeten Plündern-Effekte.","","„Einen Laden aufzuziehen, ist hier und da knifflig, aber nach einem Blick auf die Waren von Lani und mir kommt die Kohle rein. Hab’ unser Ziel unter den Käufern nicht gesehen, aber dafür genug andere, die Gewalt im Sinn haben. Schließlich lässt sich die Lage gut einschätzen, wenn man rausfindet, wer wen um die Ecke bringen will.“\n– Miel","Einheit",[],["Noxus"],"SELTEN"],"07NX001":["Verwegene Verwüsterin","Ausspielen: Verursache 1 Schaden am gegnerischen Nexus oder aktiviere den Plündern-Effekt eines Verbündeten.","","„Im Waffengeschäft muss man ein gesundes Verhältnis zu Daten haben. Konzept, Test, Neubau, Modifikation: Für all das braucht man Informationen. Nichts geht über einen kleinen Feldtest, um vernünftige Stichproben und ein paar Krater zu machen!“\n– Lani","Einheit",[],["Noxus"],"SELTEN"],"07NX005":["Hauptmann Indari","Wenn ich beschworen werde, improvisiere ich.\nPlündern: Schmiede andere Verbündete.","","„Ich habe schon mit vielen Agenten gearbeitet. Manche waren einfach, manche eine Herausforderung … und dann ist da Samira. Ich habe mich mit der Tatsache abgefunden, dass ich sie nicht im Zaum halten kann – stattdessen lenke ich den Wahnsinn, leite ihn – und gelegentlich mache ich hier und da mit.“","Einheit",["WAFFENMEISTER"],["Noxus"],"SELTEN"],"07BW018":["Verrückte alte Babs","Wenn du Mana wieder auffüllst, gewähre mir für jedes aufgefüllte Mana +1|+0.","","„Mein herzallerliebster Jack, sieh mal! Ich haben etwas Interessantes für dich gefunden, ja?“","Einheit",[],["Bilgewasser"],"GEWÖHNLICH"],"07BW021":["Forsche Freibeuterin","Plündern: Beschwöre einen zufälligen Begleiter mit 1 Kosten und gewähre ihm Furchtlos.","","„Wenn ich du wäre, würde ich einen Bogen um sie machen. Sie hat die üble Angewohnheit, ihre Probleme zu denen anderer Leute zu machen.“\n– Samira","Einheit",[],["Bilgewasser"],"GEWÖHNLICH"],"07BW002":["Jack","Schlag: Erschaffe 1 Münze auf der Hand.\nWenn du Mana wieder auffüllst, heile mich für jedes aufgefüllte Mana um 1.","Du hast in einer Runde 12+ Mana ausgegeben.","„Wenn du dich mit mir anlegst, musst du entweder mutig oder dumm sein, aber das kommt auf dasselbe raus. Mein Tipp: Sorge dich lieber drum, lebend rauszukommen.“","Einheit",[],["Bilgewasser"],"Champion"],"07BW040":["Nukkle","Wenn ich beschworen werde, erschaffe 1 flüchtige Mako auf der Hand.","","„’N kleiner Piekser hier, ein kleiner Kratzer da, alles nur zum Spaß. Aber ’n bisschen Blut im Wasser hat noch nie jemandem geschadet. Jedenfalls nich’ mir.“\n– Nukkle","Einheit",[],["Bilgewasser"],"SELTEN"],"07BW001":["Perfider Promoter","Wenn du Mana wieder auffüllst, erschaffe einen zufälligen flüchtigen Begleiter auf der Hand, den du dir genau leisten kannst.","","„Wenn du Blut willst, willst du Jack. Du willst wissen, wo, wann, wer und wie viel? Dann redest du mit mir.“","Einheit",[],["Bilgewasser"],"SELTEN"],"07BW003":["Münzmonster","Letzter Wunsch: Erschaffe 1 Münze auf der Hand.","","„Oi, komm zurück, Schleimbatzen! Das sind meine Kartoffelmünzen!“\n– Engel","Einheit",[],["Bilgewasser"],"GEWÖHNLICH"],"07BW014":["Fünf-Faust-Pablo","Wenn ich beschworen werde, erschaffe 1 flüchtigen Faustkampf auf der Hand.","","„So macht man das, Jackie! Du teilst den guten alten Bilgewasser-Charme aus und ich halt dich in Kampfform. Ahh, das erinnert mich an meine guten alten Tage, als se mich ‚Bildhübscher Pablo‘ genannt ham … Ham se nicht, sagste? Ham se wohl! Der Schlag auf die Rübe hat dir nich’ gut getan.“\n– Fünf-Faust-Pablo","Einheit",[],["Bilgewasser"],"GEWÖHNLICH"],"07BW013":["Engel","Plündern: Erschaffe 3 Münzen auf der Hand.","","„Mehr hast du nicht drauf? Wie niedlich. Jetzt bin ich dran.“","Einheit",[],["Bilgewasser"],"GEWÖHNLICH"],"07BW006":["Riskantes Unterfangen","Verursache 3 Schaden an einer Einheit. Wird sie dadurch getötet, erschaffe 2 Münzen auf der Hand.","","„Wer nicht wagt, der nicht gewinnt – und wer wagt sich an diese Beißerchen?“\n– Jack","Zauber",[],["Bilgewasser"],"EPISCH"],"07BW026":["Stachelkette","Plündern: Ich koste 2 weniger.\nZiehe beim nächsten Rundenbeginn 2 Karten und gewähre ihnen Flüchtig.","","Wenn du das Rasseln hörst, ist es schon zu spät.","Zauber",[],["Bilgewasser"],"SELTEN"],"07BW027":["Vater Furor","Plündern: Fülle 1 Zaubermana wieder auf und erschaffe einen zufälligen Zauber mit 1 Kosten aus deinen Regionen auf der Hand.","","Die Herkunft von Vater Furor ist so undurchsichtig wie eine Gewitterwolke, und niemand, der ihn je gefragt hat, hat eine Antwort erhalten – zumindest konnte sie niemand im Lärm seiner Zerstörungswut hören.","Einheit",[],["Bilgewasser"],"SELTEN"],"07BW008":["Faustkampf","Ein Verbündeter und ein Gegner schlagen sich gegenseitig. Ihr Leben kann durch diesen Schlag nicht unter 1 fallen.","","Manchmal handelt man mit Münzen und Lampenöl, und manchmal handelt man mit Fäusten und Zähnen. Das ist nun mal so, aber ein fairer Tausch? Das nenne ich ein gutes Geschäft!","Zauber",[],["Bilgewasser"],"GEWÖHNLICH"],"07BW041":["Seepockenfaust","Schlag: Erschaffe 1 Münze auf der Hand.","","„Hmmm, ich weiß, dass sie nicht gerade traditionell sind, das gebe ich zu. Aber probier sie mal aus, die wachsen dir ans Herz.“\n– Bulle","Ausrüstung",[],["Bilgewasser"],"SELTEN"],"07BW004":["Die Königshof","Wenn ich beschworen werde, ziehe einen Jack.\nWenn du einen Verbündeten beschwörst, erschaffe 1 flüchtigen Faustkampf auf der Hand.\nWenn ein Verbündeter Schaden überlebt, gewähre ihm Furchtlos.","","Jacks persönliches Schiff hat ihn und seinesgleichen über die Meere von Runeterra getragen, von Bilgewasser bis Ionia. Wie weit sie unter Wasser reist, ohne zu sinken, kann niemand sagen, aber man erzählt sich, dass die wahre Gefahr unter der Wasseroberfläche liegt …","Einheit",[],["Bilgewasser"],"EPISCH"],"07BW025":["Inferna","Wenn du Plündern aktivierst, ziehe 1 Karte und gewähre ihr Flüchtig.","","„Es hat bestimmte Vorteile, auf See ein Pyromane zu sein. Wasser verhindert, dass eine Flamme aus dem Ruder läuft, und es will nie seinen Anteil.“","Einheit",[],["Bilgewasser"],"SELTEN"],"07IO020":["Auswechseln","Rufe einen Verbündeten zurück und erschaffe 1 Münze auf der Hand, oder gib 5 Mana aus, um einen Gegner zurückzurufen und 1 Münze auf der Hand zu erschaffen.","","„Ich komme nur unter zwei Bedingungen. Erstens, wenn dein Gegner zu viel Spaß dabei hat, dich zu vermöbeln. Zweitens, wenn du selbst zu viel Spaß hast und ich auch meinen Teil haben will.“\n– Arenaprofi","Zauber",[],["Ionia"],"SELTEN"],"07IO014":["Meister Bingwen, das Sieb","Ausspielen: Wenn du das nächste Mal in dieser Runde eine Einheit ausspielst, beschwöre eine exakte vergängliche Kopie von ihr.","","Bingwen der Vogel war einst ein Kämpfer und erhielt seinen Namen wegen seiner vogelgleichen Haltung und Agilität. Im Ruhestand ist er ein Ausbilder und trennt mit scharfem Blick und strenger Hand die Spreu vom Weizen des Talents.","Einheit",[],["Ionia"],"EPISCH"],"07IO023":["Der Veteran","Ausspielen: Rufe den stärksten Gegner zurück. Wenn du in dieser Runde 16+ Mana ausgegeben hast, rufe stattdessen alle Gegner zurück.","","„Die Maske kommt nicht runter, Mädchen. Und wenn du nicht irgendwann so aussehen willst wie dieses Ding, fragst du besser nicht noch einmal.“","Einheit",[],["Ionia"],"SELTEN"],"07IO011":["Sett","Wenn ich das erste Mal beim Angriff unter 1 Leben fallen würde, gib mir stattdessen Barriere.","Du hast 40+ Mana ausgegeben.","Sett badete im Raunen der Menge seiner exklusiven Untergrundarena und gönnte sich einen seltenen Moment der Selbstbeobachtung. Er erinnert sich an alles, wofür er kämpfte, und was noch auf ihn zukommen könnte. Eines weiß er aber mit Sicherheit: Es ist gut, der Boss zu sein.","Einheit",[],["Ionia"],"Champion"],"07IO046":["Königliche Schimmerschwinge","Andere Vogelverbündete haben +1|+0 und Direktangriff.","","„In diesem Dschungel habe ich immer wieder festgestellt, dass die wunderschönsten Exemplare die tödlichsten Raubtiere sind.“\n– Anura","Einheit",["VOGEL"],["Ionia"],"SELTEN"],"07IO009":["Bedachte Buchhalterin","Nexusschlag: Erschaffe 1 Münze auf der Hand.","","Von allen ambitionierten Intriganten und eigennützigen Verschwörern verfügt Lise über die eine Eigenschaft, die Sett wichtiger als alle anderen ist: Zuverlässigkeit. Sie irrt sich nie, bleibt nichts schuldig und hat Sett nie Grund zur Sorge gegeben. So konnte Lise sein Vertrauen gewinnen und warnt alle, die Ärger machen wollen: Wenn ihr gegen das Haus wettet, verliert ihr.","Einheit",[],["Ionia"],"SELTEN"],"07IO019":["Gelassene Barkeeperin","Ausspielen: Heile einen Verbündeten oder deinen Nexus um 3 und erschaffe 1 Münze auf der Hand.","","„Bei der ersten Runde begrüßen sie sich, bei der zweiten werden sie locker. Die Probleme kommen bei der dritten raus, und ab der vierten nimmt keiner mehr ein Blatt vor den Mund – du würdest nicht glauben, was ich so alles höre!“","Einheit",[],["Ionia"],"GEWÖHNLICH"],"07IO017":["Wetteinsatz","Ziehe 2 Karten und erschaffe 2 Münzen auf der Hand.",""," „Sie geben uns echtes Geld und wir geben ihnen eine Chance. Hehe … und manche fragen sich wirklich, warum das Haus immer gewinnt.“","Zauber",[],["Ionia"],"GEWÖHNLICH"],"07IO047":["Ködernde Kobra","Wenn du in einer Runde zum ersten Mal einen anderen Begleiter ausspielst, beschwöre eine exakte Kopie von ihm. Wenn dein Spielfeld voll ist, gewähre mir stattdessen seine Werte und Schlüsselwörter.","","„Glaubst du, diese Blumen sind etwas wert? Und ich will ja nicht verrückt klingen, aber sieht es nicht irgendwie so aus, als ob sie … tanzen?“\n– Wilderer aus Piltover","Einheit",["REPTIL"],["Ionia"],"EPISCH"],"07IO013":["Arenaprofi","Wenn ich beschworen werde, erschaffe 1 Münze auf der Hand.","","„Für manche ist es das Geld, für andere das Blut und für wieder andere das Tosen der Menge. Ich? Ich könnte mich nie für eines davon entscheiden. Ich brauche alles, und ich habe von allem hier mehr als genug.“","Einheit",[],["Ionia"],"GEWÖHNLICH"],"07IO012":["Ring-Aufpasser","Wenn ich beschworen werde, erschaffe 1 flüchtigen Ring-Aufpasser auf der Hand und gewähre anderen Ring-Aufpassern +1|+1.\nVerstärkt (5): Direktangriff.","","„Wenn sie dich für dumm halten, lass sie nur. Lass die schwarzen Schafe denken, sie könnten ungeschoren zu ihren Spielen zurückkehren – es gibt nichts Besseres im Leben als ihren Blick, wenn sie feststellen, dass sie dich unterschätzt haben.“\n– Sett","Einheit",[],["Ionia"],"SELTEN"],"07IO007":["Auf die Zwölf","Betäube 2 Gegner und erschaffe 1 Münze auf der Hand.","","„Was? Er wollte doch eins auf die Nuss – er hat nicht gesagt, womit!“\n– Sett","Zauber",[],["Ionia"],"GEWÖHNLICH"],"07SH023":["General der gefallenen Sande","Ich habe +1|+0 pro vergänglichem Verbündeten, den du in diesem Spiel beschworen hast.","","„Du magst für diesen Feind zwar nichts als ein Sandkorn sein, aber ich sehe dich. Ich fühle deine Gegenwart in den Dünen. Gib mir Kraft, und wir werden gemeinsam unsere Gegner zur Strecke bringen!“","Einheit",[],["Shurima"],"SELTEN"],"07SH018":["Bewahrer der Geheimnisse","Wenn ich beschworen werde, erschaffe am Ende deines Decks zwei zufällige Champions auf Stufe 2, die sich nicht auf deiner Hand, in deinem Deck oder im Spiel befinden.","","Er verstand nicht völlig, was er sah, welche Form das Unheil annehmen würde, oder wann – aber er kannte diese Welt und ihr Volk. Sie sind nicht bereit. Sie werden es nie sein.","Einheit",[],["Shurima"],"EPISCH"],"07SH008":["Rudelangriff","Beginne einen kostenlosen Angriff mit einer exakten vergänglichen Kopie jedes Katzenverbündeten.","","Eine einsame Jägerin ist bedrohlich genug – aber ein Rudel ist wahrlich furchterregend.","Zauber",[],["Shurima"],"GEWÖHNLICH"],"07FR008":["Frostfellwelpe","Gib 6 Mana aus, um mich stattdessen als Frostfellmutter auszuspielen.","","In Freljord lauern viele Gefahren, besonders auf jene, die seine kalte Wahrheit noch nicht erfahren haben.","Einheit",["HUND"],["Freljord"],"GEWÖHNLICH"],"07FR009":["Innovative Schmiedin","Wenn ich beschworen werde, improvisiere ich.\nWenn du in einer Runde zum ersten Mal einen Verbündeten schmiedest oder ausrüstest, heile deinen Nexus um 1.","","„Durch das kleine Fellknäuel arbeite ich vielleicht nicht schneller, aber es zaubert mir ein Lächeln aufs Gesicht. Mehr Hilfe will ich gar nicht.“\n– Innovative Schmiedin","Einheit",["WAFFENMEISTER"],["Freljord"],"SELTEN"],"07FR005":["Diener-Bollwerk","Verbündete Zauber oder Fertigkeiten verursachen keinen Schaden an mir.","","„Sobald die Lawine ins Rollen kommt, ist sie nicht aufzuhalten.“\n– Lissandra","Einheit",[],["Freljord"],"SELTEN"],"07SI002":["Seelenraub","Töte einen Begleiter mit 3 oder weniger Stärke, oder gib 3 Mana aus, um einen Champion mit 3 oder weniger Stärke zu töten.","","Es ist nichts als ein Flüstern in der Luft, kaum zu hören, aber schmerzhaft verspürt, das ein Leben gegen ein anderes tauscht.","Zauber",[],["Schatteninseln"],"SELTEN"],"07SI001":["Auslöschung","Töte ALLE Einheiten mit 3 oder weniger Stärke.","","Wer auf mich herabblickt, sollte die Berührung des Vernichtung erfahren und nie wieder frei von ihr sein.","Zauber",[],["Schatteninseln"],"EPISCH"],"07SI007":["Grabbegleiter","Wenn in einer Runde zum ersten Mal ein anderer Verbündeter stirbt, ziehe 1.","","„Ich habe ihm gerade einen neuen Trick beigebracht! Willst du ihn sehen?“\n– Phantomtäuscherin","Einheit",["HUND"],["Schatteninseln"],"GEWÖHNLICH"],"07MT003":["Kosmisches Jungtier","Rundenbeginn: Heile mich und deinen Nexus um 1.","","Wie die Träne einer Aurora färben sie den Himmel ein, ihr strahlender Blick beruhigt, lindert Wunden und heilt, was gebrochen ist.","Einheit",[],["Targon"],"SELTEN"],"07MT001":["Fallender Stern","Verursache 4 Schaden an einem Gegner, der in dieser Runde angegriffen hat oder betäubt ist.","","Die Sterne blickten auf unsere Taten herab, auf die guten wie die schlechten. Die Rechtschaffenen werden belohnt, die Niederträchtigen gerichtet.","Zauber",[],["Targon"],"GEWÖHNLICH"],"07MT007":["Geopferter Gelehrter","Letzter Wunsch: Erschaffe auf der Hand Kopien der ersten 3 Zauber, die du auf mich gespielt hast.","","„Camphor hat von zu vielen zu viel genommen. Wenn es deine Zeit zu sterben ist, stirb auf deine Weise. Gib ihr nicht diese Genugtuung.“\n– Pantheon","Einheit",[],["Targon"],"EPISCH"],"07BC005":["Geschnitzte Klingenwirblerin","","","„Damit hab ich nicht gerechnet.“\n– Fee Klingenwirbler","Einheit",["FEE"],["Bandle"],"GEWÖHNLICH"],"07BC009":["Tortenwurf","Verursache 1 Schaden an einer Einheit. Erschaffe 1 Tödliche Torte auf der Hand.","","In Deckung!","Zauber",[],["Bandle"],"SELTEN"],"07BC015":["Komprimieren","Wähle einen Begleiter. Erschaffe eine Kopie von ihm mit 1 Kosten auf der Hand und setze seine Werte auf 1|1.","","„Hmm … Ich schätze, kleiner bedeutet nicht immer auch niedlicher!“\n– Lulu","Zauber",[],["Bandle"],"SELTEN"],"07DE002":["Durchsuchungsbefehl","Ein Verbündeter mit 4+ Stärke hält eine Einheit fest oder ein Verbündeter hält ein Wahrzeichen fest.","","„Beweg dich nicht und sei still. Jeglicher Widerstand wäre unklug.“\n– Inspektor der Magiesuchenden","Zauber",[],["Demacia"],"SELTEN"],"07DE005":["Formation bilden!","Gib einem Verbündeten in dieser Runde +2|+2.","","„Haltet stand! Ihr seid angeschlagen, nicht gebrochen!“\n– Unerschrockene Vorhut","Zauber",[],["Demacia"],"GEWÖHNLICH"],"07DE008":["Altar der Einigkeit","Wenn ich beschworen werde, ziehe eine Einheit.\nWenn du einen Verbündeten beschwörst, erhöhe seine Werte auf die Höhe seiner Kosten.","","Als sie zum ersten Mal den Altar sah, fehlten Cithria die Worte. Eine Weile lang konnte sie nur in Ehrfurcht vor der Würde dieser geehrten Helden vor ihm stehen. Würde sie jemals tapfer genug sein, um sich einen Platz an ihrer Seite zu verdienen?","Wahrzeichen",[],["Demacia"],"SELTEN"],"07PZ019":["Chemtech-Raupenmobil","Ich habe +1|+0 für jeden Verbündeten mit 1 Kosten, den du in diesem Spiel beschworen hast.","","„Ich muss das Pferdi mit VIELEN Beinen zeichnen, Herr Echse, weil wir müssen SCHNELL zum Schloss. Oh, oh, er is ’n bisschen … schleimig-klebrig geworden. Und ’n bisschen gwün.“ \n– Ingvar die Jüngere","Einheit",[],["Piltover & Zhaun"],"SELTEN"],"07PZ021":["Anura & Fruup","Verbündete, die eine andere Unterart als andere ausgespielte Verbündete haben, kosten 1 weniger.","","„Ich werde dir nicht wehtun, mein Freund! Ich bin in diesem Dschungel, um zu forschen, nicht, um zu zerstören.“","Einheit",["REPTIL"],["Piltover & Zhaun"],"EPISCH"],"07PZ022":["Göttlicher Windhauch","Verursache 1 Schaden an einem Gegner oder dem gegnerischen Nexus und 1 an einem anderen.","","Den meisten Piltoveranern sind die Muster des Winds völlig egal. Aber für viele Zhauniten verheißt selbst eine Schwache Brise eine Erlösung.","Zauber",["ELEMENTAR"],["Piltover & Zhaun"],"GEWÖHNLICH"],"07PZ013":["Grubenmonument","Wenn dein Nexus Schaden durch Quellen erleiden würde, die kein Giftiger Poffpilz sind, werden stattdessen pro Schaden 5 Giftige Poffpilze in deinem Deck versteckt.","","Tief unter den Straßen von Zhaun bist du, was du isst.","Wahrzeichen",[],["Piltover & Zhaun"],"EPISCH"],"07PZ015":["Epische Bastelkonstruktion","Verbrauche zum Ausspielen dein gesamtes Mana. Beschwöre 1 Unkontrollierbare Bastelei und erhöhe ihre Werte auf diesen Betrag.","","„Ein Wissenschaftler ist primär dafür verantwortlich, Variablen unter Kontrolle zu behalten. Die Konsequenzen von Unfällen in einem Forschungsfeld wie unserem – oh, ich will gar nicht daran denken!“\n– Professor Heimerdinger","Zauber",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"07NX028":["Hauptmann Kalrix","Nexusschlag: Verursache Schaden (wird aufgerundet) am gegnerischen Nexus in Höhe der Hälfte seines Lebens.","","Das Imperium von Noxus wurde in erster Linie für eine Ausweitung errichtet. Ob Holz, Stein oder Stahl – nichts kann den Vormarsch eines noxianischen Rammbocks aufhalten.","Einheit",[],["Noxus"],"EPISCH"],"07NX034":["Scharlachroter Festsaal","Verbündete kosten 1 weniger. Wenn du einen Verbündeten ausspielst, verursache 2 Schaden an ihm.","","„Kommt, meine Freunde. Setzt euch! Hier findet ihr gute Gesellschaft und reichlich zu trinken. Ich kann es kaum erwarten, euch das Abendessen zu servieren.“\n– Vladimir","Wahrzeichen",[],["Noxus"],"EPISCH"],"07NX032":["Rabendorn-Foliant","Wenn mein Träger eine Fertigkeit ausspielt, kopiere sie.","","Das Rabendorn-Konservatorium war besonders für seine Sammlung von Texten berühmt, von denen viele letztendlich zum Öl für das tobende Feuer wurden, das von einer berüchtigt schwierigen Schülerin gelegt wurde …","Ausrüstung",[],["Noxus"],"SELTEN"],"07NX033":["Dreischwänziger Knochenpanther","Wenn ich beschworen werde, gewähre mir +1|+1 pro unterschiedlicher Unterart anderer Verbündeter.","","„Seid vorsichtig, ihr Schwachköpfe! Noxianer kaufen nur Kampfbestien in perfektem Zustand. Den kleinsten Kratzer ziehe ich euch vom Lohn ab!“\n– Großwildmagnat","Einheit",["KATZE"],["Noxus"],"GEWÖHNLICH"],"07RU015":["Der Porokönig","Herkunft: Das Dekret des Porokönigs.\nWenn du in einer Runde zum ersten Mal einen anderen Poro beschwörst, erschaffe 1 Poro-Snack auf der Hand.","Du hast 6+ andere neue Poros beschworen. Wenn ich eine Stufe aufsteige, erschaffe einen zufälligen Spezial-Snack auf der Hand.","Ingvar erkennt Potenzial, wenn sie es sieht. Er mag zwar selbstgebastelt aussehen, aber dieser allseits beliebte Begleiter könnte ganz locker der Herrscher über eine Gazillion Milliarden Poros sein – wenn man es sich nur vorstellt. ","Einheit",["PORO"],["Runeterra"],"Champion"],"07RU012":["Neeko","Herkunft: Dschungelfreunde aller Arten!\nAusspielen: Du kannst mich als 1 von 3 Begleitern mit 2 Kosten aus meiner Herkunft tarnen.","Angriff: Du hast mit Verbündeten angegriffen, die 6+ verschiedene Unterarten haben.","Neeko kann viele Formen annehmen, doch ihr Herz bleibt immer unverändert – und es führt sie stets zurück zu ihrer Familie und ihrem Wald.","Einheit",["GESTALTWANDLER"],["Runeterra"],"Champion"],"07BW043":["Anrufung der Gezeiten","Verursache 1 Schaden an einer Einheit. Krakenruf (1) für jeden verursachten Schaden.","","Nur die Erfahrensten können die Elemente ihrem Willen unterwerfen.","Zauber",["ELEMENTAR"],["Bilgewasser"],"SELTEN"],"07BW035":["Versteck des Schwindlers","Deine Karten auf der Hand haben Flüchtig.\nWenn du eine Karte ausspielst, ziehe 1.","","„Entweder kennt man seine Karten und hält sie geheim, oder man muss damit rechnen, alles zu verlieren.“\n– Twisted Fate","Wahrzeichen",[],["Bilgewasser"],"EPISCH"],"07BW042":["Deckjäger","Ausspielen: Manifestiere einen Begleiter mit einer anderen Unterart als ausgespielte Verbündete.","","„Gibt schon ’nen Grund, warum wir den kleinen Streuner hier haben wollen: Keine Hafenrattenplage seit Jahren!“\n– Deckshelferin","Einheit",["KATZE"],["Bilgewasser"],"GEWÖHNLICH"],"07BW039":["Drachenprinz Grinzo","Wenn du zum ersten Mal in einer Runde einen Verbündeten mit 1 Kosten beschwörst, fülle 1 Zaubermana wieder auf.","","„Herr Echse, was machst du denn hier? Magst du auch so gerne Poros?!“\n– Ingvar die Jüngere","Einheit",["DRACHE"],["Bilgewasser"],"SELTEN"],"07BW033":["Sirenengesang","Beschwöre eine zufällige Hülle.\nGewähre Verbündeten mit 1 Kosten überall +1|+1.","","Einige Matrosen aus Bilgewasser stopfen sich sogar in den stillsten Nächten auf See Baumwolle in die Ohren. Sie wissen nur zu gut, dass die Musik, die aus den Wellen erklingt, nichts als ein nasses Grab verspricht.","Zauber",[],["Bilgewasser"],"GEWÖHNLICH"],"07IO041":["Belebende Brise","Heile deinen Nexus um 3 und ziehe 2 Zauber.","","„Der Wind ist des Wanderers einziger Verbündeter.“\n– Yasuo","Zauber",["ELEMENTAR"],["Ionia"],"GEWÖHNLICH"],"07IO043":["Allsehendes Orakel","Ausspielen: Wähle 1 von 3 schnellen oder langsamen Zaubern aus der Hand oder dem Deck deines Gegners. Erschaffe für ihn 1 Prophezeiende Schnitzereien.","","Das von der materiellen Welt gelöste Auge sieht alles. Er mag zwar blind wirken, doch jene, die das Orakel für ein leichtes Ziel halten, werden schnell und gnadenlos zurechtgewiesen.","Einheit",[],["Ionia"],"SELTEN"],"07IO049":["Airis","Nexusschlag: Beschwöre 1 zufällige Hülle.","","„Ganz ruhig, wir sind fast da. Du hast doch gesagt, du willst meine Freundin treffen, oder? Vertrau mir, sie wird dich lieben.“","Einheit",[],["Ionia"],"SELTEN"],"07SH038":["Pakaa-Junges","Hinterhalt (1).\nNexusschlag: Beschwöre 1 Pakaa-Beschützer.","","Niedlichkeit ist Aussehen, aber Wildheit ist Instinkt. Mit genug Zeit und Anweisung kann selbst der kleinste Pakiti wild und stark werden.","Einheit",["KATZE"],["Shurima"],"GEWÖHNLICH"],"07SH041":["Blindlings ins Gebüsch","Manifestiere eine Karte mit Hinterhalt.","","Die Gebietserkundung im Dschungel ist vor allem aus einem Grund die unbeliebteste Aufgabe: Sie steckt voller Überraschungen.","Zauber",[],["Shurima"],"SELTEN"],"07SH004":["Pirschen","Gib einem Verbündeten in dieser Runde +2|+0. Wenn es ein Schatten im Gebüsch ist, gib ihm stattdessen +2|+2.","","„Tritt leise, Pakiti. Schlag zu.“\n– Nidalee","Zauber",[],["Shurima"],"GEWÖHNLICH"],"07SH013":["Nidalee","Hinterhalt (2).","Ich habe gesehen, wie du 4 andere Verbündete beschworen oder verwandelt hast.","„Ich werde dich immer beschützen, Echsenmädchen. Wir werden es diesen Wilderern zeigen. Gemeinsam.“\n– Nidalee","Einheit",["KATZE"],["Shurima"],"Champion"],"07SH009":["Rächender Vastaya","Hinterhalt (3).\nWenn ich mich von einem Hinterhalt des rächenden Vastaya verwandle, halte alle gegnerischen schnellen und langsamen gegnerischen Zauber sowie Fertigkeiten auf.","","„Habt keine Angst, meine Kleinen. Ich werde euch beschützen – und meine Schuld vor Nidalee begleichen.“","Einheit",[],["Shurima"],"GEWÖHNLICH"],"07SH039":["Geländetrupp","Hinterhalt (0).\nWenn ich beschworen werde oder mich verwandle, belege den schwächsten Gegner mit Verletzlich.","","„Diese Schönheit hier kann sogar aus einem Anfänger einen baumkletternden, felsspringenden Profi machen. Hat mich ein Vermögen gekostet, aber ich bin mir sicher, ich kann diese Kredite mit der Haut von einer oder zwei seltenen Wildtieren abbezahlen …“","Einheit",[],["Shurima"],"SELTEN"],"07SH044":["Aurora Hallunatis","Hinterhalt (4).\nWenn ich mich verwandle, beschwöre 1 Aurora Hallunatis.","","„Wie gern ich selbst eine sehen würde! Die meisten Entdecker halten die Aurora Hallunatis für einen Mythos, doch ein junger Mann schwört auf das Gegenteil. Er erzählte mir, dass der Vogel bunt gefiedert ist und seine Flügelspanne so breit ist wie ein Mann groß. In ihre Augen zu blicken, vertraute er mir eines Nachts an, ist zu erkennen, dass man Beute ist.“\n–Aus Anuras Reisetagebuch, Tag 21","Einheit",["VOGEL"],["Shurima"],"SELTEN"],"07SH003":["Ballongetragener Wilderer","Hinterhalt (3).\nWenn ich mich von einem Hinterhalt des ballongetragenen Wilderers verwandle und ich in dieser Runde das nächste Mal abwehre oder abgewehrt werde, halte meinen Gegner fest.","","„Ha! Versucht jetzt, mich zu kriegen, ihr dummen Kreaturen. Nicht einmal die Schwerkraft kann die überlegene Spezies bezwingen!“","Einheit",[],["Shurima"],"EPISCH"],"07SH011":["Auflauern","Wenn ich beschworen werde oder sich in einer Runde zum ersten Mal ein Verbündeter verwandelt, belege den schwächsten Gegner mit Verletzlich.","","„Blut in der Luft.“\n– Nidalee","Wahrzeichen",[],["Shurima"],"GEWÖHNLICH"],"07SH046":["Tal der Imitation","Wenn du einen Begleiter ausspielst, verwandle mich in dieser Runde in eine exakte Kopie von ihm.","","„Und daf hier ift der WUN-DER-PFÖN-STE und beliebtefte Halt der Tour. Meine Tour gefiel fo vielen Leuten, daff sie einen GROẞEN, STARKEN KIEFEL bauten, der nun für immer und ewig Teil meiner Tour ist. Gehen wir hin und fagen „HALLO GROẞER KIEFEL!“ Großer Kiefel liebt ALLE und be-fon-ders jeden, der mit ihm auf diefe Tour gegangen ift.“\n– Abenteuer mit Kiesel, Teil 6","Wahrzeichen",[],["Shurima"],"GEWÖHNLICH"],"07SH043":["Gewaltiger Phytofant","Hinterhalt (5).","","Manche sagen, Phytofanten tragen als die ältesten Bewohner des Dschungels seine Erinnerungen und sein Herz in sich. Zwar sind sie normalerweise sanfte Kreaturen, doch sie zögern nicht, ihre Heimat gegen jede Bedrohung zu verteidigen – ob nun klein oder groß. ","Einheit",[],["Shurima"],"EPISCH"],"07SH040":["Borstenschwein","Wenn sich zum ersten Mal ein Verbündeter verwandelt, gewähre mir +2|+1.","","„Kleine allesfressende Säugetiere, mit borstenartigen Stacheln überzogen, die sie mit hoher Geschwindigkeit abfeuern können, wenn sie gestört werden. Der Schwanz ist scharf und agil, wird vermutlich zur Verteidigung verwendet. Erfahrenen Entdeckern zufolge sind diese Kreaturen berüchtigt für ihre üble Laune und schwer zu bändigen …“\n– Aus Anuras Reisetagebuch, Tag 3","Einheit",[],["Shurima"],"SELTEN"],"07SH005":["Großwildmagnat","Ausspielen: Manifestiere eine Karte mit Hinterhalt.\nWenn sich ein Verbündeter verwandelt, verdopple seine Stärke und sein Leben.","","„Ihr habt alles an WAS verloren? Eine Wissenschaftlerin und ein abnormales Reptil? Was steht ihr noch blöd rum, ihr Schwachköpfe? Ab mit euch, und holt mein Geld zurück!“","Einheit",[],["Shurima"],"SELTEN"],"07FR011":["Tempel des Wahren Eises","Wenn du einen Verbündeten beschwörst, erhöhe sein Leben auf den Wert seiner Stärke.","","Die Bedeutung dieses Tempels ist zwar seit langer Zeit vergessen, doch sein steinerner Wächter steht immer noch aufrecht, unbeeindruckt von der Last vieler Lawinen. Von Frost bedeckt scheint er mit einem merkwürdigen und verlockenden Licht erfüllt …","Wahrzeichen",[],["Freljord"],"EPISCH"],"07FR010":["Schneeweiße Klingenklaue","Plündern: Erhöhe die Werte eines Verbündeten auf meine.","","Schneeweiße Klingenklauen jagen zwar hauptsächlich kleine Säugetiere, doch dieses Raubtier aus Freljord hat genug Klauen, um aus fast allem eine Speise zu machen.","Einheit",["VOGEL"],["Freljord"],"GEWÖHNLICH"],"07FR015":["Ingvar die Jüngere","Ausspielen: Wähle einen Verbündeten. Gewähre ihm und allen anderen Verbündeten mit derselben Unterart +1|+1 oder manifestiere einen Begleiter, der dieselbe Unterart hat.","","Ingvar, selbsternannte Poroaufseherin und Erkunderin von Freljord, weiß ganz genau, dass da draußen das Abenteuer wartet – und dass sie es finden wird. ","Einheit",[],["Freljord"],"EPISCH"],"07FR017":["Kristalliner Sturmraptor","Ausspielen: Verursache 2 Schaden an ALLEN anderen Einheiten.","","Die Brutalität der kristallinen Sturmraptoren unterscheidet nicht zwischen Freund und Feind und schlägt blitzschnell zu. Sie kann das Blatt in der Schlacht von einem Augenblick zum nächsten wenden. Viele betrachten den Vogel als erstes Anzeichen für einen aufziehenden, schrecklichen Sturm, der so gewaltig sein wird, dass er die Erde selbst bis in den Kern erschüttern wird.","Einheit",["VOGEL"],["Freljord"],"SELTEN"],"07FR016":["Gletschersaurier","Wenn ich beschworen werde, gewähre den obersten 3 Einheiten in deinem Deck +1|+1. Wenn ein Verbündeter eine andere Unterart als ich hat, ziehe eine dieser Einheiten.","","Mit ihrem knochigen Äußeren, das ein großes Herz verbirgt, sind diese zuverlässigen Reittiere unverzichtbar für die Überquerung eisiger Bergpässe.","Einheit",["REPTIL"],["Freljord"],"SELTEN"],"07SI010":["Nekrotischer Arachnoid","Wenn ich beschworen werde, beschwöre 2 Nekrotische Nestlinge.\nWenn ein anderer Verbündeter stirbt, entziehe dem gegnerischen Nexus 1.","","Diese Spinnen sind nur in den finstersten Gebieten der Schatteninseln zu finden und sondern ein tödliches Nekrogift ab, das die Haut betäubt, während das Fleisch bereits zu verfaulen beginnt.","Einheit",["SPINNE"],["Schatteninseln"],"EPISCH"],"07SI012":["Pelziger Netzspinner","Ausspielen: Wenn ein Verbündeter eine andere Unterart als ich hat, gib einem Gegner in dieser Runde -2|-0.","","Pelzige Netzspinner weben ihre Netze sehr behutsam. Sie sorgen sich besonders um ihre Jungspinnen … sind aber gleichermaßen grausam, wenn es um mögliche Bedrohungen geht.","Einheit",["SPINNE"],["Schatteninseln"],"GEWÖHNLICH"],"07SI013":["Rumorender Dunkelgeist","Letzter Wunsch: Erschaffe im Deck eine exakte Kopie deines stärksten Rumorender Dunkelgeist im Deck. Verdopple die Werte von Rumorenden Dunkelgeistern im Deck.","","„Der Nebel hat mich viele Dinge gelehrt. Die wichtigste Lektion war, zu wissen, wenn es Zeit zum Wegrennen ist.“\n– Wächterin der Ixtali","Einheit",[],["Schatteninseln"],"SELTEN"],"07SI004":["Heilige Schere","Angriff: Wenn ein anderer Verbündeter Stärke durch Geweiht erhält, erhält mein Träger sie ebenfalls.","","„Mit einer scharfen Schere und einem festen Faden kann man fast alles wieder zurechtflicken!“\n– Gwen","Ausrüstung",[],["Schatteninseln"],"SELTEN"],"07MT009":["Zeitalter der Drachen","Ziehe jeden Drachen aus den obersten 9 Karten in deinem Deck und senke ihre Kosten in dieser Runde auf 0. Mische den Rest zurück ins Deck.","","„Einen Drachen zu kennen, ist Herr über das Selbst zu werden. Viele zu kennen, ist Herr über die Welt zu werden.“\n– Drachenverehrerin der Ottrani","Zauber",[],["Targon"],"SELTEN"],"07MT013":["Kosmischer Ruf","Ersuche eine himmlische Karte mit 7 oder mehr Kosten oder gib 8 Mana aus, um die Kosten deiner himmlischen Karten überall um die Hälfte zu senken (wird aufgerundet).","","Der Beurteiler hält seine ewige Wache, während die Segen des Himmels herniederfahren.","Zauber",[],["Targon"],"GEWÖHNLICH"],"07MT006":["Unglückseliges Liebespaar","Ausspielen: Rufe einen Verbündeten zurück und gewähre ihm meine Werte.","","„Nur wenige Anblicke sind prächtiger als die Begegnung von Sonne und Mond.“\n– Diana","Einheit",[],["Targon"],"GEWÖHNLICH"],"07BC020":["Herr Trödler","Wenn mindestens eine deiner Fallen oder Segen aktiviert werden, platziere 2 davon im Deck des entsprechenden Spielers.","","Niemand weiß, wie lange Herr Trödler schon sammelt oder wo er überhaupt herkommt. Er wirkt freundlich, aber man sollte auf die gefährliche Spur aus Stolperfallen aufpassen, die er hinterlässt, wohin er auch geht.","Einheit",[],["Bandle"],"SELTEN"],"07BC016":["Umdrehschlüssel","Wenn ich abgeworfen werde, rüste einen zufälligen nicht ausgerüsteten Verbündeten mit mir aus.","","„Um ehrlich zu sein, verliere ich ständig meine Werkzeuge. Dieser hier taucht aber immer wieder auf, wenn ich ihn brauche!“\n– Sicherheitsinspektor","Ausrüstung",[],["Bandle"],"GEWÖHNLICH"],"07BC018":["Portalgelehrter","Wenn ich beschworen werde, verstecke 1 Geheimnisvolles Portal in den obersten 4 Karten deines Decks.\nWenn du einen erschaffenen Verbündeten beschwörst, gewähre ihm Einschlag.","","Bei jeder Forschung muss man mit Überraschungen rechnen – zum Glück ist das hier eine von den guten. ","Einheit",["FEE"],["Bandle"],"EPISCH"],"07BC011":["Furchterregende Flauschbälle","Wenn ich beschworen werde, gewähre anderen Verbündeten, die eine Unterart haben, +1|+1 und Einschlag.","","Zum Unglück dieser piltoveranischen Wilderer sehen sie nur harmlos aus.","Einheit",["VOGEL"],["Bandle"],"GEWÖHNLICH"],"07DE014":["Kritischer Feldwebel","Ausspielen: Wähle eine Einheit aus den obersten 5 Karten deines Decks, die 3 oder weniger kostet. Beschwöre sie und lege den Rest zurück ins Deck.","","Der demacianische Einberufungsoffizier trägt eine wichtige Verantwortung. Seine Rekruten werden viele verschiedene Positionen einnehmen, vereint in ihrer Pflicht und Liebe zu Demacia.","Einheit",["ELITE"],["Demacia"],"EPISCH"],"07DE015":["Federschopf-Löwenfalke","Ausspielen: Wenn ein Verbündeter eine andere Unterart als ich hat, manifestiere einen demacianischen Zauber.","","„Ich schreibe die erste bestätigte Sichtung eines Löwenfalken in fast 50 Jahren nieder. Wunderschöne blaue Mähne, intelligenter Blick. Körper ist gepanzert, aber Knochen leicht genug für das Erklettern von Bäumen, wenn nicht sogar kurzes Gleiten. Flügelstruktur erinnert beinahe an demacianische Silberschwingen. Werde mit weiteren Erkenntnissen fortfahren.“\n– Aus Anuras Reisetagebuch, Tag 12","Einheit",["VOGEL"],["Demacia"],"SELTEN"],"07DE011":["Gehilfe der Magiesuchenden","Zauber, die weniger als 3 Mana kosten, kosten stattdessen 3 Mana.","","„Ruhe! Das hier ist nicht lediglich ein Spiel, wie du behauptest, sondern eine Art heimtückische, arkane Beschäftigung. Ich werde dich als Betrüger und Magier enttarnen, du alter Schuft – und wenn ich dafür diesen Ort niederbrennen muss!“","Einheit",[],["Demacia"],"GEWÖHNLICH"],"07DE016":["Balen der Barmherzige","Angriff: Gewähre anderen formidablen Verbündeten überall +0|+1.","","Balen gehört schon länger zu den großen Champions der Durands. Seine Größe täuscht darüber hinweg, wie präzise er sein kann. Er fing als Assistent an, doch Balen kennt sich sehr gut in der Herstellung aus und nutzt einzigartige Inspirationen in der Umsetzung. Die Durands sind sehr stolz, ihn ihren Freund zu nennen.","Einheit",[],["Demacia"],"EPISCH"],"08SI042":["Mordekaiser","Ausspielen: Töte bis zu 2 Verbündete.\nWenn du einen anderen Verbündeten besiegst, belebe ihn wieder.","15+ Verbündete sind gestorben. Verbündete mit 5+ Stärke zählen doppelt.","Mordekaiser ist im Herzen der Unsterblichen Bastion an seine Rüstung gebunden und hat sich dort einen eigenen Thron für das graue Reich geschaffen. Für jede Seele, die ihn vernichten will, gibt es mehr Seelen, die ihm treu im Leben wie im Tod dienen.","Einheit",[],["Schatteninseln","Noxus"],"Champion"],"08SI040":["Erastin, der Entehrte","Wenn ich beschworen werde, gewähre mir Unsterblich.\nAngriff: Gib Gegnern in dieser Runde -1|-0.","","Die Drachen von Camavor waren einst prächtig und geachtet – doch selbst sie waren nicht sicher vor der alles verschlingenden Verderbnis der Zerstörung. Erastin ist keine Ausnahme: Seine lange verlorene Würde wurde zum fahlen Abbild der Unsterblichen verzerrt.","Einheit",["DRACHE"],["Schatteninseln"],"EPISCH"],"08SI007":["Legion der entrissenen Seelen","Ausspielen: Gewähre einem Verbündeten auf der Hand Unsterblich.","","Es ist unerheblich, welche Form eine Seele vor ihrer Gefangenschaft im grauen Reich hatte. Dort hat Individualität keinerlei Bedeutung. Gesichtslos und furchtlos dient die Legion dem eisernen Albtraum mit ihrer unschlagbaren Gleichförmigkeit.","Einheit",[],["Schatteninseln"],"GEWÖHNLICH"],"08SI003":["Gefesselte Untote","Letzter Wunsch: Wenn du das nächste Mal einen Verbündeten wiederbelebst, erschaffe eine Kopie von mir auf der Hand.","","„Wir wurden vor undenklicher Zeit in Ketten gelegt. Schon bald wirst du unser Leiden verstehen und wir alle werden bis in alle Ewigkeit leiden, bis unser Meister uns ins Vergessen entlässt …“","Einheit",[],["Schatteninseln"],"SELTEN"],"08SI021":["Einsamer Glockenglibber","Wenn ein anderer Verbündeter stirbt oder Letzter Wunsch: Verstecke 4 Glocken in deinem Deck.","","Mach dir über das unheilvolle Klingeln keine Gedanken – das ist nur ein alter Glockenglibber, der seine Runden dreht. Er freut sich immer auf Neuankömmlinge – aber sie freuen sich ganz und gar nicht, ihn zu sehen.","Einheit",[],["Schatteninseln"],"GEWÖHNLICH"],"08SI030":["Nasses Grab","Vernichte die 6 untersten Karten im gegnerischen Deck.","","Für einige der Seeungeheuer aus Runeterras Untiefen ist ein Jaul-Schiff nur ein kleiner Imbiss.","Zauber",[],["Schatteninseln"],"EPISCH"],"08SI037":["Gespenstischer Eisenhund","Töte einen Verbündeten, um mich auszuspielen.\nWenn ich beschworen werde, beschwöre 1 Todeswinder der tausend Klauen.","","Diese Hunde vergessen niemals den Geruch jener, die zu fliehen versuchten – und wenn sie ihre Beute in die Ecke treiben, ist ein Todeswinder nie fern.","Einheit",[],["Schatteninseln"],"SELTEN"],"08SI041":["Umklammerung des Unheils","Töte einen Verbündeten, um 5 Schaden an einer Einheit zu verursachen.","","„Die Finsternis erwartet alle, bis auf mich.“\n– Mordekaiser","Zauber",[],["Schatteninseln"],"GEWÖHNLICH"],"08SI036":["Grenze zum Grauen","Ausspielen: Verfluche einen Gegner mit Schrecken.\nWenn du einen titanischen Verbündeten beschwörst, zerstöre mich, um 2 zu ziehen.","","„Diese Seelen opfern wir dir. Diese Straße bauen wir aus Knochen für dich. Diese Reiche lassen wir brennen, um den Weg für deine ewige Eisenarmee zu ebnen.“\n– Kultistin der unheilvollen Umklammerung","Wahrzeichen",[],["Schatteninseln"],"SELTEN"],"08SI004":["Todesreich","Ein Verbündeter beginnt einen kostenlosen Angriff, indem er den stärksten Gegner herausfordert.\nTöte ALLE anderen Einheiten.","","„Der Tod ist mein Herrschaftsgebiet.“\n– Mordekaiser","Zauber",[],["Schatteninseln"],"EPISCH"],"08SI026":["Kultistin der unheilvollen Umklammerung","Wenn ich beschworen werde oder du einen titanischen Verbündeten beschwörst, verfluche den stärksten Gegner mit Schrecken.","","Für seine Anhänger ist der eiserne Albtraum die einzige Hoffnung auf den endgültigen Tod. Frieden durch Dominanz. Diese Kultisten heißen sie mit offenen Armen willkommen.","Einheit",[],["Schatteninseln"],"SELTEN"],"08SI018":["Spektraler Begutachter","Ausspielen: Wähle einen Erkunderzauber, der auf der Hand erschaffen wird.","","„Das Terrain ist unergründlich. Die Sicht so gut wie nicht vorhanden. Ich bin an jeder Ecke auf Gegner getroffen – doch seltsamerweise auch auf unerwartete Verbündete.“\n– Aus den Expeditionsaufzeichnungen der Fernkundedivision der Erkundergilde, Zuteilung: Schatteninseln","Einheit",[],["Schatteninseln","Targon"],"SELTEN"],"08SI015":["Verschmelzung abscheulicher Rituale","Töte einen Verbündeten, um mich auszuspielen.\nLetzter Wunsch: Heile deinen Nexus um 2.","","Kriegsbestien haben in jeder Streitmacht ihren Platz. Im grauen Reich sind sie gepeinigte Verschmelzungen von Seelen, jede auf ihre Weise in ihrer Gefühllosigkeit verheerend. ","Einheit",[],["Schatteninseln"],"EPISCH"],"08BW008":["Nilah","Angriff: Erschaffe 1 Stromschnellen in den obersten 6 Karten deines Decks.","Du hast 15+ Karten gezogen.","Im Norden wartet ein neuer Herausforderer auf Nilah und ihre Monsterjägertruppe: eine Kreatur namens Volibear, die einst in Freljord angebetet wurde und nun mit seiner Vernichtung droht. Für Nilah ist die Chance, ihr Können gegen ein Monster zu beweisen, das andere einen Gott nennen, die Gelegenheit ihres Lebens. Ganz zu schweigen von den kleineren Monstern, mit denen sie nebenbei ihre Liste von Errungenschaften erweitert. ","Einheit",[],["Bilgewasser"],"Champion"],"08BW032":["Unendliche Freude","Gib Verbündeten in dieser Runde +1|+0 und heile verletzte Verbündete um 2.","","„Freude, unbändig und immerwährend!“\n– Nilah","Zauber",["ELEMENTAR"],["Bilgewasser"],"GEWÖHNLICH"],"08BW038":["Chakram-Tänzerin","Ausspielen: Verursache 1 Schaden an einem beliebigen Ziel.\nDeine Fertigkeiten entziehen Leben.","","Sie bewegt sich in einem Tanz von Wasser und Klingen, zieht Stahl aus dem Tosen von Gischt und Salz. Sie muss nicht sehen, um den Strom ihrer Waffen zu fühlen – sie sind lebendiges Wasser, und sie müssen immer zum Wasser zurückkehren.","Einheit",[],["Bilgewasser"],"EPISCH"],"08BW015":["Die Gezeitentänzerin","Wenn ich beschworen werde, ziehe eine Nilah.\nWenn du in einer Runde deine dritte Karte ausspielst, gib anderen Verbündeten in dieser Runde +2|+0 und Furchtlos.\nWenn ich Flüchtig erhalten würde, enthülle mich stattdessen.","","„Wie ich höre, ist dieses seltsam geformte Schiff das schnellste, das Bilgewasser je gesehen hat. Und flink. Hat eine eigentümliche Kapitänin, aber auf mich wirkte sie, als würde sie wissen, was sie tut. Vielleicht könnten wir das Eine oder Andere lernen.“\n– Barkeeper in Bilgewasser","Einheit",[],["Bilgewasser"],"EPISCH"],"08BW002":["Formlose Klinge","Verursache 2 Schaden an einer Einheit. Ihr Leben kann durch diesen Schaden nicht unter 1 fallen.","","„Monster, die sich selbst als Götter bezeichnen, fallen tief, egal in welchem Land.“\n– Nilah","Zauber",["ELEMENTAR"],["Bilgewasser"],"GEWÖHNLICH"],"08BW025":["Aufmerksamer Ausguck","Sobald du in diesem Spiel in einer Runde 3+ Karten gezogen hast, gewähre mir +1|+1 und Furchtlos.","","„Hey, Kumpel, warum der ganze Wirbel? Entspann dich! Im Wasser ist nichts, womit wir nicht fertigwerden!“\n– Anbeter der Herausforderung","Einheit",[],["Bilgewasser"],"GEWÖHNLICH"],"08BW026":["Anbeter der Herausforderung","Wenn ich beschworen werde, aktiviere Aufwind für deine gesamte Hand, um mir pro Karte +1|+1 zu gewähren und 2 zu ziehen.","","„Komm schon, gibst du dir überhaupt Mühe? Fühlt sich an, als müsste ich mich zurückhalten, und das hasse ich!“","Einheit",[],["Bilgewasser"],"SELTEN"],"08BW028":["Okto-Abenteurer","Ausspielen: Wähle einen Erkunderzauber, der auf der Hand erschaffen wird.","","„Merkwürdiges Exemplar. Sehr blau. Überaus große Augen. Unangenehm groß. Werde es mir für weitere Untersuchungen aneignen.“\n– Aus den Expeditionsaufzeichnungen der Fernkundedivision der Erkundergilde, Zuteilung: Piltover","Einheit",[],["Bilgewasser","Piltover & Zhaun"],"SELTEN"],"08BW009":["Lebenskluger Steuermann","Ausspielen: Manifestiere zwei verschiedene Elementarzauber, die du in diesem Spiel ausgespielt hast. Sie kosten in dieser Runde 0.","","„Der Verstand ist ein Fluss. Im Laufe der Zeit formt sein entschlossenes Fließen die Hänge von Bergen. Und wie der Verstand wird er durch seine Wucht immer breiter und erreicht neue Ufer.“","Einheit",[],["Bilgewasser"],"SELTEN"],"08BW010":["Sturzflut","Für den Rest des Spiels verursachen alle deine Elementarzauber und Elementarfertigkeiten 1 Schaden zusätzlich.","","„In den Händen der Weisen kann das Wasser alles formen.“\n– Anbeter der Weisheit","Zauber",["ELEMENTAR"],["Bilgewasser"],"EPISCH"],"08BW031":["Sefirsa, Geißel der Tiefe","Wenn du Mana ausgibst, um eine andere Einheit auszuspielen, erschaffe eine zufällige Karte mit denselben Kosten auf der Hand. Sie kostet 0 und ist flüchtig.","","Es gibt einige Monster, die in Bilgewasser trotz seines Heißhungers auf die seltsamsten Meeresungeheuer nicht einmal von den erfahrensten Kapitänen gejagt werden. Sie sprechen nur im Flüsterton von Sefirsa, von einem hypnotisierenden Licht, das tief unter den Wellen gleitet; einem Monster, das auf einem Massengrab von gesunkenen Schiffen und ertrunkenen Männern lebt.","Einheit",["SEEUNGEHEUER","DRACHE"],["Bilgewasser"],"EPISCH"],"08BW037":["Ehrlicher Croupier","Wenn du eine Karte ausspielst, deren Kosten meiner Stärke entsprechen, gewähre mir +1|+1.","","„Pass auf, äh, willst du nicht vielleicht noch mehr wagen? Wer nicht wagt, der nicht gewinnt, verstehst du? Das ist heute Abend ein Glückstisch, ich sag’s dir. In diesem angesehenen Etablissement handelt die Bank absolut fair. Das schwöre ich bei der Zunge meiner Mutter.“","Einheit",[],["Bilgewasser"],"SELTEN"],"08BW036":["Riffturm der Marai","Wenn du Mana ausgibst, um eine Einheit auszuspielen, fülle 1 Zaubermana wieder auf.","","„Das Riff ist seit jeher eine Zuflucht und ein Verbündeter. Es sorgt für uns, so wie wir für es sorgen, damit wir beide nicht der Tiefe des Dunkels zum Opfer fallen.“\n– Stammmutter der Marai","Wahrzeichen",[],["Bilgewasser"],"GEWÖHNLICH"],"08BW023":["Vikrash, der Überschwängliche","Wenn ich beschworen werde, erschaffe 1 Stromschnellen in den obersten 6 Karten deines Decks.","","„Seht, meine Freunde, wie sich die ganze Welt mit uns bewegt! Die Wellen tanzen unter dem Rumpf, der Wind in den Segeln, die Vögel in der Brise. Begleitet mich auf unserer höchsten Berufung und frohlocket!“","Einheit",[],["Bilgewasser"],"EPISCH"],"08PZ007":["Sturmsangschwarm","Beschwöre 1 Sturmsangschwalbe und gewähre ihr +1|+1 für jeden anderen Elementarzauber oder Elementarfertigkeit, die du in diesem Spiel ausgespielt hast.\nZiehe 1.","","Wenn sich Sturmsangschwalben in großer Zahl versammeln, ist ein Unwetter nie weit.","Zauber",["ELEMENTAR"],["Piltover & Zhaun"],"SELTEN"],"08PZ031":["Ominöse Schutzbrille","Wähle einen verbündeten Begleiter. Verwandle meinen Träger in eine exakte Kopie von ihm, solange ich ausgerüstet bin.","","Frag nicht, wie sie funktioniert.","Ausrüstung",[],["Piltover & Zhaun"],"SELTEN"],"08PZ025":["Porobot-Prototyp","Letzter Wunsch: Gewähre einem zufälligen Zauber mit 6+ Kosten auf der Hand „Wenn ich ausgespielt werde, beschwöre 1 Porobot-Prototyp“.","","„Das ist nur ein Prototyp“, rief der Lehrling, als das Labor von Flammen verschlungen wurde. „Ich habe ihn nicht dazu programmiert, jedes Zahnrad weit und breit zu fressen! Ich wusste nicht mal, wo das ganze Metall HINKOMMT!“","Einheit",["PORO"],["Piltover & Zhaun"],"SELTEN"],"08PZ005":["Auge des Sturms","Gib einem Verbündeten in dieser Runde +2|+0.\nZiehe 2.","","„Bleibe gelassen! Der Sturm mag um dich toben, doch er wird dir kein Leid antun.“\n– Janna","Zauber",["ELEMENTAR"],["Piltover & Zhaun"],"GEWÖHNLICH"],"08PZ019":["Göttlicher Wirbelwind","Wenn du in dieser Runde 3+ Karten gezogen hast, koste ich 2 weniger.\nVerursache 3 Schaden an einer Einheit und 2 Schaden am gegnerischen Nexus.","","„Der Orkan steht unter meinem Befehl.“\n– Janna","Zauber",["ELEMENTAR"],["Piltover & Zhaun"],"SELTEN"],"08PZ028":["Chemtech-Drache","Wenn du einen Zauber ausspielst, ziehe 1. Wenn du eine Karte ziehst, während deine Hand voll ist, verursache 1 Schaden am gegnerischen Nexus.","","In Zhaun muss man anpassungsfähig sein – und der Chemtech-Drache ist keine Ausnahme. Er klammert sich in der Unterwelt der Stadt fest, in das kränklich grüne Licht der Augmentierungen gehüllt. Die Zwillingsschatten der verunstalteten Flügel des Drachen hängen über verdunkelten Gassen als Vorboten eines Zorns, der aus dem Leid seiner eigenen Verderbnis entstanden ist.","Einheit",["DRACHE"],["Piltover & Zhaun"],"EPISCH"],"08PZ001":["Janna","Ausspielen: Aufwind (2), um beim nächsten Rundenbeginn 2 zu ziehen.\nDie ersten 3 Mal, wenn du in einer Runde eine Karte ziehst, senke ihre Kosten in dieser Runde um 1.","Ich habe gesehen, wie du 8 Karten mit verringerten Kosten ausgespielt hast.","„Zhaun liegt Janna mehr am Herzen als jeder andere Ort. Schließlich ist sie es, die die armen Seelen gerettet hat, die Piltover dem Tode überließ. Ja – falls es Antworten gibt, finde ich sie hier.“\n– Windsurfender Seefahrer","Einheit",[],["Piltover & Zhaun"],"Champion"],"08PZ026":["Ruf der Sturmsangschwalbe","Beschwöre 1 Sturmsangschwalbe.","","„Alle Kinder des Windes folgen meinem Ruf.“\n– Janna","Zauber",["ELEMENTAR"],["Piltover & Zhaun"],"GEWÖHNLICH"],"08PZ006":["Iascylla, Galionsfigur der Tiefe","Wenn du einen Elementarzauber oder eine Elementarfertigkeit ausspielst, kopiere sie auf dieselben Ziele.","","„Komm, Iascylla! Du bist wahrlich alt, wenn Ashlesh deinen Namen kennt. Doch ob alt oder jung, hübsch oder hässlich ist egal. Es ist für jedes Monster die höchste Ehre, durch meine Klinge auf dem offenen Meer zu fallen.“\n– Nilah","Einheit",[],["Piltover & Zhaun"],"EPISCH"],"08PZ018":["Windsurfender Seefahrer","Wenn du in dieser Runde 3+ Karten gezogen hast, koste ich 2 weniger.","","„Ja, ich hatte, was ich wollte. Aber ich habe alles durch Nehmen bekommen, und irgendwann macht es einen Menschen leer. Als Erstes bin ich dem Wind gefolgt, also bin ich jetzt hier, in der Hoffnung, sie möge mich auf einen besseren Pfad bringen.“","Einheit",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"08PZ008":["Maryam, Tempelhüterin","Ausspielen: Aufwind (1), um entweder 1 zu ziehen oder dein Zaubermana aufzufüllen.","","Maryam ist davon überzeugt, dass sie als junges Mädchen vom Windgeist gerettet wurde, und pries von ihrer Heimat Shurima bis nach Zhaun die Tugenden von Janna. Jetzt dient sie als Tempelmatriarchin von Zhaun und gibt Jannas Güte an die Jungen und Unterdrückten weiter.","Einheit",[],["Piltover & Zhaun"],"EPISCH"],"08PZ009":["Versunkener Tempel","Rundenende: Aktiviere Aufwind für deine gesamte Hand.\nRundenbeginn: Ziehe entsprechend viele Karten plus 1.","","Vieles ging im katastrophalen Zusammenbruch verloren, der letztendlich Zhaun von Piltover trennte. Janna mag ihren Tempel an die Wellen verloren haben, doch sie rettete die Leute, die in ihm beteten.","Wahrzeichen",[],["Piltover & Zhaun"],"EPISCH"],"08PZ002":["Heulender Sturm","Verursache 2 Schaden an einer Einheit.\nErhöhe meinen Schaden um 1 für jede andere Karte, die du in dieser Runde ausgespielt hast, bis zu 3 Mal.","","„Mein Zorn auf heulenden Winden!“\n– Janna","Zauber",["ELEMENTAR"],["Piltover & Zhaun"],"SELTEN"],"08PZ024":["Unlauterer Fischhändler","Rundenbeginn: ALLE Spieler ziehen 1, gewähre dann der gezogenen Karte des Gegners Flüchtig.","","„Heute gibt es zwei für einen! Nur heute! Frischer Fisch, gerade erst … äh, diesen Monat gefangen. Zwei für einen! Wie jetzt? Du willst den zweiten Fisch nicht? Er ist gratis!“","Einheit",[],["Piltover & Zhaun"],"GEWÖHNLICH"],"08PZ020":["Erhabener Wolkenwirbler","Wenn du in dieser Runde 3+ Karten gezogen hast, koste ich 2 weniger.\nWenn ich beschworen werde, ziehe beim nächsten Rundenbeginn 2 Karten.","","„Mein lieber Zephir. Komm herunter von deinen Wolken und raste eine Weile auf meiner Schulter.“\n– Janna","Einheit",[],["Piltover & Zhaun"],"SELTEN"],"08FR012":["Anrufung des Donners","Ziehe 1.\nBeschwöre 1 Siegel des Sturms.","","„Im Namen Valhirs bringen wir diese Opfergabe dar …“\n– Valhirs Prophetin","Zauber",["ELEMENTAR"],["Freljord"],"GEWÖHNLICH"],"08FR033":["Klingengebundene Berserkerin","Wenn du einen langsamen Zauber ausspielst, der einen einzigen Verbündeten anvisiert, kopiere ihn auf mich.","","„Du denkst, ein oder zwei Pfeile könnten mich aufhalten? Ha! Alles, womit du mich angreifst, wird zu einer Waffe in meinem Arsenal. Alles, was verloren geht, werde ich in Eis neu schmieden!“","Einheit",[],["Freljord"],"GEWÖHNLICH"],"08FR019":["Himmelsbrecher","Gib einem Verbündeten in dieser Runde +1|+3.","","Gehüllt in Wolken und Blitz steht der Bärengott unberührbar inmitten des Sturms.","Zauber",["ELEMENTAR"],["Freljord"],"GEWÖHNLICH"],"08FR001":["Volibear","Ausspielen: Spiele 3 Mal Unerbittlicher Sturm aus. Jeder visiert einen anderen zufälligen Gegner oder den gegnerischen Nexus an, wenn es keinen Gegner gibt.","Rundenende: Du hast 50+ Schaden verursacht.","„Knie nieder, Sterblicher, und vielleicht verschone ich dich! Deine Macht ist dürftig, doch vielleicht würdig genug, meiner zu dienen. Knie nieder oder werde vom Angesicht der Erde gefegt!“","Einheit",[],["Freljord"],"Champion"],"08FR018":["Kampf der Giganten","Beschwöre 2 zufällige titanische Begleiter.\nIch koste 1 weniger pro Elementarzauber oder Elementarfertigkeit, die du in diesem Spiel ausgespielt hast (max. 10).","","„Mit seinem Körper formte ich die Berge. Mit dem Feuer seines Schlundes erschuf ich tausend Fjorde.“\n– Volibear","Zauber",["ELEMENTAR"],["Freljord"],"EPISCH"],"08FR011":["Flammenruferin Caprine","Wenn du einen Elementarzauber oder eine Elementarfertigkeit ausspielst, schmiede mich.","","„Der Schmiedefürst versprach Veränderung und hämmerte stattdessen die Ketten der Tatenlosigkeit. Jene, die einen schwachen Gott anbeten, sind selbst schwach. Nur durch Valhirs Macht wird uns der Ruhm der alten Zeiten zuteil!“","Einheit",[],["Freljord"],"SELTEN"],"08FR008":["Sturmbringer","Verursache 4 Schaden an ALLEN Einheiten außer titanischen Verbündeten.","","„Die Tundra wird sich rot färben!“\n– Volibear","Zauber",["ELEMENTAR"],["Freljord"],"SELTEN"],"08FR024":["Yadulsk-Schneehund","Angriff: Gewähre den obersten 2 Verbündeten in deinem Deck +1|+1.","","Obwohl diese Tiere aus Yadulsk stammen, werden sie schon lange von zahlreichen Stämmen in Freljord für die Jagd, zum Spurenlesen und zur Lawinenrettung domestiziert. Ihre schier unerschöpfliche Ausdauer und ihr verspielter Charakter machen sie zu beliebten Haustieren von der Tundra bis zur Taiga.","Einheit",["HUND"],["Freljord"],"GEWÖHNLICH"],"08FR015":["Rhond, die Magmaschlange","Ausspielen: Beschwöre 3 Siegel des Sturms.","","Zwar beten ihn nur noch wenige an, doch alle Bewohner Freljords kennen die Geschichte von Volibears großer Schlacht mit Rhond. Lange bevor ein Sterblicher den gefrorenen Norden betrat, formte dieser erderschütternde Kampf die Bergzüge und Flüsse der Tundra.","Einheit",[],["Freljord"],"EPISCH"],"08FR030":["Boadir vom Geschwärzten Eis","Wenn ich beschworen werde, beschwöre 2 Gefrorenen Diener und zähle sie auf 2 herunter.","","„Sie war g-grausam! Zu schwarzem Eis verbrannte Diener, Lawinen unter ihren Klauen, ein Gebrüll, das den Schnee von den Bergen stieß! Eine Kriegerkönigin, so wahr ich hier stehe! D-Diener zu töten ist das Werk einer Kriegerkönigin.“\n– Babbelnder Björg","Einheit",["DRACHE"],["Freljord"],"EPISCH"],"08FR002":["Valhirs Prophetin","Wenn ich beschworen werde, beschwöre 1 Siegel des Sturms.","","„Ich sehe, was die anderen nicht sehen können: den Sturm, der den Berg zerschmettern wird, das Brechen der Knochen der Erde. Das alte Freljord wird in Blut erneut geschmiedet – es ist nur eine Frage der Zeit.“","Einheit",[],["Freljord"],"GEWÖHNLICH"],"08FR028":["Nützliches Geschirr","Ich habe +1|+0 für jede verschiedene Unterart, die du in diesem Spiel beschworen hast.","","„Hier oben gibt es Monster, die nicht mal eine Lawine aufhalten kann. Deshalb ist ein gutes Geschirr jeden Taler wert.“\n– Fallensteller der Avarosa","Ausrüstung",[],["Freljord"],"EPISCH"],"08FR003":["Berserker der Ursaren","Wenn du einen Zauber oder eine Fertigkeit ausspielst, beschwöre 1 Siegel des Sturms.","","Gelegentlich verlieren sich die Anhänger von Volibear so sehr in ihrem Fanatismus, dass sie beginnen, Aspekte des Bären selbst anzunehmen. Nichts wird Valhirs Willen im Wege stehen – nicht einmal jene, die die Ursaren einst Landsleute nannten.","Einheit",[],["Freljord"],"SELTEN"],"08RU014":["Ahnendrache","Herkunft: Aspekt des Drachen.\nIch koste 1 weniger für jeden unterschiedlichen Drachensegen, den du in diesem Spiel ausgespielt hast.\nAusspielen: Wirke jeden Drachensegen auf mich.","Deine Verbündeten haben mit 75+ Gesamtstärke angegriffen.","„Legenden zufolge ist dieser Drache älter als alle anderen. Er ist der König der geflügelten Monster. Wenn wir ihn zähmen … was soll uns dann noch gefährlich werden können, Alatis? Die Welt wird dann endlich begreifen, dass Menschen und Drachen zusammen am stärksten sind.“\n– Volix, Drachen-Loyalist","Einheit",["DRACHE"],["Runeterra"],"Champion"],"08NX003":["Erzürnter Feuerspeier","Ausspielen: Verursache 2 Schaden an einem Gegner und 2 am gegnerischen Nexus.","","Der noxianischen Expansion sind viele verschiedene Völker, Siedlungen und Kulturen zum Opfer gefallen. Oft waren auch wilde Kreaturen der Kriegsmaschinerie ausgeliefert – aber im Fall dieses Drachen wird jeder brutale Schritt vorwärts von Noxus mit einem ebenso brutalen Inferno der Wut beantwortet.","Einheit",["DRACHE"],["Noxus"],"EPISCH"],"08NX024":["Eiserner Legionär","Ausspielen: Verursache 3 Schaden an einem Verbündeten, um an einem Gegner 3 Schaden zu verursachen.","","„Reißt ihre Seelen aus den Käfigen ihrer Körper!“\n– Mordekaiser","Einheit",[],["Noxus"],"SELTEN"],"08NX011":["Lauffeuer","Verursache 1 Schaden am gegnerischen Nexus, erhöht um 1 für jedes andere Lauffeuer, das du ausgespielt hast. Erschaffe 1 Lauffeuer in deinem Deck.","","„Asche, Asche …“\n– Annie","Zauber",["ELEMENTAR"],["Noxus"],"GEWÖHNLICH"],"08NX028":["Unzerstörbar","Gewähre einem Verbündeten Unsterblich.","","„Ewiges Eisen.“\n– Mordekaiser","Zauber",[],["Noxus"],"GEWÖHNLICH"],"08NX019":["Gepanzerter Keulenschwinger","Nexusschlag: Verfluche deinen Gegner mit Wundsekret.","","Der Keulenschwinger ist nicht nur in der noxianischen Armee beliebt, sondern auch in den Kampfarenen der Hauptstadt. Nur wenige Gegner – egal ob Mensch oder Tier – sind gewillt, in der Arena gegen dieses Biest anzutreten. Die seltenen Kämpfe des Keulenschwingers ziehen daher jedes Mal die Massen an.","Einheit",["REPTIL"],["Noxus"],"GEWÖHNLICH"],"08NX014":["Rektorin Telsi","Verbündete Angriffs- und Unterstützungs-Effekte werden ein weiteres Mal aktiviert.","","In Rektorin Telsis Kurs zu persönlicher Disziplin werden unzählige mühsame Anweisungen, Schläge auf die Finger und Stunden des Nachsitzens verteilt. Er war für Schüler am Rabendorn-Konservatorium schon immer verpflichtend – sonst würde sich niemand einschreiben.","Einheit",[],["Noxus"],"EPISCH"],"08NX012":["Bewaffneter Beschaffer","Ausspielen: Wähle einen Erkunderzauber, der auf der Hand erschaffen wird.","","„Man könnte glauben, in der Wüste könnte man einfacher graben – aber nein! Nach ausreichend Zeit wird Sand zu Stein. Fordere ein weiteres Mal Mittel für Ersatzwerkzeug an.“\n– Aus den Expeditionsaufzeichnungen der Fernkundedivision der Erkundergilde, Zuteilung: Shurima","Einheit",[],["Noxus","Shurima"],"SELTEN"],"08NX029":["Schlag der Kashuri","Töte eine Einheit, wenn sie verletzt ist, verursache sonst stattdessen 2 Schaden an ihr.","","„Das ist zu deinem eigenen Wohl. Vertrau mir.“\n– Fürst Wildmähne","Zauber",[],["Noxus"],"EPISCH"],"08NX009":["Fürst Mallat","","","„Es hat Jahrhunderte der Planung gekostet, um diesen fürchterlichen Kriegshetzer wegzusperren. Und jetzt wollen deine armseligen Freunde ihn mit ‚Freude‘ besiegen? Du dummes, kleines Mädchen. Ihr werdet nur den Zorn des Wiedergängers heraufbeschwören und uns alle in große Gefahr bringen!“","Einheit",[],["Noxus"],"GEWÖHNLICH"],"08NX025":["Klingendurchbohrter Wiedergänger","Wenn ein Verbündeter wiederbelebt wird, gewähre ihm Herausforderer.","","„Lächle nur, doch ich kenne die Wahrheit in deinem verräterischen Herzen! Sie lachten mit mir, speisten mit mir, obwohl sie mir die ganze Zeit eine Klinge in den Rücken rammen wollten. So leicht lasse ich mich nicht wieder hereinlegen. Du wirst sterben wie der Rest von ihnen: mit einem letzten Schrei nach Vergebung!“","Einheit",[],["Noxus"],"SELTEN"],"08SH009":["Uraltes Übel","Verfluche einen Gegner mit Schrecken.","","Manche Dinge sollten im Sand begraben bleiben.","Zauber",[],["Shurima"],"GEWÖHNLICH"],"08SH014":["Gehörnter Schwarmrufer","Ausspielen: Belege zwei Gegner mit -1|-0 und deaktiviere ihre positiven Schlüsselwörter.","","Trotz seiner einschüchternden Größe ist der Schwarmrufer nur selten gefährlich. Wenn sich sein Schwarm einer shurimanischen Siedlung nähert, hinterlassen die Dorfbewohner in der nahegelegenen Wüste Obst als Opfergaben, um ihre Besucher von wichtigeren Feldern abzulenken.","Einheit",["DRACHE"],["Shurima"],"GEWÖHNLICH"],"08SH004":["General der Dünen","Tagesanbruch oder wenn du einen anderen Tagesanbruch aktivierst: Belege den schwächsten Gegner mit Verletzlich.","","Die enormen Armeen von Shurima sind bereit, die Macht der Wüste unter Beweis zu stellen. Wenn der Befehl erteilt wird, rücken sie ohne zu zögern vor.","Einheit",["ELITE"],["Shurima"],"SELTEN"],"08SH005":["Verteidiger der Sonnenscheibe","Tagesanbruch: Ziehe 1 Verteidiger der Sonnenscheibe.","","„Wir sind die Bewahrer der immerwährenden Wüste, die lebende Geschichte, die Wanderer auf dem Pfad des Glanzes. Wir knien nieder vor der Sonnenscheibe und sonst vor nichts, auf dass die Welt vor dem Ruhm von Shurima kniet.“\n– Azir","Einheit",["ELITE"],["Shurima"],"GEWÖHNLICH"],"08SH012":["Grufträuberin Barbara","Wenn in einer Runde zum ersten Mal ein anderer Verbündeter stirbt, oder Letzter Wunsch: Erschaffe 1 Glücksfund auf der Hand.","","„Das ist ein göttlicher Fang, Barb! Ich wusste, dass ich auf dich zählen kann. Was? Was meinst du damit, sie haben dich gesehen?!“\n– Vekauranischer Schläger","Einheit",["REPTIL"],["Shurima"],"SELTEN"],"08SH002":["Dünenverschlinger","Töte einen Verbündeten oder zerstöre einen deiner Manasteine 3 Mal, um mich auszuspielen.","","Der Dünenverschlinger schläft in weitaus größeren Tiefen als seine kleineren Vetter der Xer’Sai. Er ist dafür bekannt, sich an anderen Raubtieren der Xer’Sai zu laben, wurde aber nur selten gesehen – was vermutlich daran liegt, dass er ganze Dünen (und mit ihnen jegliche Augenzeugen) verschlingt. ","Einheit",[],["Shurima"],"EPISCH"],"08MT003":["Morgana","Ausspielen: Verfluche einen Gegner zweimal mit Kettenfessel.","Du hast Einheiten 10+ Mal anvisiert.","„Geschunden und blutüberströmt kommst du zu mir, doch habe ich dich noch nie so freudestrahlend gesehen. Du bist eine wahrhaft merkwürdige Frau, aber hier bist du erst einmal sicher. Ruhe dich bitte aus. Sobald du dich besser fühlst, bin ich schon ganz gespannt auf deine Geschichte.“","Einheit",[],["Targon","Demacia"],"Champion"],"08MT005":["Mihira, Aspekt der Aszendenz","Ausspielen: Verfluche 2 Gegner zweimal mit Kettenfessel.","","„Im Namen meiner Tochter nahm ich die Heiligkeit an. Für meine Familie gab ich meine Menschlichkeit auf, damit ich mit diesem Flammenschwert eine neue Welt der Gerechtigkeit und Wahrheit erschaffen konnte.“","Einheit",[],["Targon"],"EPISCH"],"08MT042":["Zwinge des Sünders","Verfluche einen Gegner mit Kettenfessel.\nErhöhe die Kosten gegnerischer Flüche überall um 1.","","„Um deine Freiheit zu finden, musst du dich deiner inneren Finsternis stellen.“\n– Morgana","Zauber",[],["Targon"],"SELTEN"],"08MT024":["Rubinäugiger Beschwörer","Ausspielen: Gewähre einem Verbündeten auf der Hand Zauberschild oder Überwältigen.","","„Hab keine Angst! Schreite voran und blicke nicht zurück! Wir haben diese Reise einst auch erlebt. Nun ist es unsere Pflicht, die deine zu beschützen. Gehe schnell in ihre Zuflucht, damit dir die Verhüllte den Schutz gewähren kann, den du suchst.“","Einheit",[],["Targon"],"GEWÖHNLICH"],"08MT045":["Gefesselter Zauberer","Ausspielen: Verfluche mich mit Kettenfessel.","","Die Magiesuchenden wussten bestens, wie sie Menschen kleinkriegen können. Sie haben seine Hände und seine Magie gefesselt. Sie haben ihm seine Stimme genommen. Doch er hat ihnen schon zuvor standgehalten – und dieses Mal hatte er die Verschleierte Herrin an seiner Seite.","Einheit",[],["Targon"],"SELTEN"],"08MT015":["Lisa und Dolly","Ausspielen: Verfluche einen Gegner mit Kettenfessel.","","„Sieh mal, Dolly! Ich kann es! Ganz so, wie du es mir gezeigt hast! Meinst du, wir werden Mama irgendwann zeigen können, wie viel ich gelernt habe? Du meinst, sie weiß es bereits? Wirklich?! Ich hoffe, dass du recht hast.“\n– Lisa","Einheit",[],["Targon"],"GEWÖHNLICH"],"08MT030":["Sanftmütiger Juwelendrache","Wenn du einen Schnellzauber, einen langsamen Zauber oder eine Fertigkeit ausspielst, gewähre anderen verbündeten Drachen +1|+1.","","Das Temperament der Drachen ist so verschieden wie ihr Aussehen. Neben den zerstörungswütigen Höllendrachen gibt es auch jene, die sich für den Schutz ihrer Familien und Lebensräume einsetzen. Zu diesen zählen der gemächliche, zutrauliche Juwelendrache.","Einheit",["DRACHE"],["Targon"],"SELTEN"],"08MT023":["Dunkle Bindung","Betäube einen Gegner und verfluche ihn mit Kettenfessel.","","„Leide, so wie du sie hast leiden lassen!“\n– Morgana","Zauber",[],["Targon"],"SELTEN"],"08MT031":["Drachenverehrerin der Ottrani","Wenn ich beschworen werde, heile deinen Nexus um 2 und erhalte nächste Runde einen zusätzlichen Manastein.","","Hoch oben an den Hängen des Targon hat eine einsame Ottrani ihr Leben den Drachen verschrieben. Sie bedeckt sich selbst mit abgeworfenen Schuppen und Knochen, sucht in verstreuten Drachenzähnen und dem wehenden Rauch, der an den Bergflanken nach oben getragen wird, nach dem Pfad in die Zukunft.","Einheit",[],["Targon"],"EPISCH"],"08MT009":["Verhüllter Beschützer","Wenn ich beschworen werde oder du einen titanischen Verbündeten beschwörst, heile deinen Nexus um 3.","","Dieser verhüllte Beschützer hat den Segen, der ihn zu mehr als einem bloßen Tier gemacht hat, nicht vergessen – und begleicht diese Schuld, indem er zusieht, dass alle, die an den Hängen des Targon nach einem bestimmten Heiligtum suchen, die Reise unbeschadet überstehen.","Einheit",[],["Targon"],"SELTEN"],"08MT006":["Schwarzer Schild","Gib einem Verbündeten in dieser Runde Zauberschild und verfluche ihn mit Kettenfessel.","","„Geschützt vor der Verfolgung!“\n– Morgana","Zauber",[],["Targon"],"SELTEN"],"08MT027":["Vorbote der himmlischen Konvergenz","Ausspielen: Aktiviere die Tagesanbruch- und Nachteinbruch-Effekte von anderen Verbündeten.\nTagesanbruch: Gewähre mir Überwältigen.\nNachteinbruch: Gewähre mir Zauberschild.","","„Über uns brennt ein Ring aus Feuer. In der verkündeten Finsternis sind wir alle gleich.“\n– Halbmondsprecher der Lunari","Einheit",["VOGEL"],["Targon"],"EPISCH"],"08MT025":["Seismische Scherbe","Ich koste 3 weniger, wenn du eine sichtbare titanische Einheit hast.\nVerursache 7 Schaden an einer Einheit.","","„Upfie, oh-oh, mach dir keine Forgen um daf da, nur ein kleiner Rumms im Fels, nur ein Unfall, nicht Papa, NÖ! Weiter gehpft.“\n– Kiesel","Zauber",["ELEMENTAR"],["Targon"],"GEWÖHNLICH"],"08DE006":["Gelehrter Pionier","Ausspielen: Wähle einen Erkunderzauber, der auf der Hand erschaffen wird.","","„Es ist kalt. Mir ist kalt. Alles ist ständig kalt. Es gibt Orte, an denen keine Menschen leben sollten. Bitte schickt mich nach dem Ganzen an einen Ort, an dem es warm ist.“\n– Aus den Expeditionsaufzeichnungen der Fernkundedivision der Erkundergilde, Zuteilung: Freljord","Einheit",[],["Demacia","Freljord"],"SELTEN"],"08DE020":["Magische Fesseln","Gewähre einem Verbündeten +0|+2. Verfluche deinen Gegner mit Unterdrückung.","","„Erkenne die Last deiner Sünden!“\n– Morgana","Zauber",[],["Demacia"],"GEWÖHNLICH"],"08DE017":["Inquisitor der Magiesuchenden","Wenn ich beschworen werde, verfluche deinen Gegner mit Unterdrückung.","","„Wir dürfen nicht zulassen, dass sie die Zuflucht der gefallenen Schwester erreichen. Ihre uralte, verruchte Magie könnte selbst ich mit meinen Fähigkeiten nicht unterdrücken. Beeilung! Schafft diese Scheusale wieder zurück aufs Schiff und dann den Berg hoch zum Rest von ihnen!“","Einheit",[],["Demacia"],"SELTEN"],"08DE025":["Wolkendrache","Wenn ich beschworen werde, senke die Kosten aller verbündeten Einheiten auf der Hand um 1.","","Dank seines dichten Fells, das wunderbar gegen Kälte schützt, kann dieser Drache leicht höher gelegene Gebiete erreichen als die meisten seiner Artgenossen. Die Drachen sind lebhaft, aber scheu und man sieht sie meist hoch oben im Himmel, wie sie durch die Wolken flitzen und mit dem Wind um die Wette fliegen.","Einheit",["DRACHE"],["Demacia"],"EPISCH"],"08DE010":["Duell der Gentlemen","Gib einem Verbündeten in dieser Runde +0|+2.\nDann schlagen sich der Verbündete und ein Gegner gegenseitig.","","„En garde, mein Freund! Sicherlich bist du kein so großer Feigling, dass du ein Duell zwischen Gentlemen ablehnen würdest?“\n– Chevalier der Laurent","Zauber",[],["Demacia"],"GEWÖHNLICH"],"08DE022":["Die Königsfischer","Wenn ich beschworen werde, ziehe 1 Exemplar jedes Champions in deinem Deck.\nWenn du in einer Runde zum ersten Mal einen Champion beschwörst, mobilisiere dich.","","„Du darfst nicht vergessen, mein Sohn, dass jede Suche nach neuen Horizonten im Dienst der Heimat stehen muss, die wir zurücklassen.“\n– König Jarvan III.","Einheit",[],["Demacia"],"EPISCH"],"08DE027":["Klauenschlag","Gewähre verbündeten Vögeln überall +1|+1. Ein verbündeter Vogel schlägt einen Gegner.","","Das Kreischen der Silberschwinge verkündet den Tod von oben.","Zauber",[],["Demacia"],"SELTEN"],"08DE026":["Alatis der Galante","Deine Drachensegen wirken auf alle verbündeten Drachen.","","„Um eins klarzustellen: Ich war nicht immer Drachen-Loyalist. Alatis hat mich überzeugt. Das war das erste Mal, dass er mein Leben gerettet hat. Er hat mich viel gelehrt. Was seine wichtigste Lektion war? Es gibt nichts Erhabeneres, als Demacia vom Rücken eines Drachen aus zu dienen.“\n– Drachen-Loyalist","Einheit",["DRACHE"],["Demacia"],"EPISCH"],"08DE013":["Drachen-Loyalist","Wenn ich beschworen werde, ziehe 1 Drachen, falls du einen sichtbaren Drachen hast.","","„Ich gebe es nur ungern zu, alter Freund, aber alleine können wir den nicht zähmen. Wir haben getan, was wir konnten. Ich benachrichtige den General. Mit der Macht von Demacia an unserer Seite kriegen wir diese magische Kreatur schon klein.“","Einheit",[],["Demacia"],"GEWÖHNLICH"],"08IO012":["Meeresdrache","Wenn du einen Schnellzauber, einen langsamen Zauber oder eine Fertigkeit ausspielst, heile deinen Nexus um 1.","","„Welch ein fabelhaftes Monster! Es bereitet mir eine große Freude, die Spitzen deiner Klauen durch die Wellen streifen zu sehen. Sollte dir je der Sinn nach anderer Beute als Fischen und Seevögeln stehen, dann wäre ich nur zu gern dein Gegner.“\n– Nilah","Einheit",["DRACHE"],["Ionia"],"SELTEN"],"08IO014":["Heisho, Schild der Welt","Die erste Karte, die du in einer Runde ausspielst, kostet 9 weniger.","","Für die Einwohner dieses ionischen Dorfs ist Heisho sowohl verehrter Beschützer als auch guter Freund. Er trägt das Dorf seit undenklichen Zeiten auf seinem Rücken und die Bewohner vertrauen darauf, dass er in unruhigen Zeiten friedliche Gestade ansteuert.","Einheit",["REPTIL"],["Ionia"],"EPISCH"],"08IO021":["Tanz des Empyreums","Halte einen gegnerischen Schnellzauber, langsamen Zauber oder Fertigkeit auf, rufe einen Gegner zurück und beschwöre Das Empyreum.","","„Der Tanz soll unser Andenken sein.“\n– Irelia","Zauber",[],["Ionia"],"SELTEN"],"08IO019":["Zuverlässiger Adnere","Wenn ich beschworen werde, beschwöre Adneres Vogelzüchter.","","„Dieses Land ist voller Lehren. Denke immer daran: Das Ende jeder Jahreszeit muss gefeiert werden, denn nur aus einem Ende kann ein neuer Anfang geboren werden.“","Einheit",[],["Ionia"],"SELTEN"],"08IO010":["Kentern","Rufe einen Gegner zurück, um die Kosten der nächsten Einheit, die dein Gegner in dieser Runde ausspielt, um 2 zu erhöhen.","","„Jene, die uns Böses wollen, werden auf dem Grund des Meeres ihre Ruhe finden.“\n– Flussformer","Zauber",["ELEMENTAR"],["Ionia"],"GEWÖHNLICH"],"08IO023":["Tanzende Meeresgeister","Ausspielen: Beschwöre eine exakte vergängliche Kopie von mir.","","Zur richtigen Jahreszeit, wenn der Wind vom Meer weht, schwören einige Zhauniten, dass sie die Umrisse von zwei riesigen schuppigen Wesen sehen können, die fröhlich mit den Gezeiten tanzen.","Einheit",[],["Ionia"],"GEWÖHNLICH"],"08BC020":["Der frühe Vogel","Dein Gegner wirft seine Karte mit den höchsten Kosten ab.","","„Stell dir Folgendes vor: Du bist ein Wurm und diese Augen sind das Letzte, was du vor deinem Tod siehst. Ach, Würmer können nicht sehen? Vielleicht ist es besser so.“\n– Elle, unbeeindruckte Reisende","Zauber",[],["Bandle"],"GEWÖHNLICH"],"08BC005":["Vollgepackter Rucksack","Verstecke 4 Glocken in deinem Deck und 4 Giftige Poffpilze im gegnerischen Deck für jeden Vollgepackter Rucksack, den du in diesem Spiel ausgespielt hast. Erschaffe 1 Vollgepackter Rucksack in deinem Deck.","","„Regel 207: Eine Späherin trägt nie mehr, als sie braucht!“\n– Ava Überflieger","Zauber",[],["Bandle"],"SELTEN"],"08BC021":["Unerwarteter Wechsel","Rufe einen Verbündeten zurück, um 1 Hungrige Eulenkatze an seiner Stelle zu beschwören.","","„SKWAA?“\n– Eulenkatze","Zauber",[],["Bandle"],"SELTEN"],"08BC002":["Skip, „König des Riffs“","Ausspielen: Wähle 1 von 2 Karten, die keine Champions sind, aus der Hand des Gegners. Ich halte sie fest.","","„Ja, ich bin attraktiv, flink – unerschütterlich cool. Weißt du das nicht, alter Mann? Ich bin der König dieses Riffs und du dringst in mein Königreich ein!“\n„W-Warte! Komm sofort zurück! Ich brauche dieses Exemplar für meine Forschung!“\n– Conchologe","Einheit",[],["Bandle"],"EPISCH"],"08BC006":["Portalpionierin","Ausspielen: Wähle einen Erkunderzauber, der auf der Hand erschaffen wird.","","„Ich mache mir Sorgen um Bunches! Oh, er wirkt in letzter Zeit immer nervöser. Sogar ein kleiner Portalhüpfer macht ihm Angst! Ich verstehe nicht, warum.“\n– Aus den Expeditionsaufzeichnungen der Fernkundedivision der Erkundergilde, Zuteilung: Bandle","Einheit",["YORDLE"],["Bandle","Ionia"],"SELTEN"],"08BC004":["Portia die Wunderliche","Ausspielen: Manifestiere einen titanischen Begleiter und setze seine Werte auf 1|1 und seine Kosten auf 0.","","„Natürlich kenne ich die alte Portia! Sie ist ein bisschen plemplem, aber notfalls kann sie einen mit einem Portal überall hinbringen. Kurz mit dem Schwanz gewedelt und schon ist man weg!“\n– Portalpionierin","Einheit",["DRACHE"],["Bandle"],"EPISCH"],"08BC018":["Zuckersüße Verlockung","Lege einen Verbündeten an das Ende deines Decks, um den obersten Verbündeten in deinem Deck zu beschwören.","","„Regel 571: Ein Späher muss stets wachsam sein. Man kann nie wissen, was ein Leckerbissen ist und was eine Falle.“\n– Ava Überflieger","Zauber",[],["Bandle"],"SELTEN"],"09SI015":["Die wunderschöne Katastrophe","I: Töte eine Einheit mit insgesamt 5 oder weniger Stärke und Leben.\nII: Entziehe dem gegnerischen Nexus 2.\nIII: Beschwöre eine exakte Kopie eines Verbündeten. Sie ist vergänglich und hat 1|1.","","Er stieg die Stufen zur Bühne empor, das Gedicht fest in der Hand umklammert. Er hatte für seine Vorstellung keine Plakate aufgehängt, weil er das einzige Publikum, das er wollte, bereits hatte.","Wahrzeichen",["GESCHICHTE"],["Schatteninseln"],"EPISCH"],"09SI013":["Die eiserne Eroberung","I–II: Wähle einen verbündeten Begleiter. Erschaffe eine vergängliche Kopie von ihm mit +1|+1 auf der Hand.\nIII: Belebe den stärksten toten verbündeten Begleiter wieder und gewähre ihm Vergänglich.","","Im grauen Reich formen sich gepeinigte Gestalten zu einer Spektralarmee. Sobald die Tore der Welt der Sterblichen geöffnet werden, wird diese nicht mehr aufzuhalten sein.","Wahrzeichen",["GESCHICHTE"],["Schatteninseln"],"SELTEN"],"09SI012":["Existenzielle Angst","Belege Gegner mit Trübsal.","","„Worin liegt überhaupt jemals der Sinn von etwas?“\n– Vex","Zauber",[],["Schatteninseln"],"SELTEN"],"09SI017":["Kharox","Letzter Wunsch oder wenn ein Verbündeter stirbt, der kein Tentakel ist: Krakenruf (2).","","Der einsame Ruderer eines gespenstischen Schiffs, das viele Seefahrer Letzte Fähre nennen, heißt Kharox. Angeblich kommuniziert er mit den Geistern aller Seeleute, die bei dem Versuch, die Inseln zu erreichen, ihr Leben verloren.","Einheit",[],["Schatteninseln"],"EPISCH"],"09SI014":["Grimm","Ausspielen: Belege eine Einheit 4 Mal mit Trübsal.","","Der geplagte Poet Grimm schätzt düstere Romantik und alles, was mit Philosophie zu tun hat. Ein wenig Trübsal und Untergangsstimmung schrecken ihn nicht ab. Das Ziel seiner Zuneigung ist für ihre Ruppigkeit bekannt, aber in seinen Augen macht sie das nur noch liebenswerter.","Einheit",["YORDLE"],["Schatteninseln"],"GEWÖHNLICH"],"09DE033":["Geisterchen","","","„Die Geisterchen sind wunderbare Kreaturen. Mit genügend Zeit und dem richtigen Träumer ist ihr Potenzial schlichtweg grenzenlos!“\n– Mutter der Geister","Einheit",[],["Demacia","Ionia"],"GEWÖHNLICH"],"09DE039":["Das Licht von Demacia","I: Gewähre einem Verbündeten Kampfgeist.\nII: Gewähre einem Verbündeten 2 Mal Kampfgeist.\nIII: Steigere alle Verbündeten.","","Der Jubel der Menge schwoll an, als ihr Strahlen über ihre nach oben gewandten Gesichter wanderte. Ihr einziges Bestreben war immer gewesen, ihr Volk zu beflügeln und zu unterstützen – und im Gegenzug erhielt auch sie Unterstützung, in Form eines vielstimmigen Sprechchors der Bewunderung: „Luxanna! Luxanna! Luxanna!“","Wahrzeichen",["GESCHICHTE"],["Demacia"],"SELTEN"],"09DE034":["Lux: Erleuchtet","Unterstützung: Gewähre meinem unterstützten Verbündeten Kampfgeist und gib mir in dieser Runde Barriere.","Verbündete haben mit insgesamt 20+ positiven Schlüsselwörtern angegriffen oder diese beim Angriff erhalten.","Licht wirbelte und umspielte Luxanna, während die Stadtbewohner sie erstaunt betrachteten. Hier war sie Demacias Lady des Lichts, eine aufrechte junge Kronwacht und eine begabte Magierin. Hier war Demacia genau so, wie sie es sich immer gewünscht hatte.","Einheit",[],["Demacia"],"Champion"],"09DE047":["Vergessenes Artefakt","Beschwöre 1 Sandstein-Stürmer, gib dann deinen Verbündeten in dieser Runde Herausforderer.","","Tief in der Schatzkammer eines Magiesuchenden voller konfiszierter magischer Gegenstände liegt unbeschriftet eine seltsame Schnitzerei, deren Zweck längst in Vergessenheit geraten ist …","Zauber",[],["Demacia"],"SELTEN"],"09DE041":["Die Petrizit-Halle","I: Ein Verbündeter hält eine Einheit fest.\nII: Verfluche deinen Gegner mit Unterdrückung.\nIII: Vernichte alle Karten, die von Verbündeten festgehalten werden.","","Der Jubel der Menge schwand, als sie die Halle betrat. Die Statuen beobachteten das Geschehen schweigend. Die Dunkelheit wartete, aber sie konnte nicht umdrehen – wer sonst sollte Demacias Abstieg in den Albtraum verhindern?","Wahrzeichen",["GESCHICHTE"],["Demacia"],"EPISCH"],"09DE030":["Gleißen","Steigere alle Einheiten.","","„Unser Strahlen ist unbändig!“\n– Lux: Erleuchtet","Zauber",[],["Demacia"],"GEWÖHNLICH"],"09DE043":["Aufsteigendes Licht","Steigere alle Einheiten 3 Mal.","","„In Licht bewahrt!“\n– Lux: Erleuchtet","Zauber",[],["Demacia"],"SELTEN"],"09DE031":["Jarro Leichtfeder","Ausspielen: Gewähre einem Verbündeten auf der Hand Kampfgeist.","","Ein junger Mann mit Karnevalsmaske manifestierte sich vor ihr, mit einem Schwung an Rosenblättern und leuchtenden Kreaturen. „Ich heiße Leichtfeder. Jarro Leichtfeder“, sagte er. „Ich hörte, Ihr benötigt möglicherweise Unterstützung, Gnädigste?“","Einheit",[],["Demacia"],"SELTEN"],"09DE046":["Verführerisches Lächeln","Steigere 2 Verbündete, die dann hintereinander einen Gegner schlagen.","","„Ganz ruhig, werte Damen. Von mir ist genug für alle da.“\n– Jarro Leichtfeder","Zauber",[],["Demacia"],"GEWÖHNLICH"],"09DE045":["Traumlicht Alina","Wenn ich beschworen werde, beschwöre 5 Geisterchen. Für jedes, das keinen Platz hat, gewähre stattdessen dem schwächsten Verbündeten 2 Mal Kampfgeist.","","„In deinem Alter hatte ich große Angst vor diesem Licht. Ich hatte niemanden, der mir sagen konnte, dass meine Magie ein Geschenk ist, dass sie mir aus einem Grund gegeben wurde. Aber du hast jetzt mich, um dir das zu sagen. Also hab keine Angst, Alina. Lass es strahlen.“\n– Lux: Erleuchtet","Einheit",[],["Demacia"],"EPISCH"],"09DE040":["Abnormer Magiesuchender","Wenn ich beschworen werde, gewähre anderen Verbündeten Kampfgeist.","","„Fräulein Kronwacht.“ Der Magiesuchende materialisierte sich aus dem Schatten und streckte ihr eine Hand entgegen. Sein eindringliches Lächeln wirkte zu breit für sein halb verborgenes Gesicht. „Wieso folgt Ihr mir nicht einfach?“","Einheit",[],["Demacia"],"GEWÖHNLICH"],"09DE036":["Baumgeister","Ausspielen: Steigere alle anderen Einheiten.","","„Los, kleine Geister! Zeigt eurem Träumer den Weg.“\n– Lillia","Einheit",[],["Demacia","Bandle"],"GEWÖHNLICH"],"09DE029":["Luminogeist","Unterstützung: Ich gebe meinem unterstützten Verbündeten in dieser Runde alle meine positiven Schlüsselwörter und ihre Steigerungen.","","„Los doch, kleiner Geist! Lass uns diese unheimlichen Schatten verbrennen!“\n– Traumlicht Alina","Einheit",[],["Demacia"],"SELTEN"],"09SH010":["Wiedererweckerin des Reichs","Ausspielen: Gewähre einem verbündeten Wahrzeichen „Wenn ich zerstört werde, belebe mich wieder“.","","Der Aufstieg des Imperators hat in ganz Shurima Hoffnung geweckt. Diese Magierin nennt sich „Wiedererweckerin des Reichs“ und ist entschlossen, Azirs Vision wahr werden zu lassen. Sie reist durch die Wüste, um vergrabene Ruinen in ihrer früheren Pracht erneut erstrahlen zu lassen.","Einheit",[],["Shurima"],"GEWÖHNLICH"],"09SH009":["Die Armee des Imperators","I: Beschwöre 2 Sandsoldaten.\nII: Prophezeie.\nIII: Wenn du in dieser Runde einen Verbündeten beschwörst, gib ihm in dieser Runde +2|+0.","","Azir kennt Shurima, wie es war, ist und sein wird. Er glaubt, dass seine Zukunftsvision viel mehr ist als nur ein Traum – nämlich eine Prophezeiung, deren Erfüllung sein Schicksal ist.","Wahrzeichen",["GESCHICHTE"],["Shurima"],"EPISCH"],"09SH012":["Beschwörung der Sonnengeborenen","Wähle 1 von 3 Champions, die sich zu Spielbeginn in deinem Deck befanden, und ziehe ihn.","","Viele Artefakte alter Sonnenkrieger gingen mit der Zeit verloren. Dasselbe lässt sich von den Götterkriegern, für die sie stehen, nicht immer sagen.","Zauber",[],["Shurima"],"SELTEN"],"09PZ044":["Das Gebet bei Kerzenschein","I–II: Aufwind (1), um 1 zu ziehen.\nIII: Ziehe 1.","","Dieser Tempel ist Janna geweiht und hat nur wenige feste Mauern, um den Kräften der Göttin angemessen zu sein. Dennoch scheinen die vielen Kerzen immer zu brennen, selbst wenn ein heulender Sturm über das übrige Zhaun hinwegfegt.","Wahrzeichen",["GESCHICHTE"],["Piltover & Zhaun"],"EPISCH"],"09PZ045":["Fliegende Kartographin","Ausspielen: Aufwind (1), um eine andere Karte zu ziehen, die entweder mehr oder weniger kostet als die gewählte Karte für Aufwind.","","„Höhe ist die sicherste Methode, um die eigene Bedeutungslosigkeit zu erkennen.“","Einheit",[],["Piltover & Zhaun"],"SELTEN"],"09PZ046":["Fehlmutation","Wähle einen verbündeten Begleiter. Beschwöre 2 Hungrige Eulenkatzen, verwandle dann Verbündete in exakte Kopien des gewählten Verbündeten.","","„Nur noch eine Kopie … dann ist es perfekt.“\n– Böse Imperfektionistin","Zauber",[],["Piltover & Zhaun"],"EPISCH"],"09IO055":["Blütenelfe","Wenn ich beschworen werde, beschwöre Geisterchen.","","„Unsere Lillia sieht ganz zerzaust aus! Bringe ihre Haare für uns in Ordnung, ja? Und denk daran, die erste Strähne ist für Wünsche, die zweite für Träume und die letzte für alles, was nicht so ist, wie es scheint.“\n– Mutter der Geister","Einheit",[],["Ionia"],"SELTEN"],"09IO056":["Geistertanz","Rufe einen Verbündeten zurück, um einem anderen Verbündeten alle Steigerungen seines Kampfgeists zu gewähren.","","„Die Träume des Herzens sind nur einen Schlummer von der Realität entfernt!“\n– Lillia","Zauber",[],["Ionia"],"SELTEN"],"09IO048":["Mutter der Geister","Wenn ich beschworen werde, gewähre verbündeten Geisterchen und Müttern der Geister überall Kampfgeist.","","Geister sind aufgeweckt, launisch und nicht immer gute Zuhörer. Damit jeder seinen Träumer erreicht, umsorgt die Mutter der Geister sie mit fester Hand und mehr als genug Tadel.","Einheit",[],["Ionia"],"EPISCH"],"09IO049":["Die Tautropfenernte","I: Beschwöre Geisterchen.\nII: Lasse einen Verbündeten schlafen.","","Jeder Tautropfen von Mutter Baum erlaubt einen Einblick in einen Traum irgendwo in Runeterra – und jeder Tropfen muss vorsichtig geerntet, genährt und beschützt werden.","Wahrzeichen",["GESCHICHTE"],["Ionia"],"GEWÖHNLICH"],"09IO052":["Lillia","Wenn ich beschworen werde oder zuschlage: Erschaffe 1 Traumstab auf der Hand oder senke seine Kosten um 1, wenn du schon einen hast.","Du hast 15+ Verbündete oder Wahrzeichen beschworen.","Im Herzen des Gartens des Vergessens rückt die Tautropfenernte näher. Obwohl diese von Lillia und den anderen Beschützern des Gartens liebevoll gepflegt werden, findet sich nun eine eigentümliche Verderbnis unter ihnen, und die Träume, die sie zeigen, werden unheimlich und düster …","Einheit",[],["Ionia"],"Champion"],"09IO046":["Gärtnerin der Ophelis","Ausspielen: Heile einen Verbündeten vollständig, lasse ihn dann schlafen.","","Den Träumenden Baum und den ihn umgebenden Garten zu pflegen, ist eine große Ehre, die aber auch Opfer erfordert. Bei einem Ritual voller Respekt und Wertschätzung bringen die Beschützer des Gartens ihre eigenen Erinnerungen dar und verlieren so jede Nacht ein Stück von sich selbst.","Einheit",[],["Ionia"],"GEWÖHNLICH"],"09IO051":["Der verwurzelte Pfad","I–II: Ziehe 1.\nIII: Senke die Kosten der Karten auf deiner Hand in dieser Runde um 1.","","Der Garten des Vergessens beherbergt eine eigentümliche Auswahl großer und kleiner Kreaturen – einige davon mit mehr Bewusstsein, als ihnen selbst lieb ist.","Wahrzeichen",["GESCHICHTE"],["Ionia"],"SELTEN"],"09IO053":["Herr Wurzel","Wenn ich beschworen werde, ziehe 1.","","„Wow! Eines Tages wird all diese Schönheit tot sein, und wir auch. Hoffentlich trifft es mich zuerst. Hehe!“","Einheit",[],["Ionia"],"GEWÖHNLICH"],"09IO045":["Blühende Knospe","Lasse eine Einheit schlafen.","","„Träume erblühen überall!“\n– Lillia","Zauber",[],["Ionia"],"SELTEN"],"09IO058":["Das Herz des Baumes","I. Heile deinen Nexus um 3 und beschwöre Geisterchen.\nII. Gewähre Verbündeten überall Kampfgeist.\nIII. Manifestiere eine Karte mit 8 oder mehr Kosten und senke ihre Kosten um die Hälfte (wird aufgerundet).","","Traumgeister gehören zu den häufigsten Bewohnern des Gartens. Form, Größe und Temperament variieren, und viele von ihnen betreten Tautropfen, um ihre Träumer zu deren tiefsten Wünschen zu begleiten.","Wahrzeichen",["GESCHICHTE"],["Ionia"],"EPISCH"],"09IO059":["Stürmischer Stahl","Betäube einen Gegner und betäube ihn beim nächsten Rundenbeginn erneut.","","„Die Klinge über alles.“\n– Yone, Windjäger","Zauber",[],["Ionia"],"GEWÖHNLICH"],"09FR009":["Die Poroparade","I–II: Manifestiere einen Begleiter mit einer anderen Unterart als ausgespielte Verbündete.\nIII: Gib einem Verbündeten in dieser Runde +1|+1 für jeden Verbündeten mit einer Unterart.","","Ingvars Beziehung zu den Untertanen des Porokönigs ist seit ihrem Besuch in seinem Königreich noch stärker geworden. Auf der Suche nach Abenteuern durch Freljord zu stürmen, gehört zu den besten Methoden, um diplomatische Beziehungen zu verbessern.","Wahrzeichen",["GESCHICHTE"],["Freljord"],"EPISCH"],"09FR014":["Brynhir Donnersang","Ausspielen: Vernichte eine Einheit auf der Hand, um 1 Sturmgeformte Säule zu beschwören, deren Countdown den Kosten der Einheit entspricht und eine exakte Kopie von ihr beschwört (mindestens 1 Kosten).","","„Ich wurde im Sturm des Berges und dem Gesang meines Volkes geschmiedet!“","Einheit",[],["Freljord"],"EPISCH"],"09FR010":["Ultraweicher Poro","Ausspielen: Heile deinen Nexus um 1 für jeden Verbündeten mit einer Unterart.","","„O ho ho, so viel Flausch!“\n– Poro-Hirte","Einheit",["PORO"],["Freljord"],"GEWÖHNLICH"],"09FR012":["Frostiges Fällen","Gewähre einem Verbündeten Leben in Höhe seiner Stärke sowie Formidabel, setze dann seine Stärke auf 0.","","Manche Bäume in Freljord können nur durch die Kraft des Winterfrosts selbst gefällt werden.","Zauber",[],["Freljord"],"SELTEN"],"09BC020":["Böser Blick","Belege eine Einheit mit Trübsal, um 1 zu ziehen.","","„Herzlichen Glückwunsch. Ich hasse dich.“\n– Vex","Zauber",[],["Bandle","Schatteninseln"],"GEWÖHNLICH"],"09BC012":["Das Familientreffen","I: Belege eine Einheit mit Trübsal.\nII: Gewähre einem Verbündeten Einschlag.\nIII: Steigere 2 Einheiten.","","Die Liebe wächst hier nicht mit der Entfernung. Aber wenigstens ist das Abendessen mit der Familie hier ruhig – genau, wie Vex es mag.","Wahrzeichen",["GESCHICHTE"],["Bandle"],"EPISCH"],"09BC001":["Vex","Angriff: Belege den stärksten Gegner mit Trübsal.","Du hast 5+ Mal Einheiten mit Trübsal belegt.","„Ugh, dummes rosa Mädchen. Ich habe ihr bereits gesagt, dass ich Partys HASSE, vor allem, wenn es Kuchen gibt. E-kel-haft. Weck mich einfach auf, wenn sie wieder weg ist.“","Einheit",["YORDLE"],["Bandle","Schatteninseln"],"Champion"],"09BC002":["Onkel Milty","Gewähre mir 2 Mal Kampfgeist, sobald du eine Geschichte abgeschlossen hast.","","Er ist zwar kein bisschen wie seine melancholische Nichte, aber Onkel Milty gibt stets sein Bestes, etwas mit ihr zu unternehmen – besonders, wenn es sich um eine Gruselgeschichte bei Kerzenlicht handelt.","Einheit",["YORDLE"],["Bandle"],"SELTEN"],"09BC013":["Flügeldankfest","I–II: Wähle einen Verbündeten. Wähle dann 1 von 3 Begleitern, die 1 mehr kosten, in den er sich verwandelt.\nIII: Wähle einen Verbündeten. Wähle dann 1 von 3 Begleitern, die 2 mehr kosten, in den er sich verwandelt.","","Der alte Herbert Schlummerich ertappt sich ständig dabei, wie er in irgendeinen Traum schwebt. Dieser hier scheint zum Glück friedlich zu sein … obwohl hier seltsamerweise jeder solche Flügel haben will, wie er sie besitzt …","Wahrzeichen",["GESCHICHTE"],["Bandle"],"SELTEN"],"09BC004":["Allay","Ausspielen: Gewähre mir Kampfgeist oder belege eine Einheit mit Trübsal.","","„Veeeeex! Waaarte! Ich hab etwas für dich! Eine Einladung zu deiner eigenen GEBURTSTAGSPARTY! Und dein Geschenk, wenn auch etwas zu früh! Ich kann einfach NICHT länger damit warten. Bist du schon aufgeregt? Wir müssen über unsere Outfits quatschen und den Kuchen und … Vex?“","Einheit",["YORDLE"],["Bandle"],"GEWÖHNLICH"],"09BC016":["Monströse Eruption","Erhöhe die Stärke oder das Leben eines Verbündeten in dieser Runde auf 5.","","„Schlechtestes. Geschenk. Aller Zeiten.“\n– Vex","Zauber",[],["Bandle"],"GEWÖHNLICH"],"09BC003":["Groteskes Geschenk","Wenn zum ersten Mal ein Gegner beschworen wird, belege ihn mit Trübsal.","","„Hm, das war am Ende doch kein so schlechtes Geschenk.“\n– Vex","Einheit",[],["Bandle"],"SELTEN"],"09BC018":["Schatten","Wenn ich beschworen werde, ziehe Vex.\nIch habe +1|+0 für jedes Mal, wenn du in diesem Spiel eine Einheit mit Trübsal belegt hast.","","„Ja, zeig’s ihnen, Schatten! Keine Geschenke, kein Konfetti und VOR ALLEM keine Partyhüte.“\n– Vex","Einheit",[],["Bandle","Schatteninseln"],"EPISCH"],"09BC011":["Trübsalgeister","Schlag: Gewähre mir Einschlag.","","„Träume verändern die Geister auf eigentümliche Weise. Diese hier scheinen … oh, ist das ein Kuchen?“\n– Lillia","Einheit",[],["Bandle"],"GEWÖHNLICH"],"09BC006":["Bodybuilder-Bürgermeister","Rundenbeginn: Steigere mich.","","Die Zeit verging plötzlich langsamer, als der merkwürdig muskulöse Bürgermeister aus der unmöglich großen Torte sprang. „Herzlichen Glückwunsch zum GEBUUUURTSTAAAAG“, sagte der Bürgermeister mit angespanntem Bizeps, „vom besten – und durchtrainiertesten – gewählten Beamten von Bandle!“\n\nVon all ihren Träumen hasste Vex diesen am meisten. ","Einheit",["YORDLE"],["Bandle"],"GEWÖHNLICH"],"09BW022":["Der Arena-Champion","I: Ein Verbündeter und ein Gegner schlagen sich gegenseitig. Ihr Leben kann durch diesen Schlag nicht unter 1 fallen.\nII: Heile einen Verbündeten vollständig.\nIII: Erschaffe 3 Münzen auf der Hand.","","Engel hat jahrelang danach gestrebt, den Kampf aller Kämpfe zu gewinnen. Jede Nacht träumt sie von einem Münzenberg, der die ganze Bucht von Bilgewasser ausfüllt. Geld für eine Kartoffelfarm.","Wahrzeichen",["GESCHICHTE"],["Bilgewasser"],"EPISCH"],"09BW028":["Motivierter Anbeter","Ich habe +1|+0 für jede Karte, die du in dieser Runde gezogen hast.","","„Was soll das heißen, ich ‚brauche mehr Training‘? Ich HABE trainiert – sieh doch!“","Einheit",[],["Bilgewasser"],"SELTEN"],"09BW027":["Söldnermanieren","Klaue in dieser Runde einen gegnerischen Begleiter mit 3 oder weniger Leben. (Nicht spielbar, wenn du bereits 6 Verbündete oder Wahrzeichen hast.)","","„Blut für Geld ist immer ein guter Start in den Tag.“\n– Söldnerin","Zauber",[],["Bilgewasser"],"GEWÖHNLICH"],"09MT002":["Die Rauchschuppen-Macht","I-II: Wirf zum Aktivieren 1 Karte ab. Ersuche eine himmlische Karte, die 7 oder mehr kostet.\nIII: Senke die Kosten einer zufälligen Karte auf der Hand um 5.","","Diese einsame Ottrani widmet sich der Verehrung und Bewunderung von Drachen – so sehr, dass ihr die majestätischen Bestien in wachen wie in schlafenden Welten erscheinen.","Wahrzeichen",["GESCHICHTE"],["Targon"],"EPISCH"],"09MT004":["Verschleierter Segen","Gewähre einem Verbündeten 2 Mal Kampfgeist.","","„Ich werde ihre Zuflucht sein.“\n– Morgana","Zauber",[],["Targon"],"GEWÖHNLICH"],"09MT005":["Träumerin des Drachenlieds","Wenn du in einer Runde zum ersten Mal ersuchst, beschwöre 1 Drachling.","","„Die Drachen sind in der Nähe. Ich kann es fühlen. Selbst jetzt gleiten sie durch meine Träume.“","Einheit",[],["Targon"],"EPISCH"],"09NX025":["Der Größte der Arena","I–II: Gib einem Verbündeten in dieser Runde +2|+0.\nIII: Mache einen Gegner in dieser Runde abwehrunfähig.","","Die Arena ist nicht zuletzt deshalb so beliebt, weil sich jeder dort einen Namen machen kann. Dieser Fan hat so viele Matches von Draven gesehen, wie er konnte – und er ist überzeugt, ganz nach oben kommen zu können, wenn man ihm nur die gleiche Chance geben würde.","Wahrzeichen",["GESCHICHTE"],["Noxus"],"EPISCH"],"09NX032":["Yetiführer","Wirf 1 Karte ab, um mich auszuspielen.\nWenn ich beschworen werde, beschwöre 1 Erzürnter Yeti.","","Der Erfolg der noxianischen Kriegsmaschinerie beruht nicht zuletzt auf ihrer Flexibilität. Wenn das Gelände oder schwierige Bedingungen eine Anpassung verlangen, macht das Militär sich auch die unwahrscheinlichsten lokalen Ressourcen zunutze.","Einheit",[],["Noxus"],"SELTEN"],"09NX033":["Befallene Kriegsaxt","Rundenende: Wenn mein Träger in dieser Runde nicht angegriffen hat, belege ihn mit Trübsal.","","Feigheit ist teuer.","Ausrüstung",[],["Noxus"],"SELTEN"]};
